/* ---------- Settings: effective getters & application ---------- */
// Reduced motion: the setting overrides the OS preference ("on"/"off"); "auto"
// follows the system. Used everywhere motion is gated in JS.
function motionReduced() {
  if (settings.reduceMotion === "on") return true;
  if (settings.reduceMotion === "off") return false;
  return prefersReducedMotion();
}
// "Instant" animation speed skips the JS-timed animations (page flip, pen circle).
function animInstant() { return settings.animSpeed === "instant"; }
// Scale factor for JS animation delays: instant→0, fast→0.5, normal→1.
function animScale() { return settings.animSpeed === "instant" ? 0 : settings.animSpeed === "fast" ? 0.5 : 1; }
// The active album→colour palette (colour-blind variant when that setting is on).
function albumPalette() { return settings.colorBlindAlbums ? CB_ALBUM_COLORS : ALBUM_COLORS; }
function albumColor(name) { return albumPalette()[name] || null; }

// Push the settings that are realised via CSS onto <body> data-attributes, and
// keep the easter-egg / motion code paths reading the live `settings` object.
// The three-way theme setting resolves to one of two real states. "system" asks the OS;
// "light"/"dark" force it. Kept as a pure helper so the pre-paint script in index.html
// (which can't import anything) and applySettings agree on the same rule.
function effectiveTheme() {
  const t = settings.theme || "light";
  if (t === "dark") return "dark";
  if (t === "system") {
    return (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches) ? "dark" : "light";
  }
  return "light";
}
// The mobile browser chrome / status bar colour. Follows the desk in dark, the paper in light,
// so the notch never stays cream over a dark page (or vice versa).
function paintThemeColor(dark) {
  const m = document.querySelector('meta[name="theme-color"]');
  if (m) m.setAttribute("content", dark ? "#14110d" : "#f5efe1");
}
/* ---------- The gold that is never quite the same gold ----------
   A private joke with a straight face. The hero button's fill is nominally #efb73e, which is
   hsl(41 85% 59%), and every page load quietly re-rolls it inside a tiny box around that point.
   The intent is that nobody ever catches it in the act: one load is never a different colour
   from the one before it, only a slightly different one, so the button reads as gold every time
   and a screenshot from last week reads as very slightly wrong for reasons nobody can name.

   The box is deliberately mean. Hue is the wide axis at ±6°, because within that arc the fill
   stays unarguably "the yellow button" — push it much further and one end goes green and the
   other goes orange, which is a different button and would be clocked instantly. Saturation and
   lightness barely move at all (±4 / ±2), since they're the axes that read as a MISTAKE rather
   than a shade: a washed-out or blown-out fill looks like a rendering bug, and the label's
   contrast against it has to survive every roll.

   Only the plain gold rolls. The Mastery finishes are earned cosmetics and a player who chose
   rose picked THAT rose, so they set their own background-color and never touch this. The one
   exception is the ink finish's hover, which returns to gold and so returns to today's gold.
   Session-scoped on purpose: it lives in a style property on <html> rather than storage, so a
   reload is the thing that changes it, which is the whole gag. */
const CTA_GOLD = { h: 41, s: 85, l: 59 };   // #efb73e, the nominal fill
const CTA_JITTER = { h: 6, s: 4, l: 2 };
let ctaGoldRoll = null;   // the hue/sat/light actually in force this load (dev readout reads it)
function rollCtaGold(fixed) {
  const jit = (base, spread) => base + (Math.random() * 2 - 1) * spread;
  ctaGoldRoll = fixed ? { ...CTA_GOLD }
    : { h: jit(CTA_GOLD.h, CTA_JITTER.h), s: jit(CTA_GOLD.s, CTA_JITTER.s), l: jit(CTA_GOLD.l, CTA_JITTER.l) };
  document.documentElement.style.setProperty("--cta-gold",
    `hsl(${ctaGoldRoll.h.toFixed(1)} ${ctaGoldRoll.s.toFixed(1)}% ${ctaGoldRoll.l.toFixed(1)}%)`);
  return ctaGoldRoll;
}

// Write the chosen words (and their mark) into the start button — the level-12 reward.
//
// Unlike the level-8 finish, which is one attribute, this owns the button's CONTENTS, so it
// is the only thing allowed to write them: index.html ships the default and this replaces it.
// `.cta-mk` suppresses the ✎ pseudo-element, because a chosen mark is a real SVG child and
// the two must never both be present. The default ("" and, defensively, any label id that is
// no longer in CTA_LABELS) puts the shipped markup back, glyph and all.
//
// The glyph keeps its playPencil wiggle and the SVG marks do not. The rotation was drawn for
// a pencil held in a hand; a nametag or a turned page rocking 12° reads as a wobble rather
// than as writing, and the ones it would suit are not worth a per-mark opt-in.
function writeCtaLabel(btn, labelId) {
  const opt = labelId ? CTA_LABELS[labelId] : null;
  if (!opt) {
    btn.classList.remove("cta-mk");
    btn.textContent = "Start writing";
    return;
  }
  btn.classList.add("cta-mk");
  const mark = opt.mark ? `<span class="cta-mark" aria-hidden="true">${CTA_MARKS[opt.mark] || ""}</span>` : "";
  btn.innerHTML = mark + escapeHtml(opt.text);
}

function applySettings() {
  const body = document.body;
  const dark = effectiveTheme() === "dark";
  // The attribute lives on <html> so the pre-paint script (which runs before <body> exists)
  // and this function write to the same element, and CSS keys off :root[data-theme].
  document.documentElement.setAttribute("data-theme", dark ? "dark" : "light");
  paintThemeColor(dark);
  const rm = settings.reduceMotion === "on" ? "on"
           : settings.reduceMotion === "off" ? "off"
           : (prefersReducedMotion() ? "on" : "off");
  body.setAttribute("data-reduce-motion", rm);
  body.setAttribute("data-anim-speed", settings.animSpeed || "normal");
  body.setAttribute("data-text-size", ["small", "large"].includes(settings.textSize) ? settings.textSize : "standard");
  body.setAttribute("data-desk-density", ["quiet", "bare"].includes(settings.deskDensity) ? settings.deskDensity : "full");
  if (settings.highContrast) body.setAttribute("data-contrast", "high");
  else body.removeAttribute("data-contrast");
  // One universal dark paper: the earned paper stocks are a light-mode cosmetic, so in dark
  // mode we drop data-paper entirely and let the dark tokens stand for every stock.
  if (settings.masteryPaper && !dark) body.setAttribute("data-paper", settings.masteryPaper);
  else body.removeAttribute("data-paper");
  // The start-button finish sits on the button itself, not the body: the Mastery reward board
  // previews every finish at once, and each swatch is a real .play-cta carrying its own.
  const playCta = $("playBtn");
  if (playCta) {
    // activeButtonFinish/activeCtaLabel, not the raw settings: either may hold "random", in
    // which case what the button wears is this page load's roll.
    const finish = activeButtonFinish();
    if (finish) playCta.setAttribute("data-startbtn", finish);
    else playCta.removeAttribute("data-startbtn");
    // A Pride finish brings its ramp with it; every other finish paints from CSS and must be
    // left with no inline stripes at all, or a stale gradient would outlive the switch away.
    const stripes = prideStripes(finish);
    if (stripes) playCta.style.setProperty("--cta-stripes", stripes);
    else playCta.style.removeProperty("--cta-stripes");
    writeCtaLabel(playCta, activeCtaLabel());
  }
  sfx.setEnabled(!!settings.sound);   // sound gate lives in js/sound.js
  paintSoundGear();                   // the corner icon is a view of settings.sound, never its own state
  refreshSnow();   // December snowfall follows the reduce-motion setting live
  refreshRain();   // midnight rain follows the reduce-motion setting live too
  refreshLeaves(); // autumn leaves follow the reduce-motion setting live too
  window.dispatchEvent(new CustomEvent("deskscatter:refresh"));
}

/* ---------- Sound icon (corner) ----------
   The speaker beside the gear is the front door to the sound palette: settings.sound is off by
   default and a player who never opens the Sound section of settings would otherwise never learn
   the game has a voice. It renders the setting and nothing else: every write goes through
   setSound → applySettings → paintSoundGear, so the icon and the settings toggle cannot disagree. */
function paintSoundGear() {
  const b = $("soundGear");
  if (!b) return;
  const on = !!settings.sound;
  b.dataset.on = on ? "true" : "false";
  b.setAttribute("aria-pressed", on ? "true" : "false");
  // The title carries the invitation the icon can only imply.
  b.title = on ? "Sound effects on. Tap to mute." : "Sound effects off. Tap to turn them on.";
}
// The single writer for settings.sound, shared by the corner icon and the settings toggle.
// Turning it on auditions the chime, which is also the gesture that wakes the AudioContext
// (see the autoplay note in js/sound.js), so the very first sound is the one they asked for.
function setSound(on) {
  settings.sound = !!on;
  saveSettings(settings);
  applySettings();
  if (settings.sound) playSound("correct");
}

// Category gates sit above the palette's master switch. Dev auditions still call sfx.play
// directly so a muted category can be inspected without rewriting the player's preferences.
const SOUND_CATEGORIES = {
  correct: "soundFeedback", wrong: "soundFeedback", hint: "soundFeedback",
  page: "soundPaper", scratch: "soundPaper", close: "soundPaper",
  tick: "soundTimer", unlock: "soundUnlocks",
};
function playSound(name, force = false, level = 1) {
  const key = SOUND_CATEGORIES[name];
  if (key && settings[key] === false) return false;
  return sfx.play(name, force, level);
}

function phoneViewport() {
  return !!(window.matchMedia && window.matchMedia("(max-width: 760px)").matches);
}
function focusRoundInput(input) {
  if (input && (!phoneViewport() || settings.openKeyboard !== false)) input.focus();
}

/* ---------- December snowfall ---------- */
// A full-viewport canvas of drifting flakes, decorative only. Active in December
// (the player's active timezone, via todayKey — so it follows the same local
// calendar as the daily reset) and only when motion is allowed.
let snowRaf = null, snowFlakes = [], snowCanvas = null, snowCtx = null,
    snowLast = 0, snowResizeT = null, snowResizeBound = false, devForceSnow = false;
// December (or dev-forced), and only when motion is allowed. The dev override
// bypasses the calendar but still respects reduce-motion, so it exercises the
// real gate rather than a special case.
function snowActive() { return settings.seasonalEffects !== false && (devForceSnow || todayKey().slice(5, 7) === "12") && !motionReduced(); }
function sizeSnowCanvas() {
  if (!snowCanvas) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = window.innerWidth, h = window.innerHeight;
  snowCanvas.width = Math.max(1, Math.round(w * dpr));
  snowCanvas.height = Math.max(1, Math.round(h * dpr));
  snowCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
  // Flake count scales with viewport area, capped for performance. Depth is faked
  // per flake (size/speed/opacity), so nearer flakes fall faster and brighter.
  const target = Math.min(150, Math.round((w * h) / 13000));
  if (snowFlakes.length > target) snowFlakes.length = target;
  while (snowFlakes.length < target) {
    const d = Math.random();
    snowFlakes.push({ x: Math.random() * w, y: Math.random() * h,
      r: 0.8 + d * 2.6, sp: 8 + d * 26, dr: 0.3 + d * 0.7,
      ph: Math.random() * 6.2832, o: 0.3 + d * 0.55 });
  }
}
function snowFrame(ts) {
  if (!snowActive() || !snowCtx) { stopSnow(); return; }
  const w = window.innerWidth, h = window.innerHeight;
  let dt = snowLast ? (ts - snowLast) / 1000 : 0.016;
  snowLast = ts;
  if (dt > 0.05) dt = 0.05;   // clamp big jumps from a throttled/backgrounded tab
  snowCtx.clearRect(0, 0, w, h);
  snowCtx.fillStyle = "#ffffff";
  for (const f of snowFlakes) {
    f.y += f.sp * dt;
    f.x += Math.sin(ts / 1000 + f.ph) * 13 * f.dr * dt;   // gentle lateral sway
    if (f.y > h + 4) { f.y = -4; f.x = Math.random() * w; }
    if (f.x > w + 4) f.x = -4; else if (f.x < -4) f.x = w + 4;
    snowCtx.globalAlpha = f.o;
    snowCtx.beginPath();
    snowCtx.arc(f.x, f.y, f.r, 0, 6.2832);
    snowCtx.fill();
  }
  snowCtx.globalAlpha = 1;
  snowRaf = requestAnimationFrame(snowFrame);
}
function startSnow() {
  if (!snowCanvas) {
    snowCanvas = document.getElementById("snowfall");
    if (!snowCanvas) return;
    snowCtx = snowCanvas.getContext("2d");
  }
  if (!snowResizeBound) {
    window.addEventListener("resize", () => {
      clearTimeout(snowResizeT);
      snowResizeT = setTimeout(() => { if (snowActive()) sizeSnowCanvas(); }, 150);
    });
    snowResizeBound = true;
  }
  sizeSnowCanvas();
  snowCanvas.style.display = "block";
  snowLast = 0;
  if (!snowRaf) snowRaf = requestAnimationFrame(snowFrame);
  unlock("snow-on-the-beach");   // weird but beautiful — you caught the December snow
}
function stopSnow() {
  if (snowRaf) { cancelAnimationFrame(snowRaf); snowRaf = null; }
  if (snowCanvas) {
    snowCtx && snowCtx.clearRect(0, 0, snowCanvas.width, snowCanvas.height);
    snowCanvas.style.display = "none";
  }
}
function refreshSnow() { if (snowActive()) startSnow(); else stopSnow(); }

/* ---------- Midnight Rain ---------- */
// The snowfall's seasonal sibling on the same rAF machinery: a full-viewport canvas
// of thin, near-vertical streaks. Active only in the first minute of the day, 12:00 to
// 12:01am in the player's active timezone (the clock reads local wall-clock, matching
// how the daily midnight sticky is gated), and only when motion is allowed. A shower
// that passes, not weather you have to sit through: an hour of it wears out its
// welcome long before the hour is up.
let rainRaf = null, rainDrops = [], rainCanvas = null, rainCtx = null,
    rainLast = 0, rainResizeT = null, rainResizeBound = false, devForceRain = false;
// Both hands straight up: getHours() === 0 && getMinutes() === 0 is the minute after
// midnight. rainFrame re-checks this every frame, so a page open across 12:01 stops
// the rain on its own. Dev override bypasses the clock but still respects
// reduce-motion, exercising the real gate rather than a special case.
function rainActive() {
  const now = new Date();
  return settings.seasonalEffects !== false && (devForceRain || (now.getHours() === 0 && now.getMinutes() === 0)) && !motionReduced();
}
function sizeRainCanvas() {
  if (!rainCanvas) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = window.innerWidth, h = window.innerHeight;
  rainCanvas.width = Math.max(1, Math.round(w * dpr));
  rainCanvas.height = Math.max(1, Math.round(h * dpr));
  rainCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
  // Drop count scales with viewport area, capped for performance. Depth is faked per
  // drop (length/speed/opacity/width), so nearer drops fall faster, longer, brighter.
  const target = Math.min(140, Math.round((w * h) / 14000));
  if (rainDrops.length > target) rainDrops.length = target;
  while (rainDrops.length < target) {
    const d = Math.random();
    rainDrops.push({ x: Math.random() * w, y: Math.random() * h,
      len: 9 + d * 18, sp: 380 + d * 520, wob: 0.6 + d * 0.9,
      o: 0.18 + d * 0.34 });
  }
}
function rainFrame(ts) {
  if (!rainActive() || !rainCtx) { stopRain(); return; }
  const w = window.innerWidth, h = window.innerHeight;
  let dt = rainLast ? (ts - rainLast) / 1000 : 0.016;
  rainLast = ts;
  if (dt > 0.05) dt = 0.05;   // clamp big jumps from a throttled/backgrounded tab
  rainCtx.clearRect(0, 0, w, h);
  rainCtx.strokeStyle = "#3f4d6b";   // dark slate-blue — reads as rain on a light desk
  rainCtx.lineCap = "round";
  const slant = 1.1;   // px of horizontal drift per px of fall — a light wind lean
  for (const d of rainDrops) {
    d.y += d.sp * dt;
    d.x += d.wob * d.sp * 0.03 * dt;   // faint drift so the streaks aren't a rigid grid
    if (d.y - d.len > h) { d.y = -d.len; d.x = Math.random() * w; }
    if (d.x > w + 4) d.x = -4;
    rainCtx.globalAlpha = d.o;
    rainCtx.lineWidth = 0.8 + d.len * 0.04;
    rainCtx.beginPath();
    rainCtx.moveTo(d.x, d.y);
    rainCtx.lineTo(d.x - slant * d.len * 0.32, d.y - d.len);
    rainCtx.stroke();
  }
  rainCtx.globalAlpha = 1;
  rainRaf = requestAnimationFrame(rainFrame);
}
function startRain() {
  if (!rainCanvas) {
    rainCanvas = document.getElementById("midnightrain");
    if (!rainCanvas) return;
    rainCtx = rainCanvas.getContext("2d");
  }
  if (!rainResizeBound) {
    window.addEventListener("resize", () => {
      clearTimeout(rainResizeT);
      rainResizeT = setTimeout(() => { if (rainActive()) sizeRainCanvas(); }, 150);
    });
    rainResizeBound = true;
  }
  sizeRainCanvas();
  rainCanvas.style.display = "block";
  rainLast = 0;
  if (!rainRaf) rainRaf = requestAnimationFrame(rainFrame);
  unlock("midnight-rain");   // you kept the page company past midnight
}
function stopRain() {
  if (rainRaf) { cancelAnimationFrame(rainRaf); rainRaf = null; }
  if (rainCanvas) {
    rainCtx && rainCtx.clearRect(0, 0, rainCanvas.width, rainCanvas.height);
    rainCanvas.style.display = "none";
  }
}
function refreshRain() { if (rainActive()) startRain(); else stopRain(); }

/* ---------- Autumn leaves ---------- */
// The third seasonal sibling on the same rAF machinery: a full-viewport canvas of leaves
// that tumble rather than fall. Where snow drifts and rain streaks, a leaf flutters — a
// pendulum sway, a slow spin, and a faked edge-on flip so each one turns over on its way
// down. Active for the Halloween week (28 Oct through 3 Nov, active timezone) and only
// when motion is allowed. Sparse and warm: a window left open in late October, not a
// leaf storm.
let leafRaf = null, leaves = [], leafCanvas = null, leafCtx = null,
    leafLast = 0, leafResizeT = null, leafResizeBound = false, devForceLeaves = false;
// Muted autumn hues — ochre, sienna, russet, faded gold, dusty red-brown. Warm but
// low-saturation, so they read as pressed leaves on a desk, not a neon confetti burst.
const LEAF_HUES = ["#b5651d", "#a0522d", "#c68a3e", "#8a5a2b", "#9e4a34", "#c9a24b"];
// The Halloween window: the 31st plus the three days either side (28 Oct through
// 3 Nov), in the player's active timezone via todayKey so it follows the same local
// calendar as the daily reset. The dev override bypasses the calendar but still
// respects reduce-motion, exercising the real gate rather than a special case.
const LEAF_DAYS = new Set(["10-28", "10-29", "10-30", "10-31", "11-01", "11-02", "11-03"]);
function leavesActive() {
  return settings.seasonalEffects !== false && (devForceLeaves || LEAF_DAYS.has(todayKey().slice(5, 10))) && !motionReduced();
}
function makeLeaf(w, h) {
  const d = Math.random();   // 0 = far/small/slow, 1 = near/big/fast (faked depth)
  return {
    x: Math.random() * w, y: Math.random() * h,
    size: 6 + d * 10,                    // half-length in px → ~12–32px tall
    sp: 20 + d * 42,                     // fall speed (px/s), gentler than rain
    sway: 16 + d * 30,                   // lateral flutter amplitude (px)
    swayFq: 0.5 + Math.random() * 0.8,   // flutter frequency
    swayPh: Math.random() * 6.2832,
    rot: Math.random() * 6.2832, rotSp: (Math.random() - 0.5) * 1.6,   // spin, either way
    flip: Math.random() * 6.2832, flipSp: 0.6 + d * 1.3,               // edge-on tumble rate
    hue: LEAF_HUES[(Math.random() * LEAF_HUES.length) | 0],
    o: 0.5 + d * 0.4 };
}
function sizeLeafCanvas() {
  if (!leafCanvas) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = window.innerWidth, h = window.innerHeight;
  leafCanvas.width = Math.max(1, Math.round(w * dpr));
  leafCanvas.height = Math.max(1, Math.round(h * dpr));
  leafCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
  // Leaf count scales with viewport area, capped for performance. Leaves are large,
  // so this runs sparser than snow. Depth is faked per leaf (size/speed/spin/opacity).
  const target = Math.min(70, Math.round((w * h) / 26000));
  if (leaves.length > target) leaves.length = target;
  while (leaves.length < target) leaves.push(makeLeaf(w, h));
}
// A single leaf silhouette at the origin, pointing up: two quad curves for the ovate
// blade, a thin darker midrib, and a short stem past the base. Caller sets the transform.
function drawLeaf(ctx, lf) {
  const s = lf.size;
  ctx.beginPath();
  ctx.moveTo(0, -s);                                   // tip
  ctx.quadraticCurveTo(s * 0.62, -s * 0.05, 0, s);     // right edge down to base
  ctx.quadraticCurveTo(-s * 0.62, -s * 0.05, 0, -s);   // left edge back to tip
  ctx.closePath();
  ctx.fillStyle = lf.hue;
  ctx.fill();
  if (s > 8) {   // skip veins on the tiniest far leaves — they'd just read as noise
    ctx.strokeStyle = "rgba(58,36,16,0.4)";
    ctx.lineWidth = Math.max(0.5, s * 0.05);
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.85);
    ctx.lineTo(0, s * 1.22);   // vein runs a little past the base to hint the stem
    ctx.stroke();
  }
}
function leafFrame(ts) {
  if (!leavesActive() || !leafCtx) { stopLeaves(); return; }
  const w = window.innerWidth, h = window.innerHeight;
  let dt = leafLast ? (ts - leafLast) / 1000 : 0.016;
  leafLast = ts;
  if (dt > 0.05) dt = 0.05;   // clamp big jumps from a throttled/backgrounded tab
  leafCtx.clearRect(0, 0, w, h);
  for (const lf of leaves) {
    lf.y += lf.sp * dt;
    lf.rot += lf.rotSp * dt;
    lf.flip += lf.flipSp * dt;
    if (lf.y - lf.size > h) { lf.y = -lf.size; lf.x = Math.random() * w; }   // recycle up top
    const drawX = lf.x + Math.sin(ts / 1000 * lf.swayFq + lf.swayPh) * lf.sway;   // flutter
    leafCtx.save();
    leafCtx.translate(drawX, lf.y);
    leafCtx.rotate(lf.rot);
    leafCtx.scale(Math.cos(lf.flip), 1);   // edge-on flip: width collapses then mirrors
    leafCtx.globalAlpha = lf.o;
    drawLeaf(leafCtx, lf);
    leafCtx.restore();
  }
  leafCtx.globalAlpha = 1;
  leafRaf = requestAnimationFrame(leafFrame);
}
function startLeaves() {
  if (!leafCanvas) {
    leafCanvas = document.getElementById("autumnleaves");
    if (!leafCanvas) return;
    leafCtx = leafCanvas.getContext("2d");
  }
  if (!leafResizeBound) {
    window.addEventListener("resize", () => {
      clearTimeout(leafResizeT);
      leafResizeT = setTimeout(() => { if (leavesActive()) sizeLeafCanvas(); }, 150);
    });
    leafResizeBound = true;
  }
  sizeLeafCanvas();
  leafCanvas.style.display = "block";
  leafLast = 0;
  if (!leafRaf) leafRaf = requestAnimationFrame(leafFrame);
  unlock("autumn-leaves-falling");   // you stayed with the page through the autumn leaves
}
function stopLeaves() {
  if (leafRaf) { cancelAnimationFrame(leafRaf); leafRaf = null; }
  if (leafCanvas) {
    leafCtx && leafCtx.clearRect(0, 0, leafCanvas.width, leafCanvas.height);
    leafCanvas.style.display = "none";
  }
}
function refreshLeaves() { if (leavesActive()) startLeaves(); else stopLeaves(); }
// Remember the last type clicked so defaultGameType:"last" can restore it next launch.
function rememberGameType(t) {
  if (settings.lastGameType !== t) { settings.lastGameType = t; saveSettings(settings); }
}

/* ---------- DOM ---------- */
const screens = {
  start: $("screen-start"),
  game: $("screen-game"),
  results: $("screen-results"),
  stats: $("screen-stats"),
  records: $("screen-records"),
  achievements: $("screen-achievements"),
  challenges: $("screen-challenges"),
  bonus: $("screen-bonus"),
  bonusplay: $("screen-bonusplay"),
  songbook: $("screen-songbook"),
  albumfocus: $("screen-albumfocus"),
  ruthless: $("screen-ruthless"),
  guests: $("screen-guests"),
  guestdetail: $("screen-guest-detail"),
  mastery: $("screen-mastery"),
};
function showScreen(name) {
  // Defensive: clear any stray inline animation a flip sheet helper might have left on a real
  // screen, so every screen animates normally on its next genuine show.
  Object.values(screens).forEach((s) => { s.classList.remove("active"); s.style.animation = ""; });
  screens[name].classList.add("active");
  // Drop any lingering perfect-game shimmer; celebratePerfect re-adds it after
  // showScreen("results") when the run was actually flawless.
  clearPerfectFX();
  // The daily reset countdown only lives on the start screen; don't let its interval
  // outlive the view (renderDailyButtonState restarts it when start is shown again).
  if (name !== "start") stopResetCountdown();
  // The era wash belongs to a run and to the results it earned. Every other page is the plain
  // gold desk — otherwise a finale era rides out of a finished game and tints the whole
  // notebook until the next run or a reload (midnight is navy, so the desk just goes blue).
  // The routes that already flip home reset this themselves before re-rendering; this is the
  // backstop for the ones that don't, like a challenge or Album Focus result heading back to
  // its own list.
  if (name !== "game" && name !== "results") applyEra("gold");
  // Hide the bottom-left lyric-search chrome during active play, so it doesn't clutter the board.
  document.body.classList.toggle("in-game", name === "game");
  if (name !== "game") dismissCoachmark();   // no guided-round note should outlive the board
  // Re-arm the quit button fresh for each visit to the game (drop any stale armed state).
  if (name === "game") {
    const qb = $("quitBtn");
    if (qb) { clearTimeout(quitTimer); qb.classList.remove("armed"); qb.textContent = qb.dataset.label; }
    renderMilestoneSticky();   // milestone-day corner sticky (silent on ordinary days)
  }
  // Re-scatter the keepsake-card tape each time its screen is shown, so the pinning
  // feels hand-done rather than templated.
  if (name === "start" || name === "results") { scatterNavTape(name); updateMasteryNav(); updateKeepsakesNav(); }
  // Move keyboard/screen-reader focus onto the newly shown screen so the next Tab
  // (and the SR reading position) start there, not on the now-hidden trigger. The
  // game screen manages its own focus on #songInput, so don't steal it there.
  if (name !== "game") {
    const sec = screens[name];
    if (sec && typeof sec.focus === "function") {
      try { sec.focus({ preventScroll: true }); } catch (_) { sec.focus(); }
    }
  }
  // Nudge the decorative gutter beads (js/scatter.js): the page height changes
  // between screens, so the scatter re-fills to match whatever is now shown.
  window.dispatchEvent(new CustomEvent("deskscatter:refresh"));
}

/* Side-to-side page turns for screen navigation. Where nextRound's flip lifts the answered
   page up from its top edge (forward through the notebook), these turn pages sideways around
   the left spine. Two complementary motions sell "going in" vs "coming back":
     • flipAwayToScreen — FORWARD into a sub-page (records/stats/charms/challenges): the page
       you're leaving turns away to the left, revealing the destination already in place beneath.
     • flipInToScreen — BACK (and give-up): the page you're returning to turns IN from the left,
       landing on top of the screen you're leaving, which then becomes the real active screen.
   Both clone a screen as a frozen sheet (the nextRound technique) and honour the same
   reduced-motion / instant-speed / page-turn-off opt-outs (else they just switch instantly).
   A flip sheet is the clone of `src`, positioned over `at` (a currently-visible screen, so its
   offsets are real even when `src` is display:none). */
function makeFlipSheet(src, at, sideClass, shadeClass) {
  const flip = src.cloneNode(true);
  // Keep element ids on the clone: some of the look is keyed off ids (e.g. #screen-start's
  // backdrop, #againBtn), so stripping them would render the sheet in a half-unstyled state.
  // The real screens come earlier in the DOM, so getElementById still resolves to them; the
  // clone carries no event listeners (cloneNode) and is pointer-events:none and short-lived.
  flip.classList.remove("screen", "active");
  // Purely a visual page-turn artifact (and a duplicate of live regions like #wordDisplay) —
  // keep it out of the a11y tree so screen readers don't re-announce the cloned word/feedback.
  flip.setAttribute("aria-hidden", "true");
  flip.classList.add("page-flip-sheet", sideClass);
  flip.style.animation = "";          // never inherit a one-off inline animation from the source
  flip.style.opacity = "";
  flip.style.transition = "";
  flip.style.top = at.offsetTop + "px";
  flip.style.left = at.offsetLeft + "px";
  flip.style.width = at.offsetWidth + "px";
  const shade = document.createElement("div");
  shade.className = "flip-shade " + shadeClass;
  flip.appendChild(shade);
  at.parentNode.appendChild(flip);
  return flip;
}
function scheduleFlipRemoval(flip, onEnd) {
  let finished = false;
  const finish = () => { if (finished) return; finished = true; flip.remove(); if (onEnd) onEnd(); };
  flip.addEventListener("animationend", (e) => { if (e.target === flip) finish(); });
  setTimeout(finish, 500 * animScale() || 250);
}
// One-shot suppressor for the next page turn. Set where two navigations run back to back
// (the bookplate's Mastery door quits a live run and then opens Mastery), so only the second
// one turns the page instead of two flips animating over each other in the same frames.
let skipNextFlip = false;
function flipDisabled(name, current) {
  if (skipNextFlip) { skipNextFlip = false; return true; }
  return !current || current === screens[name] || !pageTurnAnimated();
}
// FORWARD: the leaving page turns away to reveal the destination beneath it.
function flipAwayToScreen(name) {
  const current = Object.values(screens).find((s) => s.classList.contains("active"));
  if (flipDisabled(name, current)) { showScreen(name); return; }
  const flip = makeFlipSheet(current, current, "page-flip-sheet--side", "flip-shade--side");
  showScreen(name);                                   // destination now active beneath the sheet
  scheduleFlipRemoval(flip);
}
// BACK: the destination page turns in on top of the page you're leaving. The destination must
// already be rendered (and any display fix applied) by the caller before this runs.
function flipInToScreen(name) {
  const current = Object.values(screens).find((s) => s.classList.contains("active"));
  if (flipDisabled(name, current)) { showScreen(name); return; }
  const dest = screens[name];
  // 1. Freeze the page we're leaving as a static backdrop, so swapping the real screens
  //    underneath it is invisible.
  const backdrop = makeFlipSheet(current, current, "flip-static", "flip-shade--off");
  // 2. Activate the destination beneath the backdrop NOW — so it's fully prepared (tape
  //    re-scattered, etc.) before we clone it.
  showScreen(name);
  // Suppress the destination's own enter-fade: the incoming flip sheet IS the motion, and
  // when the page we're leaving is shorter than the destination (e.g. give-up: the game
  // card is shorter than the start screen) the real screen's fade would otherwise play in
  // the uncovered strip below the backdrop — a second animation fighting the page turn.
  // Left in place when the flip finishes: clearing it here would revert the still-active
  // destination to its CSS fade and replay it (an extra flash). The next genuine showScreen
  // clears every screen's inline animation, so the fade plays normally on the next show.
  dest.style.animation = "none";
  // 3. Clone the now-final destination for the incoming sheet — so its tape and id-styled
  //    buttons match the real screen exactly — and flip it in over the backdrop. (dest is the
  //    visible active screen now, so its offsets are real.)
  const incoming = makeFlipSheet(dest, dest, "page-flip-sheet--in", "flip-shade--in");
  // 4. Now hide the real destination for the length of the turn. The backdrop only covers the
  //    page we're leaving, so when the destination is TALLER (e.g. quitting a game: the start
  //    board is longer than the game card) its uncovered lower strip would otherwise be sitting
  //    there in full the instant the button is tapped — the bottom of the incoming page arriving
  //    before the turn that brings it. Hidden, that strip is bare desk until the incoming sheet
  //    lands on it, so the page is only ever seen flipping in. Restored in the same tick the
  //    sheets are removed (below), so there's no frame without a page. Order matters: the clone
  //    above is taken while the destination is still visible.
  dest.style.opacity = "0";
  // 5. The destination is often SHORTER than the page we're leaving, so fade the backdrop's
  //    lower (uncovered) half out near the end — it dissolves into the desk instead of snapping
  //    away when the sheets are removed.
  const s = animScale() || 1;
  backdrop.offsetHeight;                        // flush the opacity:1 baseline so the transition runs
  backdrop.style.transition = `opacity ${(0.16 * s).toFixed(3)}s linear ${(0.32 * s).toFixed(3)}s`;
  backdrop.style.opacity = "0";
  scheduleFlipRemoval(incoming, () => { backdrop.remove(); dest.style.opacity = ""; });
}

/* The back tap out of a sub-page (stats/records/achievements/mastery/challenges/album focus),
   returning to whichever screen opened it. Landing on the start screen MUST go through
   renderStartPickers: the sandboxed modes (challenge/daily/album/custom) override
   currentMode and gameType without persisting them, and renderStartPickers is the one place
   that restores the player's real picked difficulty. Skipping it leaves the launchpad wearing a
   finished run's levers — e.g. challenge results → ← challenges → back → Infinite handed you
   Revolving Door's 20s clock on a Normal board. Always route back-to-start through here. */
function backToScreen(prev) {
  if (prev === "start") {
    $("startContent").style.display = "";
    renderStartPickers();
  }
  flipInToScreen(prev);
}

/* First paint after loadData(): swap the closed notebook cover for the real start board.
   While loading, #screen-start wears `is-booting` (no ruled paper/padding) so the cover fills
   the whole card. To open, we lay the board out beneath, drop `is-booting` so the card is its
   real self, then clone the cover into a genuine .page-flip-sheet--side and turn it away on the
   left spine — the exact motion + shading used everywhere else (e.g. exiting a game). Cloning
   into the same flip machinery (rather than a bespoke transform) is what keeps the open feeling
   as polished as the other page turns. `onDone` runs once the notebook is fully open (after the
   turn, or immediately on the reduced-motion / instant / page-turn-off paths), so splash screens
   only appear over a settled layout. */
function revealNotebook(onDone) {
  const loading = $("loading");
  const content = $("startContent");
  const card = $("screen-start");
  const done = () => { if (typeof onDone === "function") onDone(); };
  const layOutBoard = () => { card.classList.remove("is-booting"); content.style.display = ""; refreshStartBoard(); };
  if (!loading || !pageTurnAnimated()) {
    if (loading) loading.style.display = "none";
    layOutBoard();
    done();
    return;
  }
  // Measure the closed cover exactly as the player sees it now — at the card's real position and
  // width (border-box, so restoring padding below won't move it) and the idle page height.
  const top = card.offsetTop, left = card.offsetLeft, width = card.offsetWidth;
  const height = loading.getBoundingClientRect().height;
  // Reveal the real board and hide the original cover, then immediately cover the seam with the
  // flip sheet (same synchronous tick, so the bare board never flashes before the turn starts).
  layOutBoard();
  loading.style.display = "none";
  const flip = loading.cloneNode(true);
  flip.removeAttribute("id");
  flip.querySelectorAll("[id]").forEach((e) => e.removeAttribute("id"));
  flip.setAttribute("aria-hidden", "true");
  flip.style.display = "";
  flip.classList.remove("loading");
  flip.classList.add("page-flip-sheet", "page-flip-sheet--side", "cover-flip");
  flip.style.top = top + "px";
  flip.style.left = left + "px";
  flip.style.width = width + "px";
  flip.style.height = height + "px";
  const shade = document.createElement("div");
  shade.className = "flip-shade flip-shade--side";
  flip.appendChild(shade);
  card.parentNode.appendChild(flip);
  let finished = false;
  const finish = () => { if (finished) return; finished = true; flip.remove(); done(); };
  flip.addEventListener("animationend", (e) => { if (e.target === flip) finish(); });
  setTimeout(finish, 500 * (animScale() || 1) + 80);
}

/* ---------- Sticky-tape on the nav keepsake cards ----------
   ONE deliberate, art-directed arrangement, fixed across visits, so the board reads as
   a set of cards someone intentionally taped down rather than a layout that re-dices
   itself on every render (which looked restless and, on unlucky rolls, left strips
   floating in the gaps between cards). One strip per card: each row of three gets corners
   on the outer pair and a centre pin on the middle card, so tape never lands in the inner
   gaps. Rotation, length, and tear vary per card for a handmade feel but never change. Order
   matches the DOM (start screen): records, stats, charms, challenges, mastery, bonus. Strips
   are injected as .nav-tape child elements (styles.css). */
const TORN_EDGES = [
  "polygon(5% 0%, 96% 0%, 91% 20%, 97% 40%, 88% 60%, 96% 80%, 90% 100%, 8% 100%, 4% 80%, 10% 60%, 3% 40%, 7% 20%)",
  "polygon(4% 0%, 95% 0%, 99% 25%, 90% 50%, 97% 75%, 93% 100%, 6% 100%, 10% 75%, 2% 50%, 9% 25%)",
  "polygon(8% 0%, 92% 0%, 96% 33%, 89% 66%, 97% 100%, 7% 100%, 3% 66%, 11% 33%)",
];
const NAV_TAPE_PATTERN = [
  { left: "-9px",   top: "-6px",             rot: -42, w: 54, tear: 0 },   // records    · top-left corner
  { left: "50%",    top: "-7px", tx: "-50%", rot: 5,   w: 50, tear: 1 },   // stats      · top-centre pin
  { right: "-9px",  top: "-6px",             rot: 40,  w: 56, tear: 2 },   // charms     · top-right corner
  { left: "-10px",  bottom: "-7px",             rot: 38,  w: 52, tear: 1 },   // challenges · bottom-left corner
  { left: "50%",    bottom: "-7px", tx: "-50%", rot: -6,  w: 50, tear: 2 },   // mastery    · bottom-centre pin
  { right: "-10px", bottom: "-7px",             rot: -44, w: 55, tear: 0 },   // bonus      · bottom-right corner
];
function makeTapeStrip(spot) {
  const t = document.createElement("span");
  t.className = "nav-tape";
  t.style.top = spot.top || "auto";
  t.style.right = spot.right || "auto";
  t.style.bottom = spot.bottom || "auto";
  t.style.left = spot.left || "auto";
  t.style.width = spot.w + "px";
  t.style.transform = `translateX(${spot.tx || "0"}) rotate(${spot.rot}deg)`;
  t.style.clipPath = TORN_EDGES[spot.tear];
  return t;
}
function scatterNavTape(screenName) {
  const root = screens[screenName] || document;
  // The results page's compact icon row (.see-also--row) has no card face to tape.
  const cards = [...root.querySelectorAll(".nav-card")].filter((c) => !c.closest(".see-also--row"));
  cards.forEach((card, i) => {
    card.querySelectorAll(".nav-tape").forEach((t) => t.remove());   // clear any prior strip
    card.appendChild(makeTapeStrip(NAV_TAPE_PATTERN[i % NAV_TAPE_PATTERN.length]));
  });
}

/* ---------- Era selection ---------- */
function pickEra() {
  // Album Focus locks the whole run to its album's era wash (bracelet/cards already use
  // the album colour; this themes the page to match).
  if (gameType === "album" && focusAlbum) return ALBUM_ERA[focusAlbum] || "gold";
  // A guest run wears its guest's own era for all thirteen pages. ALBUM_ERA can't be asked —
  // it keys on Taylor's albums — and shuffling through her eras would dress someone else's
  // catalogue in her colours, which is exactly the blending the guest shelf exists to avoid.
  if (gameType === "guest") return guestEra();
  // An album-anniversary daily already leans its words toward that album, so let the page
  // wear its colours all thirteen pages rather than shuffling eras over an album-shaped run.
  if (gameType === "daily" && dailyAlbum) return ALBUM_ERA[dailyAlbum] || "gold";
  let pool;
  // Round-5/round-13 biases apply to any fixed 13-round run (classic + daily + challenge).
  const fixedRun = gameType === "classic" || gameType === "daily" || gameType === "challenge" || gameType === "adaptive";
  if (fixedRun && round === 5) pool = TENDER_ERAS;
  else if (fixedRun && round === TOTAL_ROUNDS) pool = FINALE_ERAS;
  else pool = ERAS.filter((e) => !recentEras.includes(e));
  if (!pool.length) pool = ERAS;
  const rng = dailyRng || Math.random;
  const era = pool[Math.floor(rng() * pool.length)];
  recentEras.push(era);
  if (recentEras.length > 3) recentEras.shift();
  return era;
}
function applyEra(era) { document.body.setAttribute("data-era", era); }

/* ---------- Matching helpers ---------- */
// The pure matching core (wordVariants/wordRegex/extractLineWithWord/highlightWord)
// lives in js/match.js so the searcher reuses the exact same logic. The wrappers below
// add the game's defaults — strictness from effectiveStrict() and display censoring —
// then delegate to that core.
// The strictness used for gameplay matching: the active mode's strict flag (no mode
// sets it currently — every difficulty is stem-lenient, incl. Ultra), OR the player's
// global "stem matching off" opt-out (Settings → Gameplay) which forces exact-word
// matching even in lenient modes. NOT used for the rarity buckets/daily determinism
// (those pass explicit strict args), only for judging/highlighting a round.
function effectiveStrict() { return currentMode.strict || settings.stemMatching === false; }
// Per-challenge lever overrides: a challenge entry may set `noTitle` / `pool` to
// override the difficulty mode it borrows (e.g. Word Games allows title-word songs,
// From A to Z draws from the common pool so every round has options). Falls back to
// the active mode for non-challenge runs / challenges that don't override.
function effectiveNoTitle() {
  if (perkNoTitleOff) return false;            // Choose Your Path: Off The Record
  if (gameType === "challenge" && currentChallenge) {
    if (currentChallenge.rule === "devil" && devilNoTitle) return true;   // Devil's Path: No Giveaways
    if (currentChallenge.noTitle !== undefined) return currentChallenge.noTitle;
  }
  return currentMode.noTitle;
}
function effectivePool() {
  if (gameType === "adaptive") return ADAPTIVE_BUCKETS[adaptiveLevel] || "all";   // Adaptive: level drives the rarity bucket
  if (perkPoolOverride) return perkPoolOverride;   // Choose Your Path: Crowd Pleaser
  if (gameType === "challenge" && currentChallenge) {
    if (currentChallenge.rule === "devil" && devilPoolHard) return "hard";   // Devil's Path: Rarer Air
    if (currentChallenge.pool) return currentChallenge.pool;
  }
  return currentMode.pool;
}
// Whether suggestions (the title dropdown) are live right now. Off in lyric-only modes,
// off on a Switch-Up lyric page (a dropdown would hand over the title), and off once
// Devil's Path's "In The Dark" curse has been taken.
function effectiveDropdown() {
  if (lyricModeNow()) return false;
  if (gameType === "challenge" && currentChallenge && currentChallenge.rule === "devil" && devilDropOff) return false;
  // Adaptive: the rarest tiers switch suggestions off so they test recall, not recognition.
  if (gameType === "adaptive" && adaptiveLevel >= ADAPT_NODROP_LEVEL) return false;
  return currentMode.dropdown;
}
// Whether THIS page accepts only a sung lyric line (no title): Lyricist mode always, and
// Switch-Up on a lyric page.
function lyricModeNow() {
  if (currentMode.lyricOnly) return true;
  return gameType === "challenge" && currentChallenge && currentChallenge.rule === "switchup" && roundLyricOnly;
}
// Lenient (default) also matches the inflected forms above (cheat→cheats); strict
// requires the exact word. Defaults to the active mode + the stem-matching opt-out.
function wordRegex(word, strict) {
  if (strict === undefined) strict = effectiveStrict();
  return wordRegexCore(word, strict);
}
function songsContainingWord(word, strict) {
  const rx = wordRegex(word, strict);
  return allSongs.filter((s) => rx.test(s.lyrics));
}
// Valid answers for a round: lyrics contain the word and — when noTitle (Hard/
// Ultra) — the title does NOT, so you can't just name the obvious title song.
function validSongs(word, strict, noTitle) {
  const rx = wordRegex(word, strict);
  return allSongs.filter((s) => rx.test(s.lyrics) && !(noTitle && rx.test(s.title)));
}
// Songs whose TITLE contains the prompt word — the ones the Hard/Ultra "not in
// the title" rule blocks, so we can warn the player before they waste the clock.
function titleSongsForWord(word, strict) {
  const rx = wordRegex(word, strict);
  return allSongs.filter((s) => rx.test(s.title));
}
// Marginalia warning: in dropdown-less noTitle modes (Hard/Ultra), list the songs
// whose title holds the word so the player knows e.g. "All Too Well" won't be
// accepted. Modes WITH a dropdown (Normal) skip this — there the off-limits titles
// are greyed out in the dropdown and a reject-flash explains a blocked pick.
function renderExcludedNote() {
  const el = $("excludedNote");
  if (!el) return;
  if (!effectiveNoTitle() || effectiveDropdown()) { el.style.display = "none"; el.innerHTML = ""; return; }
  const titles = titleSongsForWord(currentWord, effectiveStrict()).map((s) => s.title);
  if (!titles.length) { el.style.display = "none"; el.innerHTML = ""; return; }
  const SHOWN = 3;
  const shown = titles.slice(0, SHOWN)
    .map((t) => `<span class="ex-title">${escapeHtml(censor(t))}</span>`);
  if (titles.length > SHOWN) shown.push(`<span class="ex-more">+${titles.length - SHOWN} more</span>`);
  const lead = titles.length === 1 ? "can’t be played — it’s in the title" : "can’t be played — they’re in the title";
  el.innerHTML = `<span class="ex-lead">${lead}</span>${shown.join("")}`;
  el.style.display = "";
}
function extractLineWithWord(lyrics, word, strict) {
  if (strict === undefined) strict = effectiveStrict();
  return extractLineWithWordCore(lyrics, word, strict);
}
// Mask explicit words for display. The racial slur is always masked; general
// profanity only when the player turns on "censor explicit words". The prompt word
// itself is never explicit (the one near-miss, "damn", is left uncensored), so
// masking a line never touches the word we go on to highlight. See censorText (util.js).
function censor(text) { return censorText(text, settings.censorExplicit === true); }
function highlightWord(line, word, strict) {
  if (strict === undefined) strict = effectiveStrict();
  return highlightWordCore(censor(line), word, strict);
}
// The variant the line actually credits when it holds a *form* of the prompt word rather than
// the word itself ("pray" → "praying"), or "" when the line has the word verbatim (or when
// strict matching is on, where forms never count). Mirrors highlightWord's own exact-first
// rule, so a non-empty answer here is precisely what the card's <mark> is wrapping.
function matchedVariant(line, word) {
  if (effectiveStrict()) return "";
  if (new RegExp("\\b" + escapeRegExp(word) + "\\b", "i").test(line)) return "";
  const m = line.match(new RegExp("\\b(" + wordVariants(word).join("|") + ")\\b", "i"));
  return m ? m[1] : "";
}

/* ---------- Stats ---------- */
// Collated view across every difficulty: summed plays / score distribution, the best
// score of any mode, and the best correct-in-a-row reached in any mode.
function aggregateStats() {
  const agg = { played: 0, totalScore: 0, best: 0, bestInRow: 0, scoreCounts: [] };
  for (const m of MODE_ORDER) {
    const s = loadStats(m);
    agg.played += s.played;
    agg.totalScore += s.totalScore;
    agg.best = Math.max(agg.best, s.best);
    agg.bestInRow = Math.max(agg.bestInRow, s.bestInRow || 0);
    s.scoreCounts.forEach((c, i) => { agg.scoreCounts[i] = (agg.scoreCounts[i] || 0) + c; });
  }
  return agg;
}
// Resolve the Stats tab to open first from the saved preference: "all", "last"
// (the active difficulty), or a specific mode id.
function defaultStatsView() {
  const d = settings.defaultStatsTab;
  if (d === "all") return "all";
  if (d && d !== "last" && MODES[d]) return d;
  return currentMode.id;
}
// Recent run scores for the "recent form" sparkline (oldest→newest, capped).
// All tab = every classic run; a mode tab = that mode's runs. Daily/Infinite use
// different score scales, so they're excluded — the same scope as the All
// histogram, which sums only the classic difficulty boards.
function recentScores(viewMode, cap = 12) {
  const picked = loadHistory().filter((e) =>
    viewMode === "all" ? e.t === "classic" : e.m === viewMode);
  return picked.slice(0, cap).map((e) => e.s).reverse();
}
// Rolling "forgiving form" average — the mean score of the last `cap` games for
// this view (TypeRacer-style, so a bad month stops haunting the number). Same
// scope as recentScores/the histogram (All = classic runs, a mode tab = that
// mode); includes hinted runs, which is fine for recent *form*. Returns the
// average and the actual sample size (< cap when there aren't `cap` games yet),
// so the label can read "last 8" honestly instead of padding.
function recentAverage(viewMode, cap = 20) {
  const picked = loadHistory().filter((e) =>
    viewMode === "all" ? e.t === "classic" : e.m === viewMode);
  const window = picked.slice(0, cap);
  const n = window.length;
  if (n === 0) return { avg: null, n: 0 };
  return { avg: window.reduce((a, e) => a + e.s, 0) / n, n };
}
// A small hand-inked sparkline of recent scores (0–TOTAL_ROUNDS), with a dotted
// baseline at the window's average and a filled dot on the latest game.
function sparklineSVG(scores) {
  const W = 360, H = 40, pad = 6, top = 6, bot = 34, n = scores.length;
  const x = (i) => n === 1 ? W / 2 : pad + (i * (W - pad * 2)) / (n - 1);
  const y = (v) => bot - (Math.min(v, TOTAL_ROUNDS) / TOTAL_ROUNDS) * (bot - top);
  const pts = scores.map((v, i) => `${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(" ");
  const avg = scores.reduce((a, b) => a + b, 0) / n;
  const ay = y(avg).toFixed(1), lx = x(n - 1).toFixed(1), ly = y(scores[n - 1]).toFixed(1);
  return `<svg class="form-spark" viewBox="0 0 ${W} ${H}" width="100%" height="${H}" preserveAspectRatio="none" aria-hidden="true">
    <line x1="0" y1="${ay}" x2="${W}" y2="${ay}" class="form-base"/>
    <polyline points="${pts}" class="form-line"/>
    <circle cx="${lx}" cy="${ly}" r="3.6" class="form-dot"/>
  </svg>`;
}
// Last difficulty viewed under the Classic tier this session — so re-clicking
// "Classic" (after a detour through All/Infinite) returns there, not to the
// active play mode. Falls back to currentMode.id until a difficulty is opened.
let lastStatsDifficulty = null;
// A zero-data screen's teaching copy tells the player to go play; this small ghost-button lets
// them do it, landing on the start screen's "Start writing" launchpad in one tap. Shared by every
// empty state so the affordance reads the same everywhere.
function playCTA(label = "start writing") {
  return `<button type="button" class="empty-cta" data-go-play>${label} →</button>`;
}
function renderStats(lastScore, viewMode = defaultStatsView()) {
  const el = $("statsBody");
  // "classic" is a tier-1 selector, not a real view — resolve it to a difficulty.
  if (viewMode === "classic") viewMode = lastStatsDifficulty || currentMode.id;
  const isAll = viewMode === "all";
  const isInf = viewMode === "infinite";
  const isAdaptive = viewMode === "adaptive";
  const isClassic = !isAll && !isInf && !isAdaptive; // a difficulty mode id
  if (isClassic) lastStatsDifficulty = viewMode;
  // Two-tier tabs (mirrors the start screen). Tier 1 = view / game type:
  // All · Classic · Infinite · Adaptive. Tier 2 = difficulty, shown only under Classic.
  const tier1 = `<div class="mode-tabs stats-tabs">` +
    `<button type="button" class="mode-tab${isAll ? " active" : ""}" data-statmode="all">All</button>` +
    `<button type="button" class="mode-tab${isClassic ? " active" : ""}" data-statmode="classic">Classic</button>` +
    `<button type="button" class="mode-tab mode-tab--inf${isInf ? " active" : ""}" data-statmode="infinite">${INF_GLYPH}Infinite</button>` +
    `<button type="button" class="mode-tab${isAdaptive ? " active" : ""}" data-statmode="adaptive">Adaptive</button>` +
    `</div>`;
  const tier2 = isClassic
    ? `<div class="mode-tabs stats-subtabs">` + MODE_ORDER.map((m) =>
        `<button type="button" class="mode-tab${m === viewMode ? " active" : ""}" data-statmode="${m}">${MODES[m].label}</button>`
      ).join("") + `</div>`
    : "";
  const tabs = tier1 + tier2;

  // Infinite is its own game type — its own headline + ledger, not the 0–13 histogram.
  if (isInf) {
    el.innerHTML = tabs + infiniteTabHTML();
    el.querySelectorAll("[data-statmode]").forEach((b) =>
      b.addEventListener("click", () => renderStats(lastScore, b.dataset.statmode)));
    return;
  }

  // Adaptive is its own game type too — ranked on the peak level reached, not a 0–13 score.
  if (isAdaptive) {
    el.innerHTML = tabs + adaptiveTabHTML();
    el.querySelectorAll("[data-statmode]").forEach((b) =>
      b.addEventListener("click", () => renderStats(lastScore, b.dataset.statmode)));
    return;
  }

  const s = isAll ? aggregateStats() : loadStats(viewMode);
  let body;
  if (s.played === 0) {
    body = (isAll
      ? `<p class="stats-empty">no games yet — start writing!</p>`
      : `<p class="stats-empty">no games yet in ${MODES[viewMode].label} — start writing!</p>`) + playCTA();
  } else {
    const avg = (s.totalScore / s.played).toFixed(1);
    const maxCount = Math.max(...s.scoreCounts, 1);
    // highlight the just-played bar on the mode that was played (and always in the All view)
    const youScore = (isAll || viewMode === currentMode.id) ? lastScore : null;
    const bars = s.scoreCounts.map((count, score) => {
      const h = Math.round((count / maxCount) * 56);
      const isYou = (score === youScore);
      const tip = `scored ${score}/${TOTAL_ROUNDS} · ${count} time${count === 1 ? "" : "s"}`;
      return `<div class="histogram-col" data-tip="${tip}">
        <div class="histogram-bar${isYou ? " has-you" : ""}" style="height:${Math.max(h, count > 0 ? 4 : 2)}px"></div>
        <div class="histogram-score">${score}</div>
      </div>`;
    }).join("");
    // Best correct-in-a-row (lifetime, per mode; max across modes in the All view) +
    // perfect-game count. Same two cells for every tab.
    // "By the numbers" header (design E): three primaries on top, then a
    // recent-form sparkline beside the secondary stats (best-in-a-row, perfect).
    const recent = recentScores(viewMode);
    const formPanel = recent.length >= 2
      ? sparklineSVG(recent)
      : `<span class="statE-form-empty">— more games will draw your form —</span>`;
    const star = `<span class="statE-star">${STAR_SVG}</span>`;
    // Rolling "forgiving form" — last-20 average, sitting beside the lifetime
    // best/average so a gentle current number reads against the aspirational one.
    const form = recentAverage(viewMode);
    const formChip = form.avg === null
      ? `<div class="statE-cell"><span class="statE-val statE-accent">–</span><span class="statE-lbl">Recent</span></div>`
      : `<div class="statE-cell"><span class="statE-val statE-accent">${form.avg.toFixed(1)}</span><span class="statE-lbl">Last ${form.n}</span></div>`;
    body = `
      <div class="statE-top">
        <div class="statE-cell"><span class="statE-val">${s.played}</span><span class="statE-lbl">Played</span></div>
        <div class="statE-cell"><span class="statE-val statE-best">${s.best}</span>${star}<span class="statE-lbl">Best</span></div>
        <div class="statE-cell"><span class="statE-val">${avg}</span><span class="statE-lbl">Average</span></div>
      </div>
      <div class="statE-form">
        <div class="statE-form-spark">
          <span class="statE-lbl statE-form-lbl">recent form${recent.length >= 2 ? " · last " + recent.length : ""}</span>
          ${formPanel}
        </div>
        <div class="statE-chips">
          ${formChip}
          <div class="statE-cell"><span class="statE-val statE-accent">${s.bestInRow || 0}</span><span class="statE-lbl">In a row</span></div>
          <div class="statE-cell"><span class="statE-val statE-accent">${s.scoreCounts[TOTAL_ROUNDS] || 0}</span>${star}<span class="statE-lbl">Perfect</span></div>
        </div>
      </div>
      <p class="histogram-label">score distribution</p>
      <div class="histogram">${bars}</div>`;
  }

  // Catalogue, lifetime numbers + daily streak are lifetime summaries — All tab only.
  if (isAll) body += extraStatsHTML() + lifetimeStatsHTML() + dailyStatsHTML();
  el.innerHTML = tabs + body;
  el.querySelectorAll("[data-statmode]").forEach((b) =>
    b.addEventListener("click", () => renderStats(lastScore, b.dataset.statmode)));
  el.querySelectorAll("[data-open-songbook]").forEach((b) =>
    b.addEventListener("click", () => openSongbook(b.dataset.openSongbook)));
}

// Highest-count entry of a {key: count} map (first one wins ties), or null if empty.
function topTallyEntry(obj) {
  let bestK = null, bestV = 0;
  for (const k in obj) if (obj[k] > bestV) { bestV = obj[k]; bestK = k; }
  return bestK === null ? null : { key: bestK, count: bestV };
}
// Exact-title → album lookup for the lifetime tally (tally keys are song.title).
function albumOfTitle(title) {
  const s = allSongs.find((x) => x.title === title);
  return s ? (s.album || null) : null;
}

// Display name for an album — long titles that overflow the keepsake cards get a
// short form (e.g. "The Tortured Poets Department" → "TTPD").
function albumDisplayName(name) {
  return name === "The Tortured Poets Department" ? "TTPD" : name;
}

// Lifetime catalogue stats — global (not per-mode), drawn from the per-song/per-word
// tally written in endGame. Shows under every Stats tab, like the daily streak.
// Three zones: a hero "songs discovered" meter (filled portion split into album-colour
// segments), two album-tinted keepsake cards, and a red-pen-circled nemesis word.
function lifetimeStatsHTML() {
  const t = loadSongTally();
  const m = loadMetrics();
  const discoveredTitles = Object.keys(t.songs);
  const discovered = discoveredTitles.length;
  const total = allSongs.length || 1;
  const favSong = topTallyEntry(t.songs);
  const favAlbum = topTallyEntry(t.albums);
  const nemesis = topTallyEntry(t.misses);
  const header = `<p class="histogram-label" style="margin-top:24px;">your catalogue</p>`;
  if (!discovered && !nemesis) {
    return header + `<p class="stats-empty">no answers logged yet — play a game to start your catalogue!</p>`;
  }
  // Floor, not round — 243/244 must read 99%, never a misleading 100% before completion.
  const pct = Math.floor((discovered / total) * 100);

  // Distinct discovered songs per album → album-rainbow meter segments, drawn in the
  // chronological album order songs appear in allSongs (covers any pseudo-albums too).
  const byAlbum = {};
  for (const title of discoveredTitles) {
    const a = albumOfTitle(title);
    if (a) byAlbum[a] = (byAlbum[a] || 0) + 1;
  }
  const albumOrder = [];
  for (const s of allSongs) if (s.album && !albumOrder.includes(s.album)) albumOrder.push(s.album);
  const segs = albumOrder.filter((a) => byAlbum[a]).map((a) =>
    `<div class="cat-seg" style="width:${(byAlbum[a] / total) * 100}%;background:${albumColor(a) || "var(--ink-soft)"}" title="${escapeHtml(a)}: ${byAlbum[a]}"></div>`
  ).join("");

  const songColor = favSong ? (albumColor(albumOfTitle(favSong.key)) || "var(--bead)") : "var(--bead)";
  const songAlbum = favSong ? albumOfTitle(favSong.key) : null;
  const albColor = favAlbum ? (albumColor(favAlbum.key) || "var(--ink-soft)") : "var(--ink-soft)";

  // The meter doubles as the door into the songbook (the missing-songs checklist that
  // backs the "I Hate It Here" charm) — same tally, drilled into per-album detail.
  const remaining = total - discovered;
  const meter = `
    <button type="button" class="cat-meter cat-meter--btn" data-open-songbook="stats">
      <div class="cat-meter-head"><span>songs discovered</span><span>${pct}%</span></div>
      <div class="cat-meter-num"><b>${discovered}</b> / ${total} songs</div>
      <div class="cat-bar">${segs}</div>
      <div class="cat-meter-cta">${remaining > 0 ? remaining + " still to find" : "every song found ★"} <span aria-hidden="true">→</span></div>
    </button>`;

  // Words discovered — distinct prompt words answered correctly, out of the playable set.
  const wordsFound = Object.keys(t.words || {}).length;
  const wordTotal = playableWords.length || 1;
  const wordPct = Math.floor((wordsFound / wordTotal) * 100);
  const wordMeter = `
    <div class="cat-meter">
      <div class="cat-meter-head"><span>words discovered</span><span>${wordPct}%</span></div>
      <div class="cat-meter-num"><b>${wordsFound}</b> / ${wordTotal} words</div>
      <div class="cat-bar"><div class="cat-seg" style="width:${(wordsFound / wordTotal) * 100}%;background:var(--ink-accent)"></div></div>
    </div>`;

  const songCard = `
    <div class="cat-card" style="border-left-color:${songColor}">
      <div class="cat-card-head"><span class="cat-star">${STAR_SVG}</span>favourite song</div>
      <div class="cat-card-val">${favSong ? escapeHtml(censor(favSong.key)) : "—"}</div>
      <div class="cat-card-sub" style="color:${songColor}">${favSong ? (songAlbum ? escapeHtml(albumDisplayName(songAlbum)) + " · " : "") + "sung ×" + favSong.count : "play a game"}</div>
    </div>`;
  const albumCard = `
    <div class="cat-card" style="border-left-color:${albColor}">
      <div class="cat-card-head"><span class="cat-dot" style="background:${albColor}"></span>favourite album</div>
      <div class="cat-card-val">${favAlbum ? escapeHtml(albumDisplayName(favAlbum.key)) : "—"}</div>
      <div class="cat-card-sub" style="color:${albColor}">${favAlbum ? "×" + favAlbum.count + " correct" : "play a game"}</div>
    </div>`;

  // The nemesis word is a real prompt word, so it deep-links straight into the lyric
  // searcher — one click to see every song that holds the word you keep missing.
  const nemesisSub = nemesis
    ? `missed ×${nemesis.count} · <a class="cat-search-link" href="search/#q=${encodeURIComponent(nemesis.key)}" title="See every song with “${escapeHtml(nemesis.key)}” in the lyric searcher">look it up →</a>`
    : "no misses yet";
  const nemesisBlock = `
    <div class="cat-nemesis">
      <div>
        <div class="cat-card-head">nemesis word</div>
        <div class="cat-nemesis-sub">${nemesisSub}</div>
      </div>
      <div class="cat-nemesis-word">
        <span>${nemesis ? escapeHtml(nemesis.key) : "—"}</span>
        <svg viewBox="0 0 160 60" preserveAspectRatio="none" aria-hidden="true">
          <path d="M18 30 C18 12, 60 8, 90 10 C130 13, 152 22, 150 34 C148 48, 100 54, 64 52 C28 50, 12 42, 16 28" fill="none" stroke="rgba(178,58,58,0.7)" stroke-width="2.2" stroke-linecap="round"/>
        </svg>
      </div>
    </div>`;

  // "From memory" — the verse-bonus prestige tally (lyric lines recalled, word-perfect ones).
  // Paired beside the nemesis word so neither owns a whole row.
  const lines = m.lyricLines || 0;
  const perfect = m.versePerfect || 0;
  const fromMemoryBlock = `
    <div class="cat-frommemory">
      <div class="cat-card-head"><span class="cat-star">${STAR_SVG}</span>from memory</div>
      <div class="cat-fm-val">${lines}</div>
      <div class="cat-fm-sub">${lines ? "lines written · " + perfect + " word-perfect" : "write a lyric line"}</div>
    </div>`;

  return header + `<div class="cat-wrap">${meter}${wordMeter}<div class="cat-cards">${songCard}${albumCard}</div><div class="cat-pair">${fromMemoryBlock}${nemesisBlock}</div></div>`;
}

// Daily-challenge streak — global (not per-mode), so it shows under every tab.
// --- Hand-inked marker marks for the daily calendar ---------------------------
// Each X/O is a one-off: drawn from pressure-tapered ribbon strokes (fat-marker
// profile — near-uniform body, blunt rounded tips) with per-mark jitter, so no two
// look stamped. Rendered as inline SVG strings (the Stats body is set via innerHTML),
// re-randomised on every renderStats call. multiply blend makes the X's crossing and
// the O's self-overlap bleed darker, like wet ink. See CLAUDE.md "daily calendar".
const MARK_REDS = ["#c0352b", "#b62f27", "#c43d31", "#aa2c25"];
const MARK_GREENS = ["#2f6d4f", "#356f4a", "#2b6044"];
const mRand = (a, b) => a + Math.random() * (b - a);
const mPick = (arr) => arr[Math.floor(Math.random() * arr.length)];

// Centerline → filled ribbon path (+ rounded tip circles). wmax = full body width.
function markerRibbon(pts, wmax) {
  const N = pts.length - 1, left = [], right = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const shape = Math.pow(Math.sin(Math.PI * t), 0.32);   // flat-topped: blunt ends
    const w = wmax * (0.78 + 0.22 * shape);
    const p0 = pts[Math.max(0, i - 1)], p1 = pts[Math.min(N, i + 1)];
    const tx = p1[0] - p0[0], ty = p1[1] - p0[1], tl = Math.hypot(tx, ty) || 1;
    const nx = -ty / tl, ny = tx / tl;
    left.push([pts[i][0] + nx * w / 2, pts[i][1] + ny * w / 2]);
    right.push([pts[i][0] - nx * w / 2, pts[i][1] - ny * w / 2]);
  }
  let d = "M " + left[0][0].toFixed(2) + " " + left[0][1].toFixed(2);
  for (let i = 1; i <= N; i++) d += " L " + left[i][0].toFixed(2) + " " + left[i][1].toFixed(2);
  for (let i = N; i >= 0; i--) d += " L " + right[i][0].toFixed(2) + " " + right[i][1].toFixed(2);
  return { d: d + " Z", a: pts[0], b: pts[N], r: wmax * 0.39 };
}

// One marker stroke: a single smooth arc (wrist pivot) with overshoot + soft lift.
function markerSlash(a, b, bow, hook) {
  const dx = b[0] - a[0], dy = b[1] - a[1], len = Math.hypot(dx, dy) || 1;
  const ux = dx / len, uy = dy / len, nx = -uy, ny = ux;
  const os = len * mRand(0.02, 0.06);
  const A = [a[0] - ux * os, a[1] - uy * os], B = [b[0] + ux * os, b[1] + uy * os];
  const cx = (A[0] + B[0]) / 2 + nx * bow, cy = (A[1] + B[1]) / 2 + ny * bow;
  const N = 24, pts = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N, mt = 1 - t;
    pts.push([mt * mt * A[0] + 2 * mt * t * cx + t * t * B[0], mt * mt * A[1] + 2 * mt * t * cy + t * t * B[1]]);
  }
  if (hook) {
    const K = 4, piv = pts[N - K], cs = Math.cos(hook), sn = Math.sin(hook);
    for (let i = N - K + 1; i <= N; i++) {
      const vx = pts[i][0] - piv[0], vy = pts[i][1] - piv[1];
      pts[i] = [piv[0] + vx * cs - vy * sn, piv[1] + vx * sn + vy * cs];
    }
  }
  return pts;
}

function ribbonSVG(rib, col, op) {
  const o = op.toFixed(2), cap = (p) =>
    `<circle cx="${p[0].toFixed(2)}" cy="${p[1].toFixed(2)}" r="${rib.r.toFixed(2)}" fill="${col}" opacity="${o}" style="mix-blend-mode:multiply"/>`;
  return `<path d="${rib.d}" fill="${col}" opacity="${o}" stroke-linejoin="round" style="mix-blend-mode:multiply"/>` + cap(rib.a) + cap(rib.b);
}

function markerX(s) {
  const col = mPick(MARK_REDS), w = s * mRand(0.12, 0.155), op = mRand(0.8, 0.9);
  const pad = s * mRand(0.18, 0.23), off = mRand(-s * 0.05, s * 0.05);
  const j = (v) => v + mRand(-s * 0.04, s * 0.04);
  const s1 = markerSlash([j(pad), j(pad)], [j(s - pad), j(s - pad)], mRand(-s * 0.06, s * 0.06), mRand(0.05, 0.22) * mPick([1, -1]));
  const s2 = markerSlash([j(s - pad) + off, j(pad)], [j(pad) + off, j(s - pad)], mRand(-s * 0.06, s * 0.06), mRand(0.05, 0.22) * mPick([1, -1]));
  const inner = ribbonSVG(markerRibbon(s1, w), col, op) + ribbonSVG(markerRibbon(s2, w * mRand(0.94, 1.06)), col, op);
  return `<svg class="cal-mark" viewBox="0 0 ${s} ${s}" style="transform:rotate(${mRand(-11, 11).toFixed(1)}deg)">${inner}</svg>`;
}

function markerO(s) {
  const col = mPick(MARK_GREENS), w = s * mRand(0.11, 0.14), op = mRand(0.8, 0.9);
  const cx = s / 2 + mRand(-s * 0.03, s * 0.03), cy = s / 2 + mRand(-s * 0.03, s * 0.03);
  const rx = s * mRand(0.32, 0.37), ry = s * mRand(0.31, 0.36);
  const tilt = mRand(-0.3, 0.3), ct = Math.cos(tilt), st = Math.sin(tilt);
  const start = mRand(-2.6, -1.6), sweep = Math.PI * 2 * mRand(1.05, 1.13), ph = mRand(0, 6.28);
  const N = 60, pts = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N, a = start + sweep * t, wob = 1 + 0.022 * Math.sin(a * 2 + ph);
    const x = Math.cos(a) * rx * wob, y = Math.sin(a) * ry * wob;
    pts.push([cx + x * ct - y * st, cy + x * st + y * ct]);
  }
  return `<svg class="cal-mark" viewBox="0 0 ${s} ${s}" style="transform:rotate(${mRand(-9, 9).toFixed(1)}deg)">${ribbonSVG(markerRibbon(pts, w), col, op)}</svg>`;
}

const MONTH_NAMES = ["January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"];

// The current month as a notebook calendar: today ringed in green marker, every
// completed-daily day struck out with a unique red marker X. Month/today come from
// todayKey() (active timezone); the crossed-off set from dailyPlayedDates().
function dailyCalendarHTML() {
  const today = todayKey();                       // YYYY-MM-DD in the active zone
  const [yy, mm, dd] = today.split("-").map(Number);
  const monthIdx = mm - 1;
  const daysInMonth = new Date(Date.UTC(yy, mm, 0)).getUTCDate();
  const firstDow = new Date(Date.UTC(yy, monthIdx, 1)).getUTCDay();   // 0 = Sunday
  const pad2 = (n) => String(n).padStart(2, "0");
  const monthPrefix = `${yy}-${pad2(mm)}-`;
  const played = dailyPlayedDates();

  let cells = "";
  for (let i = 0; i < firstDow; i++) cells += `<div class="cal-cell cal-blank"></div>`;
  for (let day = 1; day <= daysInMonth; day++) {
    const isToday = day === dd, done = played[monthPrefix + pad2(day)] != null;
    let ink = "";
    if (isToday) ink += markerO(30);
    if (done) ink += markerX(30);
    const cls = "cal-cell" + (day > dd ? " cal-future" : "") + (isToday ? " cal-today" : "");
    cells += `<div class="${cls}"><span class="cal-num">${day}</span><span class="cal-ink">${ink}</span></div>`;
  }
  const dows = ["S", "M", "T", "W", "T", "F", "S"].map((x) => `<div class="cal-dow">${x}</div>`).join("");
  return `<div class="daily-cal">` +
    `<div class="cal-head"><span class="cal-month">${MONTH_NAMES[monthIdx]}</span><span class="cal-year">${yy}</span></div>` +
    `<div class="cal-grid cal-dows">${dows}</div>` +
    `<div class="cal-grid cal-days">${cells}</div>` +
    `</div>`;
}

function dailyStatsHTML() {
  const d = effectiveDailyStreak(todayKey());
  const cal = dailyCalendarHTML();
  const head = `<p class="histogram-label" style="margin-top:24px;">daily challenge</p>`;
  if (!d.lastPlayed) {
    return head + cal + `<p class="stats-empty">no daily runs yet — try today's Daily Challenge!</p>`;
  }
  const note = d.playedToday
    ? `<p class="daily-streak-note">✓ played today's challenge</p>`
    : `<p class="daily-streak-note">today's challenge awaits</p>`;
  return head +
    `<div class="streak-row">` +
    `<div class="streak-cell"><span class="stat-val">🔥 ${d.current}</span><span class="stat-lbl">day streak</span></div>` +
    `<div class="streak-cell"><span class="stat-val">${d.best}</span><span class="stat-lbl">best streak</span></div>` +
    `</div>` + note + cal;
}

// Lifetime cross-game numbers — global (All tab only, like the catalogue). Drawn from
// the metrics store folded in endGame and the song tally. A notebook bento: an accuracy
// ring + album-spine meter up top, a row of quick-stat tiles, a daily footer. Empty
// until the first finished game. ("Best streak ever" lives in the per-tab block above —
// it's the same bestInRow value, so it isn't repeated here.)
// Tiny ink marginalia icons (18×18, stroked in currentColor).
const NUM_ICONS = {
  rounds:  `<svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"><path d="M5 3h5l3 3v9H5z"/><path d="M10 3v3h3"/></svg>`,
  bolt:    `<svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"><path d="M10.5 2L4.5 10H8l-.8 6 6.3-9H10z"/></svg>`,
  clock:   `<svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.4"><circle cx="9" cy="9" r="6.4"/><path d="M9 5v4.2l2.8 1.8" stroke-linecap="round"/></svg>`,
  lines:   `<svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"><path d="M3.5 6h11M3.5 9h11M3.5 12h7"/></svg>`,
  cal:     `<svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"><rect x="3" y="4.2" width="12" height="10.8" rx="1.2"/><path d="M3 7.4h12M6 2.6v2.6M12 2.6v2.6"/></svg>`,
  rosette: `<svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"><circle cx="9" cy="9" r="6.4"/><path d="M9 5.4l1 2.1 2.3.2-1.7 1.5.5 2.3L9 10.5 6.9 11.7l.5-2.3L5.7 7.7 8 7.5z"/></svg>`,
};

const RING_CIRC = 2 * Math.PI * 52;   // accuracy ring: r=52 in a 120×120 viewBox

function extraStatsHTML() {
  const m = loadMetrics();
  if (m.roundsTotal === 0) return "";
  const t = loadSongTally();
  const dt = dailyTotals();   // authoritative daily counts (per-day keys, not the metrics store)
  const secs = (ms) => (ms / 1000).toFixed(1) + "s";
  const fastest = m.fastestMs != null ? secs(m.fastestMs) : "—";
  const avg = m.answerN ? secs(m.answerSumMs / m.answerN) : "—";
  const accPct = m.roundsTotal ? Math.round((m.roundsCorrect / m.roundsTotal) * 100) : 0;
  const ringOffset = RING_CIRC * (1 - accPct / 100);

  // Album-spine meter: one bar per album in chronological catalogue order, lit in its
  // album colour once any of its songs has been answered, faint until then.
  const albumOrder = [];
  for (const s of allSongs) if (s.album && !albumOrder.includes(s.album)) albumOrder.push(s.album);
  const albumsTotal = albumOrder.length || 1;
  const albumsCollected = albumOrder.filter((a) => (t.albums || {})[a] > 0).length;
  const spines = albumOrder.map((a) => {
    const got = ((t.albums || {})[a] || 0) > 0;
    const c = got ? (albumColor(a) || "var(--ink-soft)") : "rgba(43,39,34,0.13)";
    return `<div class="num-spine" style="background:${c}" title="${escapeHtml(a)}"></div>`;
  }).join("");

  const tile = (icon, label, value) =>
    `<div class="num-card num-tile"><span class="num-ico">${NUM_ICONS[icon]}</span>` +
    `<span class="num-val">${value}</span><span class="num-sub">${label}</span></div>`;

  return `<p class="histogram-label" style="margin-top:24px;">by the numbers</p>
    <div class="num-hero-row">
      <div class="num-card num-acc">
        <div class="num-ring">
          <svg viewBox="0 0 120 120" aria-hidden="true">
            <circle class="num-ring-track" cx="60" cy="60" r="52"/>
            <circle class="num-ring-arc" cx="60" cy="60" r="52" transform="rotate(-90 60 60)"
              stroke-dasharray="${RING_CIRC.toFixed(1)}" stroke-dashoffset="${ringOffset.toFixed(1)}"/>
          </svg>
          <div class="num-ring-val"><b>${accPct}</b><span>%</span></div>
        </div>
        <div>
          <div class="num-lbl">Accuracy</div>
          <div class="num-sub">${m.roundsCorrect} of ${m.roundsTotal}<br>rounds right</div>
        </div>
      </div>
      <div class="num-card num-albums">
        <div class="num-albums-head">
          <span class="num-lbl">Albums collected</span>
          <span class="num-count">${albumsCollected}<i> / ${albumsTotal}</i></span>
        </div>
        <div class="num-spines">${spines}</div>
      </div>
    </div>
    <div class="num-tiles">
      ${tile("rounds", "Rounds played", m.roundsTotal)}
      ${tile("bolt", "Fastest", fastest)}
      ${tile("clock", "Avg time", avg)}
      ${tile("lines", "Lyric lines", m.lyricLines)}
    </div>
    <div class="num-card num-daily">
      <div class="num-daily-item">
        <span class="num-ico num-ico-lg">${NUM_ICONS.cal}</span>
        <div><div class="num-val num-val-md">${dt.played}</div><div class="num-sub">Daily challenges</div></div>
      </div>
      <div class="num-daily-div"></div>
      <div class="num-daily-item">
        <span class="num-ico num-ico-lg num-ico-gold">${NUM_ICONS.rosette}</span>
        <div><div class="num-val num-val-md num-gold">${dt.perfect}</div><div class="num-sub">Daily perfects</div></div>
      </div>
    </div>`;
}

// Infinite runs aren't comparable to the 13-round game (scores can exceed 13 and
// the 0–13 histogram is meaningless), so the Infinite tab gets its own body: a
// pen-circled headline (your single longest run + where it came from) and a ruled
// LEDGER — difficulty down the side, the two lives-variants across the top, each cell
// the best run + games played. No relative-fill bar (it was meaningless); the number
// carries it, the ruling does the structure, and a red-pen ellipse marks the all-time
// best. Colour-coded by variant — gold for forgiving 3-lives, danger-red for sudden death.
const INF_VARIANT_STYLE = {
  "3lives": { color: "#c08a2e", beads: 3 },
  sudden:   { color: "#b23a3a", beads: 1 },
};
function infiniteTabHTML() {
  const entries = [];
  for (const variant of ["3lives", "sudden"]) {
    for (const m of MODE_ORDER) {
      const st = loadStats("inf-" + variant + "-" + m);
      if (st.played > 0) entries.push({ variant, mode: m, best: st.best, played: st.played });
    }
  }
  if (!entries.length) {
    return `<p class="stats-empty">no infinite runs yet — try Infinite mode!</p>`;
  }
  // headline = the single longest run across every combo, + total infinite games played
  let top = entries[0], totalGames = 0;
  for (const e of entries) { totalGames += e.played; if (e.best > top.best) top = e; }
  const hero = `
    <div class="inf-hero">
      <div class="inf-medallion">
        <b>${top.best}</b><span>rounds</span>
      </div>
      <div class="inf-hero-text">
        <div class="inf-hero-title">your longest run</div>
        <div class="inf-hero-sub">${VARIANT_LABELS[top.variant]} · ${MODES[top.mode].label}</div>
      </div>
    </div>`;
  // ledger: a cell per variant×difficulty; unplayed = a faint dash; the best one is circled
  const cell = (variant, m) => {
    const e = entries.find((x) => x.variant === variant && x.mode === m);
    if (!e) return `<td class="inf-cell inf-cell--empty">–</td>`;
    const circ = (e === top)
      ? `<svg class="inf-circle" viewBox="0 0 90 50" aria-hidden="true"><ellipse cx="45" cy="25" rx="40" ry="20" fill="none" stroke="#b23a3a" stroke-width="1.6"/></svg>`
      : "";
    return `<td class="inf-cell">${circ}<span class="inf-cell-num" style="color:${INF_VARIANT_STYLE[variant].color}">${e.best}</span><span class="inf-cell-sub">${e.played} game${e.played === 1 ? "" : "s"}</span></td>`;
  };
  const colHead = (variant) => {
    const sty = INF_VARIANT_STYLE[variant];
    const beads = Array.from({ length: sty.beads }, () => `<i style="background:${sty.color}"></i>`).join("");
    return `<th><span class="inf-th-beads">${beads}</span>${VARIANT_LABELS[variant]}</th>`;
  };
  const rows = MODE_ORDER.map((m) =>
    `<tr><th class="inf-row-h">${MODES[m].label}</th>${cell("3lives", m)}${cell("sudden", m)}</tr>`
  ).join("");
  return hero +
    `<table class="inf-ledger"><thead><tr><th></th>${colHead("3lives")}${colHead("sudden")}</tr></thead>` +
    `<tbody>${rows}</tbody></table>` +
    `<p class="inf-foot">${totalGames} infinite game${totalGames === 1 ? "" : "s"} played · the circle marks your all-time best</p>`;
}

// Adaptive stats: the headline is the highest level ever reached (the board metric),
// with the four-rung ladder shown so the player can see where they've topped out.
function adaptiveTabHTML() {
  const rec = adaptiveRecord();
  if (!rec.played) {
    return `<p class="stats-empty">no adaptive runs yet — try Adaptive mode!</p>`;
  }
  const peakName = ADAPTIVE_LEVELS[rec.bestPeak] || "";
  const hero = `
    <div class="inf-hero">
      <div class="inf-medallion">
        <b>${rec.bestPeak}</b><span>level</span>
      </div>
      <div class="inf-hero-text">
        <div class="inf-hero-title">highest you've climbed</div>
        <div class="inf-hero-sub">${escapeHtml(peakName)} · ${rec.bestScore}/${TOTAL_ROUNDS} that run</div>
      </div>
    </div>`;
  // The ladder: each rung lit up to the best peak, the top one circled.
  const rungs = [];
  for (let lvl = ADAPT_MAX_LEVEL; lvl >= 1; lvl--) {
    const reached = lvl <= rec.bestPeak;
    const top = lvl === rec.bestPeak;
    rungs.push(
      `<tr class="adapt-rung${reached ? " reached" : ""}${top ? " peak" : ""}">` +
      `<th class="adapt-rung-lvl">L${lvl}</th>` +
      `<td class="adapt-rung-name">${escapeHtml(ADAPTIVE_LEVELS[lvl] || "")}</td>` +
      `<td class="adapt-rung-mark">${top ? "★ your peak" : reached ? "reached" : "—"}</td></tr>`
    );
  }
  return hero +
    `<table class="adapt-ladder"><tbody>${rungs.join("")}</tbody></table>` +
    `<p class="inf-foot">${rec.played} adaptive game${rec.played === 1 ? "" : "s"} played · ranked on the level you reach, not your score</p>`;
}

/* ---------- Achievements ---------- */
let earnedAchievements = {};   // persisted: { id: "YYYY-MM-DD" }
let newlyUnlocked = [];        // ids unlocked this game (for the results recap)
let lastSkillFold = null;      // { delta, res } from this game's foldSkillXp — the results skills recap

function charmMarkup(icon, color) {
  const style = color ? ` style="--bead:${color}"` : "";
  return `<span class="charm" aria-hidden="true"${style}>${ACH_ICONS[icon]}</span>`;
}

// The same markup for a Mastery mark, drawn from the mastery-only MASTERY_ICONS namespace
// rather than the achievement charm set. Every mastery surface — the ascent track, the reward
// tiles, the title medallions, the skill emblems — goes through here, so a mark can be redrawn
// for Mastery without a single achievement changing.
function masteryMarkup(icon, color) {
  const style = color ? ` style="--bead:${color}"` : "";
  return `<span class="charm" aria-hidden="true"${style}>${MASTERY_ICONS[icon] || ""}</span>`;
}

// The theme colour an achievement's charm should render in (undefined for non-achievement icons).
const achColor = (a) => ACH_GROUP_COLORS[achGroupOf(a.id)];

// Every unlock pops a toast. Already-earned ids no-op above, so a charm earned
// mid-game (toasted during play) never re-toasts at end-of-game. When several
// unlock at once (typically at endGame), the toasts stack in the corner.
// Longest run of consecutive CORRECT rounds that share one album (Time To Branch Out?).
function longestAlbumRun(results, albums) {
  let best = 0, run = 0, prev = null;
  for (let i = 0; i < results.length; i++) {
    if (results[i] && albums[i] && albums[i] === prev) run++;
    else if (results[i] && albums[i]) { run = 1; prev = albums[i]; }
    else { run = 0; prev = null; }
    best = Math.max(best, run);
  }
  return best;
}

// Distinct studio albums that produced a correct answer this game (The Eras Tour).
function distinctStudioAlbumsHit(results, albums) {
  const set = new Set();
  for (let i = 0; i < results.length; i++) {
    if (results[i] && albums[i] && STUDIO_ALBUMS.includes(albums[i])) set.add(albums[i]);
  }
  return set.size;
}

// Misses followed immediately by a correct answer — a "bounce back" (Shake It Off).
function recoveryCount(results) {
  let n = 0;
  for (let i = 1; i < results.length; i++) if (results[i] && !results[i - 1]) n++;
  return n;
}

// All three "Folklore love triangle" songs answered correctly this game (The Triangle).
function hasTriangle(songs) {
  return ["cardigan", "betty", "august"].every((t) => songs.includes(t));
}

// Longest run of consecutive correct answers whose titles start with B (My Mind Is Alive).
function longestBTitleRun(results, songs) {
  let best = 0, run = 0;
  for (let i = 0; i < results.length; i++) {
    if (results[i] && songs[i] && /^b/i.test(songs[i])) { run++; best = Math.max(best, run); }
    else run = 0;
  }
  return best;
}

// Lifetime missed rounds across the whole catalog tally (Death By A Thousand Cuts).
function totalLifetimeMisses() {
  const misses = loadSongTally().misses || {};
  return Object.values(misses).reduce((a, b) => a + b, 0);
}

// The challenge-progress charms (the only achievements allowed to fire while a
// challenge run is active — everything else is sandboxed out). Derived from the group
// map so future challenge charms are covered automatically.
const CHALLENGE_ACH_IDS = new Set(ACHIEVEMENTS.filter((a) => ACH_GROUP_OF[a.id] === "challenges").map((a) => a.id));
// The unlock chime (a glockenspiel flourish) marks the rare grand beats: a charm earned or
// a mastery level reached. A finished game can land several at once — a fistful of charms and
// a mastery level-up all in the same results tick — so this coalesces a burst into one chime.
// The small lead also keeps it off the top of the answer chime when a charm unlocks mid-round,
// so it reads as "ding... flourish" rather than a pile-up.
let unlockChimePending = false;
function playUnlockChime() {
  if (unlockChimePending) return;
  unlockChimePending = true;
  // A run that ends holding new charms fires both sounds in the same tick, and the
  // flourish is the longer one, so the chime waits out whatever is left of it. Any
  // other unlock keeps the small 300ms lead.
  const sinceFlourish = Date.now() - flourishPlayedAt;
  const lead = sinceFlourish < FLOURISH_MS + UNLOCK_LEAD_MS
    ? FLOURISH_MS + UNLOCK_LEAD_MS - sinceFlourish
    : UNLOCK_LEAD_MS;
  setTimeout(() => { unlockChimePending = false; playSound("unlock"); }, lead);
}

// The results flourish: the notebook shutting as a run ends. Every page turn in a
// run whooshes (see nextRound), but the page that ends the game never turns, so this
// takes that slot rather than adding a beat of its own. It plays on EVERY finished
// run, won or lost (it is the book closing, not a verdict), and once per run, since
// several end paths can fold through here.
const FLOURISH_MS = 650;      // length of close.mp3
const UNLOCK_LEAD_MS = 300;   // the chime's ordinary lead off a mid-round unlock
let flourishPlayedAt = -Infinity;
let flourishThisRun = false;
function playRunFlourish() {
  if (flourishThisRun) return;
  flourishThisRun = true;
  flourishPlayedAt = Date.now();
  playSound("close");
}

function unlock(id) {
  // Sandbox: during a live challenge run, only the challenge-progress charms unlock —
  // no game-quality achievements (streaks, speed, etc.) leak in from mid-round checks.
  // The flag is cleared before endChallenge folds, so post-run meta charms still fire.
  if (challengeRunActive && !CHALLENGE_ACH_IDS.has(id)) return;
  if (!ACH_BY_ID[id] || earnedAchievements[id]) return;
  earnedAchievements[id] = new Date().toISOString();   // full ISO so same-day charms sort by earn time
  saveAchievements(earnedAchievements);
  newlyUnlocked.push(id);
  showToast(ACH_BY_ID[id]);
  playUnlockChime();
  checkMetaAchievements();
}

// The charms that count as hidden for Is It Over Now?. Frozen as a literal rather than
// filtered off `secret` at runtime, because that made the capstone's price move every time
// a charm's mask was reconsidered: unmasking anything quietly made "find every hidden charm"
// cheaper for anyone still chasing it. Adding a new secret charm here is now a deliberate
// decision, not a side effect. Excludes the two meta charms (circularity) and the flourish
// charms, which carry `reveal` and are gated targets rather than things to be found.
const HIDDEN_ACH_IDS = [
  "getaway-car", "long-story-short", "champagne-problems", "anti-hero",
  "i-did-something-bad", "branch-out", "midnights", "the-triangle",
  "my-mind-is-alive", "cruel-summer", "i-cant-see-you", "thousand-cuts",
  "spicy-drama", "i-look-in-windows", "look-what-you-made-me-do", "snow-on-the-beach",
  "midnight-rain", "autumn-leaves-falling", "fav-song", "paris",
  "mean", "raining-monday", "seven", "piano-was-hissing",
  "the-bolter", "no-closure", "this-is-me-trying", "smallest-man",
  "you-took-a-polaroid-of-us",
];

// Re-evaluated after every unlock (each unlock no-ops if already earned, so this is safe to
// recurse). Covers the achievements whose condition is "you've earned other achievements":
//   karma          — your 13th charm.
//   is-it-over-now — every charm in HIDDEN_ACH_IDS.
//   the-lucky-one  — 100%: every achievement but itself (is-it-over-now is earnable first,
//                    so there's no circular deadlock between the two meta charms).
const META_ACH = ["is-it-over-now", "the-lucky-one"];
function checkMetaAchievements() {
  if (Object.keys(earnedAchievements).length >= 13) unlock("karma");
  if (HIDDEN_ACH_IDS.every((id) => earnedAchievements[id])) unlock("is-it-over-now");
  const all = ACHIEVEMENTS.filter((a) => a.id !== "the-lucky-one");
  if (all.length && all.every((a) => earnedAchievements[a.id])) unlock("the-lucky-one");
}

// Breadth charms — called once from the end of every finished run. `token` is this run's
// Explorer token (see EXPLORER_TOKENS), or null for the modes Explorer doesn't ask for;
// those still tick their weekday off, since Seven only cares that you played at all.
// The weekday comes off todayKey so the dev date override moves it like every other dated
// surface. Test runs (devNoLog) record nothing, exactly as stats and history don't.
function markRunBreadth(token) {
  if (devNoLog) return;
  if (token && hasExploredEverything(markModeSeen(token))) unlock("explorer");
  // Noon, so neither the timezone nor a DST shift can roll the parsed date onto its neighbour.
  const day = new Date(todayKey() + "T12:00:00").getDay();
  if (hasPlayedEveryWeekday(markWeekdayPlayed(day))) unlock("seven");
}

/* ---------- Challenges mode: token wallet + progress mutators ----------
   These run OUTSIDE the per-run fold (called from the page / endChallenge), so the
   challenge achievements they unlock don't violate the run sandbox. */
function tokenBalance() { return loadChallengeTokens().balance; }

// What this challenge costs in persistence tickets, or null when no number of tickets can
// ever buy it. Mastery-gated challenges are the null case: that gate is a requirement, not a
// price, so neither currency reaches it.
function ticketPrice(c) {
  if (!c || c.mastery) return null;
  const p = TICKET_PRICE[c.tapes || 0];
  return p == null ? null : p;
}

// Which currency an unlock would actually spend, or null if neither can cover it.
// Persistence first, no part-payment and no mixing: tickets pay whenever they cover the WHOLE
// price, otherwise a regular token does. Holding one ticket against a two-ticket challenge
// contributes nothing to that purchase — it waits until it is a whole price on its own.
function unlockPayment(c) {
  if (!c || c.mastery) return null;
  const wallet = loadChallengeTokens();
  const price = ticketPrice(c);
  if (price != null && wallet.tickets >= price) return { kind: "ticket", price };
  const cost = c.cost || 1;
  if (wallet.balance >= cost) return { kind: "token", price: cost };
  return null;
}

// Spend a token (or a whole ticket price) to unlock a challenge. Returns true on success.
function unlockChallenge(id) {
  const c = CHALLENGE_BY_ID[id];
  if (!c) return false;
  if (c.mastery) return challengeMasteryReached(c);  // mastery-gated: never purchasable
  const st = loadChallengeState();
  if (st[id] && st[id].unlocked) return true;       // already open
  const pay = unlockPayment(c);
  if (!pay) return false;                            // can't afford in either currency
  const wallet = loadChallengeTokens();
  if (pay.kind === "ticket") wallet.tickets -= pay.price; else wallet.balance -= pay.price;
  saveChallengeTokens(wallet);
  st[id] = { ...challengeRecord(id), unlocked: true };
  saveChallengeState(st);
  // Paper Rings — every challenge in the registry is now unlocked (free ones count).
  if (CHALLENGES.every((ch) => challengeUnlocked(ch.id))) unlock("paper-rings");
  return true;
}

// True if the player's Mastery level has reached a mastery-gated challenge's requirement.
function challengeMasteryReached(c) {
  return masteryLevelFromXp(loadMastery().masteryXp) >= c.mastery;
}

// True when the super-hard tier is actually open. Asked of the challenges themselves (the
// `mastery` field on the tapes:4 entries) rather than of the Mastery reward ledger, so the
// Mastery tile that advertises this tier can never disagree with the Challenges board.
function superHardTierOpen() {
  const gated = CHALLENGES.filter((c) => c.mastery);
  return gated.length > 0 && gated.every(challengeMasteryReached);
}

// True if the player can start this challenge right now. Mastery-gated challenges open
// purely on Mastery level (never via tokens); others on free/already-unlocked.
function challengeUnlocked(id) {
  const c = CHALLENGE_BY_ID[id];
  if (!c) return false;
  if (c.mastery) return challengeMasteryReached(c);
  return c.free || challengeRecord(id).unlocked;
}

// Bump the attempt counter (called when a challenge run starts). Dark runs count on their
// own tally so a dark attempt never inflates the base challenge's attempt history.
function recordChallengeAttempt(id, dark) {
  const st = loadChallengeState();
  const rec = st[id] ? { ...challengeRecord(id) } : { ...challengeRecord(id), unlocked: !!CHALLENGE_BY_ID[id].free };
  if (dark) rec.darkAttempts += 1; else rec.attempts += 1;
  st[id] = rec;
  saveChallengeState(st);
  return dark ? rec.darkAttempts : rec.attempts;
}

/* ---------- Persistence tickets ----------
   An EARNEST attempt is a run that reached the end screen, won or lost; quitting earns
   nothing. This counter therefore banks at the END of a run, which is the exact opposite of
   `attempts` above (banked at run START). They want opposite definitions because they defend
   against opposite exploits: banking at the start is what keeps State Of Grace honest, and
   banking at the end is what stops seven start-and-quit cycles minting a free ticket. Keep
   both — a quit at round 12 then costs the first-try shot AND earns no ticket progress.
   Dark runs never count: a dark side only opens once the base is beaten, so its attempts
   would be minting against a challenge that has already paid out. */
function recordEarnestAttempt(id, dark) {
  const rec = challengeRecord(id);
  // Stop once the challenge is beaten (it has already paid a token) or the seven are banked.
  if (dark || rec.defeated || rec.earnest >= PERSIST_ATTEMPTS) return rec.earnest;
  const st = loadChallengeState();
  st[id] = { ...rec, earnest: rec.earnest + 1 };
  saveChallengeState(st);
  return st[id].earnest;
}

// A ticket is not granted, it is claimed: it waits on the challenge's own card until the
// player takes it. It stays claimable after the challenge is finally beaten, because it was
// earned by trying and confiscating it for succeeding would only reward sitting on the claim.
function ticketReady(id) {
  const rec = challengeRecord(id);
  return !rec.ticketClaimed && rec.earnest >= PERSIST_ATTEMPTS;
}

// Claim the waiting ticket. One per challenge, ever — without the cap a stuck player farms a
// single challenge forever and the seven stops meaning anything.
function claimTicket(id) {
  if (!ticketReady(id)) return false;
  const st = loadChallengeState();
  st[id] = { ...challengeRecord(id), ticketClaimed: true };
  saveChallengeState(st);
  const wallet = loadChallengeTokens();
  wallet.tickets += 1;
  saveChallengeTokens(wallet);
  return true;
}

// Record a defeat. First-ever defeat awards a token and the milestone charms.
// A dark-side defeat is recorded against the dark* fields and deliberately awards none of
// the base milestones: those charms are about first-ever/one-try/persistence on the base
// roster, and re-firing them off a dark run would double-count the same beat. Dark-side
// rewards are a separate, selective set still to be designed (see PLAN.md).
function markChallengeDefeated(id, score, dark) {
  const st = loadChallengeState();
  const rec = { ...challengeRecord(id) };
  const firstTime = dark ? !rec.darkDefeated : !rec.defeated;
  if (dark) {
    rec.darkDefeated = true;
    if (score > rec.darkBest) rec.darkBest = score;
  } else {
    rec.defeated = true;
    if (score > rec.best) rec.best = score;
  }
  st[id] = rec;
  saveChallengeState(st);
  // Dark-side milestones. No per-challenge charm — the black seal and violet tick are that
  // reward. The "every dark side" charm counts DARK_SIDE_IDS rather than a fixed total, so
  // it re-targets itself as more dark sides get authored.
  if (firstTime && dark) {
    const beaten = DARK_SIDE_IDS.filter((k) => challengeRecord(k).darkDefeated).length;
    unlock("the-black-dog");
    if (beaten >= DARK_SIDE_MILESTONE) unlock("dont-blame-me");
    if (DARK_SIDE_IDS.length && beaten >= DARK_SIDE_IDS.length) unlock("darkest-paradise");
    // Mad Woman — the dark mirror of State Of Grace. darkAttempts banks at run start, the
    // way attempts does, so at this point it already counts the run that just won.
    if (rec.darkAttempts === 1) unlock("mad-woman");
  }
  if (firstTime && !dark) {
    const wallet = loadChallengeTokens();
    wallet.balance += 1;                              // the self-feeding reward
    saveChallengeTokens(wallet);
    unlock("the-archer");                             // first challenge ever defeated
    if (rec.attempts === 1) unlock("state-of-grace"); // beat it on the first try
    // Persistence, counted the persistence way: the EARNEST tally (runs seen through to the
    // end), not `attempts`, which banks at run start and would credit seven quits. Same seven
    // as the ticket, so the charm honestly means "you saw this through seven times and won".
    if (rec.earnest >= PERSIST_ATTEMPTS) unlock("this-is-me-trying");
    if (CHALLENGES.every((ch) => challengeRecord(ch.id).defeated)) unlock("the-alchemy");
  }
  return firstTime;
}

// "The Piano Was Hissing" — typing "rep tv" / "reputation tv" as an answer OR as your name.
// Letters-only so spacing/case/punctuation don't matter.
function checkPianoEgg(s) {
  const k = (s || "").toLowerCase().replace(/[^a-z]/g, "");
  if (k === "reptv" || k === "reputationtv") unlock("piano-was-hissing");
}

/* ---------- Custom tooltips (data-tip; controllable delay, no clipping) ---------- */
// A single body-level bubble shared by every [data-tip] element. Default shows
// immediately; an element can opt into a delay with data-tip-delay (ms).
let _tipEl = null, _tipTimer = null;
function ensureTipEl() {
  if (_tipEl) return _tipEl;
  _tipEl = document.createElement("div");
  _tipEl.className = "tip-pop";
  _tipEl.setAttribute("role", "tooltip");
  document.body.appendChild(_tipEl);
  return _tipEl;
}
function positionTip(el, target) {
  const r = target.getBoundingClientRect();
  el.style.left = "0px"; el.style.top = "0px";   // measure unclamped
  const tr = el.getBoundingClientRect();
  let left = r.left + r.width / 2 - tr.width / 2;
  left = Math.max(6, Math.min(left, window.innerWidth - tr.width - 6));
  let top = r.top - tr.height - 8;
  if (top < 6) top = r.bottom + 8;               // flip below if no room above
  el.style.left = left + "px";
  el.style.top = top + "px";
}
function showTip(target) {
  if (!target.isConnected) return;   // target removed before a delayed show fired
  const text = target.getAttribute("data-tip");
  if (!text) return;
  const el = ensureTipEl();
  el.textContent = text;
  el.classList.add("show");
  positionTip(el, target);
}
function hideTip() {
  clearTimeout(_tipTimer);
  if (_tipEl) _tipEl.classList.remove("show");
}
function setupTooltips() {
  document.addEventListener("mouseover", (e) => {
    const t = e.target.closest("[data-tip]");
    if (!t) return;
    clearTimeout(_tipTimer);
    const delay = parseInt(t.getAttribute("data-tip-delay") || "0", 10);
    if (delay > 0) _tipTimer = setTimeout(() => showTip(t), delay);
    else showTip(t);
  });
  document.addEventListener("mouseout", (e) => {
    const t = e.target.closest("[data-tip]");
    if (!t || t.contains(e.relatedTarget)) return;
    hideTip();
  });
  window.addEventListener("scroll", hideTip, true);
}

// A plain (non-achievement) toast — a short heading + message. Reuses the
// achievement toast stack + auto-dismiss, so failures surface instead of being silent.
function notifyNote(label, msg) {
  const layer = $("toastLayer");
  if (!layer) return;
  const t = document.createElement("div");
  t.className = "toast toast-note";
  t.innerHTML = `<div><div class="t-label">${escapeHtml(label)}</div><div class="t-name">${escapeHtml(msg)}</div></div>`;
  layer.appendChild(t);
  scheduleToastDismiss();
}

function showToast(a) {
  const layer = $("toastLayer");
  if (!layer) return;
  const t = document.createElement("div");
  t.className = "toast";
  t.setAttribute("data-tip", a.desc);
  t.setAttribute("data-tip-delay", "500");
  t.innerHTML = charmMarkup(a.icon, achColor(a)) +
    `<div><div class="t-label">achievement unlocked</div><div class="t-name">${escapeHtml(a.name)}</div></div>`;
  layer.appendChild(t);
  scheduleToastDismiss();
}

// Toasts leave the stack one at a time from the bottom (not all at once when
// several unlock together): the bottom one slides out, the toasts above glide
// down into the freed slot (FLIP) and dwell ~1s, then the new bottom leaves.
let toastDismissTimer = null;
function scheduleToastDismiss() {
  if (toastDismissTimer) return;            // a dismissal cycle is already running
  const layer = $("toastLayer");
  if (!layer) return;
  const tick = () => {
    const toasts = [...layer.querySelectorAll(".toast:not(.leaving)")];
    if (!toasts.length) { toastDismissTimer = null; return; }
    const bottom = toasts[toasts.length - 1];   // last child = bottom of the stack
    const above = toasts.slice(0, -1);
    const beforeTops = above.map((el) => el.getBoundingClientRect().top);
    bottom.classList.add("leaving");
    setTimeout(() => {
      bottom.remove();
      hideTip();   // removal fires no mouseout, so a tooltip on this toast would otherwise linger

      // FLIP: the removal collapses the layout instantly, so smoothly animate the
      // toasts above from their old positions down into their new ones.
      if (!motionReduced()) {
        above.forEach((el, i) => {
          const dy = beforeTops[i] - el.getBoundingClientRect().top;   // <0: moved down
          if (!dy) return;
          el.style.transition = "none";
          el.style.transform = `translateY(${dy}px) rotate(-1deg)`;
          requestAnimationFrame(() => {
            el.style.transition = "transform 0.34s cubic-bezier(.34,1.1,.64,1)";
            el.style.transform = "rotate(-1deg)";
          });
        });
      }
    }, 420);
    toastDismissTimer = setTimeout(tick, 420 + 340 + 1220);   // leave + drop + dwell
  };
  toastDismissTimer = setTimeout(tick, 4050);   // initial dwell before the first leaves
}

// The results keepsake: lines the player recalled word-for-word this run, re-written
// in faint handwriting like verses pressed into the notebook. Skipped when empty or on
// a held-back daily score (it would leak how the round went). ★ = word-perfect line,
// ★★ = a whole verse.
const VA_SHOWN = 3;   // keepsake lines shown before the rest fold behind "+ N more"
function renderVerseAnthology() {
  const el = $("verseAnthology");
  if (!el) return;
  if (!verseKeepsake.length || (gameType === "daily" && settings.hideDailyScore)) {
    el.style.display = "none"; el.innerHTML = ""; return;
  }
  const rows = verseKeepsake.map((k, i) => {
    const mark = k.tier === "verse" ? "★★" : "★";
    return `<li class="va-row${i >= VA_SHOWN ? " va-folded" : ""}"><span class="va-mark">${mark}</span>` +
      `<span class="va-text">${highlightWord(k.line, k.word)}</span></li>`;
  }).join("");
  const n = verseKeepsake.length;
  const folded = n - VA_SHOWN;
  const more = folded > 0
    ? `<button type="button" class="va-more">+ ${folded} more line${folded > 1 ? "s" : ""}</button>`
    : "";
  el.innerHTML = `<p class="va-caption">pages you filled in, ${n} line${n > 1 ? "s" : ""} from memory</p>` +
    `<ul class="va-list">${rows}</ul>` + more;
  const moreBtn = el.querySelector(".va-more");
  if (moreBtn) moreBtn.addEventListener("click", () => {
    el.querySelectorAll(".va-folded").forEach((r) => r.classList.remove("va-folded"));
    moreBtn.remove();
  });
  el.style.display = "";
}

// The recap band frames itself, so it has to know when both its halves went quiet: two
// hidden children would otherwise leave a pair of rules around nothing. Called at the end
// of both renderers, since the two run in either order across the end paths.
function syncRecapBand() {
  const band = $("recapBand");
  if (!band) return;
  const live = [...band.children].filter((c) => c.style.display !== "none");
  band.style.display = live.length ? "" : "none";
  band.classList.toggle("recap-band--solo", live.length === 1);
}

const ACH_RECAP_SHOWN = 5;   // unlock charms shown before "+N" points at the collection
// (5, not 6: six charms plus the overflow count wrap to a second line in the band's half-width column)
function renderResultRecap() {
  const el = $("resultAchievements");
  if (!el) return;
  const ids = [...new Set(newlyUnlocked)].filter((id) => ACH_BY_ID[id] && earnedAchievements[id]);
  if (!ids.length) { el.style.display = "none"; el.innerHTML = ""; syncRecapBand(); return; }
  // The charms carry no name of their own here: at this size six names would fill the
  // column and blow the band's height out. The names read underneath as one handwritten
  // line instead, and each charm keeps its name in the tooltip and its aria-label.
  // EVERY charm is rendered; the ones past the cap are folded away in CSS so the overflow
  // count can unfold them in place rather than throwing the player at the collection.
  const chips = ids.map((id, i) => {
    const a = ACH_BY_ID[id];
    return `<button type="button" class="ach-chip${i >= ACH_RECAP_SHOWN ? " ach-folded" : ""}" aria-label="${escapeHtml(a.name)}" ` +
      `data-tip="${escapeHtml(a.name)} · ${escapeHtml(a.desc)}" data-tip-delay="120">${charmMarkup(a.icon, achColor(a))}</button>`;
  }).join("");
  const folded = ids.length > ACH_RECAP_SHOWN;
  const extra = folded
    ? `<button type="button" class="ach-chip--more">+${ids.length - ACH_RECAP_SHOWN}</button>`
    : "";
  el.innerHTML = `<p class="sr-lab ach-recap-lab">newly unlocked · ${ids.length}</p>` +
    `<div class="ach-recap-row">${chips}${extra}</div>` +
    `<p class="ach-recap-names">${unlockNameLine(ids)}</p>`;
  el.style.display = "";

  // The two overflow counts ("+3" on the charms, "3 more" in the names) are one gesture:
  // either unfolds both halves in place. Only a charm itself still leaves for the
  // collection, which is what a player tapping a charm is actually asking for.
  const expand = () => {
    el.querySelectorAll(".ach-folded").forEach((c) => c.classList.remove("ach-folded"));
    el.querySelector(".ach-chip--more")?.remove();
    const names = el.querySelector(".ach-recap-names");
    if (names) names.textContent = joinNames(ids);
  };
  el.querySelectorAll(".ach-chip--more, .ach-names-more").forEach((c) => c.addEventListener("click", expand));
  el.querySelectorAll(".ach-chip").forEach((c) => c.addEventListener("click", () => openAchievements("results")));
  syncRecapBand();
}

// "Word For Word, Wordsmith and Getaway Car" — or, past three, "…and 3 more", where the
// count is the button that unfolds the rest. Reads as a sentence under the charm row so an
// unlock is still legible without a hover.
const ACH_NAMES_SHOWN = 3;
function joinNames(ids) {
  const names = ids.map((id) => ACH_BY_ID[id].name);
  if (names.length === 1) return names[0];
  return `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
}
function unlockNameLine(ids) {
  if (ids.length <= ACH_NAMES_SHOWN) return escapeHtml(joinNames(ids));
  const shown = ids.slice(0, ACH_NAMES_SHOWN).map((id) => ACH_BY_ID[id].name).join(", ");
  return `${escapeHtml(shown)} and ` +
    `<button type="button" class="ach-names-more">${ids.length - ACH_NAMES_SHOWN} more</button>`;
}

// The results-screen skills recap: what each skill earned this game, plus a live Mastery
// bar. Reads the stashed foldSkillXp outcome (lastSkillFold); shows nothing when no fold
// ran (a daily replay) or nothing was earned. Also the trigger point for the first-class
// Mastery level-up / unlock celebration (celebrateMastery), so it lands on the results card.
function renderSkillsRecap() {
  const el = $("resultSkills");
  if (!el) return;
  const fold = lastSkillFold;
  const hideForDaily = gameType === "daily" && settings.hideDailyScore;  // don't leak how the day went
  if (!fold || !fold.res || hideForDaily) { el.style.display = "none"; el.innerHTML = ""; syncRecapBand(); return; }
  const { delta, res } = fold;

  const levelTo = {};
  for (const up of res.levelUps) levelTo[up.id] = up.to;
  const gained = SKILLS.filter((sk) => (delta[sk.id] || 0) > 0);
  const masteryMoment = res.masteryJustUnlocked || !!res.masteryUp;
  if (!gained.length && !masteryMoment) { el.style.display = "none"; el.innerHTML = ""; syncRecapBand(); return; }

  const items = gained.map((sk) => {
    const up = levelTo[sk.id];
    return `<span class="sr-it${up ? " up" : ""}">` +
      `<span class="sr-ic">${masteryMarkup(sk.icon)}</span>` +
      `<span class="sr-nm">${escapeHtml(sk.name)}</span>` +
      `<span class="sr-xp">+${delta[sk.id]}${up ? ` · lv ${up}` : ""}</span></span>`;
  }).join("");

  // Mastery. The big stacked bar is reserved for a mastery MOMENT (the unlock or a
  // level-up, where celebrateMastery lands on top of it); ordinary games get a single
  // hairline row — label, thin bar, count — sitting under the skills so the whole half
  // stays one block rather than growing a section of its own.
  const m = res.mastery;
  let mastery;
  const mrow = (lab, val, pct, cls) =>
    `<div class="sr-mrow${cls ? ` ${cls}` : ""}"><span>${lab}</span>` +
    `<div class="ms-bar sr-mbar${cls === "maxed" ? " maxed" : ""}"><i style="width:${pct}%"></i></div>` +
    `<span>${val}</span></div>`;
  if (masteryMoment) {
    const lvl = masteryLevelFromXp(m.masteryXp);
    if (lvl >= MASTERY_MAX_LEVEL) {
      mastery = `<div class="sr-mastery"><div class="sr-mtop"><span>Mastery: level ${lvl}</span>` +
        `<span class="sr-mxp">max</span></div>` +
        `<div class="ms-bar sr-mbar maxed"><i style="width:100%"></i></div></div>`;
    } else {
      const cur = masteryXpForLevel(lvl), next = masteryXpForLevel(lvl + 1);
      const pct = Math.max(0, Math.min(100, ((m.masteryXp - cur) / (next - cur)) * 100));
      mastery = `<div class="sr-mastery"><div class="sr-mtop"><span>Mastery: level ${lvl}</span>` +
        `<span class="sr-mxp">${m.masteryXp - cur} / ${next - cur} to ${lvl + 1}</span></div>` +
        `<div class="ms-bar sr-mbar"><i style="width:${pct.toFixed(1)}%"></i></div></div>`;
    }
  } else if (isMasteryUnlocked(m)) {
    const lvl = masteryLevelFromXp(m.masteryXp);
    if (lvl >= MASTERY_MAX_LEVEL) {
      mastery = mrow(`mastery lv ${lvl}`, "max", 100, "maxed");
    } else {
      const cur = masteryXpForLevel(lvl), next = masteryXpForLevel(lvl + 1);
      const pct = Math.max(0, Math.min(100, ((m.masteryXp - cur) / (next - cur)) * 100));
      mastery = mrow(`mastery lv ${lvl}`, `${m.masteryXp - cur} / ${next - cur}`, pct.toFixed(1));
    }
  } else {
    const lv = totalSkillLevels(m);
    mastery = mrow("mastery", `${lv} / ${MASTERY_GATE}`, ((lv / MASTERY_GATE) * 100).toFixed(1), "locked");
  }

  el.innerHTML =
    (items ? `<p class="sr-lab">skills</p><div class="sr-grid">${items}</div>` : "") + mastery;
  el.style.display = "";
  syncRecapBand();
  // A mastery moment gets the whole band's width: the celebration banner and its sparkle
  // burst are the loudest thing on the results card and should not be squeezed into a half.
  const band = $("recapBand");
  if (band) band.classList.toggle("recap-band--moment", masteryMoment);

  celebrateMastery(res, el);
}

// A first-class Mastery moment on the results card: a gold seal banner for the unlock or a
// level-up, naming any reward just earned, with a soft sparkle burst (honours reduced
// motion / reduced flashing). Skill level-ups stay as plain toasts; this is only the rarer,
// bigger beat. Injected at the top of the skills recap so it reads before the detail.
function celebrateMastery(res, host) {
  if (!res || !host) return;
  const isUnlock = res.masteryJustUnlocked;
  const up = res.masteryUp;
  if (!isUnlock && !up) return;
  const lvl = up ? up.to : masteryLevelFromXp(res.mastery.masteryXp);
  const rewards = (res.newUnlocks || []).map((id) => MASTERY_REWARD_BY_ID[id]).filter(Boolean);
  const rewardLine = rewards.length
    ? `<div class="mc-reward">new reward${rewards.length > 1 ? "s" : ""}: ${rewards.map((r) => escapeHtml(r.name)).join(", ")}</div>`
    : "";
  const title = isUnlock ? "Mastery unlocked" : `Mastery: level ${lvl}`;
  const sub = isUnlock ? "every skill now feeds your mastery" : "another page turns in your songbook";

  const banner = document.createElement("div");
  banner.className = "mastery-celebrate";
  banner.innerHTML = `<div class="mc-seal">${STAR_SVG}</div>` +
    `<div class="mc-title">${escapeHtml(title)}</div>` +
    `<div class="mc-sub">${escapeHtml(sub)}</div>${rewardLine}` +
    `<button type="button" class="mc-cta">see mastery →</button>`;
  host.insertBefore(banner, host.firstChild);
  banner.querySelector(".mc-cta").addEventListener("click", () => openMastery("results"));

  if (!motionReduced() && !settings.reducedFlashing) {
    const burst = document.createElement("div");
    burst.className = "mc-burst"; burst.setAttribute("aria-hidden", "true");
    for (let i = 0; i < 22; i++) {
      const s = document.createElement("span");
      s.className = "mcs";
      const ang = (Math.PI * 2 * i) / 22 + Math.random() * 0.3;
      const dist = 54 + Math.random() * 74;
      s.style.setProperty("--dx", (Math.cos(ang) * dist).toFixed(0) + "px");
      s.style.setProperty("--dy", (Math.sin(ang) * dist).toFixed(0) + "px");
      s.style.animationDelay = (Math.random() * 0.22).toFixed(2) + "s";
      s.innerHTML = SPARKLE_SVG;
      burst.appendChild(s);
    }
    banner.appendChild(burst);
    setTimeout(() => burst.remove(), 2100);
  }
  if (!motionReduced()) { void banner.offsetWidth; }
  banner.classList.add("in");
  playUnlockChime();   // same grand chime as a charm; coalesced if charms unlocked this tick too
}

// Is this charm still behind the ??? mask? Secret by default, but a flourish charm names a
// challenge in `reveal` and unmasks the moment that challenge is defeated — from then on it
// reads as an ordinary locked target and sits back in its own theme, not the Secret section.
// Every masking decision on the achievements page goes through here, never `a.secret`.
const achMasked = (a) => !!a.secret && !(a.reveal && challengeRecord(a.reveal).defeated);

// Everything the trailing Secret section holds — the still-masked charms you haven't earned.
// An earned secret leaves it (it moves into its real theme), so the section empties out and
// eventually stops rendering at all. The Mastery hints vault asks the same question, because a
// door pointing at a section that no longer exists is worse than no door.
const secretCharmsLeft = () => ACHIEVEMENTS.filter((a) => achMasked(a) && !earnedAchievements[a.id]);

// One charm tile: earned (revealed), a still-masked secret (???), or a visible
// locked target. Shared by the grid + secret section.
function achTile(a) {
  if (earnedAchievements[a.id]) {
    return `<div class="ach ach--earned">${charmMarkup(a.icon, achColor(a))}<div class="ach-text"><div class="ach-nm">${escapeHtml(a.name)}</div><div class="ach-dc">${escapeHtml(a.desc)}</div></div></div>`;
  }
  if (achMasked(a)) {
    // Once the level-10 "secret hints" reward is earned, reveal the how-to (desc) while
    // keeping the name and charm a surprise; otherwise it stays fully masked.
    const dc = hiddenHintsUnlocked() ? escapeHtml(a.desc) : "a secret charm";
    const cls = hiddenHintsUnlocked() ? "ach locked secret hinted" : "ach locked secret";
    return `<div class="${cls}"><span class="charm-q" aria-hidden="true">?</span><div class="ach-text"><div class="ach-nm">???</div><div class="ach-dc">${dc}</div></div></div>`;
  }
  return `<div class="ach locked">${charmMarkup(a.icon)}<div class="ach-text"><div class="ach-nm">${escapeHtml(a.name)}</div><div class="ach-dc">${escapeHtml(a.desc)}</div></div></div>`;
}

const achGroupOf = (id) => ACH_GROUP_OF[id] || "core";

function renderAchievementsPage() {
  const total = ACHIEVEMENTS.length;
  // earned, oldest → newest (the newest is the "latest charm")
  const earnedAsc = ACHIEVEMENTS.filter((a) => earnedAchievements[a.id])
    .sort((x, y) => (earnedAchievements[x.id] || "").localeCompare(earnedAchievements[y.id] || ""));
  const earnedCount = earnedAsc.length;
  const pct = Math.round((earnedCount / total) * 100);

  let html = `<div class="ach-page-head"><div class="ach-page-title">Charm Collection</div>` +
    `<div class="ach-page-sub">${earnedCount} / ${total} charms collected</div>` +
    `</div>`;

  // by-theme breakdown — one small colour-coded bar per group (denominators count
  // every charm in the theme, secret ones included, so the five sum to the total).
  const themeRows = ACH_GROUPS.map((g) => {
    const members = ACHIEVEMENTS.filter((a) => achGroupOf(a.id) === g.id);
    const got = members.filter((a) => earnedAchievements[a.id]).length;
    const tot = members.length;
    const col = ACH_GROUP_COLORS[g.id];
    return `<button type="button" class="ach-theme" data-ach-theme="${g.id}" aria-label="Go to ${escapeHtml(g.label)} charms">` +
      `<div class="ach-theme-head"><span class="ach-theme-name"><span class="ach-group-dot" style="background:${col}"></span>${g.short}</span><span>${got} / ${tot}</span></div>` +
      `<div class="ach-theme-bar"><div style="width:${tot ? (got / tot) * 100 : 0}%;background:${col}"></div></div>` +
      `</button>`;
  }).join("");
  html += `<div class="ach-themes"><div class="ach-themes-label">by theme</div>` +
    `<div class="ach-themes-grid">${themeRows}</div></div>`;

  const meter = `<div class="cat-meter">` +
    `<div class="cat-meter-head"><span>charms collected</span><span>${pct}%</span></div>` +
    `<div class="cat-meter-num"><b>${earnedCount}</b> / ${total}</div>` +
    `<div class="cat-bar"><div class="cat-seg" style="width:${(earnedCount / total) * 100}%;background:var(--ink-accent)"></div></div>` +
    `</div>`;

  // newest charm as a proper keepsake — its real icon, the name (wraps), and the date.
  const latest = earnedAsc[earnedAsc.length - 1];
  const latestCard = latest ? `<div class="ach-latest">` +
    `<span class="ach-latest-charm">${charmMarkup(latest.icon, achColor(latest))}</span>` +
    `<div class="ach-latest-text"><div class="ach-latest-label">your newest charm</div>` +
    `<div class="ach-latest-name">${escapeHtml(latest.name)}</div>` +
    `<div class="ach-latest-meta">${escapeHtml(latest.desc)} · ${recordDateLabel(earnedAchievements[latest.id])}</div></div>` +
    `</div>` :
    `<div class="ach-latest ach-latest--empty"><div class="ach-latest-text">` +
    `<div class="ach-latest-label">your newest charm</div>` +
    `<div class="ach-latest-meta">no charms yet — finish a game to earn your first</div>` +
    playCTA() + `</div></div>`;

  html += `<div class="ach-head-row">${meter}${latestCard}</div>`;

  // "The long game" — the catalogue-completion charm ("I Hate It Here") gets a pinned
  // quest card above the grid: live song-completion progress (the album-rainbow bar) and
  // a door into the songbook. It's the only charm with a browsable collection behind it,
  // so it's promoted out of its theme grid (it still counts toward Catalogue below).
  html += goalCardHTML();
  html += questCardHTML();

  // themed sections: earned (revealed, newest first) then visible locked targets.
  // Still-masked secrets are held back for the trailing Secret section.
  ACH_GROUPS.forEach((g) => {
    const members = ACHIEVEMENTS.filter((a) =>
      achGroupOf(a.id) === g.id && (earnedAchievements[a.id] || !achMasked(a)));
    if (!members.length) return;
    const earnedM = members.filter((a) => earnedAchievements[a.id])
      .sort((x, y) => (earnedAchievements[y.id] || "").localeCompare(earnedAchievements[x.id] || ""));
    const lockedM = members.filter((a) => !earnedAchievements[a.id]);
    const tiles = [...earnedM, ...lockedM].map(achTile).join("");
    html += `<p class="histogram-label ach-section" id="achTheme-${g.id}" style="--group:${ACH_GROUP_COLORS[g.id]}"><span class="ach-group-dot" style="background:${ACH_GROUP_COLORS[g.id]}"></span>${g.label}</p>` +
      `<div class="ach-grid">${tiles}</div>`;
  });

  const secretLocked = secretCharmsLeft();
  if (secretLocked.length) {
    // This group only ever holds LOCKED secrets (an earned one moves into its real theme),
    // so once the level-10 reveal has spelled out how to earn each of them, the word goes
    // in quotation marks and the count gives way to the joke.
    const revealed = hiddenHintsUnlocked();
    const secretLabel = revealed
      ? `“Secret” charms · in name only`
      : `Secret charms · ${secretLocked.length}`;
    // The id is an anchor rather than a hook for styling: the Mastery hints vault's door scrolls
    // the window here, since this section is far below the fold on a full charm collection.
    html += `<p class="histogram-label ach-section ach-section--secret" id="achSecretSection"><span class="ach-group-dot ach-group-dot--secret"></span>${secretLabel}</p>` +
      `<div class="ach-grid">${secretLocked.map(achTile).join("")}</div>`;
  }

  $("achievementsBody").innerHTML = html;
  $("achievementsBody").querySelectorAll("[data-ach-theme]").forEach((theme) =>
    theme.addEventListener("click", () => {
      const section = document.getElementById(`achTheme-${theme.dataset.achTheme}`);
      if (section) section.scrollIntoView({
        behavior: motionReduced() ? "auto" : "smooth",
        block: "start",
      });
    }));
  $("achievementsBody").querySelectorAll("[data-open-songbook]").forEach((b) =>
    b.addEventListener("click", () => openSongbook(b.dataset.openSongbook)));
  const repin = $("achievementsBody").querySelector("[data-goal-repin]");
  if (repin) repin.addEventListener("click", () => {
    const rec = loadGoal();
    const id = pickGoal(rec && rec.id);
    if (id) saveGoal(id); else clearGoal();
    renderAchievementsPage();
  });
  const play = $("achievementsBody").querySelector("[data-goal-play]");
  if (play) play.addEventListener("click", () => { playGoal(); });
}

// Shared album-rainbow segments for a {album: discoveredCount} split out of total.
// Drawn in the order albums first appear in allSongs (the catalogue rainbow).
function albumRainbowSegs(byAlbum, total) {
  const order = [];
  for (const s of allSongs) if (s.album && !order.includes(s.album)) order.push(s.album);
  return order.filter((a) => byAlbum[a]).map((a) =>
    `<div class="cat-seg" style="width:${(byAlbum[a] / total) * 100}%;background:${albumColor(a) || "var(--ink-soft)"}" title="${escapeHtml(a)}: ${byAlbum[a]}"></div>`
  ).join("");
}

/* ---------- The pinned goal — one charm to actually go and get ----------
   Draws from the charms tagged `sitting: true` in config.js: unearned, never secret, and
   plausibly closeable in one sitting. There is deliberately NO "closest one" ranking — there
   is no per-charm progress model to rank by (unlocking is imperative `unlock()` calls), and
   once the cumulative charms are excluded as status bars the rest are binary. So: a draw.

   The draw picks a CATEGORY first and only then a charm inside it. Flat over charms would be
   badly lopsided — 26 of the ~45 placeable charms are a plain classic run — and the goal would
   read as "go play a difficulty" more than half the time. Weighting by category is what makes
   Guest, Adaptive and Album goals show up as often as classic ones. */
function goalPool() {
  return ACHIEVEMENTS.filter((a) => a.sitting && !a.secret && !earnedAchievements[a.id]);
}

function pickGoal(exceptId) {
  let pool = goalPool();
  // Never re-pin what we're replacing, unless it's genuinely the last one left.
  if (exceptId && pool.length > 1) pool = pool.filter((a) => a.id !== exceptId);
  if (!pool.length) return null;
  const byCat = {};
  for (const a of pool) {
    const k = a.earn ? a.earn.cat : "";   // "" = the no-destination charms, their own bucket
    (byCat[k] = byCat[k] || []).push(a);
  }
  const cats = Object.keys(byCat);
  const bucket = byCat[cats[Math.floor(Math.random() * cats.length)]];
  return bucket[Math.floor(Math.random() * bucket.length)].id;
}

// The pinned charm, or null when the pool is empty. Re-pins when the stored id no longer
// belongs on the card (retagged, or earned in a mode that doesn't route through this page) —
// but NOT merely because it has been earned: an earned goal is a result the card should show.
function currentGoal() {
  const rec = loadGoal();
  const a = rec && ACH_BY_ID[rec.id];
  if (a && (earnedAchievements[a.id] || goalPool().some((p) => p.id === a.id))) return a;
  const id = pickGoal(rec && rec.id);
  if (!id) { if (rec) clearGoal(); return null; }
  saveGoal(id);
  return ACH_BY_ID[id];
}

/* Where to send someone chasing a goal. Answered by filtering the RANDOMISER's live pool
   rather than by dispatching on `earn.cat` ourselves, which is the whole reason `earn.cat`
   borrows that vocabulary: the pool already refuses to deal anything locked and already
   refuses to spend a token or a ticket, and inheriting both beats re-deriving them here and
   getting one of them subtly wrong. An empty result means the destination genuinely isn't
   open yet, and the card says so instead of offering a door that isn't there. */
function goalEntries(earn) {
  if (!earn || !earn.cat) return [];
  return buildRandomPool().filter((e) => {
    if (e.cat !== earn.cat) return false;
    // The difficulty category tokenises per mode, so a `diff` is matched against the entry
    // itself. Every other category rolls its difficulty at dispatch, so it rides along there.
    if (earn.diff && e.cat === "difficulty") return e.mode === earn.diff;
    return true;
  });
}

// Button text: "play Ultra", "play a challenge", "play Album Focus on Lyricist".
function goalDestLabel(earn) {
  const cat = RANDOM_CATEGORIES.find((c) => c.id === earn.cat);
  const base = cat ? cat.label : earn.cat;
  const diff = earn.diff && MODES[earn.diff] ? MODES[earn.diff].label : "";
  if (earn.cat === "difficulty") return diff || base;
  return diff ? base + " on " + diff : base;
}

function goalCardHTML() {
  const a = currentGoal();
  if (!a) {
    return `<div class="ach-goal ach-goal--empty">
      <div class="ach-goal-main">
        <div class="ach-goal-eyebrow">your goal</div>
        <div class="ach-goal-name">Nothing left to pin</div>
        <div class="ach-goal-desc">Every charm a single sitting could close is already yours. What's left is the long hauls, the streaks that want a calendar, and the secrets.</div>
      </div>
    </div>`;
  }
  const done = !!earnedAchievements[a.id];
  const entries = done ? [] : goalEntries(a.earn);
  const foot = done
    ? `<span class="ach-goal-note">earned ${escapeHtml(recordDateLabel(earnedAchievements[a.id]))} ★</span>` +
      `<button type="button" class="ach-goal-btn" data-goal-repin="1">pin another <span aria-hidden="true">→</span></button>`
    : (entries.length
        ? `<button type="button" class="ach-goal-btn ach-goal-btn--go" data-goal-play="1">play ${escapeHtml(goalDestLabel(a.earn))} <span aria-hidden="true">→</span></button>`
        // Two different truths, and they must not be collapsed. A charm WITH an `earn` whose
        // pool came back empty has a destination that is locked (no dark side unlocked yet, say).
        // A charm with no `earn` has no destination at all — Custom isn't in the randomiser's
        // pool, and the desk actions aren't runs. Neither may pretend to be the other.
        : `<span class="ach-goal-note">${escapeHtml(a.earn ? "not open to you yet" : "you'll have to go and find this one")}</span>`) +
      `<button type="button" class="ach-goal-btn" data-goal-repin="1">pin something else</button>`;

  return `<div class="ach-goal${done ? " done" : ""}">
    <div class="ach-goal-main">
      <div class="ach-goal-eyebrow">your goal${done ? " · met" : ""}</div>
      <div class="ach-goal-name">${escapeHtml(a.name)}</div>
      <div class="ach-goal-desc">${escapeHtml(a.desc)}</div>
      <div class="ach-goal-foot">${foot}</div>
    </div>
    <div class="ach-goal-aside">
      <span class="ach-goal-charm${done ? " earned" : ""}">${charmMarkup(a.icon, achColor(a))}</span>
      <span class="ach-goal-state">${done ? "earned" : "pinned"}</span>
    </div>
  </div>`;
}

// Send the player at the pinned goal. Same dispatcher the randomiser uses, so a goal can
// never open a door the randomiser wouldn't.
async function playGoal() {
  const a = currentGoal();
  if (!a) return;
  const entries = goalEntries(a.earn);
  if (!entries.length) return;
  const e = entries[Math.floor(Math.random() * entries.length)];
  // A named difficulty on a category that rolls one at dispatch (album, guest) rides along
  // on the entry; dispatchRandom prefers it over its own roll.
  await dispatchRandom(a.earn.diff ? { ...e, diff: a.earn.diff } : e);
}

// The pinned catalogue-completion quest card on the Charm Collection page.
function questCardHTML() {
  const a = ACH_BY_ID["i-hate-it-here"];
  if (!a) return "";
  const found = (loadSongTally().songs) || {};
  const total = allSongs.length || 1;
  const discovered = allSongs.filter((s) => found[s.title]).length;
  const done = discovered >= total;
  const byAlbum = {};
  for (const s of allSongs) if (found[s.title] && s.album) byAlbum[s.album] = (byAlbum[s.album] || 0) + 1;
  const note = done ? "every song found ★" : (total - discovered) + " still hiding from you";
  return `<button type="button" class="ach-quest${done ? " done" : ""}" data-open-songbook="achievements">
    <div class="ach-quest-main">
      <div class="ach-quest-eyebrow">the long game · catalogue</div>
      <div class="ach-quest-name">${escapeHtml(a.name)}</div>
      <div class="ach-quest-desc">${escapeHtml(a.desc)}</div>
      <div class="ach-quest-meterhead"><span>songs named</span><span><b>${discovered}</b> / ${total}</span></div>
      <div class="cat-bar ach-quest-bar">${albumRainbowSegs(byAlbum, total)}</div>
      <div class="ach-quest-foot">
        <span class="ach-quest-note">${note}</span>
        <span class="ach-quest-cta">see what's missing <span aria-hidden="true">→</span></span>
      </div>
    </div>
    <div class="ach-quest-aside">
      <span class="ach-quest-charm${done ? " earned" : ""}">${charmMarkup(a.icon, achColor(a))}</span>
      <span class="ach-quest-state">${done ? "earned" : "locked"}</span>
    </div>
  </button>`;
}

/* ---------- Songbook — the missing-songs checklist (backs "I Hate It Here") ---------- */
let songbookBackTarget = "stats";  // where the Songbook's ← back returns to
function openSongbook(from) {
  songbookBackTarget = from;
  renderSongbook();
  flipAwayToScreen("songbook");
}
// A full per-album checklist of the catalogue: which songs you've named (gold star) and
// which are still missing (hollow). Reads the lifetime tally, so it spans every mode.
function renderSongbook() {
  const found = (loadSongTally().songs) || {};
  const total = allSongs.length || 1;
  const discovered = allSongs.filter((s) => found[s.title]).length;
  const remaining = total - discovered;
  const complete = remaining <= 0;
  const pct = Math.floor((discovered / total) * 100);

  const byAlbum = {};
  for (const s of allSongs) if (found[s.title] && s.album) byAlbum[s.album] = (byAlbum[s.album] || 0) + 1;

  const sub = complete
    ? "every song found: the whole catalogue, by heart ★"
    : remaining + " song" + (remaining === 1 ? "" : "s") + " still hiding from you";

  let html = `<div class="sb-meter${complete ? " done" : ""}">
      <div class="cat-meter-head"><span>songs named correctly</span><span>${pct}%</span></div>
      <div class="cat-meter-num"><b>${discovered}</b> / ${total} songs</div>
      <div class="cat-bar">${albumRainbowSegs(byAlbum, total)}</div>
      <div class="sb-sub">${sub}</div>
    </div>`;

  // Album order = first appearance in allSongs (the catalogue order).
  const order = [];
  for (const s of allSongs) if (s.album && !order.includes(s.album)) order.push(s.album);
  html += order.map((album) => {
    const songs = allSongs.filter((s) => s.album === album);
    const got = songs.filter((s) => found[s.title]).length;
    const albDone = got === songs.length;
    const col = albumColor(album) || "var(--ink-soft)";
    const items = songs.map((s) => {
      const has = !!found[s.title];
      return `<li class="sb-song${has ? " got" : ""}">` +
        (has ? `<span class="sb-tick">${STAR_SVG}</span>` : `<span class="sb-hollow" aria-hidden="true"></span>`) +
        `<span class="sb-title">${escapeHtml(censor(s.title))}</span></li>`;
    }).join("");
    return `<section class="sb-album${albDone ? " done" : ""}">
      <div class="sb-album-head">
        <span class="sb-spine" style="background:${col}"></span>
        <span class="sb-album-name">${escapeHtml(album)}</span>
        <span class="sb-album-count">${albDone ? `<span class="sb-done-tag">all found ✓</span>` : got + " / " + songs.length}</span>
      </div>
      <ul class="sb-list">${items}</ul>
    </section>`;
  }).join("");

  $("songbookBody").innerHTML = html;
}

/* ---------- Personal records (your own best runs, per mode) ---------- */
function recordDateLabel(date) {
  // Accepts both legacy date-only ("YYYY-MM-DD") and full ISO timestamps.
  return date
    ? new Date(date.slice(0, 10) + "T00:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" })
    : "—";
}
// Completion time (seconds) → "m:ss". null when the mode has no clock.
function fmtTime(sec) {
  if (sec == null) return null;
  const s = Math.round(sec);
  return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0");
}
// Time of day in the player's chosen clock format (settings.clock: "12" | "24").
// One resolver behind every clock-time surface, so a future one just calls this.
function fmtClock(date) {
  return date.toLocaleTimeString("en-US", {
    hour: settings.clock === "24" ? "2-digit" : "numeric",
    minute: "2-digit",
    hour12: settings.clock !== "24",
  });
}
// Human label for a board-mode token: "medium" → "Normal", "inf-3lives-easy" →
// "3 lives · Easy", "daily" → "Daily".
function modeLabel(token) {
  if (token === "daily") return "Daily";
  if (token && token.startsWith("chl-")) {
    const c = CHALLENGE_BY_ID[token.slice(4)];
    return c ? "Challenge · " + c.name : "Challenge";
  }
  if (token && token.startsWith("af-")) return "Album · " + token.slice(3);
  if (token && token.startsWith("rl-")) {
    const l = ruthlessLens(token.slice(3));
    return l ? "Ruthless · " + l.label : "Ruthless";
  }
  if (token === "adaptive") return "Adaptive";
  if (token && token.startsWith("inf-")) {
    const parts = token.split("-");   // ["inf", variant, mode]
    return (VARIANT_LABELS[parts[1]] || parts[1]) + " · " + (MODES[parts[2]] ? MODES[parts[2]].label : parts[2]);
  }
  return MODES[token] ? MODES[token].label : (token || "—");
}
const isInfiniteToken = (token) => !!token && token.startsWith("inf-");
const isAdaptiveToken = (token) => token === "adaptive";
const isRuthlessToken = (token) => !!token && token.startsWith("rl-");
// Compact "your best" line for a single mode (start screen + results). Shows the
// mode's top personal record, or a target line if you've never finished a run in it.
function renderBestLine(el, mode) {
  let rec = loadRecords(mode)[0];
  if (!rec && !isInfiniteToken(mode) && MODES[mode]) {
    const best = loadStats(mode).best;
    if (best > 0) rec = { score: best, date: null };
  }
  if (!rec) {
    el.innerHTML = `<div class="best-empty">no runs yet — set your first record <span class="best-empty-star">${STAR_SVG}</span></div>`;
    return;
  }
  const unit = isInfiniteToken(mode) ? " rounds" : " / " + TOTAL_ROUNDS;
  const timePart = rec.time != null ? " · " + fmtTime(rec.time) : "";
  el.innerHTML =
    `<div class="best-line"><span class="best-num">${rec.score}<span class="best-unit">${unit}</span></span>` +
    `<span class="best-meta">★ best · ${escapeHtml(modeLabel(mode))}${timePart}${rec.date ? " · " + recordDateLabel(rec.date) : ""}</span></div>`;
}

/* ---------- Records page (personal-best tiles + run history) ---------- */
const HISTORY_PAGE = 20;          // history rows revealed per "load more"
let historyShown = 0;             // rows currently rendered
let recordsBackTarget = "start";  // where ← back returns to
let _pbByMode = {};               // per-mode best, for crowning history rows

// Best daily score ever (daily runs don't live in the per-mode records store).
function dailyBest() {
  let best = 0;
  for (const h of loadHistory()) if (h.t === "daily" && h.s > best) best = h.s;
  return best;
}
// Accent colour for a record tile — classic mode, infinite token (borrows its
// difficulty), or daily (the red margin rule).
function modeAccent(token) {
  if (token === "daily") return "#b23a3a";
  const base = isInfiniteToken(token) ? token.split("-")[2] : token;
  return MODE_COLORS[base] || "var(--ink-accent)";
}
function pbTile(mode, opts = {}) {
  const rec = opts.score != null ? { score: opts.score, date: null } : loadRecords(mode)[0];
  const empty = !rec || rec.score == null;
  const isInf = isInfiniteToken(mode);
  const unit = isInf ? "" : "/" + TOTAL_ROUNDS;
  // Infinite tiles split the label into a small variant kicker + the difficulty;
  // the sudden-death variant gets a distinct tape tint so the two read apart.
  let kicker = "", label = opts.label || modeLabel(mode), sudden = false;
  if (isInf) {
    const parts = mode.split("-");                 // ["inf", variant, modeid]
    kicker = VARIANT_LABELS[parts[1]] || parts[1];
    label = MODES[parts[2]] ? MODES[parts[2]].label : parts[2];
    sudden = parts[1] === "sudden";
  }
  let sub = opts.sub;
  if (!sub) {
    if (!rec) sub = "no runs yet";
    else {
      const parts = [];
      if (isInf) parts.push("rounds");
      if (rec.time != null) parts.push(fmtTime(rec.time));
      if (rec.date) parts.push(recordDateLabel(rec.date));
      sub = parts.length ? parts.join(" · ") : "—";
    }
  }
  const cls = "pb-tile" + (empty ? " pb-empty" : "") + (isInf ? " pb-inf" : "") +
    (sudden ? " pb-sudden" : "") + (mode === "daily" ? " pb-daily" : "");
  return `<div class="${cls}" style="--pb-accent:${modeAccent(mode)}">` +
    (kicker ? `<span class="pb-kicker">${escapeHtml(kicker)}</span>` : "") +
    `<span class="pb-mode">${escapeHtml(label)}</span>` +
    `<span class="pb-score">${empty ? "—" : rec.score + (unit ? `<span class="pb-unit">${unit}</span>` : "")}</span>` +
    `<span class="pb-sub">${escapeHtml(sub)}</span></div>`;
}
function histDateLabel(iso) {
  const d = new Date(iso);
  return d.toLocaleDateString("en-US", { day: "numeric", month: "short" }) + " · " +
         d.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit", hour12: false });
}
function appendHistoryRows(hist) {
  const rowsEl = $("histRows");
  if (!rowsEl) return;
  const next = hist.slice(historyShown, historyShown + HISTORY_PAGE);
  rowsEl.insertAdjacentHTML("beforeend", next.map((h) => {
    const adaptive = isAdaptiveToken(h.m);
    // A Ruthless row is the one whose score is not out of thirteen: it counts the pages NAMED
    // out of the ten the run dealt, and its RECORD is the time in the next column over.
    const ruthless = isRuthlessToken(h.m);
    const unit = (isInfiniteToken(h.m) || adaptive) ? "" : "/" + (ruthless ? (h.n || BONUS_ROUNDS) : TOTAL_ROUNDS);
    const scoreText = adaptive ? `<span class="lvl-prefix">L</span>${h.s}` : "" + h.s;
    // ...so the crown has to be won on the time, and won LOW. Crowning ten-out-of-ten would
    // crown most rows of a lens and say nothing about which run was the good one.
    const isPB = ruthless
      ? h.tm != null && h.tm === ruthlessRecord(h.m.slice(3)).best
      : h.s > 0 && h.s === _pbByMode[h.m];
    return `<div class="hist-row${isPB ? " hist-pb" : ""}">` +
      `<span class="hist-score">${isPB ? `<span class="hist-crown" aria-hidden="true">${ACH_ICONS.crown}</span>` : ""}${scoreText}${unit ? `<span class="hist-unit">${unit}</span>` : ""}</span>` +
      `<span class="hist-time">${h.tm != null ? fmtTime(h.tm) : "—"}</span>` +
      `<span class="hist-verse">${h.v > 0 ? `<span class="hist-verse-star" aria-hidden="true">★</span>+${h.v}` : "—"}</span>` +
      // `dk` marks a challenge run played on its dark side. It rides as a violet eclipse
      // rather than a word because modeLabel is deliberately token-only (the dark flag is
      // not a token suffix — see the appendHistory call in endChallenge) and because the
      // mode column is the tightest one in the row.
      `<span class="hist-mode">${escapeHtml(modeLabel(h.m))}` +
        `${h.dk ? `<span class="hist-dark" title="dark side" aria-label="dark side">${CHALL_ECLIPSE}</span>` : ""}</span>` +
      `<span class="hist-date">${histDateLabel(h.d)}</span></div>`;
  }).join(""));
  historyShown += next.length;
  const more = $("histMore");
  if (more && historyShown >= hist.length) more.style.display = "none";
}

/* ---------- Records calendar heatmap (games played per day / per hour) ----------
   A GitHub-style contribution grid. Data comes entirely from the run history log —
   each entry's ISO datetime, bucketed by the player's active timezone so squares land
   on their local calendar day/hour (consistent with the daily challenge). Gold "ink
   density" = games played: faint = none, deepening to solid for a heavy day. The grid
   fills the full content width (JS sizes the cells from the measured width so they stay
   square and the day labels line up exactly with the rows). */
const HEAT_GAP = 3;                          // px gap between squares
const HEAT_FILL = ["rgba(43,39,34,0.09)", "rgba(200,149,31,0.30)", "rgba(200,149,31,0.56)", "rgba(200,149,31,0.80)", "#a9791f"];
const MON_ABBR = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
const WD_ABBR = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];   // indexed by getUTCDay
const HEAT_HOURS = { 0: "12a", 6: "6a", 12: "12p", 18: "6p", 23: "11p" };
let _heatView = null;            // "y1" | "ytd" | "m1" | "wk"; null until the adaptive default is picked
let _heatResizeWired = false;    // window-resize listener attached once

// An ISO datetime → the player's local calendar-day key / hour, in the active zone.
function localDayKeyOf(iso) {
  try { return new Date(iso).toLocaleDateString("en-CA", { timeZone: activeTimeZone() }); }
  catch (e) { return String(iso).slice(0, 10); }
}
function localHourOf(iso) {
  try {
    const p = new Intl.DateTimeFormat("en-GB", { timeZone: activeTimeZone(), hour12: false, hour: "2-digit" }).formatToParts(new Date(iso));
    return (+(p.find((x) => x.type === "hour")?.value) || 0) % 24;
  } catch (e) { return new Date(iso).getHours(); }
}
// Pure date-string math on a UTC anchor — stable, no zone drift (keys are "YYYY-MM-DD").
function keyPlus(key, n) { const d = new Date(key + "T00:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
function keyMinus(key, n) { return keyPlus(key, -n); }
function keyDiff(a, b) { return Math.round((new Date(a + "T00:00:00Z") - new Date(b + "T00:00:00Z")) / 864e5); }
function keyDow(key) { return new Date(key + "T00:00:00Z").getUTCDay(); }      // 0=Sun..6=Sat
function keyMonth(key) { return new Date(key + "T00:00:00Z").getUTCMonth(); }
function heatPrettyDate(key) {
  try { return new Date(key + "T00:00:00Z").toLocaleDateString("en-GB", { timeZone: "UTC", weekday: "short", day: "numeric", month: "short" }); }
  catch (e) { return key; }
}
function hourLabel(h) { const ap = h < 12 ? "am" : "pm"; let hr = h % 12; if (hr === 0) hr = 12; return hr + ap; }

// Mon-start (default) puts Monday on row 0; Sun-start puts Sunday on row 0.
function heatRow(key) { const d = keyDow(key); return settings.weekStart === "sun" ? d : (d + 6) % 7; }
function dowLabels() { return settings.weekStart === "sun" ? ["sun", "mon", "tue", "wed", "thu", "fri", "sat"] : ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]; }
// Games played per local day, across the whole history log.
function heatDayCounts() {
  const m = Object.create(null);
  for (const h of loadHistory()) { const k = localDayKeyOf(h.d); m[k] = (m[k] || 0) + 1; }
  return m;
}
function heatLevel(c, max) { if (c <= 0) return 0; if (max <= 4) return Math.min(4, c); return Math.min(4, Math.ceil(c / (max / 4))); }
// >1 month of history → default to the year; otherwise the compact 30-day view.
function heatDefaultView() {
  const hist = loadHistory();
  if (!hist.length) return "m1";
  return keyDiff(todayKey(), localDayKeyOf(hist[hist.length - 1].d)) > 30 ? "y1" : "m1";
}

function heatSectionHTML() {
  const opts = [["y1", "last 12 months"], ["ytd", todayKey().slice(0, 4)], ["m1", "last 30 days"], ["wk", "last 7 days · by hour"]];
  const optHTML = opts.map(([v, l]) => `<option value="${v}"${v === _heatView ? " selected" : ""}>${escapeHtml(l)}</option>`).join("");
  const legend = [0, 1, 2, 3, 4].map((l) => `<i style="background:${HEAT_FILL[l]}"></i>`).join("");
  return `<p class="rec-group-label">calendar: games played</p>` +
    `<div class="heat-wrap">` +
      `<div class="heat-controls">` +
        `<select id="heatRange" class="heat-select" aria-label="calendar timeframe">${optHTML}</select>` +
        `<div class="heat-legend"><span>less</span>${legend}<span>more</span></div>` +
      `</div>` +
      `<div id="heatBody"></div>` +
      `<div id="heatFoot" class="heat-foot"></div>` +
    `</div>`;
}

function setHeatFoot(view, total, days) {
  const f = $("heatFoot"); if (!f) return;
  const g = (n) => `${n} game${n === 1 ? "" : "s"}`;
  let msg;
  if (total === 0) msg = view === "m1" ? `no games yet this month — <b>play to start filling your calendar</b>` : `nothing logged here yet — <b>play a round to begin</b>`;
  else if (view === "y1") msg = `<b>${g(total)}</b> across <b>${days} day${days === 1 ? "" : "s"}</b>, darker means more games`;
  else if (view === "ytd") msg = `<b>${g(total)}</b> so far in ${todayKey().slice(0, 4)}`;
  else msg = `<b>${g(total)}</b> over the last 30 days`;
  f.innerHTML = msg;
}

function renderDailyHeat(body, view) {
  const today = todayKey();
  const counts = heatDayCounts();
  let rangeStart;
  if (view === "y1") rangeStart = keyMinus(today, 364);
  else rangeStart = today.slice(0, 4) + "-01-01";                       // ytd: counts up from 1 Jan
  const gridStart = keyMinus(rangeStart, heatRow(rangeStart));          // back up to the week-start boundary
  const weeks = Math.floor(keyDiff(today, gridStart) / 7) + 1;

  let max = 0, total = 0, daysPlayed = 0;
  for (let w = 0; w < weeks; w++) for (let r = 0; r < 7; r++) {
    const key = keyPlus(gridStart, w * 7 + r);
    if (keyDiff(today, key) < 0 || keyDiff(key, rangeStart) < 0) continue;   // future / before range
    const c = counts[key] || 0;
    if (c > max) max = c;
    if (c > 0) { total += c; daysPlayed++; }
  }

  const cells = [], months = []; let lastMonth = -1;
  for (let w = 0; w < weeks; w++) {
    const topKey = keyPlus(gridStart, w * 7);
    const repKey = keyDiff(topKey, rangeStart) < 0 ? rangeStart : topKey;     // don't label a pre-range month
    const m = keyMonth(repKey);
    if (m !== lastMonth) { months.push(`<span style="left:${(w / weeks * 100).toFixed(3)}%">${MON_ABBR[m]}</span>`); lastMonth = m; }
    for (let r = 0; r < 7; r++) {
      const key = keyPlus(gridStart, w * 7 + r);
      if (keyDiff(today, key) < 0 || keyDiff(key, rangeStart) < 0) { cells.push(`<div class="heat-cell" style="background:transparent"></div>`); continue; }
      const c = counts[key] || 0;
      cells.push(`<div class="heat-cell" title="${c} game${c === 1 ? "" : "s"} · ${heatPrettyDate(key)}" style="background:${HEAT_FILL[heatLevel(c, max)]};border:0.5px solid rgba(43,39,34,0.10)"></div>`);
    }
  }

  const labels = dowLabels();
  const dayLabelHTML = [0, 2, 4].map((r) => `<span style="grid-row:${r + 1}">${labels[r]}</span>`).join("");
  const prov = 11;                                                       // provisional cell px until fitHeatGrid measures
  body.innerHTML =
    `<div class="heat-row">` +
      `<div class="heat-side"><div class="heat-corner" style="height:15px"></div>` +
        `<div class="heat-days" id="heatDays" style="grid-template-rows:repeat(7,${prov}px)">${dayLabelHTML}</div></div>` +
      `<div class="heat-main">` +
        `<div class="heat-months" style="height:15px">${months.join("")}</div>` +
        `<div class="heat-grid" id="heatGrid" data-view="${view}" data-weeks="${weeks}" style="grid-auto-flow:column;grid-template-columns:repeat(${weeks},1fr);grid-template-rows:repeat(7,${prov}px)">${cells.join("")}</div>` +
      `</div>` +
    `</div>`;
  setHeatFoot(view, total, daysPlayed);
  fitHeatGrid();
}

// The 30-day view renders as a single full-width strip (one row of 30 days, today on the
// right) rather than a 7×5 calendar block — 5 calendar columns capped to square cells left a
// lot of empty space on the right. Month markers ride the top where the month changes; the
// weekday axis is dropped (thin at this range). fitHeatGrid sizes the row to keep cells square.
function renderMonthStrip(body) {
  const today = todayKey();
  const counts = heatDayCounts();
  const DAYS = 30;
  const start = keyMinus(today, DAYS - 1);
  let max = 0, total = 0, daysPlayed = 0;
  for (let i = 0; i < DAYS; i++) {
    const c = counts[keyPlus(start, i)] || 0;
    if (c > max) max = c;
    if (c > 0) { total += c; daysPlayed++; }
  }
  const months = [], cells = []; let lastMonth = -1;
  for (let i = 0; i < DAYS; i++) {
    const key = keyPlus(start, i);
    const m = keyMonth(key);
    if (m !== lastMonth) { months.push(`<span style="left:${(i / DAYS * 100).toFixed(3)}%">${MON_ABBR[m]}</span>`); lastMonth = m; }
    const c = counts[key] || 0;
    cells.push(`<div class="heat-cell" title="${c} game${c === 1 ? "" : "s"} · ${heatPrettyDate(key)}" style="background:${HEAT_FILL[heatLevel(c, max)]};border:0.5px solid rgba(43,39,34,0.10)"></div>`);
  }
  body.innerHTML =
    `<div class="heat-strip">` +
      `<div class="heat-months" style="height:15px">${months.join("")}</div>` +
      `<div class="heat-grid" id="heatGrid" data-view="m1" data-strip="1" data-days="${DAYS}" style="grid-auto-flow:column;grid-template-columns:repeat(${DAYS},1fr);grid-template-rows:11px">${cells.join("")}</div>` +
      `<div class="heat-strip-ends"><span>${heatPrettyDate(start)}</span><span>today</span></div>` +
    `</div>`;
  setHeatFoot("m1", total, daysPlayed);
  fitHeatGrid();
}

function renderWeekHeat(body) {
  const today = todayKey();
  const nowHour = localHourOf(new Date().toISOString());
  const counts = Object.create(null);
  for (const h of loadHistory()) {
    const dk = localDayKeyOf(h.d);
    if (keyDiff(today, dk) > 6 || keyDiff(today, dk) < 0) continue;     // outside the rolling 7-day window
    const k = dk + "|" + localHourOf(h.d); counts[k] = (counts[k] || 0) + 1;
  }
  let max = 0, total = 0;
  for (let d = 0; d < 7; d++) { const dk = keyMinus(today, 6 - d); for (let h = 0; h < 24; h++) { if (dk === today && h > nowHour) continue; const c = counts[dk + "|" + h] || 0; if (c > max) max = c; total += c; } }

  const colLabels = [];
  for (let d = 0; d < 7; d++) colLabels.push(`<span>${WD_ABBR[keyDow(keyMinus(today, 6 - d))]}</span>`);
  const hourLabelHTML = [0, 6, 12, 18, 23].map((h) => `<span style="grid-row:${h + 1}">${HEAT_HOURS[h]}</span>`).join("");
  const cells = [];
  for (let d = 0; d < 7; d++) {
    const dk = keyMinus(today, 6 - d);
    for (let h = 0; h < 24; h++) {
      if (dk === today && h > nowHour) { cells.push(`<div class="heat-cell" style="background:transparent"></div>`); continue; }
      const c = counts[dk + "|" + h] || 0;
      cells.push(`<div class="heat-cell" title="${c} game${c === 1 ? "" : "s"} · ${heatPrettyDate(dk)} ${hourLabel(h)}" style="background:${HEAT_FILL[heatLevel(c, max)]};border:0.5px solid rgba(43,39,34,0.10)"></div>`);
    }
  }
  const CH = 12;
  body.innerHTML =
    `<div class="heat-row">` +
      `<div class="heat-side"><div class="heat-corner" style="height:16px"></div>` +
        `<div class="heat-hours" style="grid-template-rows:repeat(24,${CH}px);gap:${HEAT_GAP}px">${hourLabelHTML}</div></div>` +
      `<div class="heat-main">` +
        `<div class="heat-cols" style="grid-template-columns:repeat(7,1fr);gap:${HEAT_GAP}px;height:16px">${colLabels.join("")}</div>` +
        `<div class="heat-grid" id="heatGrid" data-view="wk" style="grid-auto-flow:column;grid-template-columns:repeat(7,1fr);grid-template-rows:repeat(24,${CH}px);gap:${HEAT_GAP}px">${cells.join("")}</div>` +
      `</div>` +
    `</div>`;
  const f = $("heatFoot");
  if (f) f.innerHTML = total ? `<b>${total} game${total === 1 ? "" : "s"}</b> in the last 7 days — busiest hours are darkest` : `nothing in the last 7 days — <b>play to light up your week</b>`;
}

function renderHeatBody() {
  const body = $("heatBody"); if (!body) return;
  if (_heatView === "wk") renderWeekHeat(body);
  else if (_heatView === "m1") renderMonthStrip(body);
  else renderDailyHeat(body, _heatView);
  const sel = $("heatRange"); if (sel) sel.value = _heatView;
}
// Size the daily grid to the full content width: square cells + matching day-label rows.
// Dense ranges (12 months, year) fill the width with small cells. The 30-day view is a single
// full-width strip (data-strip) — its one row is sized square from the column width. Any range
// wide enough to exceed HEAT_CELL_MAX is capped+left-aligned so squares don't balloon. The
// month-label strip is pinned to the grid's actual width either way so labels stay aligned.
// Retries on rAF while the width reads 0 (the records screen is hidden during the initial
// render, so the first measurement after showScreen can still be mid-layout).
const HEAT_CELL_MAX = 30;   // sparse ranges cap here (left-aligned)
const HEAT_CELL_MIN = 6;    // dense ranges on a narrow screen floor here (row scrolls)
function fitHeatGrid(retries = 10) {
  const grid = $("heatGrid"); if (!grid || grid.dataset.view === "wk") return;
  const w = grid.clientWidth;
  if (!w) { if (retries > 0) requestAnimationFrame(() => fitHeatGrid(retries - 1)); return; }
  if (grid.dataset.strip) {                                            // 30-day strip: square the single row to the 1fr column width
    const days = +grid.dataset.days || 30;
    grid.style.gridTemplateRows = `${(w - (days - 1) * HEAT_GAP) / days}px`;
    return;
  }
  const weeks = +grid.dataset.weeks || 1;
  const full = (w - (weeks - 1) * HEAT_GAP) / weeks;
  // Three regimes: cap big (sparse → left-aligned), floor small (dense+narrow → fixed px, the
  // row scrolls), else fill the width exactly with 1fr columns. Fixed-width keeps cells square.
  let cell, fixed;
  if (full > HEAT_CELL_MAX) { cell = HEAT_CELL_MAX; fixed = true; }
  else if (full < HEAT_CELL_MIN) { cell = HEAT_CELL_MIN; fixed = true; }
  else { cell = full; fixed = false; }
  grid.style.gridTemplateColumns = fixed ? `repeat(${weeks},${cell}px)` : `repeat(${weeks},1fr)`;
  grid.style.gridTemplateRows = `repeat(7,${cell}px)`;
  const days = $("heatDays"); if (days) days.style.gridTemplateRows = `repeat(7,${cell}px)`;
  const months = grid.parentElement.querySelector(".heat-months");
  if (months) months.style.width = fixed ? `${weeks * cell + (weeks - 1) * HEAT_GAP}px` : "";
}

/* ---------- Profile polaroid (a photo tucked into the notebook) ---------- */
const POL_CAMERA_SVG = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 8h3l1.4-2h5.2L16 8h3a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1z"/><circle cx="12" cy="13" r="3.2"/></svg>`;
const POL_CLIP_SVG = `<svg class="pol-clip" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15.5 7.5l-6.8 6.8a2.4 2.4 0 0 0 3.4 3.4l7.1-7.1a4 4 0 0 0-5.66-5.66l-7.1 7.1"/></svg>`;

// One polaroid — a photo (data-URL) clipped to the page, or the empty
// "add a photo" slot when `photo` is "". `caption` rides the white lip;
// `tilt`/`small` tune the look. The washi tape colour is era-tinted in CSS.
function polaroidHTML(photo, caption, opts = {}) {
  const tilt = opts.tilt != null ? opts.tilt : -4;
  const cap = (caption || "").trim();

  // Keepsake variant — a collectible polaroid carrying SVG art (not a photo data-URL), a
  // two-line caption, and one of three develop states. It shares the frame, washi tape and
  // tilt with the profile polaroid below; only the photo well and caption block differ.
  //   locked     — never earned: a plain black rectangle, no frame or caption (a sealed mystery).
  //   developing — earned <13min ago: the photo under a black veil that is still fading up.
  //   developed  — earned 13min+ ago: the fully cleared photo + both caption lines.
  if (opts.keepsake) {
    const state = opts.state || "locked";
    if (state === "locked") {
      return `<span class="keep-locked${opts.small ? " keep-locked-sm" : ""}" style="--tilt:${tilt}deg" aria-hidden="true"></span>`;
    }
    const cls = "polaroid polaroid-keep is-" + state + (opts.small ? " polaroid-sm" : "");
    // Instant film: the photo sits under a black veil whose opacity slides from 1 (just
    // unlocked) to 0 across POLAROID_DEVELOP_MS. `elapsed` drives a linear CSS animation
    // (a live, continuous fade via negative delay) AND a static opacity fallback that
    // takes over when the animation is off (reduced motion).
    const total = POLAROID_DEVELOP_MS;
    const elapsed = Math.max(0, opts.elapsed || 0);
    const frac = Math.max(0, Math.min(1, 1 - elapsed / total));
    const veil = `<span class="pol-veil" style="opacity:${frac.toFixed(3)};` +
      `animation-duration:${Math.round(total / 1000)}s;animation-delay:-${Math.round(elapsed / 1000)}s"></span>`;
    const well = `<span class="pol-photo pol-art">${opts.art || ""}${veil}</span>`;
    const lines = `<span class="pol-lip-main">${escapeHtml(cap)}</span>` +
      (state === "developed" && opts.sub ? `<span class="pol-lip-sub">${escapeHtml(opts.sub)}</span>` : "");
    return `<span class="${cls}" style="--tilt:${tilt}deg">` +
      `<span class="pol-tape" aria-hidden="true"></span>` +
      well +
      `<span class="pol-cap">${lines}</span></span>`;
  }

  const cls = "polaroid" + (photo ? "" : " is-empty") + (opts.small ? " polaroid-sm" : "");
  if (photo) {
    return `<span class="${cls}" style="--tilt:${tilt}deg">` +
      `<span class="pol-tape" aria-hidden="true"></span>` +
      `<span class="pol-photo" style="background-image:url('${photo}')"></span>` +
      `<span class="pol-lip">${escapeHtml(cap)}</span></span>`;
  }
  return `<span class="${cls}" style="--tilt:${tilt}deg">${POL_CLIP_SVG}` +
    `<span class="pol-photo pol-add">${POL_CAMERA_SVG}</span>` +
    `<span class="pol-lip">add a photo</span></span>`;
}

/* ---------- Keepsakes: the collectible polaroid set (see js/polaroids.js) ---------- */
// A polaroid develops like real instant film: solid black on unlock, the photo fading in
// POLAROID_DEVELOP_MS (13 min) later. "developed" is DERIVED from the stored unlock time at
// render, never a running timer — so it survives reloads/closes and self-heals.
function polaroidDeveloped(iso) {
  if (!iso) return false;
  const t = Date.parse(iso);
  return Number.isFinite(t) && (Date.now() - t) >= POLAROID_DEVELOP_MS;
}
// "locked" (not earned) | "developing" (earned, still black) | "developed" (earned, 13min+).
function polaroidState(id, earned) {
  const map = earned || loadKeepsakes();
  const iso = map[id];
  if (!iso) return "locked";
  return polaroidDeveloped(iso) ? "developed" : "developing";
}
// Build a keepsake tile for polaroid `p` at its current develop state. `small` shrinks it.
// `elapsed` (ms since unlock) drives the develop veil's live fade.
function keepsakePolaroidHTML(p, opts = {}) {
  const earned = opts.earned || loadKeepsakes();
  const state = opts.state || polaroidState(p.id, earned);
  const iso = earned[p.id];
  const elapsed = iso ? Date.now() - Date.parse(iso) : 0;
  return polaroidHTML(null, p.name, { keepsake: true, state, elapsed, art: p.art, sub: p.sub, tilt: opts.tilt, small: opts.small });
}
// Re-render the Keepsakes wall if its modal is currently open (otherwise a no-op).
function refreshKeepsakes() {
  if ($("keepsakesModal") && $("keepsakesModal").classList.contains("open")) renderKeepsakesPage();
}
// Dev-only: grant `id` backdated `agoMs` milliseconds (0 = fresh/developing, >13min = developed).
function devSetKeepsake(id, agoMs) {
  if (!POLAROID_BY_ID[id]) return "unknown polaroid: " + id;
  const e = loadKeepsakes();
  e[id] = new Date(Date.now() - (agoMs || 0)).toISOString();
  saveKeepsakes(e);
  refreshKeepsakes();
  updateKeepsakesNav();
  return polaroidState(id);
}

// Earn a polaroid: persist the unlock time (which starts its 13-min develop clock), fire the
// "developing" toast, refresh the wall + nav counter, and check the collection meta. Idempotent
// — re-earning an owned polaroid is a no-op, so triggers can fire freely on every game.
function earnPolaroid(id) {
  const p = POLAROID_BY_ID[id];
  if (!p) return false;
  const earned = loadKeepsakes();
  if (earned[id]) return false;                      // already have it
  earned[id] = new Date().toISOString();
  saveKeepsakes(earned);
  showKeepsakeToast(p);
  updateKeepsakesNav();
  refreshKeepsakes();                                // if the wall is open, show it developing
  checkKeepsakeMeta(earned);
  return true;
}

// The keepsake unlock toast — a mini polaroid caught mid-develop (its art under a
// half-lifted black veil) beside the "new keepsake / {name} · developing" note.
function showKeepsakeToast(p) {
  const layer = $("toastLayer");
  if (!layer) return;
  const t = document.createElement("div");
  t.className = "toast toast-keepsake";
  const thumb = `<span class="pol-thumb" aria-hidden="true"><span class="pol-thumb-art">${p.art || ""}` +
    `<span class="pol-thumb-veil"></span></span></span>`;
  t.innerHTML = thumb +
    `<div><div class="t-label">new keepsake</div>` +
    `<div class="t-name">${escapeHtml(p.name)}</div>` +
    `<div class="t-sub">developing…</div></div>`;
  layer.appendChild(t);
  scheduleToastDismiss();
}

// You Took A Polaroid Of Us — every polaroid earned. Keys off what actually EXISTS (POLAROIDS),
// so it re-targets automatically as the set grows toward POLAROID_TOTAL and needs no migration.
function checkKeepsakeMeta(earned = loadKeepsakes()) {
  if (POLAROIDS.length && POLAROIDS.every((p) => earned[p.id])) unlock("you-took-a-polaroid-of-us");
}

// Song-discovery keepsakes — checked from every end-of-game tally (main + sandboxed paths),
// mirroring the i-hate-it-here discovery check. `tally.songs` keys are exact stored titles
// (TLGAD is lowercase), so match case-insensitively. Idempotent via earnPolaroid.
function checkSongKeepsakes(tally) {
  const found = (tally && tally.songs) || {};
  const has = (titleLc) => Object.keys(found).some((t) => t.toLowerCase() === titleLc);
  if (has("the last great american dynasty")) earnPolaroid("holiday-house");   // TLGAD → the Watch Hill house
  if (has("cornelia street")) earnPolaroid("cornelia-street");
  if (has("the fate of ophelia")) earnPolaroid("doughphelia");
  // Getting Married — every song with "love" in its title discovered.
  const love = allSongs.filter((s) => /\blove\b/i.test(s.title));
  if (love.length && love.every((s) => found[s.title])) earnPolaroid("getting-married");
}

// How many polaroids the player has earned (any develop state counts as "found").
function keepsakeCount(earned) {
  const map = earned || loadKeepsakes();
  return POLAROIDS.reduce((n, p) => n + (map[p.id] ? 1 : 0), 0);
}
// Keep the little count badge on the keepsakes icon current (hidden until the first is found).
function updateKeepsakesNav() {
  const n = keepsakeCount();
  document.querySelectorAll(".js-keepsakes-count").forEach((el) => {
    el.textContent = n ? String(n) : "";
    el.classList.toggle("is-empty", !n);
  });
}

// A stable per-polaroid tilt + vertical nudge so the wall reads as hand-pinned rather than
// gridded — deterministic (hashed from the id), so it never reshuffles between renders.
function polaroidJitter(id) {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) { h = Math.imul(h ^ id.charCodeAt(i), 16777619); }
  const rng = mulberry32(h >>> 0);
  const tilt = (rng() * 14 - 7).toFixed(2);  // -7deg .. +7deg — pinned any-old-how
  const dy = (rng() * 22 - 7).toFixed(1);    // -7px .. +15px
  const dx = (rng() * 16 - 8).toFixed(1);    // -8px .. +8px
  return { tilt, dy, dx };
}

// The Keepsakes modal — opened from the camera icon beside the settings gear. Reuses the
// settings-modal chrome (scrim + card + close), so it behaves like the other captive dialogs.
let lastFocusedBeforeKeepsakes = null;
function openKeepsakes() {
  lastFocusedBeforeKeepsakes = document.activeElement;
  renderKeepsakesPage();   // also schedules the develop watch
  const m = $("keepsakesModal");
  m.classList.add("open");
  m.setAttribute("aria-hidden", "false");
  document.body.classList.add("modal-open");
  const close = $("keepsakesCloseBtn");
  if (close) { try { close.focus({ preventScroll: true }); } catch (_) { close.focus(); } }
}
function closeKeepsakes() {
  const m = $("keepsakesModal");
  if (!m.classList.contains("open")) return;
  stopKeepsakeDevWatch();
  m.classList.remove("open");
  m.setAttribute("aria-hidden", "true");
  // Only unfreeze the page if no other modal is still holding it open.
  if (!$("settingsModal").classList.contains("open")) document.body.classList.remove("modal-open");
  const back = lastFocusedBeforeKeepsakes;
  lastFocusedBeforeKeepsakes = null;
  const target = (back && typeof back.focus === "function" && document.contains(back)) ? back : $("keepsakesGear");
  if (target) { try { target.focus({ preventScroll: true }); } catch (_) { target.focus(); } }
}

// The polaroid wall: a lead, the found counter, then the messy pinned grid. Every tile is a
// keepsake polaroid at its current develop state (blacked-out lock / developing / developed),
// pinned at its deterministic jitter so the wall reads hand-done rather than gridded.
function renderKeepsakesPage() {
  const body = $("keepsakesBody");
  if (!body) return;
  const earned = loadKeepsakes();
  const found = keepsakeCount(earned);

  const intro =
    `<p class="chall-eyebrow">Your keepsakes</p>` +
    `<p class="keep-lead">Polaroids from the notebook, earned by playing. A fresh one develops like real ` +
    `instant film, fading up from black over thirteen minutes, so give a new photo a while to come through.</p>`;

  const counter =
    `<div class="keep-counter"><span class="keep-counter-n">${found}</span>` +
    `<span class="keep-counter-d">/ ${POLAROID_TOTAL}</span>` +
    `<span class="keep-counter-l">pinned up</span></div>`;

  const tiles = POLAROIDS.map((p) => {
    const state = polaroidState(p.id, earned);
    const j = polaroidJitter(p.id);
    const label = state === "locked" ? "a keepsake not yet earned"
      : state === "developing" ? p.name + " (developing)" : p.name;
    return `<div class="keep-cell" data-id="${p.id}" data-state="${state}" style="--dy:${j.dy}px;--dx:${j.dx}px" title="${escapeHtml(label)}">` +
      keepsakePolaroidHTML(p, { earned, state, tilt: j.tilt, small: true }) + `</div>`;
  }).join("");

  body.innerHTML = intro + counter + `<div class="keep-grid">${tiles}</div>`;
  scheduleKeepsakeDevWatch();   // re-arm the develop watch for the next tile due to finish
}

// The photo veil fades continuously in pure CSS, so the only thing the watch still does is
// re-render when a tile crosses the 13-min line, to reveal its second caption line. One
// timeout for the soonest pending tile; none at all when nothing is developing. Derived from
// stored unlock times, so it never earns anything.
let keepsakeDevTimer = null;
function scheduleKeepsakeDevWatch() {
  stopKeepsakeDevWatch();
  const earned = loadKeepsakes();
  let soonest = Infinity;
  for (const p of POLAROIDS) {
    const iso = earned[p.id];
    if (!iso) continue;
    const left = Date.parse(iso) + POLAROID_DEVELOP_MS - Date.now();
    if (left > 0 && left < soonest) soonest = left;
  }
  if (!Number.isFinite(soonest)) return;   // nothing developing → no timer needed
  keepsakeDevTimer = setTimeout(() => {
    keepsakeDevTimer = null;
    if (!$("keepsakesModal").classList.contains("open")) return;
    renderKeepsakesPage();   // re-renders + reschedules for the next pending tile
  }, Math.min(soonest + 250, 0x7fffffff));
}
function stopKeepsakeDevWatch() {
  if (keepsakeDevTimer) { clearTimeout(keepsakeDevTimer); keepsakeDevTimer = null; }
}

// Read a chosen image file, center-crop it to a square and downscale it to a
// small JPEG data-URL (~kBs) so it sits comfortably in localStorage. No crop UI.
const AVATAR_SIZE = 240;
// `cb(url)` on success; `done()` always fires (success or failure) so the caller
// can tear down the file input only after the read finishes.
function processAvatarFile(file, cb, done) {
  const finish = () => { if (done) done(); };
  const fail = (msg) => { console.warn("avatar:", msg); notifyNote("couldn’t add that photo", "try a JPG or PNG image"); finish(); };
  if (!file) return fail("no file");
  // Don't hard-gate on file.type — Safari/iCloud sometimes report "" for a real
  // image. The picker's accept="image/*" already filters; let decode be the judge.
  if (file.type && !/^image\//.test(file.type)) return fail("not an image (" + file.type + ")");
  const reader = new FileReader();
  reader.onerror = () => fail("could not read the file");
  reader.onload = () => {
    const img = new Image();
    img.onerror = () => fail("could not decode the image");
    img.onload = () => {
      const side = Math.min(img.width, img.height);
      if (!side) return fail("image has no dimensions");
      const sx = (img.width - side) / 2, sy = (img.height - side) / 2;
      const c = document.createElement("canvas");
      c.width = c.height = AVATAR_SIZE;
      const ctx = c.getContext("2d");
      ctx.drawImage(img, sx, sy, side, side, 0, 0, AVATAR_SIZE, AVATAR_SIZE);
      let url;
      try { url = c.toDataURL("image/jpeg", 0.82); } catch (e) { return fail("encode failed: " + e); }
      cb(url);
      finish();
    };
    img.src = reader.result;
  };
  reader.readAsDataURL(file);
}

// Pop the native file picker, process the pick, hand the data-URL back.
// WebKit gotchas this avoids: a `display:none` (or fully off-screen) file input
// may not fire `change`, and removing the input before the async read finishes
// can invalidate the File. So the input is kept rendered (visually-hidden but
// in-viewport) and only removed once reading is done.
function chooseAvatar(cb) {
  const inp = document.createElement("input");
  inp.type = "file"; inp.accept = "image/*";
  inp.style.cssText = "position:fixed;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;";
  document.body.appendChild(inp);
  let picked = false;
  const cleanup = () => { if (inp.parentNode) inp.remove(); };
  inp.addEventListener("change", () => {
    picked = true;
    const f = inp.files && inp.files[0];
    if (!f) { cleanup(); return; }
    processAvatarFile(f, cb, cleanup);
  });
  // If the dialog is cancelled, no `change` fires — tidy up once focus returns.
  window.addEventListener("focus", () => setTimeout(() => { if (!picked) cleanup(); }, 500), { once: true });
  inp.click();
}

// Persist a new (or cleared) photo and refresh wherever it shows.
function applyAvatar(url) {
  settings.avatar = setAvatar(url);
  if (screens.records.classList.contains("active")) renderRecordsPage();
  if ($("settingsModal").classList.contains("open")) renderSettingsBody();
}

function renderRecordsPage() {
  if (_heatView === null) _heatView = heatDefaultView();
  const name = getPlayerName();
  const avatar = getAvatar();
  const title = wornTitleName();
  const titleHTML = (name && title) ? `<span class="rec-sig-title">${escapeHtml(title)}</span>` : "";
  const sigText = name
    ? `<span class="rec-sig-name">${escapeHtml(name)}’s notebook</span><span class="rec-sig-sub">best scores &amp; history</span>${titleHTML}`
    : `<div class="rec-sign-row"><input id="recSignInput" class="set-text" maxlength="20" placeholder="sign your notebook" autocomplete="off" spellcheck="false" data-1p-ignore data-lpignore="true" data-bwignore="true" data-protonpass-ignore="true" data-dashlane-ignore="true" data-form-type="other" /><button id="recSignSave" class="btn-ghost">sign</button></div>`;
  const sig =
    `<button type="button" id="recPolBtn" class="rec-pol-btn" aria-label="${avatar ? "change your photo" : "add a photo"}">${polaroidHTML(avatar, name)}</button>` +
    `<div class="rec-sig-text">${sigText}</div>`;

  // Personal bests — classic difficulties always shown; infinite/daily only if played.
  const classicTiles = MODE_ORDER.map((m) => pbTile(m)).join("");
  const infTokens = [];
  for (const v of ["3lives", "sudden"]) for (const m of MODE_ORDER) {
    const tok = "inf-" + v + "-" + m;
    if (loadRecords(tok).length) infTokens.push(tok);
  }
  const infBlock = infTokens.length
    ? `<p class="rec-group-label">infinite — rounds survived</p><div class="pb-grid pb-grid-inf">${infTokens.map((t) => pbTile(t)).join("")}</div>`
    : "";
  const db = dailyBest();
  const streak = effectiveDailyStreak(todayKey());
  const dailyBlock = (db > 0 || streak.best > 0)
    ? `<p class="rec-group-label">daily</p><div class="pb-grid">` +
        pbTile("daily", { label: "Daily best", score: db, sub: `🔥 ${streak.current} day streak · best ${streak.best}` }) +
      `</div>`
    : "";

  // Verse bonus — the prestige metric's lifetime keepsake (best run + word-perfect totals).
  const vm = loadMetrics();
  const verseBlock = vm.bestVerseBonus > 0
    ? `<p class="rec-group-label">verse bonus</p><div class="pb-grid">` +
        `<div class="pb-tile pb-verse" style="--pb-accent:var(--bead)">` +
          `<span class="pb-mode">Best in a game</span>` +
          `<span class="pb-score">+${vm.bestVerseBonus}</span>` +
          `<span class="pb-sub">${vm.versePerfect} word-perfect · ${vm.wholeVerses} whole verse${vm.wholeVerses === 1 ? "" : "s"}</span>` +
        `</div></div>`
    : "";

  // Dark sides — hidden until one is beaten, so a fresh notebook stays clean. Counts
  // DARK_SIDE_IDS, so the "of N" re-targets itself as more dark sides get authored.
  const darkBeaten = DARK_SIDE_IDS.filter((k) => challengeRecord(k).darkDefeated).length;
  const darkBlock = darkBeaten > 0
    ? `<p class="rec-group-label">dark sides</p><div class="pb-grid">` +
        `<div class="pb-tile" style="--pb-accent:#7a4bb0">` +
          `<span class="pb-mode">Dark sides beaten</span>` +
          `<span class="pb-score">${darkBeaten}</span>` +
          `<span class="pb-sub">of ${DARK_SIDE_IDS.length}</span>` +
        `</div></div>`
    : "";

  const hist = loadHistory();
  _pbByMode = {};
  for (const h of hist) if (!(h.m in _pbByMode)) _pbByMode[h.m] = h.m === "daily" ? db : h.m === "adaptive" ? (adaptiveRecord().bestPeak || -1) : (loadRecords(h.m)[0] ? loadRecords(h.m)[0].score : -1);
  const histBlock = hist.length
    ? `<p class="rec-group-label">history — ${hist.length} run${hist.length === 1 ? "" : "s"}</p>` +
      `<div class="hist-head"><span>score</span><span>time</span><span>verse</span><span>mode</span><span>date</span></div>` +
      `<div id="histRows" class="hist-rows"></div>` +
      (hist.length > HISTORY_PAGE ? `<button id="histMore" class="btn-ghost">load more</button>` : "")
    : `<p class="rec-group-label">history</p><p class="stats-empty">no runs yet — finish a game to start your log.</p>${playCTA()}`;

  $("recordsBody").innerHTML =
    `<div class="rec-sig">${sig}</div>` +
    `<p class="rec-group-label">personal bests</p><div class="pb-grid">${classicTiles}</div>` +
    infBlock + dailyBlock + verseBlock + darkBlock + heatSectionHTML() + histBlock;

  renderHeatBody();
  const heatSel = $("heatRange");
  if (heatSel) heatSel.addEventListener("change", () => { _heatView = heatSel.value; renderHeatBody(); });
  if (!_heatResizeWired) { _heatResizeWired = true; window.addEventListener("resize", () => { if ($("heatGrid")) fitHeatGrid(); }); }

  const saveBtn = $("recSignSave");
  if (saveBtn) saveBtn.addEventListener("click", () => {
    const v = ($("recSignInput").value || "").trim().slice(0, 20);
    if (v) { settings.playerName = setPlayerName(v); checkPianoEgg(v); refreshStartBoard(); renderRecordsPage(); if ($("masteryBody")) renderMasteryPage(); }
  });
  const signInput = $("recSignInput");
  if (signInput) signInput.addEventListener("keydown", (e) => { if (e.key === "Enter") saveBtn.click(); });

  const polBtn = $("recPolBtn");
  if (polBtn) polBtn.addEventListener("click", () => chooseAvatar((url) => applyAvatar(url)));

  historyShown = 0;
  if (hist.length) appendHistoryRows(hist);
  const more = $("histMore");
  if (more) more.addEventListener("click", () => appendHistoryRows(hist));
}
function openRecords(from) {
  recordsBackTarget = from;
  renderRecordsPage();
  flipAwayToScreen("records");
  fitHeatGrid();                                   // now visible (display:block) → size to the real width
  requestAnimationFrame(() => fitHeatGrid());      // and again next frame, in case layout wasn't flushed
}
let achievementsBackTarget = "start";  // where the Charm Collection's ← back returns to
// `focus` is the one place a caller can ask to land somewhere other than the top of the charm
// collection: "secret" brings the trailing Secret section up, which is what the Mastery hints
// vault's door is for. The page has no inner scroller, so it's the window that moves.
function openAchievements(from, focus) {
  achievementsBackTarget = from;
  renderAchievementsPage();
  flipAwayToScreen("achievements");
  if (focus === "secret") {
    revealAfterFlip(() => document.getElementById("achSecretSection"), { pad: 18 });
  }
}
let masteryBackTarget = "start";       // where the Mastery page's ← back returns to
function openMastery(from, focus) {
  masteryBackTarget = from;
  _titleView = null;   // recenter the title stepper on the worn title each time the page opens
  renderMasteryPage();
  flipAwayToScreen("mastery");
  if (focus === "titles") scrollMasteryTitlesIntoView();
}

// The settings bookplate links to the place where its engraved title is chosen. The reward
// board is at the bottom of a long page, so wait for the page turn and its layout before
// placing the Prestige titles tile at the top of the viewport.
function scrollMasteryTitlesIntoView() {
  revealAfterFlip(() => document.querySelector("#masteryBody .rb-titles"), { pad: 18 });
}
// Keep the live indicator on the mastery nav-cards (both start + results) current: the
// Mastery level once unlocked, otherwise progress toward the unlock gate.
function updateMasteryNav() {
  const m = loadMastery();
  const text = isMasteryUnlocked(m)
    ? "mastery · level " + masteryLevelFromXp(m.masteryXp)
    : totalSkillLevels(m) + " / " + MASTERY_GATE + " to unlock";
  document.querySelectorAll(".js-mastery-kicker").forEach((el) => { el.textContent = text; });
}

// Mastery cosmetic kinds: which setting persists the choice, the payload field holding the
// value, and the labels for that kind's "reset to default" row. Pens swap the writing hand;
// papers retint the page surface. New cosmetic kinds (ink colours, etc.) drop in here.
const MASTERY_COSMETICS = {
  pen:       { setting: "masteryPen",       field: "pen",       resetLabel: "Default pen",    resetMeta: "the everyday hand", resetIcon: "nib" },
  paper:     { setting: "masteryPaper",     field: "paper",     resetLabel: "Plain paper",    resetMeta: "the everyday page" },
  charm:     { setting: "masteryCharm",     field: "charm",     resetLabel: "Star charm",     resetMeta: "the default keepsake" },
  button:    { setting: "masteryButton",    field: "button",    resetLabel: "Gold marker",    resetMeta: "the everyday button" },
  label:     { setting: "masteryLabel",     field: "label",     resetLabel: "Start writing", resetMeta: "the everyday words" },
};

// True once the level-10 "secret hints" milestone has been earned (reveals the how-to on
// still-locked secret charms in the achievements page). Derived from the unlocked map.
function hiddenHintsUnlocked() { return !!loadMastery().unlocked["reveal-hints"]; }

// The Mastery page: a headline rank, the five skills with their levels + progress, and the
// reward ladder (unlocked cosmetics are selectable; still-locked tiers read "locked").
function renderMasteryPage() {
  const body = $("masteryBody");
  if (!body) return;
  const m = loadMastery();
  const unlocked = isMasteryUnlocked(m);
  const total = totalSkillLevels(m);
  const mLevel = masteryLevelFromXp(m.masteryXp);

  // Headline — a notebook-card hero with three states: locked (the wax not yet
  // pressed), climbing (the ascent track), and complete (sealed at the cap).
  let head;
  if (unlocked && mLevel >= MASTERY_MAX_LEVEL) head = masteryHeadComplete(mLevel);
  else if (unlocked) head = masteryHeadClimb(m, mLevel);
  else head = masteryHeadLocked(total);

  // Skills — each a full-width row of SKILL_MAX_LEVEL "pips" (one per level) inked in the
  // skill's own tint, with the current level's pip part-filled to progress toward the next.
  // A maxed skill overrides its tint to gold.
  const GOLD_TINT = "199, 149, 31";
  const skills = SKILLS.map((sk) => {
    const xp = m.skills[sk.id] || 0;
    const lvl = skillLevelFromXp(xp);
    const maxed = lvl >= SKILL_MAX_LEVEL;
    const cur = skillXpForLevel(lvl), next = skillXpForLevel(lvl + 1);
    const frac = maxed ? 1 : Math.max(0, Math.min(1, (xp - cur) / (next - cur)));
    const tint = maxed ? GOLD_TINT : sk.tint;
    let pips = "";
    for (let i = 1; i <= SKILL_MAX_LEVEL; i++) {
      if (i <= lvl) pips += `<span class="on"></span>`;
      else if (i === lvl + 1 && !maxed && frac > 0) pips += `<span class="part" style="--p:${(frac * 100).toFixed(1)}%"></span>`;
      else pips += `<span></span>`;
    }
    const lvlText = (maxed ? "★ " : "") + "Level " + lvl;
    const nextText = maxed ? "mastered" : `${xp - cur} ink to ${lvl + 1}`;
    return `<div class="skill-row" style="--c:rgb(${tint});--cs:rgba(${tint},0.14);--cr:rgba(${tint},0.42)">` +
      `<span class="skill-emblem">${MASTERY_ICONS[sk.icon] || ""}</span>` +
      `<div class="skill-main">` +
        `<div class="skill-top"><span class="skill-name">${escapeHtml(sk.name)}</span><span class="skill-lvl">${lvlText}</span></div>` +
        `<div class="skill-bar">${pips}</div>` +
        `<div class="skill-foot"><span class="skill-blurb">${escapeHtml(sk.blurb)}</span><span class="skill-next">${nextText}</span></div>` +
      `</div></div>`;
  }).join("");

  // Reward board — a bento of grouped cosmetic tiles (pens, charms, paper, the super-hard
  // milestone) plus the prestige-titles tile. Titles fold in as the last tile.
  const bento = buildRewardBento(m, mLevel, unlocked);

  body.innerHTML = `<div class="mastery-page">` +
    `<div class="mastery-head">${head}</div>` +
    `<div class="mastery-section-label">Skills</div>${skills}` +
    bento +
    `</div>`;

  renderTitleStepper();   // fills #titleStepper inside the titles tile (present only once unlocked)

  // Wire cosmetic selection: data-reward chooses that reward; data-reward-reset reverts a
  // whole kind (pen / paper / charm) to its default; data-reward-random hands a kind over to
  // chance. The three are separate attributes rather than sentinel reward ids so that neither
  // "default" nor "random" can ever be mistaken for something in the ledger.
  body.querySelectorAll("[data-reward]").forEach((el) => {
    el.addEventListener("click", () => chooseMasteryCosmetic(el.getAttribute("data-reward"), el.getAttribute("data-variant")));
  });
  body.querySelectorAll("[data-reward-reset]").forEach((el) => {
    el.addEventListener("click", () => resetMasteryCosmetic(el.getAttribute("data-reward-reset")));
  });
  body.querySelectorAll("[data-reward-random]").forEach((el) => {
    el.addEventListener("click", () => chooseRandomCosmetic(el.getAttribute("data-reward-random")));
  });
  // The Pride tray is pure disclosure: it opens and shuts in the DOM without re-rendering,
  // and picking a flag re-renders the page from scratch with it shut again.
  const prideTray = body.querySelector("#pridePicker");
  const prideDoor = body.querySelector("[data-open-pride-picker][aria-controls]");
  body.querySelectorAll("[data-open-pride-picker]").forEach((el) => {
    el.addEventListener("click", () => {
      if (!prideTray) return;
      prideTray.hidden = !prideTray.hidden;
      if (prideDoor) prideDoor.setAttribute("aria-expanded", String(!prideTray.hidden));
      if (!prideTray.hidden) prideTray.scrollIntoView({ block: "nearest", behavior: "smooth" });
      else if (prideDoor) prideDoor.focus();
    });
  });
  // ...and the rank ladder above the stepper: data-title-tier scrolls the stepper to that
  // tier's default title. Browsing only — it never changes which title you wear.
  body.querySelectorAll("[data-title-tier]").forEach((el) => {
    el.addEventListener("click", () => { _titleView = +el.getAttribute("data-title-tier"); renderTitleStepper(); });
  });
  // The super-hard vault's door: straight to the brutal group on the Challenges board. NOT
  // the bottom of that list — the groups render [1,2,3,4,0], so the bottom is the UNRATED
  // tier and scrolling there would land the player nowhere near what they just unlocked.
  const brutal = body.querySelector("[data-open-brutal]");
  if (brutal) brutal.addEventListener("click", () => {
    const id = firstSuperHardChallenge();
    if (id) openChallenges("mastery", id);
  });
  // The hints vault's door: the Secret section of the charm collection, which is where the
  // reward actually shows itself. Only drawn while that section still has something in it.
  const hints = body.querySelector("[data-open-secret-charms]");
  if (hints) hints.addEventListener("click", () => openAchievements("mastery", "secret"));
}

// ---- Mastery hero ----
// The card at the top of the Mastery page. Three states share a notebook-card shell
// (paper, a red margin rule, a wax-seal medallion) but diverge in the middle:
//   locked   → a dashed, unpressed seal + a bar toward the unlock gate
//   climbing → a gold seal with your level + the ascent track (13 pips, reward
//              markers, a pen nib riding the ink line at your exact progress)
//   complete → a sealed gold medallion + a full gold bar

// What each mastery level introduces, for the ascent-track markers and the "next reward"
// note. Only the levels that unlock something appear. The marks themselves come from
// MASTERY_LEVEL_ICONS in config.js, which the reward tiles read too.
const MASTERY_LEVEL_LABEL = {
  1: "a new pen", 2: "a new pen", 3: "a new pen", 4: "paper stocks", 5: "bracelet charms",
  6: "super-hard challenges", 7: "a prestige title", 8: "a button finish",
  9: "a prestige title", 10: "secret hints", 11: "a prestige title",
  12: "a signature flourish", 13: "your final title",
};

// The next reward waiting up the track, phrased for the sub-line ("" once none remain).
function masteryNextRewardNote(mLevel) {
  for (let lv = mLevel + 1; lv <= MASTERY_MAX_LEVEL; lv++) {
    if (MASTERY_LEVEL_LABEL[lv]) return `Next — ${MASTERY_LEVEL_LABEL[lv]} at level ${lv}`;
  }
  return "";
}

// Locked — the wax not yet pressed. Bar runs toward the skill-level gate.
function masteryHeadLocked(total) {
  const pct = Math.max(0, Math.min(100, (total / MASTERY_GATE) * 100));
  const left = Math.max(0, MASTERY_GATE - total);
  return `<div class="mh-card mh-locked"><span class="mh-rule"></span>` +
    `<div class="mh-row">` +
      `<div class="mh-seal locked"><span class="mh-seal-emblem">${masteryMarkup("lock")}</span></div>` +
      `<div class="mh-body">` +
        `<div class="mh-kicker">Mastery</div>` +
        `<div class="mh-title">Not yet sealed</div>` +
        `<div class="mh-bar"><i style="width:${pct.toFixed(1)}%"></i><span class="mh-gate"></span></div>` +
        `<div class="mh-sub"><b>${total} / ${MASTERY_GATE}</b> skill levels · ${left} more to press the wax</div>` +
      `</div>` +
    `</div></div>`;
}

// Complete — sealed at the cap. The last thing in the game and seen exactly once, so the bar
// stops being a progress meter and becomes a strip of gold leaf pressed into the page. The
// drama is built out of the notebook's own materials: foil, paper grain, and ink.
//
// Three layers, and each answers to a different setting, because they are different things:
//   flecks — fine gold specks in the leaf and in the card's paper. Printed, not moving, so
//            no motion setting has anything to say about them; they are always drawn.
//   sheen  — a slow highlight travelling the length of the foil. That is motion, so
//            reduceMotion takes it away (and on "auto" the system preference does).
//   glint  — the seal catching that same light as it passes. A specular flash on top of the
//            motion, so it needs reducedFlashing off as well: the same pairing every other
//            sparkle in the game is gated by.
function masteryHeadComplete(mLevel) {
  const sheen = !motionReduced();
  const glint = sheen && !settings.reducedFlashing;
  return `<div class="mh-card mh-complete"><span class="mh-rule"></span>` +
    `<div class="mh-row">` +
      `<div class="mh-seal complete${glint ? " glint" : ""}"><span class="mh-seal-emblem">${masteryMarkup("crown")}</span></div>` +
      `<div class="mh-body">` +
        `<div class="mh-kicker">Mastery</div>` +
        `<div class="mh-title">Mastered</div>` +
        `<div class="mh-bar"><i style="width:100%">${sheen ? `<span class="mh-foil-sheen"></span>` : ""}</i></div>` +
        `<div class="mh-sub"><b>Level ${mLevel}</b> · every reward earned</div>` +
      `</div>` +
    `</div></div>`;
}

// Climbing — the ascent track. Pips are levels 1–13; reached ones ink gold, the current
// one glows plum, and the ink line fills to the exact fraction between levels.
function masteryHeadClimb(m, mLevel) {
  const cur = masteryXpForLevel(mLevel), next = masteryXpForLevel(mLevel + 1);
  const inCur = Math.max(0, m.masteryXp - cur), span = Math.max(1, next - cur);
  const pct = Math.max(0, Math.min(100, (inCur / span) * 100));
  const frac = Math.max(0, Math.min(1, ((mLevel - 1) + pct / 100) / (MASTERY_MAX_LEVEL - 1)));
  const fillPos = `calc((100% - 16px) * ${frac.toFixed(4)})`;

  let pips = "";
  for (let i = 1; i <= MASTERY_MAX_LEVEL; i++) {
    const reached = i <= mLevel, current = i === mLevel;
    const icon = MASTERY_LEVEL_ICONS[i];
    const label = MASTERY_LEVEL_LABEL[i];
    const tip = `Level ${i}${label ? " · " + label : ""}`;
    pips += `<div class="mh-nd${reached ? " reached" : ""}${current ? " current" : ""}" title="${escapeHtml(tip)}">` +
      `<span class="mh-ic">${icon ? masteryMarkup(icon) : ""}</span>` +
      `<span class="mh-dot"></span><span class="mh-lv">${i}</span></div>`;
  }

  const seal = mLevel >= 1
    ? `<span class="mh-seal-num">${mLevel}</span>`
    : `<span class="mh-seal-emblem">${masteryMarkup("star")}</span>`;
  const title = mLevel >= 1 ? `Level ${mLevel}` : "Freshly sealed";

  return `<div class="mh-card mh-climb"><span class="mh-rule"></span>` +
    `<div class="mh-row">` +
      `<div class="mh-seal climb">${seal}</div>` +
      `<div class="mh-body">` +
        `<div class="mh-kicker">Mastery</div>` +
        `<div class="mh-title">${title}</div>` +
        `<div class="mh-next">${masteryNextRewardNote(mLevel)}</div>` +
      `</div>` +
    `</div>` +
    `<div class="mh-track">` +
      `<span class="mh-line"></span>` +
      `<span class="mh-fill" style="width:${fillPos}"></span>` +
      `<div class="mh-nodes">${pips}</div>` +
    `</div>` +
    `<div class="mh-sub"><b>${inCur} / ${span}</b> ink to level ${mLevel + 1}` +
      `<span class="mh-law"> · every level asks ${MASTERY_LEVEL_STEP} more ink than the last</span></div></div>`;
}

// ---- Reward bento ----
// The reward board groups the cosmetics into tiles sized by weight: pens as a stacked
// column, charms hung from a bracelet strand (the hero), paper as live-tinted swatches,
// the super-hard milestone as a sealed vault, and the prestige titles as a rank ladder.
// Each group carries its own "default" option so a kind can always be reverted; still-locked
// items read as empty slots (a lock, no glyph) so the reward stays a surprise until earned.
function buildRewardBento(m, mLevel, unlocked) {
  const groups = { pen: [], paper: [], charm: [], unlock: [], button: [], label: [] };
  MASTERY_REWARDS.forEach((r) => { if (groups[r.kind]) groups[r.kind].push(r); });
  const all = MASTERY_REWARDS.filter((r) => r.kind !== "title");
  const earned = all.filter((r) => m.unlocked[r.id]).length;
  const pct = Math.round((earned / all.length) * 100);
  const hardR = groups.unlock.find((r) => r.id === "hardmode-unlock");
  const hintR = groups.unlock.find((r) => r.id === "reveal-hints");
  const secretsLeft = secretCharmsLeft().length > 0;

  return `<div class="reward-bento">` +
    `<div class="rb-head">` +
      `<div><div class="rb-title">Rewards</div><div class="rb-sub">Your collected spoils</div></div>` +
      `<div class="rb-meter"><div class="rb-count">${earned} of ${all.length} earned</div>` +
        `<div class="rb-prog"><i style="width:${pct}%"></i></div></div>` +
    `</div>` +
    `<div class="rb-grid">` +
      buildPensTile(groups.pen, m) +
      buildCharmTile(groups.charm, m) +
      buildPaperTile(groups.paper, m) +
      // The super-hard vault reports the real gate, not the ledger: `mastery: 6` on the
      // tapes:4 challenges is what actually opens the tier.
      buildMilestoneTile(hardR, {
        area: "hard", tone: "dark", watermark: true, earned: superHardTierOpen(),
        // With the button below carrying the verb, the copy no longer has to point at
        // Challenges in words as well.
        earnedCopy: "Unlocked — a whole tier of brutal challenges.",
        lockedCopy: `A tier of brutal new challenges. Reach Mastery ${hardR ? hardR.level : ""} to break the seal.`,
        action: { label: "Take one on", attr: `data-open-brutal` },
      }) +
      buildButtonTile(groups.button, m) +
      buildCtaTile(groups.label, m) +
      // The other vault. It guards knowledge rather than a tier, so it is made of different
      // stuff — plum leather and rose foil against the super-hard tile's iron and brass —
      // and it opens with the key it already wears rather than being broken into.
      // Its earned state has two readings, because the thing it points at can run out: the
      // Secret section only holds charms you haven't earned yet, and it stops rendering once
      // you've found them all. A door to a section that isn't there is worse than no door, so
      // the tile spends its last state saying so and offers nothing.
      buildMilestoneTile(hintR, {
        area: "hint", tone: "ink", watermark: true, earned: !!(hintR && m.unlocked[hintR.id]),
        earnedCopy: secretsLeft
          ? "Unlocked — every secret charm now shows how to earn it."
          : "Every secret charm found. The hints have nothing left to reveal.",
        lockedCopy: `What every secret charm wants from you, kept shut. Reach Mastery ${hintR ? hintR.level : ""} for the key.`,
        action: secretsLeft ? { label: "Read the hints", attr: `data-open-secret-charms` } : null,
      }) +
      buildTitlesTile(m, unlocked) +
    `</div>` +
  `</div>`;
}

// Small level pill shown top-right of a tile.
function rbChip(text) { return `<span class="rb-chip">${escapeHtml(text)}</span>`; }

// A tile's level pill with a die fused to its left end: the control that hands that tile's
// whole set over to chance. Drawn as ONE object rather than two, because the randomiser is
// not one more member of the set — it is a state the tile itself can be in. The die's circle
// stands slightly proud of the pill and melts into it (#fuseGoo, painted on .rb-fuse::before
// so the die and the words above it stay crisp).
//
// The die is raw MASTERY_ICONS markup, deliberately NOT run through masteryMarkup: that wraps
// every icon in .charm, whose ::before lays a roundish highlighter smudge behind it, and a
// square die on a round smudge reads as a clipped icon. A control is not a keepsake anyway.
//
// Falls back to a bare chip while the set is still locked — there is nothing to randomise yet.
function rbRandChip(kind, text, active, available, label) {
  if (!available) return rbChip(text);
  return `<span class="rb-fuse${active ? " active" : ""}">` +
    `<button type="button" class="rb-rand" data-reward-random="${kind}"` +
      ` aria-pressed="${active ? "true" : "false"}" title="${escapeHtml(label)}"` +
      ` aria-label="${escapeHtml(label)}">${MASTERY_ICONS.die}</button>` +
    rbChip(text) + `</span>`;
}

// A stacked pick-list row — the shape the pens tile and the signature tile both wear: a glyph,
// a name, and a tag that reads "in use" on the row you're wearing. The two kinds differ only
// in how much room the glyph needs, which the list's variant class handles.
function rbRow(attr, glyphHTML, name, active) {
  return `<button type="button" class="rb-row${active ? " active" : ""}" ${attr}>` +
    `<span class="rb-row-ic">${glyphHTML}</span><span class="rb-row-nm">${escapeHtml(name)}</span>` +
    `<span class="rb-row-tag">${active ? "in use" : "use"}</span></button>`;
}
// Its locked twin — an empty slot, so the reward stays a surprise until it's earned.
function rbRowSlot(level) {
  return `<div class="rb-row locked"><span class="rb-row-ic rb-lock">${MASTERY_ICONS.lock}</span>` +
    `<span class="rb-row-nm">Locked</span><span class="rb-row-tag">Mastery ${level}</span></div>`;
}

// Pens — a stacked column. A "default" hand plus each unlockable pen; locked pens are slots.
function buildPensTile(pens, m) {
  const active = settings.masteryPen || "";
  let rows = rbRow(`data-reward-reset="pen"`, masteryMarkup("nib"), "Default", active === "");
  pens.forEach((r) => {
    if (!m.unlocked[r.id]) rows += rbRowSlot(r.level);
    else rows += rbRow(`data-reward="${r.id}"`, masteryMarkup(r.icon), r.name, active === r.payload.pen);
  });
  return `<div class="rb-tile rb-pens" style="grid-area:pens">` +
    `<div class="rb-tile-top"><span class="rb-tt">Pens</span>${rbChip("Mastery 1–3")}</div>` +
    `<div class="rb-tt-sub">Your writing hand</div>` +
    `<div class="rb-rows rb-rows--pen">${rows}</div></div>`;
}

// "random" is a VALUE a cosmetic setting can hold, not a reward in the ladder — there is no
// MASTERY_REWARDS entry behind it and there must not be, since it grants nothing on its own.
// So it gates on that kind's SET being unlocked, which is what earns all its members at once.
const COSMETIC_RANDOM = "random";
function rewardSetUnlocked(m, kind) {
  const first = MASTERY_REWARDS.find((r) => r.kind === kind);
  return !!(first && m.unlocked[first.id]);
}
const charmSetUnlocked = (m) => rewardSetUnlocked(m, "charm");

// A random start button is a different animal from a random charm strand. The strand hangs
// nine beads at once, so chance there is visible standing still. There is only ever ONE start
// button, so its randomness has to be a cadence instead — and that cadence is the page load:
// rolled once here, then held for the life of the tab. Rolling inside applySettings would
// reshuffle the button every time the theme, the text size or a sound toggle changed, which
// reads as a glitch rather than a surprise.
//
// The pools include the DEFAULT finish and the default words, the same way a random charm
// strand can still deal a plain star: "random" means any of them, not any of the earned ones.
//
// The Pride flags are deliberately NOT in the finish pool. They are a set behind a doorway
// rather than four more inks, and a flag worn without anyone having chosen it is a different
// kind of thing from a random colour.
const randomFinishPool = () => ["", ...MASTERY_REWARDS
  .filter((r) => r.kind === "button" && r.id !== "btn-pride").map((r) => r.payload.button)];
const randomLabelPool = () => ["", ...MASTERY_REWARDS
  .filter((r) => r.kind === "label").map((r) => r.payload.label)];
const pickOne = (arr) => arr[Math.floor(Math.random() * arr.length)] || "";
let rolledFinish = "", rolledLabel = "";
function rollRandomCosmetics() {
  rolledFinish = pickOne(randomFinishPool());
  rolledLabel = pickOne(randomLabelPool());
}
rollRandomCosmetics();
// What the start button ACTUALLY wears right now: the stored pick, or this load's roll when
// the stored pick is "random". Every surface that paints or previews the button reads these
// rather than the raw setting, so a preview can never disagree with the button itself.
function activeButtonFinish() {
  return settings.masteryButton === COSMETIC_RANDOM ? rolledFinish : (settings.masteryButton || "");
}
function activeCtaLabel() {
  return settings.masteryLabel === COSMETIC_RANDOM ? rolledLabel : (settings.masteryLabel || "");
}

// Charms hang from a bracelet strand on alternating drops. The random action lives in the
// tile header because it changes the whole strand rather than selecting one charm.
function buildCharmTile(charms, m) {
  const setUnlocked = charmSetUnlocked(m);
  const active = settings.masteryCharm || "";
  let beads = charmBead(`data-reward-reset="charm"`, charmPreviewSVG("star"), "star", active === "", true, 0);
  charms.forEach((r, i) => {
    beads += charmBead(`data-reward="${r.id}"`, charmPreviewSVG(r.payload.charm), r.payload.charm, active === r.payload.charm, setUnlocked, i + 1);
  });
  return `<div class="rb-tile rb-charm" style="grid-area:charm">` +
    `<div class="rb-tile-top"><span class="rb-tt">Bracelet charms</span>` +
      rbRandChip("charm", "Mastery 5", active === COSMETIC_RANDOM, setUnlocked, "Give every bead its own charm") +
    `</div>` +
    `<div class="rb-tt-sub">Hangs from every bead you earn · random gives each bead its own</div>` +
    `<div class="rb-strand"><span class="rb-cord"></span>` +
      `<span class="rb-clasp l"></span><span class="rb-clasp r"></span>` +
      `<div class="rb-beads">${beads}</div></div></div>`;
}
// `glyph` is finished markup rather than a charm id so the shared bead shape can render it.
function charmBead(attr, glyph, name, active, available, idx) {
  const drop = idx % 2 === 0 ? "short" : "long";   // alternating hang, like a laid-out bracelet
  if (!available) {
    return `<span class="rb-bead-col ${drop} locked"><span class="rb-stem"></span>` +
      `<span class="rb-bead"><span class="rb-lock">${MASTERY_ICONS.lock}</span></span></span>`;
  }
  return `<button type="button" class="rb-bead-col ${drop}${active ? " active" : ""}" ${attr}>` +
    `<span class="rb-stem"></span><span class="rb-bead">${glyph}</span>` +
    `<span class="rb-bead-nm">${active ? "in use" : escapeHtml(name)}</span></button>`;
}

// Paper stock — swatches of the real stock (default plus each unlockable set member).
function buildPaperTile(papers, m) {
  const setUnlocked = papers.length ? !!m.unlocked[papers[0].id] : false;
  const active = settings.masteryPaper || "";
  let sw = rbSwatch(`data-reward-reset="paper"`, paperChip("default"), "plain", active === "", true, 0);
  papers.forEach((r) => {
    sw += rbSwatch(`data-reward="${r.id}"`, paperChip(r.payload.paper), r.payload.paper, active === r.payload.paper, setUnlocked, r.level);
  });
  return `<div class="rb-tile rb-paper" style="grid-area:paper">` +
    `<div class="rb-tile-top"><span class="rb-tt">Paper stock</span>${rbChip("Mastery 4")}</div>` +
    `<div class="rb-tt-sub">Retints the whole page</div>` +
    `<div class="rb-swatches">${sw}</div></div>`;
}
// A swatch column — the shape the paper tile and the start-button tile both wear: a chip of
// the real thing above its name, or a dashed empty chip while the set is still locked. `chip`
// is the kind's own chip renderer, called with the locked flag.
//
// The worn swatch says "in use" instead of its name, which the chip above it has already
// shown. `activeName` overrides that for the one swatch where the name is NOT redundant: the
// Pride doorway, whose chip shows a flag the swatch would otherwise leave unnamed.
function rbSwatch(attr, chip, name, active, available, level, activeName) {
  if (!available) {
    return `<span class="rb-sw-col locked">${chip(true)}<span class="rb-sw-nm">Mastery ${level}</span></span>`;
  }
  return `<button type="button" class="rb-sw-col${active ? " active" : ""}" ${attr}>` +
    `${chip(false)}<span class="rb-sw-nm">${escapeHtml(active ? (activeName || "in use") : name)}</span></button>`;
}
// The two chips a swatch can wear: a sheet of the real paper stock, and a miniature of the
// real start button. Each carries its own locked finish.
const paperChip = (paper) => (locked) => locked
  ? `<span class="rb-sw locked"><span class="rb-lock">${MASTERY_ICONS.lock}</span></span>`
  : `<span class="rb-sw paper-chip" data-paper="${paper}"></span>`;
// The button chip is the real "start writing" CTA, markup and label and all, shrunk to fit:
// it carries the same .play-cta the home screen does, so a finish looks here exactly as it
// will look there, with no second description of the four fills to drift out of step.
const buttonChip = (style) => (locked) => locked
  ? `<span class="rb-btn-sw locked"><span class="rb-lock">${MASTERY_ICONS.lock}</span></span>`
  : `<span class="rb-btn-sw"><span class="btn-primary play-cta"${finishAttrs(style)} aria-hidden="true">Start writing</span></span>`;
// What a .play-cta has to be told to wear a finish: the finish itself, plus — for the Pride
// set, whose eight ramps live in PRIDE_BUTTONS rather than in CSS — that flag's gradient.
// Everything that previews a start button goes through this, so a preview cannot wear a
// finish differently from the real button.
function finishAttrs(finish) {
  if (!finish) return "";
  const stripes = prideStripes(finish);
  return ` data-startbtn="${escapeHtml(finish)}"` +
    (stripes ? ` style="--cta-stripes:${stripes}"` : "");
}

// A milestone tile — the shape both toggle-less rewards wear (super-hard challenges at 6,
// secret hints at 10): a vault, sealed shut until the milestone is reached, with the level
// chip, the name, and one line of copy that changes with the state.
// Both tones are vaults; `opts.tone` only says what this one is made of ("dark" iron and
// brass, "ink" plum leather and rose foil), which is the whole of the difference between
// them. `opts.watermark` floats the reward's mark oversized behind the copy. `opts.action`
// ({label, attr}) adds a door out of the tile to wherever the reward actually lives, and is
// drawn only once the milestone is earned — a sealed tile offers nothing.
function buildMilestoneTile(r, opts) {
  if (!r) return "";
  const mark = MASTERY_ICONS[r.icon] || "";
  const act = (opts.earned && opts.action)
    ? `<button type="button" class="rb-ms-go" ${opts.action.attr}>${escapeHtml(opts.action.label)}</button>`
    : "";
  return `<div class="rb-tile rb-ms rb-ms--${opts.tone}${opts.earned ? " earned" : ""}" style="grid-area:${opts.area}">` +
    (opts.watermark ? `<span class="rb-ms-mark">${mark}</span>` : "") +
    rbChip("Mastery " + r.level) +
    `<span class="rb-ms-seal">${opts.earned ? mark : MASTERY_ICONS.lock}</span>` +
    `<div class="rb-ms-nm">${escapeHtml(r.name)}</div>` +
    `<div class="rb-ms-sub">${opts.earned ? opts.earnedCopy : opts.lockedCopy}</div>${act}</div>`;
}

// Start-writing button finishes — swatches of the real CTA (default plus each unlockable
// finish). Selecting one restyles the home-screen hero button globally.
// Pride is the one finish that is a set, so its swatch is a doorway rather than a choice: it
// opens a tray of the eight flags below the grid. The tray is always in the markup and merely
// hidden, so opening it is a DOM change and not app state — the only thing that re-renders
// this page is picking a flag, which closes the tray anyway.
function buildButtonTile(buttons, m) {
  const setUnlocked = buttons.length ? !!m.unlocked[buttons[0].id] : false;
  const active = settings.masteryButton || "";
  const wornFlag = PRIDE_BUTTON_BY_ID[active] || null;
  let sw = rbSwatch(`data-reward-reset="button"`, buttonChip(""), "gold marker", active === "", true, 0);
  let pride = "";
  buttons.forEach((r) => {
    if (r.id === "btn-pride") {
      sw += rbSwatch(`data-open-pride-picker aria-expanded="false" aria-controls="pridePicker"`,
        buttonChip(wornFlag ? wornFlag.id : r.payload.button),
        "Pride flags", !!wornFlag, setUnlocked, r.level, wornFlag ? wornFlag.name : "");
      // Flag rows are the same swatch shape as the tile's own, and route through the same
      // data-reward guard: the variant is the flag, the unlock is still btn-pride's.
      if (!setUnlocked) return;   // no doorway while the set is locked, so no tray behind it
      const flags = PRIDE_BUTTONS.map((flag) =>
        rbSwatch(`data-reward="${r.id}" data-variant="${flag.id}"`, buttonChip(flag.id),
          flag.name, active === flag.id, setUnlocked, r.level)
      ).join("");
      pride = `<div class="pride-picker" id="pridePicker" hidden>` +
        `<div class="pride-picker-top"><span>Pride flags</span>` +
        `<button type="button" data-open-pride-picker>‹ button finishes</button></div>` +
        `<div class="rb-swatches">${flags}</div></div>`;
    } else {
      sw += rbSwatch(`data-reward="${r.id}"`, buttonChip(r.payload.button), r.name, active === r.payload.button, setUnlocked, r.level);
    }
  });
  return `<div class="rb-tile rb-button" style="grid-area:button">` +
    `<div class="rb-tile-top"><span class="rb-tt">Start button</span>` +
      rbRandChip("button", "Mastery 8", active === COSMETIC_RANDOM, setUnlocked, "A different finish every visit") +
    `</div>` +
    `<div class="rb-tt-sub">Restyles your home-screen button · random redraws it every visit</div>` +
    `<div class="rb-swatches">${sw}</div>${pride}</div>`;
}
// One row's preview: a real start button, scaled down, wearing the words on offer and the
// mark that comes with them. It is the button itself rather than a picture of one, for the
// same reason the paper and finish swatches are — the preview cannot drift from the thing.
//
// The finish comes along for free: the preview carries no data-startbtn of its own, so it
// inherits nothing and must be told. Level 8 owns how the button looks and level 12 owns what
// it says, and the pair only reads as one object if a label previews in the finish you are
// actually wearing.
//
// The button is laid out at full size and scaled, so a long label ("I'll write your name")
// keeps the real button's proportions instead of wrapping. 280px is its floor rather than its
// width, or the longest label would run through the right border.
function ctaPreviewHTML(labelId, finish) {
  const opt = labelId ? CTA_LABELS[labelId] : null;
  const mark = opt && opt.mark ? `<span class="cta-mark">${CTA_MARKS[opt.mark] || ""}</span>` : "";
  const text = opt ? escapeHtml(opt.text) : "Start writing";
  // .cta-mk suppresses the ✎ pseudo-element on every row except the default, which IS the
  // glyph. Blank page gets .cta-mk with no mark child, which is the point of it.
  const cls = opt ? " cta-mk" : "";
  return `<span class="cta-prev"><span class="btn-primary play-cta${cls}"` +
    `${finishAttrs(finish)} aria-hidden="true">${mark}${text}</span></span>`;
}

// A start-button words row. The preview is aria-hidden (it is a decorative copy of a button
// that already exists on the start screen), so the row has to state its own name for anyone
// not looking at it — hence the aria-label rather than a visible .rb-row-nm. Every other
// pick-list row in the bento names itself on screen; here the preview says the words out
// loud already, and printing them twice reads as a stutter.
function ctaRow(attr, labelId, name, active, finish) {
  return `<button type="button" class="rb-row${active ? " active" : ""}" ${attr} aria-label="${escapeHtml(name)}">` +
    `<span class="rb-row-ic">${ctaPreviewHTML(labelId, finish)}</span>` +
    `<span class="rb-row-tag">${active ? "in use" : "use"}</span></button>`;
}

// Start-button words — a stacked column of live button previews (the default "Start writing"
// plus each unlockable label). Selecting one rewrites the home-screen button.
//
// The default row and the first option are the same thing here, unlike pens or paper where
// the default is a distinct fifth object. So it renders as the RESET row and there is no
// separate "Start writing" entry in the ladder, or the words would appear twice.
function buildCtaTile(labels, m) {
  const setUnlocked = labels.length ? !!m.unlocked[labels[0].id] : false;
  const active = settings.masteryLabel || "";
  // The finish the previews wear is the one the real button is wearing right now, which on a
  // randomised button is this load's roll rather than the word "random".
  const finish = activeButtonFinish();
  let rows = ctaRow(`data-reward-reset="label"`, "", "Start writing", active === "", finish);
  if (!setUnlocked) {
    // One slot for the whole set, not eight. The pens tile locks a row at a time because its
    // three arrive on three separate levels; these eight arrive together, and eight identical
    // "Locked / Mastery 12" rows stacked in a column is a wall rather than a promise.
    const level = labels.length ? labels[0].level : 12;
    rows += `<div class="rb-row locked"><span class="rb-row-ic rb-lock">${MASTERY_ICONS.lock}</span>` +
      `<span class="rb-row-nm">${labels.length} more ways to say it</span>` +
      `<span class="rb-row-tag">Mastery ${level}</span></div>`;
  } else {
    labels.forEach((r) => {
      rows += ctaRow(`data-reward="${r.id}"`, r.payload.label, r.name, active === r.payload.label, finish);
    });
  }
  return `<div class="rb-tile rb-cta" style="grid-area:cta">` +
    `<div class="rb-tile-top"><span class="rb-tt">Start button words</span>` +
      rbRandChip("label", "Mastery 12", active === COSMETIC_RANDOM, setUnlocked, "Different words every visit") +
    `</div>` +
    `<div class="rb-tt-sub">Rewrites the label on your home-screen button · random rewrites it every visit</div>` +
    `<div class="rb-rows rb-rows--cta">${rows}</div></div>`;
}

// Prestige titles — the rank ladder (four tier medallions along a rail) above the title
// picker. The medallions show progress; the stepper (once unlocked) does the actual choosing.
const RB_TIER_ROMAN = ["I", "II", "III", "IV"];
const RB_TIER_SHORT = ["Poet", "Bridge", "Chairman", "Showgirl"];
function buildTitlesTile(m, unlocked) {
  const worn = wornTitleValue(m);
  const wornR = MASTERY_TITLE_BY_VALUE[worn];
  const wornTier = wornR ? wornR.level : -1;
  const tiers = MASTERY_TITLES.filter((t) => t.isDefault);   // one representative per tier
  const nextLocked = tiers.find((t) => !m.unlocked[t.id]);
  const medals = tiers.map((t, i) => {
    const reached = !!m.unlocked[t.id];
    const isWorn = reached && t.level === wornTier;
    const isNext = !reached && nextLocked && t.level === nextLocked.level;
    const cls = reached ? (isWorn ? "reached worn" : "reached") : (isNext ? "next" : "locked");
    const state = isWorn ? "worn" : isNext ? "next" : "";
    // The flag line is always rendered, even empty: it keeps the four columns the same
    // height, and it is the slot the "see titles" hover cue swaps into.
    const flag = `<span class="rb-medal-flag"><i class="rb-medal-state">${state}</i>` +
      (unlocked ? `<i class="rb-medal-hint">see titles</i>` : "") + `</span>`;
    // The medallion wears the TIER's mark (MASTERY_TIER_ICONS), not the default title's:
    // the rail is a rank ladder, and tier IV and Ultimate Showgirl are two different things.
    const face = `<span class="rb-medal-ic">${masteryMarkup(MASTERY_TIER_ICONS[i])}</span>` +
      `<span class="rb-medal-lv">${RB_TIER_ROMAN[i]} · L${t.level}</span>` +
      `<span class="rb-medal-nm">${RB_TIER_SHORT[i]}</span>${flag}`;
    // A medallion jumps the stepper to that tier's default title — including a tier you have
    // not reached, since browsing ahead is what the stepper is for. Without the stepper on the
    // page (mastery still locked) there is nothing to jump, so it stays a plain mark.
    return unlocked
      ? `<button type="button" class="rb-medal ${cls}" data-title-tier="${MASTERY_TITLES.indexOf(t)}">${face}</button>`
      : `<div class="rb-medal ${cls}">${face}</div>`;
  }).join("");
  const picker = unlocked
    ? `<div id="titleStepper" class="title-stepper"></div>`
    : `<div class="rb-title-lock"><span class="rb-lock">${MASTERY_ICONS.lock}</span>Reach Mastery 7 to earn your first title</div>`;
  return `<div class="rb-tile rb-titles" style="grid-area:title">` +
    `<div class="rb-tile-top"><span class="rb-tt">Prestige titles</span>${rbChip("Mastery 7")}</div>` +
    `<div class="rb-tt-sub">Four ranks, fourteen titles. Engraved on your records signature.</div>` +
    `<div class="rb-ladder"><span class="rb-ladder-rail"></span>${medals}</div>${picker}</div>`;
}

// Apply a Mastery-unlocked cosmetic. Pens swap the writing hand; papers retint the page
// (applied globally via applySettings). Persists in settings and re-renders the page.
// `variant` is for a reward that holds a SET rather than one value (Pride's eight flags): it
// is honoured only if the reward itself declares it, so a variant can never smuggle in a
// value the reward does not own, and the unlock guard below is still the reward's own.
function chooseMasteryCosmetic(rewardId, variant) {
  const r = MASTERY_REWARD_BY_ID[rewardId];
  const cos = r && MASTERY_COSMETICS[r.kind];
  if (!cos || !loadMastery().unlocked[rewardId]) return;   // guard: must be an unlocked cosmetic
  const owned = variant && (r.variants || []).some((v) => v.id === variant);
  applyMasteryCosmetic(r.kind, (owned ? variant : (r.payload && r.payload[cos.field])) || "");
}
// Hand a whole cosmetic kind over to chance. "random" has no reward entry to look up (it
// grants nothing), so the ledger guard in chooseMasteryCosmetic would refuse it forever — it
// rides its own set's unlock instead, the same unlock that earned every member it deals from.
// Pressing it again while it is already on turns it back off, since the die is the only thing
// marked "in use" while random is worn and there would otherwise be nothing to press.
function chooseRandomCosmetic(kind) {
  if (!MASTERY_COSMETICS[kind] || !rewardSetUnlocked(loadMastery(), kind)) return;
  const worn = settings[MASTERY_COSMETICS[kind].setting] === COSMETIC_RANDOM;
  applyMasteryCosmetic(kind, worn ? "" : COSMETIC_RANDOM);
}
// Reset a cosmetic kind to its default ("" clears the setting).
function resetMasteryCosmetic(kind) {
  if (MASTERY_COSMETICS[kind]) applyMasteryCosmetic(kind, "");
}
function applyMasteryCosmetic(kind, value) {
  const cos = MASTERY_COSMETICS[kind];
  if (!cos) return;
  settings[cos.setting] = value;
  saveSettings(settings);
  if (kind === "pen") setPen(value || null);
  else applySettings();   // paper + button realised on <body> attributes
  // The signature flourish only lives on the records page — refresh it if it's showing.
  if (kind === "signature" && screens.records.classList.contains("active")) renderRecordsPage();
  renderMasteryPage();
}

/* ---------- Prestige titles ---------- */
// The title the player currently wears: their explicit pick (if still unlocked), else the
// "follows your mastery" default — the highest tier's default they've reached. "" = none yet.
function wornTitleValue(m = loadMastery()) {
  const pick = settings.masteryTitle;
  const picked = pick && MASTERY_TITLE_BY_VALUE[pick];
  if (picked && m.unlocked[picked.id]) return pick;
  return isMasteryUnlocked(m) ? masteryDefaultTitle(masteryLevelFromXp(m.masteryXp)) : "";
}
function wornTitleName(m = loadMastery()) {
  const r = MASTERY_TITLE_BY_VALUE[wornTitleValue(m)];
  return r ? r.name : "";
}
// Persist a title choice ("" = follow your mastery) and refresh anywhere it shows.
function setMasteryTitle(value) {
  settings.masteryTitle = value || "";
  saveSettings(settings);
  checkTitleCharm();
  renderTitleStepper();
  if (screens.records.classList.contains("active")) renderRecordsPage();
}

let _titleView = null;   // index into MASTERY_TITLES the stepper is currently viewing
const TS_STAR = `<span class="ts-star"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l2.9 6.3 6.9.7-5.2 4.6 1.5 6.8L12 17.8 5.9 21.4l1.5-6.8L2.2 9l6.9-.7z"/></svg></span>`;
const TS_CHEV_L = `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5l-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const TS_CHEV_R = `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5l7 7-7 7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;

// The title picker: one title at a time with ← → to browse, a star marking the worn title
// and a circle marking the one being viewed, tier-grouped position dots, and a context action
// (wear / currently worn / N levels to go). Re-renders itself on each step; commits on "wear".
function renderTitleStepper() {
  const host = $("titleStepper");
  if (!host) return;
  const m = loadMastery();
  const last = MASTERY_TITLES.length - 1;
  const worn = wornTitleValue(m);
  const wornIdx = MASTERY_TITLES.findIndex((t) => t.payload.title === worn);
  if (_titleView == null) _titleView = wornIdx >= 0 ? wornIdx : 0;
  _titleView = Math.max(0, Math.min(last, _titleView));

  const r = MASTERY_TITLES[_titleView];
  const mLevel = masteryLevelFromXp(m.masteryXp);
  const isUnlocked = !!m.unlocked[r.id];
  const isWorn = r.payload.title === worn;
  const isCapstone = r.level >= 13;

  const nameHTML = (isCapstone ? masteryMarkup(r.icon) + "<span>" + escapeHtml(r.name) + "</span>" : escapeHtml(r.name)) +
    (r.isDefault ? ` <span class="ts-def">default</span>` : "");
  const sub = isCapstone ? `the capstone · Mastery ${r.level}` : `Mastery ${r.level}`;

  let action;
  if (!isUnlocked) {
    const togo = Math.max(1, r.level - mLevel);
    action = `<div class="ts-act lock"><span class="charm">${MASTERY_ICONS.lock}</span>${togo} level${togo === 1 ? "" : "s"} to go</div>`;
  } else if (isWorn) {
    action = `<div class="ts-act worn">currently worn</div>`;
  } else {
    action = `<button type="button" class="ts-act wear" id="tsWear">wear this title</button>`;
  }

  // Position dots, grouped by tier level. Star = worn, filled circle = viewing, hollow = locked.
  const levels = [...new Set(MASTERY_TITLES.map((t) => t.level))];
  const dots = levels.map((lv) => {
    const cells = MASTERY_TITLES.map((t, i) => ({ t, i })).filter((x) => x.t.level === lv).map(({ t, i }) => {
      const locked = !m.unlocked[t.id];
      if (t.payload.title === worn) return TS_STAR;
      if (i === _titleView) return `<i class="ts-cur${locked ? " lk" : ""}"></i>`;
      return `<i class="${locked ? "ts-lk" : ""}"></i>`;
    }).join("");
    return `<span class="ts-grp">${cells}</span>`;
  }).join("");

  const reset = settings.masteryTitle
    ? `<button type="button" class="ts-reset" id="tsReset">reset to default · follows your mastery</button>`
    : `<div class="ts-reset muted">following your mastery</div>`;

  host.innerHTML =
    `<div class="ts-cap">Choose your title</div>` +
    `<div class="ts-row">` +
      `<button type="button" class="ts-arw" id="tsPrev"${_titleView === 0 ? " disabled" : ""} aria-label="previous title">${TS_CHEV_L}</button>` +
      `<div class="ts-mid">` +
        `<div class="ts-title${isUnlocked ? "" : " lk"}">${nameHTML}</div>` +
        `<div class="ts-sub">${sub}</div>` +
        `<div class="ts-dots">${dots}</div>` +
        `<div class="ts-legend"><span>${TS_STAR}worn</span><span><span class="d"></span>viewing</span></div>` +
      `</div>` +
      `<button type="button" class="ts-arw" id="tsNext"${_titleView === last ? " disabled" : ""} aria-label="next title">${TS_CHEV_R}</button>` +
    `</div>` +
    action + reset;

  const prev = $("tsPrev"); if (prev) prev.onclick = () => { _titleView--; renderTitleStepper(); };
  const next = $("tsNext"); if (next) next.onclick = () => { _titleView++; renderTitleStepper(); };
  const wear = $("tsWear"); if (wear) wear.onclick = () => setMasteryTitle(r.payload.title);
  const rst = $("tsReset"); if (rst) rst.onclick = () => setMasteryTitle("");
}

/* ---------- Bonus games shelf ----------
   A shelf of quick, self-contained mini-games away from the main association loop. Every
   entry in BONUS_GAMES is gated by its `ready` flag: a false one can still sit on the deck,
   where it says in words that it isn't written yet and offers no Play button. To build one:
   flip `ready` and add its branch to `buildBonusPuzzle` + `renderBonusRound`.

   SANDBOXED, like Challenges/Album Focus/Custom. A bonus run is not a run of the association
   game and is never ranked beside one: nothing here touches stats, records, history, the song
   tally, metrics, achievements or skill XP. The only thing a run writes is its own best score
   (`recordBonusRun`). Keep it that way — these are deliberately unbalanced against the main
   game's scoring. */
let bonusBackTarget = "start";       // where the shelf's back link returns to

// The puzzle builders need three catalogue-wide indexes (see js/bonus.js). Each is a full pass
// over every lyric line, so they're built once on first play and cached for the session —
// never at load, since most sessions never open the shelf.
let bonusLineIndex = null;
let bonusSlipCtx = null;
let bonusWordIndex = null;
function bonusIndexes() {
  if (!bonusLineIndex) bonusLineIndex = buildLineIndex(allSongs);
  if (!bonusSlipCtx) bonusSlipCtx = buildSlipContext(allSongs);
  if (!bonusWordIndex) bonusWordIndex = buildWordIndex(allSongs);
  return { lineIndex: bonusLineIndex, ctx: bonusSlipCtx, wordIndex: bonusWordIndex };
}

// The Ruthless exclusions are catalogue-wide bonus-game exclusions. The full catalogue still
// builds the fairness indexes above, so a barred song's duplicate line cannot accidentally make
// an eligible Name That Song or Redacted page look unique; it simply cannot be dealt or named
// anywhere on the bonus shelf.
function bonusSongs() { return allSongs.filter((song) => !ruthlessBar(song)); }

/* In-run state. Deliberately separate from the main game's state (score/round/currentSongs):
   a bonus run must never be mistaken for an association run by any shared code path. */
let bonusGame = null;      // the BONUS_GAMES entry being played
let bonusRound = 0;        // 1-based page number
let bonusScore = 0;
let bonusPuzzle = null;    // this round's puzzle from js/bonus.js
let bonusLocked = false;   // round answered — ignore further input until the next round
let bonusRaf = null;       // clock handle (setInterval id — see startBonusClock)
let bonusEnded = false;
let bonusRecentFakes = []; // Spot the Slip: impostor words used recently, so a run doesn't repeat one
let bonusRecentSongs = []; // Name That Song / Sing It Back / Redacted: songs already used this run, so one doesn't come round twice
let redactWorth = 0;       // Redacted: what THIS page is still worth, one point per strip left unpeeled
let redactPeeled = 0;      // ...and how many strips have come off it
// Only Here: the word this page was answered with, once one has been accepted —
// {word, count, points} — or null while the page is still open. It IS the page's score, so it
// is also what bonusPageScore reads.
let onlyPlayed = null;
// Only Here: every word already DEALT this run, so a run can't teach you a word's count on page
// 3 and then ask about it on page 8 — a hand that grades its own answer key.
let onlyDealt = new Set();
/* Then What: which pick the page is on, what has been picked so far, and what the page has
   banked. `chainBusy` is the beat between a tap and the next three cards being dealt — it is
   NOT bonusLocked, which means the whole page is over; a pick being marked up must stop a
   second tap without ending the run's page.
   `chainNow` and `chainRun` are the longest unbroken chain: not scored, deliberately, and
   carried across the whole run because a 0-60 total gives a run no personal chase. */
let chainStep = 0;
let chainTaken = [];       // per pick: { picked: card index or -1 for the clock, right }
let chainPage = 0;         // points banked on THIS page
let chainNow = 0;
let chainRun = 0;
let chainBusy = false;
let chainBeatId = null;
// Ruthless Game: how much of the stream is out, when this page started, what it has been fined
// for a give-up, and the frozen cost of the page once it settles. `ruthlessSpent` exists so the
// seconds are read off the clock exactly ONCE — the verdict line and bonusPageScore both want
// them, and two reads a millisecond apart can round to different numbers.
/* The LENS this run opens its streams on, or null for the shelf's whole-song game. It is set
   once at the start of a run and read everywhere the lens changes what a page does: which
   section the stream opens on, and what walking away from a page costs. Null is also the only
   marker of which of the two things is being played, so it must be cleared by the shelf's own
   start path rather than only set by the mode's. */
let ruthlessLensId = null;
let ruthlessShown = 0;
let ruthlessStart = 0;
let ruthlessPenalty = 0;
let ruthlessSpent = 0;
let ruthlessDripId = null;
/* Skill XP earned by a Ruthless MODE run, accrued page by page. It is kept here rather than in
   the main game's `gameTempoXp`/`gameResolveXp` because the bonus loop never calls
   resetRunState, so writing into those would spend an abandoned classic run's accumulator or
   leave this run's numbers lying in wait for the next one. foldSkillXp takes them as an
   override instead. `ruthlessStreak` is this run's own correct-in-a-row, for the same reason. */
let ruthlessXp = { resolve: 0, tempo: 0 };
let ruthlessStreak = 0;
/* When the RUN started, as a performance.now() baseline, for the games keeping a clean-sweep
   time (bonusSweeps). Wall clock across the whole run rather than the sum of the page clocks:
   the page turns and the verdict beats are part of what a sweep costs, and a total that skips
   them would be a number the player cannot see themselves spending. It ticks nothing and is
   read exactly once, at the end. */
let bonusRunStart = 0;
let bonusLog = [];         // one entry per settled round, for the end card's track listing
/* The finished run, written down as the strings the sleeve already shows, so the keepsake
   PNG is the sleeve on screen rather than a second derivation of it. Snapshotted at the end
   of the run instead of read live, because `bonusGame` and `bonusScore` are cleared the
   moment the player leaves for the shelf while the sleeve is still the page they're on. */
let bonusSleeveRun = null;
/* The same trick for the Ruthless mode's bracelet: the run written down as the card's own
   strings at the moment it ends, because the keepsake is pressed off a results screen whose
   bonus globals have already been handed back. */
let ruthlessCard = null;
// Bumped on every start. The between-rounds pause is a setTimeout, so without a token a run
// that's quit and immediately restarted would have the old pause advance the NEW run a round.
let bonusRunId = 0;

function openBonus(from) {
  bonusBackTarget = from;
  renderBonusPage();
  flipAwayToScreen("bonus");
}

/* The game's pressing. All the geometry is shared (#bd-* in index.html); a game supplies
   only its label colour and its mark, and an unwritten game gets the bare test pressing
   with its title pencilled on. `extra` lets a caller add classes without re-declaring the
   whole disc, so the shelf, the play screen and the end card all draw the same object. */
function bonusDisc(g, extra = "") {
  const cls = `bonus-disc${extra ? " " + extra : ""}`;
  const open = `<svg class="${cls}" viewBox="0 0 140 140" aria-hidden="true">`;
  if (!g.ready) {
    return open +
      `<use href="#bd-vinyl"/><use href="#bd-test-label"/>` +
      `<text x="70" y="95" text-anchor="middle" class="bd-pencil" font-size="11"` +
      ` transform="rotate(-2 70 92)">${escapeHtml(g.name.toLowerCase())}</text>` +
      `<use href="#bd-hub"/></svg>`;
  }
  return open +
    `<use href="#bd-vinyl"/>` +
    `<circle cx="70" cy="70" r="44" fill="${escapeHtml(g.tint)}"/>` +
    `<use href="#bd-rays"/><use href="#bd-furniture"/>` +
    `<g stroke="${escapeHtml(g.tint)}" fill="${escapeHtml(g.tint)}"><use href="#bd-mark-${escapeHtml(g.mark)}"/></g>` +
    `<use href="#bd-hub"/></svg>`;
}

/* The shelf is a record deck: one game is ON the platter with its details written beside
   it, and the rest wait on the shelf below as smaller pressings, each with its own name,
   line and score so nothing has to be guessed from a colour. Tapping one drops it onto the
   platter; Play starts it. Two taps to play instead of one is the deliberate cost of the
   metaphor, and it buys the games somewhere to be described properly.
   `bonusPick` is the id on the platter. It survives the screen so returning from a run
   leaves your record where you left it. */
let bonusPick = null;

/* What the SHELF is, as opposed to what the roster is. They stopped being the same list when
   Ruthless graduated to its own mode: its entry is still in BONUS_GAMES because the mode plays
   through it, but it is not a record on the deck any more and nothing player-facing may offer it.
   Every shelf surface and the randomiser go through here; the dev tools deliberately do NOT, so
   `__dev.bonus.play("ruthless-game")` can still drive the lens-less run directly. */
function shelfGames() { return BONUS_GAMES.filter((g) => g.shelf !== false); }

function bonusPicked() {
  const shelf = shelfGames();
  return shelf.find((g) => g.id === bonusPick)
      || shelf.find((g) => g.ready)
      || shelf[0];
}

/* ---------- What a run is out of ----------
   Most games score a page right or wrong, so a run is out of BONUS_ROUNDS. A game carrying
   `points` scores each page on a scale instead (Redacted's six-minus-what-you-peeled), so its
   run is out of ten times that. Everywhere a score is shown goes through these two, which is
   what stops a 63-point run being written up as "63 correct" out of ten. */
function bonusPagePoints(g) { return (g && g.points) || 1; }
function bonusMaxScore(g) { return BONUS_ROUNDS * bonusPagePoints(g); }
/* A game scored in SECONDS, where low is the good number. It has no maximum at all — a run is
   as long as it takes — so every surface that quotes a score against a total has to ask this
   first rather than reach for bonusMaxScore, which for a timed game would quote a meaningless
   ten. This one flag is the whole difference; there is no second timed code path. */
function bonusTimed(g) { return !!(g && g.timed); }
/* A game that keeps a best CLEAN-SWEEP TIME beside its score, because its ceiling is reachable
   and a tenth 10/10 is not a chase (see BONUS_GAMES). The clock runs on every run of one of
   these and is thrown away on any run that drops a page: it is the sweep that is being timed,
   not the run, so nothing below the ceiling is ever shown a number or asked to hurry. That is
   also why there is no clock on screen while a run is in progress — a visible one would apply
   exactly the pressure this design is avoiding. */
function bonusSweeps(g) { return !!(g && g.sweep); }
// A best is read back through the maximum it is quoted against, because a game's `points` can
// be retuned after a run has been banked — and a stored 74 shown as "best 74 / 60" is a
// notebook contradicting itself. Clamped on the way out rather than rewritten in storage: the
// run really did happen, and a later re-tune upwards should give the number back.
// A timed game's best is a time, and there is nothing to clamp it against: it is not out of
// anything, and a retune can't invalidate it the way a changed `points` scale can.
function bonusBest(g) {
  if (bonusTimed(g)) return bonusRecord(g.id).best;
  return Math.min(bonusRecord(g.id).best, bonusMaxScore(g));
}
function bonusScoreText() {
  if (bonusTimed(bonusGame)) return `${fmtTime(bonusScore)} so far`;
  // Then What carries its longest unbroken chain beside the score. It is not scored and never
  // will be — it is there so a run has a personal chase that a 0-60 total cannot give it.
  // The page's points are banked into bonusScore only when it settles, so while it is still
  // being played they have to be added on here for the chrome to keep up with the taps.
  if (bonusGame && bonusGame.id === "then-what")
    return `${bonusScore + (bonusLocked ? 0 : chainPage)} points · chain ${Math.max(chainRun, chainNow)}`;
  return `${bonusScore} ${bonusGame && bonusGame.points ? "points" : "correct"}`;
}

// What a game's record reads under its name: an unpressed record has no score to report,
// only a promise.
// `short` is the shelf STRIP, which shares one line with the game's name and clips it rather
// than wrapping. A game with a sweep on record spends that room on the sweep instead of on the
// played count: the count is on the platter a tap away, and the sweep is the number the strip
// exists to tempt you with. Before a first sweep the line is exactly what it always was, so
// nothing on the shelf announces a ceiling the player has not reached yet.
function bonusScoreLine(g, short = false) {
  const rec = bonusRecord(g.id);
  if (!g.ready) return "not pressed yet";
  if (!rec.plays) return "unplayed";
  // A time is quoted on its own — "best 3:41 / 10" would be nonsense, and there is no total
  // for it to be out of.
  if (bonusTimed(g)) return `best ${fmtTime(bonusBest(g))} · played ${rec.plays}`;
  const score = `best ${bonusBest(g)} / ${bonusMaxScore(g)}`;
  if (rec.sweep && short) return `${score} · swept ${fmtTime(rec.sweep)}`;
  const swept = rec.sweep ? ` · swept ${fmtTime(rec.sweep)}` : "";
  return `${score}${swept} · played ${rec.plays}`;
}

// The tonearm, resting on the record. Drawn here rather than in the sprite because it
// belongs to the deck, not to any pressing.
const BONUS_TONEARM =
  `<svg class="bonus-arm" viewBox="0 0 150 150" aria-hidden="true">` +
    `<circle cx="126" cy="26" r="13" fill="#cfc7ba" stroke="rgba(43,39,34,0.35)" stroke-width="1.5"/>` +
    `<circle cx="126" cy="26" r="4" fill="#8d8477"/>` +
    `<path d="M126 26 L117 48 L111 63" fill="none" stroke="#cfc7ba" stroke-width="7" stroke-linecap="round"/>` +
    `<path d="M126 26 L117 48 L111 63" fill="none" stroke="rgba(43,39,34,0.22)" stroke-width="1" stroke-linecap="round"/>` +
    // the head, sat down on the outer grooves rather than in the label: a stylus resting on
    // the paper label is the tell that gives a drawn record player away
    `<rect x="104" y="59" width="15" height="11" rx="2" transform="rotate(22 111 65)" fill="#4a433a"/>` +
  `</svg>`;

function renderBonusPage() {
  const g = bonusPicked();
  bonusPick = g.id;
  const others = shelfGames().filter((x) => x.id !== g.id);

  const deck =
    `<div class="bonus-deck">` +
      `<div class="bonus-platter${g.ready ? "" : " is-soon"}">` +
        // An unpressed record sits still: nothing is playing it, and a turning test
        // pressing would promise a game that isn't there.
        `<div class="bonus-platter-disc">${bonusDisc(g, g.ready ? "bonus-spin" : "")}</div>` +
        BONUS_TONEARM +
      `</div>` +
      `<div class="bonus-now">` +
        `<div class="bonus-now-kicker">${escapeHtml(g.kicker)}</div>` +
        `<h3 class="bonus-now-name">${escapeHtml(g.name)}</h3>` +
        `<p class="bonus-now-blurb">${escapeHtml(g.blurb)}</p>` +
        `<div class="bonus-now-meta">${escapeHtml(bonusScoreLine(g))}</div>` +
        (g.ready
          // the same gold pencil sticker the Challenges detail plays from, so starting a
          // run looks the same act wherever you start it from
          ? `<button type="button" id="bonusPlayBtn" class="chall-go bonus-play">${bonusRecord(g.id).plays ? "Play again" : "Play"}</button>`
          : `<p class="bonus-now-soon">This one is still being written, so there is nothing to put the needle on yet.</p>`) +
      `</div>` +
    `</div>`;

  /* The rest of the shelf, as title strips: a colour tab, the pressing, and two lines of
     writing — the name with its score out on the right, and the game's one-line `line`
     under both. Two to a row, so the shelf grows sideways as well as down.
     The strip is deliberately a FIXED two lines tall whatever is written on it: the score
     rides up onto the name's line so the description gets the whole width, and the
     description is clipped rather than wrapped. That is the whole reason this replaced the
     old described rows — those reprinted the platter's `blurb`, which is three sentences
     long, so nine of them ran to twice the page. The kicker is not repeated here; on the
     shelf `line` does its job, and it says more. */
  const shelf = others.map((x) =>
    `<button type="button" class="bonus-alt${x.ready ? "" : " is-soon"}" data-id="${escapeHtml(x.id)}">` +
      `<span class="bonus-alt-tab" style="background:${x.ready ? escapeHtml(x.tint) : "#cfc7ba"}"></span>` +
      `<span class="bonus-alt-disc">${bonusDisc(x)}</span>` +
      `<span class="bonus-alt-text">` +
        `<span class="bonus-alt-top">` +
          `<span class="bonus-alt-name">${escapeHtml(x.name)}</span>` +
          `<span class="bonus-alt-meta">${escapeHtml(bonusScoreLine(x, true))}</span>` +
        `</span>` +
        // Falls back to the kicker rather than printing an empty row: a game added to the
        // roster before its shelf line is written should still say something true about
        // itself, and the kicker is the one description every entry has always carried.
        `<span class="bonus-alt-line">${escapeHtml(x.line || x.kicker)}</span>` +
      `</span>` +
    `</button>`).join("");

  const el = $("bonusBody");
  el.innerHTML =
    `<div class="bonus-head">` +
      `<p class="bonus-intro">Quick games kept apart from the main round. Put one on and play it.</p>` +
      `<span class="bonus-count">${shelfGames().filter((x) => x.ready).length} in print</span>` +
    `</div>` +
    deck +
    `<div class="bonus-shelf">` +
      `<div class="bonus-shelf-label">also on the shelf</div>` +
      `<div class="bonus-strips">` + shelf + `</div>` +
    `</div>`;

  if ($("bonusPlayBtn")) $("bonusPlayBtn").addEventListener("click", () => startBonusGame(bonusPicked()));
  el.querySelectorAll(".bonus-alt").forEach((b) =>
    b.addEventListener("click", () => selectBonusGame(b.dataset.id)));
}

// Dropping a record onto the platter. Every game can be loaded, including one that isn't
// written yet: its test pressing goes on the deck and the panel says so in words. Nothing
// launches from here, so a shell can be read about without ever being playable.
function selectBonusGame(id) {
  const g = shelfGames().find((x) => x.id === id);
  if (!g) return;
  bonusPick = id;
  renderBonusPage();
  const disc = $("bonusBody").querySelector(".bonus-platter-disc");
  if (disc) { disc.classList.remove("drop"); void disc.offsetWidth; disc.classList.add("drop"); }
}

// `lensId` is the Ruthless mode's section lens, and null for every shelf game including the
// shelf's own Ruthless. It is assigned HERE rather than by the mode's start function so that
// walking from a lens run onto the shelf cannot leave the last lens applied to a shelf page.
function startBonusGame(g, lensId = null) {
  disarmBonusQuit();
  ruthlessLensId = lensId;
  /* A lens run is the Ruthless MODE, and it ends on the results screen the way every other
     gameType does, so the flag has to say so — the era, the keepsake card and the sandbox
     guards all read it. A shelf game is not a gameType at all, so it hands the flag back
     rather than leaving a retired lens run's on it. */
  if (lensId) gameType = "ruthless";
  else if (gameType === "ruthless") gameType = "classic";
  updateTagline();   // the masthead is shared, and a lens run's is not the last difficulty's
  bonusGame = g;
  notePlayed("bonus", g.id);
  bonusRound = 0;
  bonusScore = 0;
  bonusEnded = false;
  flourishThisRun = false;   // the shelf never touches resetRunState, so it re-arms its own flourish
  bonusRecentFakes = [];
  bonusRecentSongs = [];
  bonusLog = [];
  bonusSleeveRun = null;
  redactWorth = 0;
  redactPeeled = 0;
  onlyPlayed = null;
  // The dealt-word ban belongs to the RUN, so it is cleared here and nowhere else.
  onlyDealt = new Set();
  ruthlessShown = 0;
  ruthlessPenalty = 0;
  ruthlessSpent = 0;
  // The run's own XP and streak, cleared here for the same reason the chain is: they belong to
  // the run and nothing else clears them.
  ruthlessXp = { resolve: 0, tempo: 0 };
  ruthlessStreak = 0;
  /* Both of these are the results screen's, and both are normally cleared by resetRunState —
     which the shelf never calls. A Ruthless run ends on that screen, so without this it would
     open showing the charms and the skill fold of whatever main run came before it. */
  newlyUnlocked = [];
  lastSkillFold = null;
  // The longest chain belongs to the RUN, not the page, so it is reset here and nowhere else.
  chainNow = 0;
  chainRun = 0;
  bonusRunId++;
  // Started for every game, read only by the ones that keep a sweep. A flag checked here and
  // again at the end is two places for a game to be half-timed.
  bonusRunStart = performance.now();
  stopBonusClock();
  stopBonusCountdown();
  // The pressing follows the game in from the shelf, so the play screen is visibly the
  // same record you picked up rather than a generic titled page. A LENS run is not off the shelf
  // at all, so it is titled for the mode and the lens instead of for the roster entry it happens
  // to be played through — "Ruthless Game" is a retired card, and with six lenses the one thing
  // the header has to say is which of them you are on.
  const lens = lensId ? ruthlessLens(lensId) : null;
  const title = lens ? `Ruthless · ${lens.label}` : g.name;
  screens.bonusplay.dataset.bonusGame = lens ? "ruthless" : g.id;
  $("bonusPlayTitle").innerHTML = `${bonusDisc(g, "bonus-disc-sm")}<span>${escapeHtml(title)}</span>`;
  flipAwayToScreen("bonusplay");
  nextBonusRound();
}

function bonusSeconds() {
  if (!bonusGame) return BONUS_NAME_SECONDS;
  if (bonusGame.id === "spot-the-slip") return BONUS_SLIP_SECONDS;
  if (bonusGame.id === "sing-it-back") return BONUS_BLANK_SECONDS;
  if (bonusGame.id === "redacted") return BONUS_REDACT_SECONDS;
  if (bonusGame.id === "only-here") return BONUS_ONLY_SECONDS;
  // Then What's budget is spent per PICK rather than per page: the clock restarts under
  // every set of three cards, which is what keeps the answer an instinct rather than a
  // deliberation.
  if (bonusGame.id === "then-what") return BONUS_CHAIN_SECONDS;
  // Ruthless Game has no budget: its page runs until it is named or given up on, and the
  // seconds it took ARE the score. Nothing asks this for a timed game (startBonusClock takes
  // the count-up branch before it gets here), so the value is never reached in practice.
  return BONUS_NAME_SECONDS;
}

// This game's puzzle for one page, avoid-lists included. Split out from nextBonusRound so the
// dev tools can build a page's worth without driving the screen.
function buildBonusPuzzle() {
  const { lineIndex, ctx } = bonusIndexes();
  const songs = bonusSongs();
  if (bonusGame.id === "spot-the-slip")
    return buildSlipPuzzle(songs, playableWords, lineIndex, ctx, Math.random, 120, new Set(bonusRecentFakes));
  if (bonusGame.id === "sing-it-back")
    return buildBlankPuzzle(songs, ctx, Math.random, 120, new Set(bonusRecentSongs));
  if (bonusGame.id === "redacted")
    return buildRedactedPuzzle(songs, ctx, lineIndex, Math.random, 120, new Set(bonusRecentSongs));
  if (bonusGame.id === "only-here")
    // The run's ramp: the early pages deal a wide hand with an obvious outlier, the later ones
    // a compressed one where the answer is a judgement rather than a read.
    return buildOnlyHerePuzzle(songs, bonusIndexes().wordIndex, Math.random, 120,
                               new Set(bonusRecentSongs),
                               { tight: bonusRound > ONLY_WIDE_PAGES, words: onlyDealt });
  if (bonusGame.id === "then-what")
    // The run's own ramp: the early pages keep the chain inside one section, the later ones
    // ask for a chain that crosses a section boundary.
    return buildChainPuzzle(songs, Math.random, 120, new Set(bonusRecentSongs),
                            { cross: bonusRound > CHAIN_EASY_PAGES });
  if (bonusGame.id === "ruthless-game")
    return buildRuthlessPuzzle(songs, Math.random, 120, new Set(bonusRecentSongs), activeLens());
  return buildNamePuzzle(songs, lineIndex, Math.random, 120, new Set(bonusRecentSongs));
}

function nextBonusRound() {
  if (bonusRound >= BONUS_ROUNDS) { endBonusRun(); return; }
  bonusRound++;
  bonusPuzzle = buildBonusPuzzle();
  // A builder returning null means it couldn't find a puzzle clearing its fairness bars. That
  // should be vanishingly rare, but skipping the page is the honest response — never show a
  // puzzle we can't vouch for. Settled BEFORE the page turns, so a skip can never leave a
  // half-turned sheet on the desk or start two flips over each other.
  if (!bonusPuzzle) { nextBonusRound(); return; }
  if (bonusPuzzle.fakeWord) {
    bonusRecentFakes.push(bonusPuzzle.fakeWord.toLowerCase());
    if (bonusRecentFakes.length > 6) bonusRecentFakes.shift();
  }
  if (bonusGame.id === "name-that-song" || bonusGame.id === "sing-it-back" || bonusGame.id === "redacted" ||
      bonusGame.id === "only-here" || bonusGame.id === "then-what" ||
      bonusGame.id === "ruthless-game")
    bonusRecentSongs.push(bonusPuzzle.song.title);
  // A fresh page opens worth the full ten and nothing has been spent on it yet.
  redactWorth = bonusPagePoints(bonusGame);
  redactPeeled = 0;
  onlyPlayed = null;
  if (bonusGame.id === "only-here" && bonusPuzzle.hand)
    bonusPuzzle.hand.forEach((c) => onlyDealt.add(c.key));
  // A fresh chain: nothing picked, nothing banked. The longest run survives the page.
  chainStep = 0;
  chainTaken = [];
  chainPage = 0;
  chainBusy = false;
  stopChainBeat();
  // Nothing of the song is out yet, nothing has been fined, and the page has cost nothing.
  ruthlessShown = 0;
  ruthlessPenalty = 0;
  ruthlessSpent = 0;

  // Everything that makes the new page: the shared chrome, then the game's own body.
  const lay = () => {
    bonusLocked = false;
    $("bonusFeedback").innerHTML = "";
    $("bonusFeedback").className = "bg-feedback";
    $("bonusProgress").textContent = `round ${bonusRound} / ${BONUS_ROUNDS}`;
    $("bonusScore").textContent = bonusScoreText();
    $("bonusTimer").style.display = "";
    renderBonusPageRegister();
    renderBonusRound();
  };
  // The same page turn the round screen uses, and the same whoosh — a bonus page is a page of
  // this notebook too. Page 1 lays down instantly: startBonusGame has just turned the whole
  // card in, so there is no answered page to lift (the round screen's round-0 case exactly).
  playSound("page");
  if (bonusRound === 1 || !pageTurnAnimated()) { lay(); startBonusClock(); return; }
  turnPageSheet($("screen-bonusplay"), lay, startBonusClock);
}

// Shelf games are ten-page notebook stacks. Ruthless only borrows their loop and keeps its
// own mode furniture, so it deliberately does not inherit the shelf's margin register.
function renderBonusPageRegister() {
  const el = $("bonusPageRegister");
  const shelfRun = bonusGame && bonusGame.shelf !== false && !ruthlessLensId && !bonusEnded;
  renderNotebookPageRegister(el, bonusRound, shelfRun ? BONUS_ROUNDS : 0,
                             shelfRun ? bonusGame.tint : "");
}

/* The writing line, borrowed wholesale from the round screen: same `.input-area` (which is
   what puts the pencil at the start of the line), same `.song-input`, same washi-taped
   `.dropdown` cards. A bonus game asks a different question, but it should ask it on the
   same stationery. `hint` mirrors the round screen's hint line under the input. */
function bonusWritingLine({ placeholder, aria, hint, dropdown = false }) {
  return `<div class="input-area bg-write${dropdown ? " bg-write--sug" : ""}">` +
      `<input id="bonusInput" class="song-input" type="search" autocomplete="off" autocapitalize="off" ` +
             `data-1p-ignore data-lpignore="true" data-bwignore="true" data-protonpass-ignore="true" data-dashlane-ignore="true" data-form-type="other" ` +
             `spellcheck="false" placeholder="${escapeHtml(placeholder)}" aria-label="${escapeHtml(aria)}"` +
             (dropdown
               ? ` role="combobox" aria-expanded="false" aria-controls="bonusDropdown" ` +
                 `aria-haspopup="listbox" aria-autocomplete="list"`
               : "") + ` />` +
      `<div id="bonusReject" class="bg-reject"></div>` +
      (dropdown ? `<div id="bonusDropdown" class="dropdown" role="listbox" aria-label="Matching songs"></div>` : "") +
    `</div>` +
    `<p class="bg-hint">${escapeHtml(hint)}</p>`;
}

/* A song heading written across the top of the page, the way a lyric sheet in this notebook
   would be titled: the name in pen, the section it came from noted underneath. */
function bonusSongHead(song, label) {
  return `<div class="bg-sheet">` +
      `<h3 class="bg-sheet-title">${escapeHtml(song.title)}</h3>` +
      `<div class="bg-sheet-rule" aria-hidden="true"></div>` +
      `<div class="bg-sheet-meta">${escapeHtml(song.album)}` +
        (label ? ` · ${escapeHtml(label.toLowerCase())}` : "") + `</div>` +
    `</div>`;
}

function renderBonusRound() {
  const body = $("bonusPlayBody");
  const p = bonusPuzzle;
  const label = p.label ? `<div class="bg-section">${escapeHtml(p.label.toLowerCase())}</div>` : "";

  if (bonusGame.id === "spot-the-slip") {
    const words = p.tokens.map((t, i) => t.tappable
      ? `<button type="button" class="bg-word" data-i="${i}">${escapeHtml(t.text)}</button>`
      : `<span class="bg-word-plain">${escapeHtml(t.text)}</span>`).join(" ");
    body.innerHTML =
      `<p class="bg-ask">tap the word that was swapped in</p>` +
      label +
      `<div class="bg-line" role="group" aria-label="Lyric line with one wrong word">${words}</div>`;
    body.querySelectorAll(".bg-word").forEach((b) =>
      b.addEventListener("click", () => judgeSlip(+b.dataset.i)));
  } else if (bonusGame.id === "sing-it-back") {
    // The song is named on purpose (see buildBlankPuzzle) — the test is recalling this line,
    // not deducing a word that would fit any line. The gap is a fixed width whatever the
    // answer is, so it never quietly hands over a letter count.
    const words = p.tokens.map((t) => escapeHtml(t.pre) +
      (t.blank
        ? `<span class="bg-blank" id="bonusBlank"></span>`
        : escapeHtml(t.core)) +
      escapeHtml(t.post)).map((w) => `<span class="bg-word-plain">${w}</span>`).join(" ");
    body.innerHTML =
      `<p class="bg-ask">write the missing word</p>` +
      bonusSongHead(p.song, p.label) +
      `<div class="bg-line bg-blank-line" role="group" aria-label="Lyric line with one word missing">${words}</div>` +
      bonusWritingLine({ placeholder: "the missing word…", aria: "Type the missing word",
                         hint: "one word, then Enter" });
    const input = $("bonusInput");
    // Mirror the typing straight into the gap, so the player is filling the line in rather
    // than answering a question about it.
    input.addEventListener("input", () => {
      const gap = $("bonusBlank");
      if (gap) gap.textContent = input.value.trim();
    });
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") { e.preventDefault(); judgeGap(); }
    });
    focusRoundInput(input);
  } else if (bonusGame.id === "then-what") {
    // The song is named at the top for Sing It Back's reason: the answer has to be pinned by a
    // real song rather than by whatever lines could be argued into. Solving it means singing
    // the thing in your head, and you can't sing a song you haven't been told.
    body.innerHTML =
      `<p class="bg-ask">tap the line that comes next</p>` +
      bonusSongHead(p.song, p.label) +
      `<div class="bg-chain" id="bonusChain"></div>` +
      `<div class="bg-chain-cards" id="bonusChainCards"></div>` +
      `<p class="bg-hint" id="bonusChainHint"></p>`;
    renderChainSheet();
    renderChainCards();
  } else if (bonusGame.id === "only-here") {
    // A song's name and six of its own words, and nothing else. The price ladder used to be
    // pencilled in between the two, from the version where you WROTE a word and were betting
    // on what it would turn out to be worth. Dealing the hand killed the bet: the rarest card
    // is the right card at every price, so the ladder cannot change a single pick, and the
    // reveal teaches it properly by writing each card's count and payout on the card itself.
    body.innerHTML =
      `<p class="bg-ask">pick the word the fewest other songs sing</p>` +
      bonusSongHead(p.song, "") +
      `<div class="bg-hand" id="bonusHand"></div>` +
      `<p class="bg-hint">every one of them is in the song, spelled the way it is sung</p>`;
    renderOnlyHand();
  } else if (bonusGame.id === "ruthless-game") {
    // The song writes itself out into `.bg-stream`, a word a second, breaking where the song
    // breaks. Nothing about the song is named anywhere on the page — no title, no album, no
    // section — because the stream is the only evidence there is meant to be.
    body.innerHTML =
      `<p class="bg-ask">name the song — a word arrives every second</p>` +
      `<div class="bg-stream" id="bonusStream" role="log" aria-live="polite" ` +
           `aria-label="The song, one word at a time"></div>` +
      `<p class="bg-worth"><b id="bonusWords">0</b> words · <b id="bonusSpent">0:00</b> on this page` +
        `<span id="bonusOut" class="bg-out"></span></p>` +
      bonusWritingLine({ placeholder: "type the title…", aria: "Type the song title",
                         hint: "a wrong guess costs nothing but the seconds it took", dropdown: true }) +
      `<button type="button" id="bonusGiveUp" class="btn-ghost bg-giveup"></button>`;
    const input = $("bonusInput");
    input.addEventListener("input", updateBonusDropdown);
    input.addEventListener("keydown", (e) => {
      if (bonusDropdownKey(e)) return;
      if (e.key === "Enter") { e.preventDefault(); judgeName(); }
    });
    $("bonusGiveUp").addEventListener("click", giveUpRuthless);
    /* Baselined HERE as well as in startRuthlessClock, which runs a page-flip later. The page is
       live from the moment it is laid down — the input is rendered and focused — so an answer
       given during the flip would otherwise be timed from the PREVIOUS page's baseline and
       charged a minute it never took. The clock re-baselines when it starts a beat later, so
       the flip itself is not charged to anyone who doesn't answer during it. */
    ruthlessStart = performance.now();
    // The first word is on the page before the clock's first tick, so it never opens blank and
    // the player is reading something from the moment the sheet lands.
    for (let i = 0; i < RUTHLESS_OPEN_WORDS; i++) revealRuthlessWord();
    updateRuthlessMeta();
    focusRoundInput(input);
  } else if (bonusGame.id === "redacted") {
    // Punctuation stays OUTSIDE the strip, on both counts: a comma is grammar rather than a
    // secret, and real redaction blacks the word, not the line's furniture. The word itself is
    // in the DOM under the tape, hidden rather than absent — which is what makes every block
    // exactly its own word's width without the code guessing at letter widths in a
    // handwriting face, and what lets a strip peel off to reveal something already there.
    let bi = 0;
    const rows = p.rows.map((toks) =>
      `<div class="bg-rline">` + toks.map((t) => {
        const core = t.hide
          ? `<button type="button" class="bg-tape" data-i="${bi++}" data-w="${escapeHtml(t.key)}" ` +
              `aria-label="peel a strip">` +
              `<span class="bg-tape-word">${escapeHtml(t.core)}</span>` +
              `<span class="bg-tape-strip" aria-hidden="true"></span></button>`
          : escapeHtml(t.core);
        return `<span class="bg-tok">${escapeHtml(t.pre)}${core}${escapeHtml(t.post)}</span>`;
      }).join("") + `</div>`).join("");
    body.innerHTML =
      `<p class="bg-ask">name the song — every strip you peel costs a point</p>` +
      label +
      `<div class="bg-redact" role="group" aria-label="A verse with words taped over">${rows}</div>` +
      `<p class="bg-worth">this page is worth <b id="bonusWorth">${redactWorth}</b></p>` +
      bonusWritingLine({ placeholder: "type the title…", aria: "Type the song title",
                         hint: "Enter accepts the top match", dropdown: true });
    body.querySelectorAll(".bg-tape").forEach((b) => b.addEventListener("click", () => peelTape(b)));
    const input = $("bonusInput");
    input.addEventListener("input", updateBonusDropdown);
    input.addEventListener("keydown", (e) => {
      if (bonusDropdownKey(e)) return;
      if (e.key === "Enter") { e.preventDefault(); judgeName(); }
    });
    // Deliberately NOT focused: the first thing to do on this page is read it and choose a
    // strip, and a focused field on a phone would put a keyboard over the verse before the
    // player had seen it.
  } else {
    body.innerHTML =
      `<p class="bg-ask">name the song this line is from</p>` +
      label +
      `<blockquote class="bg-lyric">${escapeHtml(p.line)}</blockquote>` +
      bonusWritingLine({ placeholder: "type the title…", aria: "Type the song title",
                         hint: "Enter accepts the top match", dropdown: true });
    const input = $("bonusInput");
    input.addEventListener("input", updateBonusDropdown);
    input.addEventListener("keydown", (e) => {
      if (bonusDropdownKey(e)) return;
      if (e.key === "Enter") { e.preventDefault(); judgeName(); }
    });
    focusRoundInput(input);
  }
}

/* ---------- the clock ----------
   setInterval off a performance.now() baseline, matching the main game's timer rather than
   requestAnimationFrame: rAF is suspended in a backgrounded tab, which would freeze the clock
   while hidden and then, because the deadline is absolute, expire the round the instant the
   player came back. An interval keeps ticking (throttled but firing) and stays accurate. */
function startBonusClock() {
  stopBonusClock();
  // A page answered during its own flip-in is already settled by the time this runs (it is
  // turnPageSheet's after-callback), and restarting a clock over a verdict would run the drip
  // on a page that is showing its answer.
  if (bonusLocked) return;
  if (bonusTimed(bonusGame)) { startRuthlessClock(); return; }
  const fill = $("bonusTimerFill");
  const label = $("bonusTimerLabel");
  const secs = bonusSeconds();
  const total = secs * 1000;
  const started = performance.now();
  fill.style.width = "100%";
  fill.classList.remove("low");
  // The seconds are written out as well as drawn, exactly as the round screen does it — a bar
  // alone tells you time is going but never how much of it there is left to spend.
  label.textContent = secs.toFixed(1);
  bonusRaf = setInterval(() => {
    const left = Math.max(0, total - (performance.now() - started));
    const pct = (left / total) * 100;
    fill.style.width = pct + "%";
    label.textContent = (left / 1000).toFixed(1);
    fill.classList.toggle("low", pct <= 25);
    if (left <= 0) bonusTimeout();
  }, 50);
}
function stopBonusClock() {
  if (bonusRaf) clearInterval(bonusRaf);
  bonusRaf = null;
  stopRuthlessDrip();
}

/* ---------- Ruthless Game: the count-up clock and the drip ----------
   Two intervals rather than one, because they are measuring different things and must not
   drift into each other: the clock is a readout off a performance.now() baseline (so it stays
   accurate however the interval is throttled), and the drip is a metronome that has to keep a
   one-second beat. setInterval for both, matching every other clock here — rAF is suspended in
   a background tab, and a game whose whole score is elapsed time cannot have its clock stop
   when the tab does.

   Nothing happens when the gauge fills. There is no deadline on this page, so the bar is a read
   on how expensive the page is getting rather than a countdown, and it fills UP as the seconds
   go on rather than draining away. */
function startRuthlessClock() {
  const fill = $("bonusTimerFill");
  const label = $("bonusTimerLabel");
  ruthlessStart = performance.now();
  fill.style.width = "0%";
  fill.classList.remove("low");
  label.textContent = "0.0";
  bonusRaf = setInterval(() => {
    const spent = (performance.now() - ruthlessStart) / 1000;
    label.textContent = spent.toFixed(1);
    const pct = Math.min(100, (spent / RUTHLESS_PACE_SECONDS) * 100);
    fill.style.width = pct + "%";
    fill.classList.toggle("low", pct >= 75);
    const el = $("bonusSpent");
    if (el) el.textContent = fmtTime(spent);
  }, 50);
  startRuthlessDrip();
}

function startRuthlessDrip() {
  stopRuthlessDrip();
  ruthlessDripId = setInterval(() => {
    if (bonusLocked) return;
    revealRuthlessWord();
  }, RUTHLESS_WORD_MS);
}
function stopRuthlessDrip() {
  if (ruthlessDripId) clearInterval(ruthlessDripId);
  ruthlessDripId = null;
}

// One more word onto the page. The stream simply stops when the song runs out — by then the
// player is looking at the entire lyric, and there is nothing left to give them.
function revealRuthlessWord() {
  const p = bonusPuzzle;
  const el = $("bonusStream");
  if (!p || !el || ruthlessShown >= p.stream.length) return;
  const tok = p.stream[ruthlessShown++];
  if (tok.br) el.appendChild(document.createElement("br"));
  const s = document.createElement("span");
  s.className = "bg-drip";
  s.textContent = tok.text;
  el.appendChild(s);
  el.scrollTop = el.scrollHeight;
  updateRuthlessMeta();
}

// The word count, and what the give-up button is offering. The button says how far off it is
// while it is still locked, so it never reads as broken — a disabled control with no
// explanation is the same thing as a bug.
// The run's lens object, or null on the shelf's whole-song game.
function activeLens() { return ruthlessLensId ? ruthlessLens(ruthlessLensId) : null; }
// What walking away costs on this run. Priced off the LENS's own median rather than one pair of
// constants, because the chorus resolves at a median of 22 words and the second verse at 79: at
// the shelf's 20-words-then-90-seconds the chorus would be offering the valve only after the
// answer had already gone past, at a price nothing could make worth taking.
function ruthlessSkip() { return ruthlessGiveUp(activeLens()); }
function updateRuthlessMeta() {
  const n = $("bonusWords");
  if (n) n.textContent = ruthlessShown;
  /* A page CAN run dry: 26 of the 287 songs never sing their own title, so for those the stream
     ends without ever handing the answer over. Said out loud rather than left to look like a
     stalled metronome — a page that has stopped giving and doesn't say so reads as broken, and
     it is also the moment the give-up stops being a mercy and becomes the only move. */
  const out = $("bonusOut");
  if (out && bonusPuzzle)
    out.textContent = ruthlessShown >= bonusPuzzle.stream.length ? " · that is the whole song" : "";
  const b = $("bonusGiveUp");
  if (!b) return;
  const { after, penalty } = ruthlessSkip();
  const left = after - ruthlessShown;
  b.disabled = left > 0;
  b.textContent = left > 0
    ? `give up in ${left} word${left === 1 ? "" : "s"}`
    : `give up · +${fmtTime(penalty)}`;
}

// What this page has cost, read off the clock ONCE and then held. A page is never free: a title
// typed inside half a second still rounds up to a second, so ten pages can never total nothing.
function ruthlessFreeze() {
  if (!ruthlessSpent)
    ruthlessSpent = Math.max(1, Math.round((performance.now() - ruthlessStart) / 1000)) + ruthlessPenalty;
  return ruthlessSpent;
}

/* Walking away from a page. The penalty is banked BEFORE the page is frozen, so it lands in the
   one number the run carries. Deliberately not a fail state in the run's terms — the page is
   over and paid for, and the sleeve marks it with a cross so a given-up page can never pass for
   a named one (which is also what stops it counting toward a clean sweep). */
function giveUpRuthless() {
  if (bonusLocked || !bonusTimed(bonusGame)) return;
  const { after, penalty } = ruthlessSkip();
  if (ruthlessShown < after) return;
  ruthlessPenalty = penalty;
  const input = $("bonusInput");
  if (input) input.disabled = true;
  settleRuthless(false);
}

// The verdict line: what the page cost and what it took to get there, or what walking away
// cost. Both are the only number on screen that matters, so both are said in full.
function settleRuthless(correct) {
  const secs = ruthlessFreeze();
  accrueRuthlessXp(correct, secs);
  const detail = correct
    ? `named in <b>${fmtTime(secs)}</b> off <b>${ruthlessShown}</b> word${ruthlessShown === 1 ? "" : "s"}`
    : `given up after <b>${ruthlessShown}</b> words · <b>+${fmtTime(ruthlessSkip().penalty)}</b> on the run`;
  settleBonusRound(correct, detail);
}

/* Instinct and Quick Pen, page by page, in the main game's own formulas. Accrued here rather
   than worked out at the end because a streak has to be watched as it happens, and because a
   page's speed only means anything against the page it was.

   The main game reads Quick Pen off what was LEFT on the buzzer; a Ruthless page has no buzzer,
   so the lens's own measured median stands in for one. A page named at the median earns the
   base and nothing more, a page named instantly earns the lot, and a page that ran long earns
   the base — which is the right shape, since the median is what an honest page of that lens
   costs and beating it is the only thing there is to be quick about. A given-up page earns
   nothing and breaks the streak: it was not named, and nothing else here pretends otherwise. */
function accrueRuthlessXp(correct, secs) {
  if (!ruthlessLensId) return;   // the shelf's lens-less run is a bonus game and banks nothing
  if (!correct) { ruthlessStreak = 0; return; }
  ruthlessStreak++;
  ruthlessXp.resolve += Math.round(RESOLVE_BASE * (1 + 0.1 * Math.min(ruthlessStreak, RESOLVE_STREAK_CAP)));
  const median = (activeLens() && activeLens().median) || 60;
  const speedFactor = Math.max(0, Math.min(1, 1 - secs / median));
  ruthlessXp.tempo += Math.round(TEMPO_BASE + TEMPO_SPEED * speedFactor);
}

/* The reveal. The heading that every other page on this shelf opens with goes on at the END
   here, because naming the song is the whole question — and once it is answered the page is
   simply a lyric sheet with the song's name written over it. No answer card, for the usual
   reason: the heading names it and the words are already all there. */
function revealRuthless() {
  const body = $("bonusPlayBody");
  const ask = body.querySelector(".bg-ask");
  if (ask) ask.remove();
  const stream = $("bonusStream");
  if (!stream) return;
  stream.classList.add("is-done");
  stream.insertAdjacentHTML("beforebegin", bonusSongHead(bonusPuzzle.song, ""));
}

/* Dev only: how many words in the stream first spells the song's own title out, or -1 if the
   song never names itself. That number is the guarantee this game rests on — a page cannot be
   unsolvable, only expensive — so it is worth being able to measure across a sample rather than
   trusted. Kept beside the game rather than in the dev block because the builder's comment
   points at it. */
function devRuthlessTitleAt(p) {
  const key = (s) => String(s).toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");
  const want = String(p.song.title).split(/\s+/).map(key).filter(Boolean);
  if (!want.length) return -1;
  const got = p.stream.map((w) => key(w.text));
  for (let i = 0; i + want.length <= got.length; i++) {
    let hit = true;
    for (let j = 0; j < want.length; j++) if (got[i + j] !== want[j]) { hit = false; break; }
    if (hit) return i + want.length;
  }
  return -1;
}

function bonusTimeout() {
  if (bonusLocked) return;
  // Then What's clock runs per PICK, so its timeout is a missed pick rather than a lost page:
  // the correct line still locks in and the chain carries on. It is the one game here whose
  // page cannot time out at all.
  if (bonusGame && bonusGame.id === "then-what") { judgeChain(-1); return; }
  // Spot the Slip names the impostor even on a timeout: that word is the one thing the page
  // still has to teach, and unlike the other two games the answer card can't carry it (the card
  // shows the line as it really goes, with no sign of what stood in the gap).
  const detail = bonusGame && bonusGame.id === "spot-the-slip"
    ? `<b>${escapeHtml(bonusPuzzle.fakeWord)}</b> was the slip`
    : "";
  settleBonusRound(false, detail, true);
}

/* ---------- judging ---------- */
function judgeSlip(i) {
  if (bonusLocked) return;
  const correct = i === bonusPuzzle.answer;
  // Mark the tap and always reveal the real impostor, so a wrong guess still teaches the line.
  const btns = $("bonusPlayBody").querySelectorAll(".bg-word");
  btns.forEach((b) => {
    const idx = +b.dataset.i;
    b.disabled = true;
    if (idx === bonusPuzzle.answer) b.classList.add("is-answer");
    else if (idx === i) b.classList.add("is-wrong");
  });
  // Naming the impostor is worth saying either way: on a hit it confirms what was spotted, on a
  // miss it's the whole lesson. The real word is then shown in place on the card below.
  settleBonusRound(correct, `<b>${escapeHtml(bonusPuzzle.fakeWord)}</b> was the slip`);
}

/* ---------- Then What: the chain ----------
   Two halves of one page: the SHEET, a verse growing down the paper a line at a time, and the
   CARDS, three lines under it of which one really comes next.

   ONE TAP COMMITS. No confirm, no undo, and the verdict lands in the same instant — which is a
   deliberate departure from the shelf's tap-then-tap rule. That rule exists for ARRANGING
   (Invisible String), where nothing should be judged until the board is complete; here instant
   judgement IS the design, and a confirm step would be actively hostile to it. The cards are
   spaced to absorb the misclick, and a fat finger costs a point.

   Whatever was picked, the RIGHT line locks into the sheet: a wrong pick goes into the margin
   above it, struck through in pencil with a red cross, and the page carries on. So the page is
   always building toward the truth and never has a wrong verse on it — which is why, unlike the
   board it replaced, this game has nothing to straighten out at the end.

   A miss does NOT end the page. Sudden death is more dramatic and was rejected: it makes a
   clean sweep arithmetically unreachable, and it restores exactly the bimodal problem this
   rebuild exists to solve, since a page on a song you don't know would end on pick 1. */
const CHAIN_BEAT_MS = 780;   // long enough to read the mark before the next three deal

function stopChainBeat() {
  if (chainBeatId) clearTimeout(chainBeatId);
  chainBeatId = null;
}

/* The verse as it stands: the line the page opened on, then every pick's real successor, with
   any wrong pick noted in the margin above the line that corrected it. Nothing here is the
   player's arrangement — it is the song, annotated. */
function chainSheetRows() {
  const p = bonusPuzzle;
  const rows = [{ text: p.anchor.text, label: p.anchor.label, si: p.anchor.si }];
  chainTaken.forEach((t, i) => {
    if (!t.right) rows.push({ miss: true, text: t.picked >= 0 ? p.picks[i].cards[t.picked].text : null });
    rows.push({ ...p.picks[i].answer, fresh: i === chainTaken.length - 1 });
  });
  return rows;
}

function renderChainSheet() {
  const wrap = $("bonusChain");
  if (!wrap || !bonusPuzzle) return;
  let seen = null;   // the section the last locked line belonged to
  wrap.innerHTML = chainSheetRows().map((r) => {
    if (r.miss)
      // The clock taking a pick is not a wrong answer, so it isn't struck through like one —
      // there was nothing written to strike out.
      return `<div class="bg-chain-row is-miss">` +
          `<span class="bg-chain-mark" aria-hidden="true">${BG_CROSS}</span>` +
          (r.text
            ? `<span class="bg-chain-text"><s>${escapeHtml(censor(r.text))}</s></span>` +
              `<span class="sr-only">you picked this, and it was wrong</span>`
            : `<span class="bg-chain-text is-late">the clock took this one</span>`) +
        `</div>`;
    // The section is noted in the margin only where it CHANGES, so a chain crossing a boundary
    // shows where it crossed instead of repeating one word down the whole page.
    const turn = r.si !== undefined && r.si !== seen;
    if (turn) seen = r.si;
    const sec = turn && r.label
      ? `<span class="bg-chain-sec">${escapeHtml(r.label.toLowerCase())}</span>` : "";
    // The newest line inks in. Nothing depends on the animation finishing, so reduced motion
    // and instant speed simply have it there already.
    const fresh = r.fresh && !motionReduced() && !animInstant() ? " is-new" : "";
    return `<div class="bg-chain-row${fresh}">${sec}` +
        `<span class="bg-chain-text">${escapeHtml(censor(r.text))}</span></div>`;
  }).join("");
}

function renderChainCards() {
  const wrap = $("bonusChainCards");
  const hint = $("bonusChainHint");
  if (!wrap || !bonusPuzzle) return;
  const pick = bonusPuzzle.picks[chainStep];
  if (!pick) { wrap.innerHTML = ""; if (hint) hint.textContent = ""; return; }
  // Full-width lines rather than a row of columns: a lyric line wants to be read left to right,
  // and squeezing three of them into thirds of the page makes all three unreadable.
  wrap.innerHTML = pick.cards.map((c, i) =>
    `<button type="button" class="bg-chain-card" data-i="${i}">` +
      `<span class="bg-chain-text">${escapeHtml(censor(c.text))}</span></button>`).join("");
  wrap.querySelectorAll(".bg-chain-card").forEach((b) =>
    b.addEventListener("click", () => judgeChain(+b.dataset.i)));
  // What this pick is worth is said out loud. The ramp is meant to be felt rather than
  // explained, but being paid more for a harder pick is not a secret worth keeping.
  if (hint) hint.textContent =
    `pick ${chainStep + 1} of ${CHAIN_PICKS} · worth ${CHAIN_PAY[chainStep]}`;
}

/* One tap, judged on the spot. `i` is -1 when the clock took the pick, which counts as a miss
   in every way except that there is nothing to strike through: the correct line still locks in
   and the chain carries on, exactly as a wrong tap does. */
function judgeChain(i) {
  if (bonusLocked || chainBusy || !bonusPuzzle) return;
  const pick = bonusPuzzle.picks[chainStep];
  if (!pick) return;
  chainBusy = true;
  stopBonusClock();

  const right = i >= 0 && !!pick.cards[i].right;
  if (right) {
    chainPage += CHAIN_PAY[chainStep];
    chainNow++;
    if (chainNow > chainRun) chainRun = chainNow;
  } else chainNow = 0;
  chainTaken.push({ picked: i, right });
  playSound(right ? "correct" : "wrong");

  // Mark the cards where they sit: the real one either way, and the wrong tap struck out. The
  // player's eye is on the cards at this moment, so that is where the verdict has to land.
  $("bonusPlayBody").querySelectorAll(".bg-chain-card").forEach((b) => {
    const idx = +b.dataset.i;
    b.disabled = true;
    if (pick.cards[idx].right) b.classList.add("is-answer");
    else if (idx === i) b.classList.add("is-wrong");
  });
  chainStep++;
  renderChainSheet();
  $("bonusScore").textContent = bonusScoreText();

  const on = () => {
    chainBeatId = null;
    chainBusy = false;
    if (chainStep >= CHAIN_PICKS) { settleChain(); return; }
    renderChainCards();
    startBonusClock();
  };
  if (motionReduced() || animInstant()) on();
  else chainBeatId = setTimeout(on, CHAIN_BEAT_MS);
}

// A page is CLEARED at the full six, which is the verse whole — that is what the sleeve's tick
// and the clean-sweep stamp mean here, as everywhere else on the shelf. The picks still pay
// either way: two lines heard out of four is half a page's knowledge and should read as it.
function settleChain() {
  const got = chainTaken.filter((t) => t.right).length;
  settleBonusRound(chainPage === CHAIN_PAGE, chainDetail(got));
}
function chainDetail(got) {
  return `<b>${got}</b> of ${CHAIN_PICKS} lines · <b>${chainPage}</b> point${chainPage === 1 ? "" : "s"}`;
}

/* Dev only: the page's whole chain written out, with each pick's true successor and where its
   two decoys were mined from. The ramp is invisible on screen by design — three lines look the
   same whatever song they came off — which means it is also invisible to anyone checking that
   the ramp happened, so it has to be printable. Kept beside the game rather than in the dev
   block because the builder's comment points at it. */
function devChainLines(p) {
  return [`0. ${p.anchor.text}   [${p.anchor.label}]`].concat(
    p.picks.map((pk, i) =>
      `${i + 1}. ${pk.answer.text}   [${pk.answer.label}] · pays ${CHAIN_PAY[i]} · decoys ` +
      pk.cards.filter((c) => !c.right).map((c) => c.from).join("+")));
}

/* ---------- Redacted: peeling a strip ----------
   The only move on the page, and it is a purchase rather than an answer: the word underneath
   comes back and the page is worth one point less for having it. Past the floor the peels are
   free (see REDACT_MIN_POINTS) — the readout simply stops falling, so a page you have already
   over-spent is still worth finishing rather than abandoning. */
function peelTape(btn) {
  if (bonusLocked || btn.classList.contains("is-open")) return;
  // One WORD, one point. A verse that echoes a line back at itself covers the same word twice,
  // and charging for the twin would be charging for something already on the page — so every
  // strip hiding this word comes off together.
  const twins = btn.dataset.w
    ? [...$("bonusPlayBody").querySelectorAll(`.bg-tape[data-w="${CSS.escape(btn.dataset.w)}"]`)]
    : [btn];
  // The tape lifting off is the whole satisfaction of the game, so it gets a real peel — but
  // it is also the reveal, so with motion reduced the strip simply goes.
  twins.forEach((b) => {
    b.classList.add("is-open");
    b.disabled = true;
    const s = b.querySelector(".bg-tape-strip");
    if (!s) return;
    if (motionReduced() || animInstant()) s.remove();
    else { s.classList.add("is-peeling"); setTimeout(() => s.remove(), 340); }
  });
  redactPeeled++;
  redactWorth = Math.max(REDACT_MIN_POINTS, bonusPagePoints(bonusGame) - redactPeeled);
  const worth = $("bonusWorth");
  if (worth) {
    worth.textContent = redactWorth;
    // A quick knock on the number, so a point going is something you see happen rather than
    // something you notice later.
    worth.classList.remove("is-spent"); void worth.offsetWidth; worth.classList.add("is-spent");
  }
  playSound("hint");   // the same quiet pip the round screen's hint ladder uses — this is one
}

// Everything still taped comes off when the page settles, so the verse is left whole and
// readable. The strips the player never paid for are marked, which is the page's own
// after-the-fact answer to "how much of it was I flying blind on?".
// The verse is also where the song is finally named: the instruction line and the bare section
// label give way to the real lyric-sheet heading (title, red rule, album · section), so the
// finished page is the answer rather than a peeled page with the answer quoted underneath it.
// That is why bonusAnswerCard gives this game no card — see the note there.
function revealRedacted() {
  const body = $("bonusPlayBody");
  body.querySelectorAll(".bg-tape").forEach((b) => {
    b.disabled = true;
    if (b.classList.contains("is-open")) return;
    b.classList.add("is-open", "was-taped");
    const strip = b.querySelector(".bg-tape-strip");
    if (strip) strip.remove();
  });
  const ask = body.querySelector(".bg-ask");
  if (ask) ask.remove();
  const sec = body.querySelector(".bg-section");
  if (sec) sec.remove();
  const verse = body.querySelector(".bg-redact");
  if (verse) verse.insertAdjacentHTML("beforebegin", bonusSongHead(bonusPuzzle.song, bonusPuzzle.label));
}

// What the verdict says about a won page: what it paid out and what it cost.
function redactDetail(points) {
  return `<b>${points}</b> point${points === 1 ? "" : "s"} · ` +
    (redactPeeled ? `${redactPeeled} strip${redactPeeled === 1 ? "" : "s"} peeled` : "not one strip peeled");
}

/* ---------- Name That Song's suggestions ----------
   The round screen's dropdown, on the shelf: same washi-taped cards, same arrow-keys-then-
   Enter feel. It ranks its own matches rather than calling `rankMatches`, deliberately —
   that one filters through `roundAcceptsSong`, which reads the live round's state (Album
   Focus's locked album, a challenge's constraint). A bonus run never sets that state and
   must not be judged by it, so borrowing the ranking would let whatever was played last
   quietly shorten this list. */
let bonusDdItems = [];
let bonusDdIndex = -1;

function bonusRankMatches(query) {
  const q = normalizeTitle(query);
  if (!q) return [];
  const compactQuery = q.replace(/ /g, "");
  const scored = [];
  for (const song of bonusSongs()) {
    const normalIdx = song._norm.indexOf(q);
    // The final title judge already forgives missing or misplaced spaces. Mirror that
    // leniency here so "illicita" can suggest "illicit affairs" as the player types.
    const compactIdx = normalIdx === -1 ? song._norm.replace(/ /g, "").indexOf(compactQuery) : normalIdx;
    const idx = normalIdx === -1 ? compactIdx : normalIdx;
    if (idx === -1) continue;
    scored.push({ song, rank: idx === 0 ? 0 : 1, idx });
  }
  scored.sort((a, b) => a.rank - b.rank || a.idx - b.idx || a.song.title.localeCompare(b.song.title));
  return scored.slice(0, 6).map((s) => s.song);
}

function updateBonusDropdown() {
  bonusDdItems = bonusLocked ? [] : bonusRankMatches($("bonusInput").value);
  bonusDdIndex = bonusDdItems.length ? 0 : -1;
  renderBonusDropdown();
}

function renderBonusDropdown() {
  const dd = $("bonusDropdown");
  const input = $("bonusInput");
  if (!dd || !input) return;
  if (!bonusDdItems.length) { hideBonusDropdown(); return; }
  dd.innerHTML = "";
  bonusDdItems.forEach((song, i) => {
    const div = document.createElement("div");
    div.className = "item" + (i === bonusDdIndex ? " active" : "");
    div.id = "bg-dd-opt-" + i;
    div.setAttribute("role", "option");
    div.setAttribute("aria-selected", i === bonusDdIndex ? "true" : "false");
    div.textContent = censor(song.title);
    div.addEventListener("mousedown", (e) => { e.preventDefault(); judgeName(song); });
    dd.appendChild(div);
  });
  dd.classList.add("show");
  input.setAttribute("aria-expanded", "true");
  input.setAttribute("aria-activedescendant", "bg-dd-opt-" + bonusDdIndex);
}

function hideBonusDropdown() {
  const dd = $("bonusDropdown");
  const input = $("bonusInput");
  if (dd) { dd.classList.remove("show"); dd.innerHTML = ""; }
  if (input) {
    input.setAttribute("aria-expanded", "false");
    input.removeAttribute("aria-activedescendant");
  }
  bonusDdItems = [];
  bonusDdIndex = -1;
}

// Arrow keys walk the list, Escape puts it away. Returns true when the key belonged to the
// dropdown, so the caller's own Enter handling doesn't fire as well.
function bonusDropdownKey(e) {
  if (e.key === "Escape") { hideBonusDropdown(); return true; }
  if (!bonusDdItems.length) return false;
  if (e.key === "ArrowDown") {
    e.preventDefault();
    bonusDdIndex = (bonusDdIndex + 1) % bonusDdItems.length;
    renderBonusDropdown();
    return true;
  }
  if (e.key === "ArrowUp") {
    e.preventDefault();
    bonusDdIndex = (bonusDdIndex - 1 + bonusDdItems.length) % bonusDdItems.length;
    renderBonusDropdown();
    return true;
  }
  return false;
}

// `picked` is a suggestion clicked outright; otherwise Enter takes the highlighted one, and
// failing that whatever was typed is resolved as a title.
function judgeName(picked = null) {
  if (bonusLocked) return;
  const raw = $("bonusInput").value;
  const key = normalizeTitle(raw);
  // Same forgiving title resolution the main game uses, so aliases and misplaced spaces work.
  const typed = key ? (titleIndex.get(key) || spacelessIndex.get(key.replace(/ /g, "")) || null) : null;
  const song = picked || bonusDdItems[bonusDdIndex] || typed;
  if (!song) {
    if (!key) return;
    // Not a song we know: don't burn the round, just say so and let them keep typing.
    const r = $("bonusReject");
    r.textContent = "not a song I know";
    r.classList.remove("show"); void r.offsetWidth; r.classList.add("show");
    return;
  }
  hideBonusDropdown();
  const correct = song.title === bonusPuzzle.song.title;
  /* Ruthless Game judges the same title the same way, but a miss does not end the page: wrong
     guesses are free there by design, so a wrong one is a SOFT reject — say which song was
     rejected, clear the line, and leave the clock running. Guessing early
     and often is the intended play, and it self-regulates because every guess is paid for in
     the seconds it took to type. */
  if (bonusTimed(bonusGame)) {
    if (!correct) {
      const r = $("bonusReject");
      r.textContent = `not ${censor(song.title)}`;
      r.classList.remove("show"); void r.offsetWidth; r.classList.add("show");
      $("bonusInput").value = "";
      return;
    }
    $("bonusInput").disabled = true;
    settleRuthless(true);
    return;
  }
  $("bonusInput").disabled = true;
  // The card below names the right song, so the only thing left to say is what was written —
  // and on a hit that's the same thing twice. Redacted is the exception: a won page there has
  // a number on it, and the number is the whole brag.
  const detail = correct
    ? (bonusGame.id === "redacted" ? redactDetail(bonusPageScore(true)) : "")
    : `you wrote <b>${escapeHtml(censor(song.title))}</b>`;
  settleBonusRound(correct, detail);
}

function judgeGap() {
  if (bonusLocked) return;
  const raw = $("bonusInput").value.trim();
  // Enter on an empty line is a slip of the hand, not an answer — never burn the page on it.
  if (!raw) return;
  const { ctx } = bonusIndexes();
  // The catalogue's word frequencies double as its vocabulary, which is what lets judgeBlank
  // forgive a typo without forgiving a genuinely different word (see judgeBlank).
  const correct = judgeBlank(raw, bonusPuzzle, ctx.freq);
  // The gap is filled with the real word either way, and the card below highlights it in the
  // whole line — so on a miss the only thing worth adding is what was written instead.
  settleBonusRound(correct, correct ? "" : `you wrote “<b>${escapeHtml(raw)}</b>”`);
}

/* ---------- Only Here: the hand ----------
   Six real words off the song, dealt as cut scraps rather than as chips: ransom-note energy
   fits the notebook, and more practically it makes them read as FOUND words rather than as UI
   buttons. Two rows of three, because six in a line is a menu.
   One tap answers the page and there is no fail state, so the only way to score nothing is to
   let the clock go. */
function renderOnlyHand(reveal = false) {
  const wrap = $("bonusHand");
  if (!wrap || !bonusPuzzle) return;
  const p = bonusPuzzle;
  const best = new Set(p.optimal);
  wrap.innerHTML = p.hand.map((c, i) => {
    const picked = !!onlyPlayed && onlyPlayed.i === i;
    // The reveal turns the WHOLE hand over. Everything this game knows and used to keep to
    // itself goes on the page, including on a page played badly — that is the whole redesign.
    const cls = ["bg-scrap",
      reveal ? (best.has(i) ? "is-best" : "") : "",
      reveal && picked ? (best.has(i) ? "is-got" : "is-missed") : ""].filter(Boolean).join(" ");
    const aria = censor(c.word) +
      (reveal ? ` — sung by ${c.count} song${c.count === 1 ? "" : "s"}, worth ${c.points}` +
                (best.has(i) ? ", the rarest in the hand" : "") + (picked ? ", your pick" : "")
              : "");
    return `<button type="button" class="bg-scrap ${cls}" data-i="${i}"${reveal ? " disabled" : ""}` +
        ` aria-label="${escapeHtml(aria)}">` +
        `<span class="bg-scrap-word">${escapeHtml(censor(c.word.toLowerCase()))}</span>` +
        (reveal
          ? `<span class="bg-scrap-count">${c.count === 1 ? "only here" : `in ${c.count}`} · ${c.points}</span>` +
            (picked ? `<span class="bg-scrap-mark" aria-hidden="true">${best.has(i) ? BG_TICK : BG_CROSS}</span>` : "")
          : "") +
      `</button>`;
  }).join("");
  if (!reveal) wrap.querySelectorAll(".bg-scrap").forEach((b) =>
    b.addEventListener("click", () => judgeOnly(+b.dataset.i)));
}

/* One tap, and the page is answered. Every card is real, so every pick banks at least a point
   and nothing here can be WRONG — a page is CLEARED by picking the rarest word in the hand,
   whatever it paid, not by scoring five. A hand's best word might only be worth 3, and a tick
   should mean you played it perfectly rather than that the deal was generous. */
function judgeOnly(i) {
  if (bonusLocked || !bonusPuzzle) return;
  const c = bonusPuzzle.hand[i];
  if (!c) return;
  onlyPlayed = { i, word: c.word, count: c.count, points: c.points,
                 best: bonusPuzzle.optimal.includes(i) };
  settleBonusRound(onlyPlayed.best, onlyDetail(onlyPlayed));
}

// What the verdict says about a played word: the word, what it cost the catalogue to keep
// secret, and what that paid. The count is the whole brag, so it is said before the points.
function onlyDetail(p) {
  return `<b>${escapeHtml(censor(p.word.toLowerCase()))}</b> · ` +
    (p.count === 1 ? "in no other song" : `in <b>${p.count}</b> songs`) +
    ` · ${p.points} point${p.points === 1 ? "" : "s"}`;
}

/* The reveal. The hand turns over in place — every card's true count, the rarest marked in gold,
   the player's own card ticked or crossed — and under it goes the line the rarest word lives in.
   There is no lyric card (see bonusAnswerCard): the heading already names the song, and the one
   thing the page still owes is where that word actually sits. A player who found it is shown
   THEIR word's line, because the page has nothing better to hold up than what they just played. */
function revealOnlyHere() {
  const body = $("bonusPlayBody");
  const ask = body.querySelector(".bg-ask");
  if (ask) ask.remove();
  const p = bonusPuzzle;
  renderOnlyHand(true);
  const best = p.hand[onlyPlayed && onlyPlayed.best ? onlyPlayed.i : p.optimal[0]];
  const line = extractLineWithWord(p.song.lyrics, best.word, true);
  const lead = best.count === 1
    ? `nothing else in the catalogue sings it`
    : `<b>${best.count}</b> songs sing it, and that was the fewest on the page`;
  const html = `<div class="bg-only-reveal">` +
      `<p class="bg-only-said">${lead}</p>` +
      `<p class="bg-only-line">${highlightWord(line, best.word, true)}</p>` +
    `</div>`;
  const wrap = $("bonusHand");
  if (wrap) wrap.insertAdjacentHTML("afterend", html);
  else body.insertAdjacentHTML("beforeend", html);
}

/* The proof of the page, on the round screen's own lyric card: the song in small caps with its
   album tag, the real lyric written out large, and an "in context" peek into the lines either
   side of it. Two of the three games need it, and for opposite reasons — Spot the Slip's page
   shows a DOCTORED line, so the card is where the line goes right (highlighting the real word
   the impostor stood in for), and Name That Song's page shows a real line but no song, so the
   card is the answer.
   Redacted gets no card either, and for Sing It Back's reason: its reveal peels the whole verse
   and writes the song's name and album at the top of it, so a card underneath would quote one
   of the lines already sitting in full an inch above itself — which is exactly what it did
   before revealRedacted took over the attribution.
   Sing It Back is therefore the other exception and gets no card: settleBonusRound writes the
   missing word back into the gap, under a heading that already names the song and album. What
   its page genuinely can't show is the lines EITHER SIDE, so the context peek goes out alone. */
function bonusAnswerCard() {
  const p = bonusPuzzle;
  // Then What has no card for Sing It Back's reason: the page finishes as a verse written out
  // under a heading that already names the song and album, so a card could only reprint a
  // quarter of what is sitting an inch above it.
  // Ruthless Game has none either, and most obviously of all: its reveal writes the song's name
  // over a page that is already the song, printed out further than any card could quote it.
  if (bonusGame.id === "redacted" || bonusGame.id === "only-here" ||
      bonusGame.id === "then-what" || bonusGame.id === "ruthless-game") return "";
  if (bonusGame.id === "sing-it-back")
    return `<div class="bg-ctx">${lyricCardContext(p.song, p.answer, p.line)}</div>`;
  const slip = bonusGame.id === "spot-the-slip";
  return lyricCard(p.song, slip ? p.realWord : null, false, slip ? p.realLine : p.line, true);
}

// The one place a bonus round ends: locks input, scores it, shows the verdict, moves on.
// `detail` is trusted HTML (callers build it from escaped pieces) and may be empty when the
// answer card below says everything worth saying.
// What this page pays. One for a page cleared, unless the game scores on a scale — Redacted's
// page is worth whatever is left of its six, floored so a correct answer always beats a wrong
// one however much of the verse it took.
function bonusPageScore(correct) {
  // A timed game's page doesn't pay, it CHARGES: what the run adds up is the seconds each page
  // took, penalty included, and the lowest total wins.
  if (bonusTimed(bonusGame)) return ruthlessFreeze();
  // Only Here pays for the card that was picked, whatever it was worth — the page is never
  // failed, only answered cheaply or not at all.
  if (bonusGame && bonusGame.id === "only-here") return onlyPlayed ? onlyPlayed.points : 0;
  // Then What pays per PICK, and the picks are not worth the same: 1, 1, 2, 2 up the page, so
  // what the page banked is already added up in chainPage.
  if (bonusGame && bonusGame.id === "then-what") return chainPage;
  if (!correct) return 0;
  if (bonusGame && bonusGame.id === "redacted") return Math.max(REDACT_MIN_POINTS, redactWorth);
  return 1;
}

// The handwritten verdict over the page. A game whose page isn't a single right answer needs
// its own words for a near miss — "not this one" is nonsense about a page of four picks.
function bonusBannerText(correct, isTimeout) {
  // Nothing here times out and nothing here is wrong twice — a page is either named or handed
  // back, so the bad banner reports the decision rather than a mistake.
  if (bonusTimed(bonusGame)) return correct ? "named it" : "handed it back";
  // Nothing is ever WRONG on an Only Here page — every card is real and every pick pays — so
  // the banners grade the read rather than the answer, and the bad one only ever means the
  // clock or a card that wasn't the rarest.
  if (bonusGame && bonusGame.id === "only-here")
    return correct ? (onlyPlayed && onlyPlayed.count === 1 ? "only here" : "the rarest on the page")
                   : isTimeout || !onlyPlayed ? "the page ran out" : "one of them was rarer";
  // Nothing times out here at the page level — the clock takes single picks — so the bad
  // banner reports a broken chain rather than a lost page.
  if (bonusGame && bonusGame.id === "then-what")
    return correct ? "sung it straight through" : "the chain broke";
  return correct ? "that's the one" : isTimeout ? "the page ran out" : "not this one";
}

function settleBonusRound(correct, detail, isTimeout = false) {
  bonusLocked = true;
  stopBonusClock();
  const gained = bonusPageScore(correct);
  bonusScore += gained;
  playSound(correct ? "correct" : "wrong");

  const input = $("bonusInput");
  if (input) input.disabled = true;
  hideBonusDropdown();
  $("bonusPlayBody").querySelectorAll(".bg-word").forEach((b) => { b.disabled = true; });
  // The writing line has done its job, so put it away for the verdict — the round screen hides
  // its play area at exactly this beat. It also gives back the space the answer card wants, which
  // is what keeps the countdown on screen instead of below the fold.
  $("bonusPlayBody").querySelectorAll(".bg-write, .bg-hint, .bg-worth, .bg-giveup, .bg-chain-cards").forEach((el) => { el.style.display = "none"; });

  // The run's track listing, written up on the end card. Each game notes the one thing worth
  // remembering about its page: the impostor you were hunting, the word that was missing, or
  // (Name That Song, where the song IS the answer) which record it came off.
  // `album` and `words` are the Ruthless MODE's alone — the sleeve prints neither. They ride
  // here rather than in a second log because the mode's results page needs exactly this list
  // with two more columns on it: the album to tint the page's bead, and how many words were on
  // the page when it was named.
  bonusLog.push({
    n: bonusRound, ok: correct,
    title: bonusPuzzle.song.title,
    album: bonusPuzzle.song.album,
    words: ruthlessShown,
    note: bonusGame.id === "spot-the-slip" ? bonusPuzzle.fakeWord
        : bonusGame.id === "sing-it-back" ? bonusPuzzle.answer
        // Redacted's pages are worth different amounts, and that number is the only thing the
        // sleeve can't already work out — so it takes the note column outright.
        : bonusGame.id === "redacted" ? `${gained} pts`
        // Every other game notes the answer it was hiding; this one never hid an answer, so
        // the useful keepsake is how the page went.
        : bonusGame.id === "then-what" ? `${gained} pts`
        // What it paid and the word that paid it: this column is the run's own vocabulary,
        // which is the thing worth carrying off ten pages of it. The number leads because the
        // note is clipped from the right at 10ch, and a long word half-shown still reads. A page
        // the clock took carries the word it was hiding instead, in red — every other game's
        // missed note is the answer you didn't have, and this is what that is here.
        : bonusGame.id === "only-here" ? (onlyPlayed ? `${gained} · ${onlyPlayed.word.toLowerCase()}`
                                                     : bonusPuzzle.hand[bonusPuzzle.optimal[0]].word.toLowerCase())
        // The time alone. The word count is the more interesting number and it was tried here
        // first, but the note column runs out around six characters on a two-up sleeve and
        // "1:23 · 62w" came back as "1:23 · …" — so the column keeps the one that adds up to
        // the score, and the verdict line is where a page's word count gets said in full.
        : bonusGame.id === "ruthless-game" ? fmtTime(gained)
        : bonusPuzzle.song.album,
  });
  // Reveal the answer on a timeout too, whichever game we're in.
  if (bonusGame.id === "spot-the-slip") {
    $("bonusPlayBody").querySelectorAll(".bg-word").forEach((b) => {
      if (+b.dataset.i === bonusPuzzle.answer) b.classList.add("is-answer");
    });
  } else if (bonusGame.id === "redacted") {
    revealRedacted();
  } else if (bonusGame.id === "only-here") {
    revealOnlyHere();
  } else if (bonusGame.id === "then-what") {
    // Nothing to reveal: every correct line locked in as it was picked, so the sheet on screen
    // is already the finished verse. All that is left is to take the spent cards away.
    stopChainBeat();
    const cards = $("bonusChainCards");
    if (cards) cards.remove();
  } else if (bonusGame.id === "ruthless-game") {
    revealRuthless();
  } else if (bonusGame.id === "sing-it-back") {
    // Whatever was in the gap — a wrong word, a half-typed one, nothing at all — the real
    // word goes in, so the line is left whole and correct on the page.
    const gap = $("bonusBlank");
    if (gap) {
      gap.textContent = bonusPuzzle.answer;
      gap.classList.add(correct ? "is-got" : "is-answer");
    }
  }

  // The verdict is written up the way the round screen writes one: the handwritten banner, then
  // the proof on a lyric card, then the countdown to the next page. Same furniture, same
  // reading order — a bonus page is answered on this notebook's terms, not the shelf's own.
  const last = bonusRound >= BONUS_ROUNDS;
  const auto = settings.autoAdvance;
  const advanceUI = auto
    ? `<div class="countdown">${last ? "the sleeve" : "next page"} in ` +
        `<b id="bonusCd">${settings.countdownSecs}</b></div>` +
      `<button type="button" id="bonusSkipBtn" class="countdown-skip">skip →</button>`
    : `<button type="button" id="bonusNextBtn" class="btn-ghost">${last ? "the sleeve" : "next page"} →</button>`;
  const fb = $("bonusFeedback");
  fb.className = "bg-feedback show " + (correct ? "ok" : "no");
  fb.innerHTML =
    (correct
      ? `<div class="banner good">✓ ${escapeHtml(bonusBannerText(true, isTimeout))}</div>`
      : `<div class="banner bad">✗ ${escapeHtml(bonusBannerText(false, isTimeout))}</div>`) +
    (detail ? `<p class="bg-detail">${detail}</p>` : "") +
    bonusAnswerCard() +
    advanceUI;
  $("bonusScore").textContent = bonusScoreText();
  bonusFeedbackAt = Date.now();
  $(auto ? "bonusSkipBtn" : "bonusNextBtn").addEventListener("click", advanceFromBonusFeedback);
  if (auto) runBonusCountdown();
}

/* ---------- Between the pages ----------
   The round screen's countdown, on the shelf: the player's own auto-advance setting and their
   own countdown length, so a bonus page waits exactly as long as a real one. With auto-advance
   off it's a "next page" button instead and the run waits to be told. Unlike the round screen,
   the countdown runs on a MISS too — these are ten quick pages and the shelf has always turned
   its own; the reveal is still readable for the full count, and opening "in context" pauses it. */
let bonusCdId = null;
let bonusFeedbackAt = 0;        // ms timestamp the verdict appeared — Enter is held off for ENTER_SKIP_GRACE after it

function stopBonusCountdown() {
  if (bonusCdId) { clearInterval(bonusCdId); bonusCdId = null; }
}

function runBonusCountdown() {
  let n = settings.countdownSecs;
  stopBonusCountdown();
  // Tokenised against the run, like the old between-rounds timeout was: quitting and instantly
  // replaying must not let the abandoned run's countdown turn the new run's page.
  const runAtSettle = bonusRunId;
  bonusCdId = setInterval(() => {
    if ($("settingsModal").classList.contains("open")) return;   // paused while settings is open
    n--;
    if (n <= 0) {
      stopBonusCountdown();
      if (!bonusEnded && bonusGame && bonusRunId === runAtSettle) nextBonusRound();
    } else {
      const el = $("bonusCd");
      if (el) el.textContent = n;
    }
  }, 1000);
}

// Leave the verdict and turn the page — the skip button, the "next page" button and Enter all
// come through here. Guarded so it only fires while a verdict is actually on screen.
function advanceFromBonusFeedback() {
  if (!bonusLocked || bonusEnded || !bonusGame) return;
  stopBonusCountdown();
  nextBonusRound();
}

/* ---------- end of run ----------
   The marks in the margin of the track listing: a gold pen tick, a red pen cross. Drawn
   rather than typed, like every other mark on the site. */
const BG_TICK = `<svg viewBox="0 0 16 16" class="bg-mark-svg" aria-hidden="true"><path d="M3 8.6 L6.4 12 L13 4.6" fill="none" stroke="#c7951f" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const BG_CROSS = `<svg viewBox="0 0 16 16" class="bg-mark-svg" aria-hidden="true"><path d="M4 4 L12 12 M12 4 L4 12" fill="none" stroke="#b23a3f" stroke-width="2" stroke-linecap="round"/></svg>`;

/* The mark on the sleeve's copy button: a second sheet slipped out from behind the first,
   ruled with the two lines every card on this desk is written on, and the gold tick the run
   already uses for a page it got right. Both glyphs ship in the button and the state on the
   element decides which one shows, so a landed copy needs no relayout and no second render. */
const KEEPSAKE_COPY_MARK =
  `<svg viewBox="0 0 24 24" class="keepsake-ic keepsake-ic--copy" aria-hidden="true">` +
    `<path d="M9.7 7 L9.7 4.3 A1.8 1.8 0 0 1 11.5 2.5 L19.2 2.5 A1.8 1.8 0 0 1 21 4.3` +
    ` L21 14.7 A1.8 1.8 0 0 1 19.2 16.5 L16.6 16.5"/>` +
    `<rect x="3" y="7" width="13.5" height="14" rx="1.9"/>` +
    // Two ruled lines, not three: at seventeen pixels a third closes the gaps up into a smudge.
    `<path d="M6.2 12.4 L13.3 12.4 M6.2 16.2 L10.8 16.2"/>` +
  `</svg>` +
  `<svg viewBox="0 0 24 24" class="keepsake-ic keepsake-ic--kept" aria-hidden="true">` +
    `<path d="M4.4 12.9 L9.6 18.2 L19.6 5.9"/>` +
  `</svg>`;

// One line in pen under the game's name. Kept in the shelf's own record-shop voice, and read
// off the same proportions for every game so no game reads as the important one.
// `clean` — every page cleared — carries the top remark rather than a full score, because a
// game scored in points has a maximum nobody will ever reach (Redacted's 100 would mean naming
// ten songs off untouched verses) and the perfect run it CAN have is a run with no misses.
function bonusRemark(score, max, clean) {
  if (bonusTimed(bonusGame)) return ruthlessRemark(score, clean);
  if (clean) return "a perfect pressing";
  const r = max ? score / max : 0;
  if (r >= 0.9) return "one crackle, no more";
  if (r >= 0.7) return "a clean side";
  if (r >= 0.5) return "half the record";
  if (r >= 0.3) return "a rough cut";
  if (score > 0) return "mostly static";
  return "a blank tape";
}

/* The same remark in the shelf's voice, read off a time instead of a proportion — a run scored
   in seconds has no maximum to be a fraction of, so it is graded on what a page averaged. The
   top remark is reserved for a run with nothing given up, for every other game's reason: a
   clean sweep is ten pages named, and a fast run built on two abandoned pages is not one. */
function ruthlessRemark(secs, clean) {
  const avg = secs / BONUS_ROUNDS;
  if (clean && avg <= 10) return "you knew them cold";
  if (avg <= 15) return "barely let it play";
  if (avg <= 25) return "off the first verse, mostly";
  if (avg <= 40) return "a chorus a song";
  if (avg <= 60) return "you heard them out";
  return "the record played you";
}

function endBonusRun() {
  bonusEnded = true;
  renderBonusPageRegister();
  stopBonusClock();
  stopBonusCountdown();
  stopChainBeat();
  playRunFlourish();   // the shelf turns pages like the notebook does, so it closes like it too
  /* A LENS run is the Ruthless mode and leaves here before a single line of the shelf's ending
     runs — most of all before recordBonusRun, which would bank a mode run on the retired card's
     shelf board. The lens-less run below it is the dev-only whole-song game, and that one still
     ends on its sleeve. */
  if (ruthlessLensId) { endRuthlessRun(); return; }
  const timed = bonusTimed(bonusGame);
  // A clean sweep is ten pages cleared, which on a right/wrong game is the same thing as a
  // full score and on a points game is the only perfect run available (see bonusRemark).
  const perfect = bonusLog.length === BONUS_ROUNDS && bonusLog.every((t) => t.ok);
  // The sweep clock, banked only when the run actually swept. A time off a run that dropped a
  // page is not a slower sweep, it is not a sweep, so it is thrown away rather than stored and
  // compared — which is the whole reason the clock costs a player nothing to ignore.
  const sweepSecs = (perfect && bonusSweeps(bonusGame))
    ? (performance.now() - bonusRunStart) / 1000 : null;
  // Read BEFORE the run is banked: a first sweep and a faster one are both `isSweepBest`, and
  // only the second of them has beaten anything, so only the second may say so.
  const hadSweep = bonusRecord(bonusGame.id).sweep;
  const rec = recordBonusRun(bonusGame.id, bonusScore, bonusMaxScore(bonusGame), timed, sweepSecs);
  $("bonusTimer").style.display = "none";
  $("bonusProgress").textContent = "run complete";
  $("bonusScore").textContent = bonusScoreText();
  $("bonusFeedback").innerHTML = "";
  $("bonusFeedback").className = "bg-feedback";

  const max = bonusMaxScore(bonusGame);
  // The run written up on the back of its own sleeve: the pressing, the score in pen, and the
  // ten tracks listed out with what each one turned on. A bonus run has no bracelet and no
  // stats to show for itself by design, so the track listing is the keepsake — and it doubles
  // as the only place the missed answers are all readable at once.
  // The chain line is Then What's alone, and the score sub is the "/60" a timed run doesn't
  // have — both are pulled out here because the sleeve and its PNG have to agree exactly.
  /* The second line under the remark, and the two games that have one can never collide: Then
     What is a points game and so never sweeps, and a sweep line only exists on a run that swept.
     The stamp above it already says CLEAN SWEEP, so this line says what the sweep cost rather
     than repeating that it happened. */
  const aside = bonusGame.id === "then-what"
    ? `longest chain · ${chainRun} line${chainRun === 1 ? "" : "s"}`
    : sweepSecs != null
    ? `in ${fmtTime(sweepSecs)}` + (rec.isSweepBest && hadSweep ? " · fastest yet" : "")
    : "";
  const stampText = perfect ? "clean sweep" : (rec.isBest && rec.plays > 1 ? "new best" : "");
  // The fastest sweep joins the small print only once there IS one. An empty slot on a game
  // you have never swept advertises a ceiling you haven't reached, which is the opposite of
  // what a second axis is for.
  const sweepFoot = rec.sweep ? ` · swept ${fmtTime(rec.sweep)}` : "";
  const foot = timed ? `best ${fmtTime(rec.best)} · played ${rec.plays}`
                     : `best ${Math.min(rec.best, max)} / ${max}${sweepFoot} · played ${rec.plays}`;
  bonusSleeveRun = {
    game: bonusGame,
    remark: bonusRemark(bonusScore, max, perfect),
    aside, stamp: stampText, foot,
    score: timed ? fmtTime(bonusScore) : String(bonusScore),
    scoreSub: timed ? "" : "/" + max,
    tracks: bonusLog.slice(),
  };

  const tracks = bonusLog.map((t) =>
    `<li class="bg-track ${t.ok ? "ok" : "no"}">` +
      `<span class="bg-track-n">${t.n}</span>` +
      `<span class="bg-track-title">${escapeHtml(censor(t.title))}</span>` +
      (t.note ? `<span class="bg-track-note">${escapeHtml(t.note)}</span>` : "") +
      `<span class="bg-track-mark" aria-hidden="true">${t.ok ? BG_TICK : BG_CROSS}</span>` +
      `<span class="sr-only">${t.ok ? "correct" : "missed"}</span>` +
    `</li>`).join("");

  $("bonusPlayBody").innerHTML =
    `<div class="bg-end">` +
      `<div class="bg-sleeve" style="--bg-tint:${escapeHtml(bonusGame.tint)}">` +
        `<div class="bg-sleeve-head">` +
          `<div class="bg-end-disc">${bonusDisc(bonusGame)}</div>` +
          `<div class="bg-sleeve-titles">` +
            `<div class="bg-sleeve-kicker">${escapeHtml(bonusGame.kicker)}</div>` +
            `<h3 class="bg-sleeve-name">${escapeHtml(bonusGame.name)}</h3>` +
            `<div class="bg-sleeve-remark">${escapeHtml(bonusSleeveRun.remark)}</div>` +
            // Then What's other number. It costs nothing and is scored by nothing, but it is
            // the one thing about a run that a total out of sixty can't say.
            (aside ? `<div class="bg-sleeve-chain">${escapeHtml(aside)}</div>` : "") +
          `</div>` +
          // A time stands alone: there is no total for a run of seconds to be out of, and the
          // number is the whole of what the run was.
          `<div class="bg-sleeve-score">${escapeHtml(bonusSleeveRun.score)}` +
            (bonusSleeveRun.scoreSub ? `<span>${escapeHtml(bonusSleeveRun.scoreSub)}</span>` : "") + `</div>` +
          (stampText ? `<i class="bg-stamp">${escapeHtml(stampText)}</i>` : "") +
        `</div>` +
        `<div class="bg-sleeve-label">the run, track by track</div>` +
        `<ol class="bg-tracks">${tracks}</ol>` +
        // The run's only souvenir, taken off the page the way the bracelet is: click to copy
        // the sleeve, shift-click to save it. It rides at the end of the sleeve's own small
        // print rather than under the card, because what it copies is the card it sits in.
        `<div class="bg-sleeve-foot"><span>${escapeHtml(foot)}</span>` +
          `<button type="button" id="saveSleeveBtn" class="bg-sleeve-copy"` +
          ` data-tip="Copy sleeve to clipboard (shift-click to download)">${KEEPSAKE_COPY_MARK}` +
          `<span class="sr-only">Copy sleeve</span></button>` +
        `</div>` +
      `</div>` +
      `<div class="bg-end-actions">` +
        `<button type="button" id="bonusShelfBtn" class="btn-primary">← the shelf</button>` +
        `<button type="button" id="bonusAgainBtn" class="btn-primary">replay ↺</button>` +
      `</div>` +
    `</div>`;
  $("bonusAgainBtn").addEventListener("click", () => startBonusGame(bonusGame));
  $("bonusShelfBtn").addEventListener("click", () => leaveBonusGame());
  $("saveSleeveBtn").addEventListener("click", saveSleevePNG);
}

/* ---------- Ruthless mode: the ending ----------
   The mode's own results path, taken instead of the sleeve, and the whole reason the lens run
   is a gameType rather than a card. It writes the lens's best time, a history row and skill XP,
   and it strings a bracelet — which is the point of the promotion: the most fun thing here used
   to leave one number behind on a shelf board nothing else could see.

   Sandboxed like Custom and Guest, and for the same reasons. No lifetime tally: the ten songs
   were DEALT rather than found from a word, so folding them into Songs Discovered would credit
   the deal to the player. No difficulty records and no cross-game metrics: a run measured in
   seconds cannot be ranked beside one measured out of thirteen. What it does write is its own
   board, the history log (a run you finished happened, and the calendar should show it) and
   skill XP, which is the line Custom and Guest already draw.

   The skills it earns are Instinct and Quick Pen, and NOT Discography, which the roadmap
   expected. Discography measures how far your ANSWERS reach across the albums, and a Ruthless
   page gives you no answer to choose: the song is dealt and there is exactly one thing to type,
   so the breadth on the strand is the deal's breadth and not the player's. That is Album
   Focus's own reason for omitting it, arrived at from the other end. By Heart is out because
   you name titles rather than sing lines, and The Long Game because ten pages is a sitting, not
   a distance. */
function endRuthlessRun() {
  const lensId = ruthlessLensId, lens = ruthlessLens(lensId);
  const secs = bonusScore;
  const pages = bonusLog.slice();
  const named = pages.filter((t) => t.ok).length;
  const gaveUp = pages.length - named;

  let rec = ruthlessRecord(lensId);
  if (!devNoLog) {
    rec = recordRuthlessRun(lensId, secs, gaveUp, todayKey());
    // The score column is pages NAMED and the time column is the run — which is the honest way
    // round, since the seconds are what the board ranks and the pages are what they bought.
    appendHistory({
      s: named, c: named, n: pages.length,
      m: "rl-" + lensId, t: "ruthless",
      d: new Date().toISOString(), tm: secs,
    });
    foldSkillXp(["resolve", "tempo"], ruthlessXp);
  }

  // The strand, one bead a page: tinted to the album the song came off, and a matte spacer
  // wherever a page was handed back. Ten beads and no letter bead — the 13 belongs to a
  // thirteen-round run and would be a borrowed flourish here.
  const results = pages.map((t) => t.ok);
  const albums = pages.map((t) => t.album || null);

  showScreen("results");
  applyEra(FINALE_ERAS[Math.floor(Math.random() * FINALE_ERAS.length)]);
  $("resultBracelet").innerHTML = renderBraceletSVG(results, 0, -1, albums,
    { colors: albumPalette(), total: pages.length, letterBead: false });
  // A time is the whole result, so it takes the big number; the pages it took are the sub.
  $("finalScore").textContent = fmtTime(secs);
  $("finalSub").textContent = gaveUp
    ? `${named} of ${pages.length} named` : `all ${pages.length} named`;
  $("keepGoingBtn").style.display = "none";
  $("namePrompt").style.display = "none";
  $("verseAnthology").style.display = "none";
  hideNewBestBanner();
  document.querySelector("#screen-results .podium-title").textContent =
    "Ruthless · " + (lens ? lens.label : "");

  const beat = rec.isBest && rec.plays > 1;
  let status;
  if (beat) {
    status = `<div class="chall-result-status win">a new best for ${escapeHtml(lens ? lens.label : "this lens")} ★</div>`;
  } else if (rec.plays <= 1) {
    status = `<div class="chall-result-status win">the first time down this lens — a time to beat</div>`;
  } else {
    // How far off the best, said in the same seconds the whole mode is counted in. A run that
    // ties it is neither a beat nor a miss, and saying so is more use than rounding it either way.
    const gap = secs - rec.best;
    status = gap === 0
      ? `<div class="chall-result-status">level with your best</div>`
      : `<div class="chall-result-status">${fmtTime(gap)} off your best</div>`;
  }
  const note = rec.bestGaveUp
    ? `${rec.bestGaveUp} given up` : `named all ${pages.length}`;
  const meta = `<div class="chall-result-meta">best ${fmtTime(rec.best)} · ${escapeHtml(note)}` +
    ` · played ${rec.plays}</div>`;

  // The ten pages, kept BELOW the actions where the fine print goes: the run's own keepsake and
  // the only place a given-up page is readable as the song it was. It rides inside the podium
  // rather than in a block of its own so that every other end path, which rewrites the podium
  // outright, is incapable of leaving a stale Ruthless listing behind it.
  const rows = pages.map((t) =>
    `<li class="rl-page ${t.ok ? "ok" : "no"}">` +
      `<span class="rl-page-n">${t.n}</span>` +
      `<span class="rl-page-title">${escapeHtml(censor(t.title))}</span>` +
      `<span class="rl-page-words">${t.ok ? `${t.words}w` : "gave up"}</span>` +
      `<span class="rl-page-time">${escapeHtml(t.note)}</span>` +
    `</li>`).join("");

  $("resultPodium").innerHTML = status + meta +
    `<div class="chall-result-actions">` +
      `<button id="backToRuthless" class="btn-primary">← ruthless</button>` +
      `<button id="replayRuthless" class="btn-primary">replay ↺</button>` +
    `</div>` +
    `<div class="rl-pages"><p class="rl-pages-label">the run, page by page</p>` +
      `<ol class="rl-page-list">${rows}</ol></div>`;
  $("backToRuthless").addEventListener("click", () => openRuthless(ruthlessBackTarget));
  $("replayRuthless").addEventListener("click", () => startRuthlessMode(lensId));

  // The finished run, written down for the bracelet keepsake, which is pressed long after
  // `bonusGame` and `bonusScore` have been cleared — the sleeve's snapshot for the same reason.
  ruthlessCard = { lens: lens ? lens.label : "", secs, named, pages: pages.length };
  bonusGame = null;
  bonusPuzzle = null;

  renderResultRecap();
  renderSkillsRecap();
  if (beat) celebratePerfect();
}

// Leaving a game (quit or from the end card) always lands back on the shelf, with the board
// re-rendered so a new best shows immediately.
function leaveBonusGame() {
  disarmBonusQuit();
  stopBonusClock();
  stopBonusCountdown();
  stopChainBeat();
  bonusEnded = true;
  bonusGame = null;
  bonusPuzzle = null;
  renderBonusPageRegister();
  renderBonusPage();
  flipInToScreen("bonus");
}

let bonusQuitTimer = null;
function disarmBonusQuit() {
  clearTimeout(bonusQuitTimer);
  bonusQuitTimer = null;
  const btn = $("bonusQuitBtn");
  if (!btn) return;
  btn.classList.remove("armed");
  btn.textContent = btn.dataset.label || "← quit";
}
function armBonusQuit() {
  const btn = $("bonusQuitBtn");
  if (!btn) return;
  if (settings.confirmLeave === false) { leaveBonusGame(); return; }
  if (btn.classList.contains("armed")) { leaveBonusGame(); return; }
  btn.classList.add("armed");
  btn.textContent = "give up? tap again";
  bonusQuitTimer = setTimeout(disarmBonusQuit, 3000);
}

/* ---------- Challenges page ---------- */
let challengesBackTarget = "start";  // where the Challenges' back link returns to
let challSelectedId = null;          // which challenge the detail panel is showing
let challDetailPeek = false;         // ...and whether its "what changes on the dark side?" is unfolded
let challListResizeHandler = null;   // window-resize handler that re-snaps the list peek

// Status marks for the contents list (gold tick = defeated, violet tick = dark side also
// defeated, hollow ring = open, lock = locked).
const CHALL_TICK = `<svg viewBox="0 0 20 20" class="chall-mark-svg" aria-hidden="true"><circle cx="10" cy="10" r="8.5" fill="none" stroke="#d8a32f" stroke-width="1.6"/><path d="M5.5 10.2 L8.7 13.4 L14.5 6.4" fill="none" stroke="#d8a32f" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const CHALL_TICK_DARK = `<svg viewBox="0 0 20 20" class="chall-mark-svg" aria-hidden="true"><circle cx="10" cy="10" r="8.5" fill="none" stroke="#7a4bb0" stroke-width="1.6"/><path d="M5.5 10.2 L8.7 13.4 L14.5 6.4" fill="none" stroke="#7a4bb0" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const CHALL_RING = `<svg viewBox="0 0 20 20" class="chall-mark-svg" aria-hidden="true"><circle cx="10" cy="10" r="8.5" fill="none" stroke="#b6a98d" stroke-width="1.6"/></svg>`;
const CHALL_LOCK = `<svg viewBox="0 0 20 20" class="chall-mark-svg" aria-hidden="true"><rect x="4.5" y="9" width="11" height="8" rx="1.4" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M6.8 9 V6.7 a3.2 3.2 0 0 1 6.4 0 V9" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>`;
const CHALL_STAR = `<svg viewBox="0 0 24 24" class="chall-star-svg" aria-hidden="true"><path d="M12 2.3 L14.94 7.96 L21.22 9 L16.76 13.55 L17.7 19.85 L12 17 L6.3 19.85 L7.24 13.55 L2.78 9 L9.06 7.96 Z" fill="#e0a32f" stroke="#b9821f" stroke-width="1.1" stroke-linejoin="round" stroke-linecap="round"/></svg>`;
// The pin: a drawing pin pushed in at an angle, grip up and needle running down to the
// corner, so the glyph reads as a pin at a glance instead of needing to be worked out —
// which the old head-on tack did not, at the 15px it renders inside a 24px button. This
// is the one mark in the game NOT drawn here: it is Bootstrap Icons' pin-angle, used
// under MIT and recorded in NOTICE.md. Kept as a single filled path in currentColor, so
// the button's three states (blue pencil idle, darker when pinned, tan at the pin limit)
// still recolour the whole pin.
const CHALL_PIN = `<svg viewBox="0 0 16 16" class="chall-pin-svg" aria-hidden="true" fill="currentColor">` +
  `<path d="M9.828.722a.5.5 0 0 1 .354.146l4.95 4.95a.5.5 0 0 1 0 .707c-.48.48-1.072.588-1.503.588-.177 0-.335-.018-.46-.039l-3.134 3.134a5.927 5.927 0 0 1 .16 1.013c.046.702-.032 1.687-.72 2.375a.5.5 0 0 1-.707 0l-2.829-2.828-3.182 3.182c-.195.195-1.219.902-1.414.707-.195-.195.512-1.22.707-1.414l3.182-3.182-2.828-2.829a.5.5 0 0 1 0-.707c.688-.688 1.673-.767 2.375-.72a5.922 5.922 0 0 1 1.013.16l3.134-3.133a2.772 2.772 0 0 1-.04-.461c0-.43.108-1.022.589-1.503a.5.5 0 0 1 .353-.146zm.122 2.112v-.002.002zm0-.002v.002a.5.5 0 0 1-.122.51L6.293 6.878a.5.5 0 0 1-.511.12H5.78l-.014-.004a4.507 4.507 0 0 0-.288-.076 4.922 4.922 0 0 0-.765-.116c-.422-.028-.836.008-1.175.15l5.51 5.509c.141-.34.177-.753.149-1.175a4.924 4.924 0 0 0-.192-1.054l-.004-.013v-.001a.5.5 0 0 1 .12-.512l3.536-3.535a.5.5 0 0 1 .532-.115l.096.022c.087.017.208.034.344.034.114 0 .23-.011.343-.04L9.927 2.028c-.029.113-.04.23-.04.343a1.779 1.779 0 0 0 .062.46z"/>` +
  `</svg>`;
// The dark side's mark: an eclipse — the blotted disc with its corona still showing. Drawn
// in currentColor so the same glyph greys out with the button in its locked state.
const CHALL_ECLIPSE = `<svg viewBox="0 0 20 20" class="chall-mark-svg" aria-hidden="true"><circle cx="10" cy="10" r="8.1" fill="none" stroke="currentColor" stroke-width="1.1" opacity="0.5"/><circle cx="10" cy="10" r="5.6" fill="currentColor"/></svg>`;

// The beaten seal is a genuine two-tone: the wax body ages to a warm grey while the
// beaded rim keeps its red. A uniform CSS filter can't do that (body and beads are both
// red at the source), so we derive an "aged" copy of each wax seal by string-swapping the
// body/motif gradient reds (and the pink relief highlights) for warm taupes, leaving the
// bead red (#b04046) and its highlight untouched. The internal ids are re-scoped (wax- ->
// waxaged-) so an aged seal and a red one never collide over a shared gradient id.
const AGED_SEAL_BODY = {
  "#b8413f": "#bca99f", "#a72e33": "#aa9a8f", "#93232a": "#8f8279", "#781a20": "#726860",
  "#ae363b": "#b2a498", "#9c282e": "#978a80", "#8a2028": "#847770",
  "#cd5c55": "#c8bcb0", "#ad353a": "#ab9d92", "#96262d": "#8f8279",
};
const AGED_SEAL_HILITE = {
  "rgba(250,188,168,0.4)": "rgba(216,206,196,0.4)", "rgba(255,216,198,0.17)": "rgba(224,215,205,0.17)",
  "rgba(255,190,170,0.06)": "rgba(216,207,197,0.06)", "rgba(246,182,162,0.38)": "rgba(212,203,193,0.38)",
  "rgba(246,184,164,0.28)": "rgba(213,204,194,0.28)", "rgba(252,198,180,0.45)": "rgba(218,209,199,0.45)",
  "rgba(252,198,182,0.5)": "rgba(218,209,199,0.5)",
};
function agedSealSvg(redSvg) {
  let s = redSvg.split("wax-").join("waxaged-");   // re-scope ids so aged + red can coexist
  for (const k in AGED_SEAL_BODY) s = s.split(k).join(AGED_SEAL_BODY[k]);
  for (const k in AGED_SEAL_HILITE) s = s.split(k).join(AGED_SEAL_HILITE[k]);
  return s;
}
const CHALLENGE_SEALS_AGED = Object.fromEntries(
  Object.entries(CHALLENGE_SEALS).map(([id, svg]) => [id, agedSealSvg(svg)])
);

// The dark side's seal: the same wax poured black. Derived exactly like the aged copy, but
// the swap is wider — as well as the body reds and the pink relief, the deep red SHADOW
// tints have to move too, or a violet seal keeps casting red shadows. The bead rim, which
// the aged seal leaves red, goes bright lilac here: that pop against the near-black body is
// what makes it read as "black and purple" rather than just a dark blob.
// Because the dark side is gated on defeating the challenge, this seal strictly implies the
// aged one, so showing it in place of the aged seal hides nothing the player had earned.
const DARK_SEAL_BODY = {
  "#cd5c55": "#6b5480", "#b8413f": "#55406b", "#ae363b": "#4c3862", "#ad353a": "#4a3660",
  "#a72e33": "#443159", "#9c282e": "#3c2b4f", "#96262d": "#382848", "#93232a": "#352544",
  "#8a2028": "#2e203b", "#781a20": "#241a2e",
  "#b04046": "#a274d8",   // the beaded rim — the violet that carries the whole seal
};
const DARK_SEAL_HILITE = {
  "rgba(250,188,168,0.4)": "rgba(206,180,240,0.4)", "rgba(255,216,198,0.17)": "rgba(216,198,246,0.17)",
  "rgba(255,190,170,0.06)": "rgba(210,186,242,0.06)", "rgba(246,182,162,0.38)": "rgba(204,178,238,0.38)",
  "rgba(246,184,164,0.28)": "rgba(205,180,238,0.28)",
  "rgba(252,198,182,0.5)": "rgba(212,190,244,0.5)", "rgba(250,192,172,0.5)": "rgba(208,184,242,0.5)",
  // The motif's offset highlight copy. On the red and taupe seals the body is light enough
  // that a soft pink relief reads fine; against near-black wax the same value disappears and
  // the motif flattens out, so this one is pushed brighter and more opaque than a like-for-
  // like swap would give. It is what keeps each seal's motif legible once poured dark.
  "rgba(252,198,180,0.45)": "rgba(232,214,255,0.62)",
};
const DARK_SEAL_SHADOW = {
  "rgba(88,14,18,0.4)": "rgba(30,18,46,0.4)", "rgba(74,13,17,0.6)": "rgba(26,16,40,0.6)",
  "rgba(70,10,14,0.42)": "rgba(24,14,38,0.42)", "rgba(70,10,14,0.35)": "rgba(24,14,38,0.35)",
  "rgba(60,8,12,0.42)": "rgba(21,12,34,0.42)", "rgba(60,8,11,0.42)": "rgba(21,12,34,0.42)",
  "rgba(56,7,10,0.55)": "rgba(20,11,32,0.55)", "rgba(56,7,10,0.5)": "rgba(20,11,32,0.5)",
  "rgba(56,7,10,0.45)": "rgba(20,11,32,0.45)", "rgba(50,6,9,0.6)": "rgba(18,10,30,0.6)",
};
function darkSealSvg(redSvg) {
  let s = redSvg.split("wax-").join("waxdark-");   // re-scope ids so all three copies coexist
  for (const k in DARK_SEAL_BODY) s = s.split(k).join(DARK_SEAL_BODY[k]);
  for (const k in DARK_SEAL_HILITE) s = s.split(k).join(DARK_SEAL_HILITE[k]);
  for (const k in DARK_SEAL_SHADOW) s = s.split(k).join(DARK_SEAL_SHADOW[k]);
  return s;
}
const CHALLENGE_SEALS_DARK = Object.fromEntries(
  Object.entries(CHALLENGE_SEALS).map(([id, svg]) => [id, darkSealSvg(svg)])
);

// Every wax seal carries internal SVG ids (the blob path, the gradients, the wax filter),
// scoped by challenge id — which is only unique while ONE copy of that seal is in the
// document. Two routinely are: the play page's corner stamp stays in the (now hidden) game
// screen after a run ends, and the challenge card then stamps the same seal again. A
// duplicate id means the card's href/url(#…) references resolve to the FIRST match, the one
// buried in a display:none screen, and the seal renders washed-out taupe — which is exactly
// what a DEFEATED seal looks like, on a challenge you had just failed or walked out of. Only
// a reload cleared it. So every render gets its own id scope: put seal markup through here,
// never straight from the maps above.
let sealScopeSeq = 0;
function sealMarkup(svg) {
  if (!svg) return "";
  const n = ++sealScopeSeq;
  return svg.replace(/(wax(?:aged|dark)?)-/g, `$1${n}-`);
}

// Difficulty rating — cassette tapes (1 easy → 3 hard). Echoes the dark-shell +
// cream-label cassette desk prop; the shell is recoloured per tier by the
// wrapper's t1/t2/t3 class (green → orange → red, set in CSS).
const TAPE_GLYPH = `<svg viewBox="0 0 24 16" class="tape-glyph" aria-hidden="true"><rect class="tape-shell" x="1" y="1.6" width="22" height="12.8" rx="2.2"/><rect class="tape-label" x="5" y="3.3" width="14" height="3.2" rx="0.7"/><circle class="tape-reel" cx="8.5" cy="10.2" r="2.4"/><circle class="tape-reel" cx="15.5" cy="10.2" r="2.4"/></svg>`;
// tapes:0 is a placeholder "unrated" tier for freshly-built challenges whose real
// difficulty hasn't been decided yet (see the Tier C minigames in config).
const TAPE_WORD = { 0: "unrated", 1: "easy", 2: "tricky", 3: "tough", 4: "brutal" };

// `n` tapes (0 = unrated placeholder, else clamped 1–4); the wrapper's t<n> class
// colours them by tier. Unrated draws a single ghosted, dashed tape.
function tapesMarkup(n) {
  if ((n || 0) === 0) return `<span class="chall-tapes t0" aria-label="difficulty not yet rated">${TAPE_GLYPH}</span>`;
  const t = Math.max(1, Math.min(4, n));
  return `<span class="chall-tapes t${t}" aria-label="difficulty ${t} of 4">${TAPE_GLYPH.repeat(t)}</span>`;
}

function openChallenges(from, focusId) {
  challengesBackTarget = from;
  // Arriving at the page always starts with the dark rules folded away — they're an aside
  // you go looking for, not the first thing the card says.
  challDetailPeek = false;
  // A caller can point the page at one challenge (the Mastery super-hard tile does): it
  // becomes the selection, so the detail panel is already showing the right thing, and the
  // list scrolls its GROUP into view once the screen has a height to scroll within.
  if (focusId && CHALLENGE_BY_ID[focusId]) challSelectedId = focusId;
  renderChallengesPage();
  flipAwayToScreen("challenges");
  if (focusId && CHALLENGE_BY_ID[focusId]) scrollChallengeGroupIntoView(focusId);
}

// The first challenge of the super-hard tier worth landing on: the first one still
// undefeated, else the first of the tier. "" if the tier doesn't exist.
function firstSuperHardChallenge() {
  const tier = CHALLENGES.filter((c) => (c.tapes || 0) === 4);
  if (!tier.length) return "";
  return (tier.find((c) => !challengeRecord(c.id).defeated) || tier[0]).id;
}

// Scroll the challenge list so a challenge's DIFFICULTY GROUP sits at the top of the
// scroller — the group header first, not the row, because a caller arriving from Mastery
// is being shown a tier rather than one entry.
//
// The row's data-id lives on the inner .chall-item-select button, not on the .chall-item
// wrapper. A pinned challenge is also drawn TWICE (once in the local Pinned shortlist above the
// tiers, once in its own tier), and the shortlist copy comes first in the DOM — so take the last
// match, which is always the one sitting under a real difficulty header. Landing on "Pinned"
// would be the same failure as landing at the top: a caller sent here to be shown the brutal
// tier has to arrive at the brutal tier.
function scrollChallengeGroupIntoView(id) {
  revealAfterFlip(
    () => {
      const rows = document.querySelectorAll(`#challengesBody .chall-list .chall-item-select[data-id="${CSS.escape(id)}"]`);
      const row = rows[rows.length - 1];
      const group = row && row.closest(".chall-group");
      return (group && group.querySelector(".chall-group-head")) || row || null;
    },
    { within: () => document.querySelector("#challengesBody .chall-list"), pad: 4 }
  );
}

// Arrive on a screen you have just flipped to and bring one thing on it into view. Both doors
// out of the Mastery reward vaults land somewhere specific on a page they don't own, and the
// two pages scroll differently: the challenge list is its own scroller inside a notebook page
// that never grows, while the charm collection has no inner scroller at all and moves the
// window. `opts.within` names a scroller to move; without it the window moves.
//
// Three things this has to survive, all of them consequences of the flip:
//   • The window is left exactly where the page you came FROM was scrolled to (showScreen
//     doesn't reset it, and focuses with preventScroll so nothing resets it by accident). A
//     tile sitting a screenful down the Mastery page would otherwise hand you a destination
//     scrolled past its own top — worst on narrow layouts, where a page is at its tallest.
//     So the window goes to the top first, before anything is measured.
//   • The destination has no layout at the moment it's asked for: it was display:none a tick
//     ago, and the challenge list in particular has no height until fitPeek has snapped it.
//     Hence the retry loop — wait for a real measurement rather than guessing at the flip's
//     duration. `find` returns null until its target exists, so it can be re-run each frame.
//   • The jump is instant on purpose. The page is already arriving on a page turn, and a
//     scroll animating underneath that turn is two motions at once — the destination should
//     simply be where it belongs by the time the flip lands.
function revealAfterFlip(find, opts) {
  const o = opts || {};
  const pad = o.pad || 0;
  window.scrollTo({ top: 0, behavior: "instant" });
  let tries = 40, settled = -1;
  const step = () => {
    const el = find();
    const scroller = o.within ? o.within() : null;
    // Not laid out yet (or, for an inner scroller, not yet given a height) — try again next frame.
    if (!el || (o.within && (!scroller || !scroller.clientHeight)) || !el.getClientRects().length) {
      if (--tries > 0) requestAnimationFrame(step);
      return;
    }
    if (scroller) {
      const top = el.getBoundingClientRect().top - scroller.getBoundingClientRect().top + scroller.scrollTop;
      // Clamped by the scroller itself: the last groups can't reach the top edge, and landing
      // as high as they go is exactly right. The edge fade follows on the list's scroll handler.
      scroller.scrollTop = Math.max(0, top - pad);
    } else {
      window.scrollTo({ top: Math.max(0, window.scrollY + el.getBoundingClientRect().top - pad), behavior: "instant" });
    }
    // One placement isn't enough: the destination's geometry is still settling for a frame or
    // two. The challenge list's fitPeek trims the scroller's height AFTER this first runs, and
    // a shorter scroller can reach further down its own content — so a target clamped against
    // the taller measurement is left stranded mid-list. Re-place it until a frame measures the
    // same as the one before it.
    const now = scroller ? scroller.clientHeight : document.documentElement.scrollHeight;
    if (now !== settled) { settled = now; if (--tries > 0) requestAnimationFrame(step); }
  };
  requestAnimationFrame(step);
}

const CHALLENGE_PIN_LIMIT = 3;

function pinnedChallenges() {
  return CHALLENGES.filter((c) => challengeRecord(c.id).pinned && challengeUnlocked(c.id));
}

function toggleChallengePin(id) {
  if (!challengeUnlocked(id)) return false;
  const rec = challengeRecord(id);
  if (!rec.pinned && pinnedChallenges().length >= CHALLENGE_PIN_LIMIT) return false;
  const st = loadChallengeState();
  st[id] = { ...rec, pinned: !rec.pinned };
  saveChallengeState(st);
  return true;
}

function renderChallengesPage() {
  const wallet = loadChallengeTokens();
  const tk = wallet.balance, tt = wallet.tickets;
  const defeated = CHALLENGES.filter((c) => challengeRecord(c.id).defeated).length;

  // Default selection: keep the current pick if still valid, else the first
  // not-yet-defeated challenge, else the very first.
  if (!challSelectedId || !CHALLENGE_BY_ID[challSelectedId]) {
    const firstOpen = CHALLENGES.find((c) => !challengeRecord(c.id).defeated);
    challSelectedId = (firstOpen || CHALLENGES[0]).id;
  }

  // Grouped by difficulty, with a small local shortlist above it. Pins deliberately
  // change no game state beyond this shelf: they do not affect the randomiser,
  // unlock economy, records, or the completion tally.
  const challengeRow = (c) => {
    const rec = challengeRecord(c.id);
    const open = challengeUnlocked(c.id);
    let mark, stateCls;
    if (rec.darkDefeated) { mark = CHALL_TICK_DARK; stateCls = "is-defeated is-dark-defeated"; }
    else if (rec.defeated) { mark = CHALL_TICK; stateCls = "is-defeated"; }
    else if (open)      { mark = CHALL_RING; stateCls = "is-open"; }
    else                { mark = CHALL_LOCK; stateCls = "is-locked"; }
    const pinLimitReached = !rec.pinned && pinnedChallenges().length >= CHALLENGE_PIN_LIMIT;
    const pin = open
      ? `<button type="button" class="chall-item-pin${rec.pinned ? " is-pinned" : ""}" data-pin="${c.id}"` +
          `${pinLimitReached ? " disabled aria-disabled=\"true\"" : ""}` +
          ` aria-pressed="${rec.pinned}" aria-label="${rec.pinned ? "Remove " : "Pin "}${escapeHtml(c.name)}${pinLimitReached ? "; pin limit reached" : ""}"` +
          ` title="${rec.pinned ? "remove from pinned challenges" : pinLimitReached ? "you can pin up to three challenges" : "pin this challenge"}">${CHALL_PIN}</button>`
      : "";
    return `<div class="chall-item ${stateCls}">` +
      `<button type="button" class="chall-item-select" data-id="${c.id}"><span class="chall-item-name">${escapeHtml(c.name)}</span></button>` +
      `<span class="chall-item-mark">${mark}</span>${pin}</div>`;
  };
  let list = "";
  const pinned = pinnedChallenges();
  if (pinned.length) {
    list += `<div class="chall-group chall-group--pinned">` +
      `<div class="chall-group-head chall-group-head--pinned">${CHALL_PIN}` +
      `<span class="chall-group-label">Pinned</span>` +
      `<span class="chall-group-count">${pinned.length} / ${CHALLENGE_PIN_LIMIT}</span></div>` +
      pinned.map(challengeRow).join("") + `</div>`;
  }
  [1, 2, 3, 4, 0].forEach((tier) => {
    const inTier = CHALLENGES.filter((c) => (c.tapes || 0) === tier);
    if (!inTier.length) return;
    list += `<div class="chall-group">` +
      `<div class="chall-group-head t${tier}">` +
        `${tapesMarkup(tier)}` +
        `<span class="chall-group-label">${TAPE_WORD[tier]}</span>` +
        `<span class="chall-group-count">${inTier.length}</span>` +
      `</div>`;
    inTier.forEach((c) => { list += challengeRow(c); });
    list += `</div>`;
  });

  const html =
    `<div class="chall-head">` +
      `<div class="chall-head-sub">spend a token · defeat the rule</div>` +
      // Both wallets in one right-hand group, because the row is space-between and the
      // sub-label owns the left. The punch card sits to the left of the kraft stub: it is
      // the quieter currency, and the ticket stub stays the thing your eye lands on.
      `<span class="chall-wallet">` +
        `<span class="chall-tickets" title="persistence tickets — see a challenge through seven times to earn one">` +
          `<span class="chall-tick-punch" aria-hidden="true"></span>` +
          `<b>${tt}</b><span class="chall-tick-label">persist</span></span>` +
        `<span class="chall-tokens" title="spend a token to unlock a challenge">` +
          `<span class="chall-tok-perf"></span>` +
          `🎟 <b>${tk}</b> <span class="chall-tok-label">token${tk === 1 ? "" : "s"}</span></span>` +
      `</span>` +
    `</div>` +
    `<div class="chall-layout">` +
      `<div class="chall-col">` +
        `<div class="chall-list">${list}</div>` +
        `<div class="chall-tally">${defeated} of ${CHALLENGES.length} defeated</div>` +
      `</div>` +
      `<div class="chall-detail" id="challDetail"></div>` +
    `</div>`;

  const el = $("challengesBody");
  el.innerHTML = html;
  el.querySelectorAll(".chall-item-select").forEach((b) =>
    b.addEventListener("click", () => selectChallenge(b.dataset.id)));
  el.querySelectorAll(".chall-item-pin").forEach((b) =>
    b.addEventListener("click", () => { if (toggleChallengePin(b.dataset.pin)) renderChallengesPage(); }));

  // The list scrolls internally; cue that with a soft edge fade plus a half-row
  // "peek" — trim the visible height so the bottom edge bisects the next row, so
  // its top half shows under the fade and reads as "there's more below".
  const listEl = el.querySelector(".chall-list");
  if (listEl) {
    const FADE = 30;
    const updateFade = () => {
      if (!listEl.clientHeight) return;  // hidden (screen not shown yet) — keep CSS default
      const atTop = listEl.scrollTop <= 1;
      const atBottom = listEl.scrollTop + listEl.clientHeight >= listEl.scrollHeight - 1;
      listEl.style.setProperty("--fade-top", atTop ? "0px" : FADE + "px");
      listEl.style.setProperty("--fade-bot", atBottom ? "0px" : FADE + "px");
    };
    // Snap the visible height to the deepest row midpoint that fits the vh budget,
    // so the bottom edge lands mid-row and that row's top half peeks through.
    const fitPeek = () => {
      if (!listEl.clientHeight) return;  // hidden — nothing to measure yet
      const budget = Math.round(window.innerHeight * 0.58);  // mirrors CSS max-height: 58vh
      const listTop = listEl.getBoundingClientRect().top;
      let target = budget;
      for (const it of listEl.querySelectorAll(".chall-item")) {
        const r = it.getBoundingClientRect();
        const mid = (r.top - listTop + listEl.scrollTop) + r.height / 2;  // row midpoint in content
        if (mid <= budget - 2) target = mid; else break;
      }
      target = Math.round(target);
      if (Math.abs(listEl.clientHeight - target) > 1) listEl.style.maxHeight = target + "px";
      updateFade();
    };
    listEl.addEventListener("scroll", updateFade, { passive: true });
    // Re-snap once the screen is actually shown (0→real size) and on viewport resize.
    if (typeof ResizeObserver === "function") new ResizeObserver(fitPeek).observe(listEl);
    if (challListResizeHandler) window.removeEventListener("resize", challListResizeHandler);
    challListResizeHandler = fitPeek;
    window.addEventListener("resize", challListResizeHandler);
    fitPeek();
  }

  selectChallenge(challSelectedId);
}

function selectChallenge(id) {
  // Picking a different challenge folds the dark rules away again; re-rendering the same one
  // (a page refresh after a win, say) leaves what you were reading open.
  if (id !== challSelectedId) challDetailPeek = false;
  challSelectedId = id;
  const body = $("challengesBody");
  if (!body) return;
  // The row's data-id is on its select button, not on the .chall-item wrapper that carries the
  // selected styling, so read the id from the button and mark its row.
  body.querySelectorAll(".chall-item-select").forEach((b) =>
    b.closest(".chall-item").classList.toggle("selected", b.dataset.id === id));
  renderChallengeDetail(id);
}

function renderChallengeDetail(id) {
  const el = $("challDetail");
  if (!el) return;
  const c = CHALLENGE_BY_ID[id];
  const rec = challengeRecord(id);
  const open = challengeUnlocked(id);
  const cost = c.cost || 1;
  const tt = loadChallengeTokens().tickets;
  const price = ticketPrice(c);          // null = no number of tickets ever buys this one

  let action;
  if (!open && c.mastery) {
    // Mastery-gated tier: never purchasable in either currency. Show a clear
    // "unlocks at Mastery L{n}" state.
    action = `<div class="chall-need chall-need--mastery">${CHALL_LOCK} Unlocks at Mastery level ${c.mastery}</div>`;
  } else if (!open) {
    const pay = unlockPayment(c);
    if (pay) {
      // One button either way — what changes is which currency it tears. Paying in tickets
      // swaps the kraft stub's wash and stamp for the punch card's, so the button says what
      // it is about to spend without a second control to read.
      const persist = pay.kind === "ticket";
      action = `<div class="chall-buy">` +
        `<button type="button" class="chall-go is-unlock${persist ? " is-persist" : ""}" data-unlock="${id}"` +
          ` title="${persist ? "spend persistence to unlock" : "tear a ticket to unlock"}">` +
          `<span class="chall-unlock-perf"></span>` +
          `<span class="chall-unlock-stamp">${persist ? "persistence" : "admit one"}</span>` +
          `<span class="chall-unlock-lab">unlock</span></button>` +
        `<div class="chall-buy-cost">${persist
          ? `spends ${pay.price} persistence ticket${pay.price === 1 ? "" : "s"}`
          : `spends 🎟 ${pay.price} token${pay.price === 1 ? "" : "s"}`}</div>` +
      `</div>`;
    } else {
      // Can't afford it. The hint names the route that is actually open to you: how to earn
      // a token when you hold no tickets at all, and how far off the ticket price is when
      // you hold some but not the whole price (holding 1 against a 2 buys nothing).
      const hint = price == null
        ? "this one only opens with a token — persistence tickets don't reach its tier"
        : tt > 0
          ? `or ${price} persistence ticket${price === 1 ? "" : "s"} — you have ${tt}`
          : "beat any challenge for the first time, or see one through seven times, to earn one";
      action = `<div class="chall-need-wrap">` +
          `<div class="chall-need">need a token · 🎟 ${cost}</div>` +
          `<div class="chall-need-hint">${hint}</div>` +
        `</div>`;
    }
  } else {
    action = `<button type="button" class="chall-go" data-play="${id}">${rec.defeated ? "Play again" : "Play"}</button>`;
  }

  // The dark side, sitting beside Play. Only rendered for challenges that actually have one
  // authored — a permanently locked button on a challenge with no dark side would be a lie.
  // Greyed with a padlock until the challenge itself is beaten, then inked black.
  let darkAction = "";
  const darkOpen = darkSideUnlocked(id);
  if (open && hasDarkSide(id)) {
    const cls = "chall-dark" + (darkOpen ? "" : " is-locked") + (rec.darkDefeated ? " is-conquered" : "");
    darkAction =
      `<button type="button" class="${cls}"` +
        (darkOpen ? ` data-dark="${id}"` : ` disabled aria-disabled="true"`) +
        ` title="${darkOpen ? "play the dark side" : "beat this challenge to unlock its dark side"}">` +
        `<span class="chall-dark-mark">${darkOpen ? CHALL_ECLIPSE : CHALL_LOCK}</span>` +
        `<span class="chall-dark-lab">Dark Side</span>` +
      `</button>`;
  }

  // Thirty-One's best is a round number, and the risk batch's is a bead total that can
  // legitimately run past the page count — neither belongs over a "/ 13" denominator.
  // Declared before `meta` because the dark-side note below reuses it against `darkBest`.
  const outOfFor = (best) => RISK_RULES.has(c.rule) ? ` bead${best === 1 ? "" : "s"}`
    : c.rule === "survive" ? "" : `/${TOTAL_ROUNDS}`;
  const bestOutOf = outOfFor(rec.best);
  let meta = "";
  if (rec.defeated) meta = `best ${rec.best}${bestOutOf} · ${rec.attempts} attempt${rec.attempts === 1 ? "" : "s"}`;
  else if (rec.attempts) meta = `${rec.attempts} attempt${rec.attempts === 1 ? "" : "s"} · not yet beaten`;

  // "What changes on the dark side?" — the rules you're being offered, readable without
  // committing to a run. Rather than printing a diff underneath, it swaps the card's own
  // rule/goal/mods text for the dark figures, written in violet: the same three lines in the
  // same three places, so the change is legible as a change instead of as a second paragraph
  // to cross-reference. Same gate as the button — beating the base earns the reveal.
  //
  // The card therefore does sit in a state, which an earlier tabs pass got badly wrong, so
  // three things make the state impossible to miss or to be stuck in: every swapped line is
  // violet, an eclipse + "dark side" flag rides beside the challenge name while it's showing,
  // and the toggle below reads "show me the light side again". Crucially the ACTION ROW never
  // changes — Play still starts the base run, Dark Side still starts the dark one, both one
  // click away — so the state changes what you're reading, never what a button does.
  const showDark = open && darkOpen && challDetailPeek;
  const view = showDark ? resolveChallenge(c, true) : c;
  const viewMode = MODES[view.mode];
  let darkPeek = "";
  if (open && darkOpen) {
    darkPeek =
      `<div class="chall-peek">` +
        `<button type="button" class="chall-peek-toggle" data-peek aria-expanded="${challDetailPeek}">` +
          `<span class="chall-peek-mark">${CHALL_ECLIPSE}</span>` +
          `<span class="chall-peek-lab">${showDark ? "show me the light side again" : "what changes on the dark side?"}</span>` +
        `</button>` +
      `</div>`;
  }

  // Persistence, below the action row. Either the claim — a ticket is not granted, you take
  // it deliberately from the card of the challenge that cost you the seven runs — or, while
  // the runs are still stacking up, the tally, so the seven is something you can see coming
  // rather than a hidden threshold that pays out by surprise.
  let persist = "";
  if (ticketReady(id)) {
    persist =
      `<button type="button" class="chall-claim" data-claim="${id}">` +
        `<span class="chall-claim-punch" aria-hidden="true"></span>` +
        `<span class="chall-claim-lab">Claim your persistence ticket</span>` +
        `<span class="chall-claim-sub">seven runs seen through</span>` +
      `</button>`;
  } else if (!rec.ticketClaimed && rec.earnest > 0 && !rec.defeated) {
    persist =
      `<div class="chall-persist">` +
        `<span class="chall-persist-count">${rec.earnest} / ${PERSIST_ATTEMPTS}</span>` +
        `<span class="chall-persist-lab">runs seen through — ${PERSIST_ATTEMPTS} earns a persistence ticket</span>` +
      `</div>`;
  }

  // While the dark rules are showing, the record line has to follow them: quoting the base
  // best beside the dark goal would credit a run played on the easy version.
  const shownMeta = showDark
    ? (rec.darkDefeated
        ? `best ${rec.darkBest}${outOfFor(rec.darkBest)} · ${rec.darkAttempts} attempt${rec.darkAttempts === 1 ? "" : "s"}`
        : rec.darkAttempts
          ? `${rec.darkAttempts} attempt${rec.darkAttempts === 1 ? "" : "s"} · not yet beaten`
          : "dark side not yet attempted")
    : meta;

  el.innerHTML =
    `<div class="chall-detail-head">` +
      `<span class="chall-detail-seal ${rec.darkDefeated ? "is-dark" : rec.defeated ? "is-beaten" : open ? "is-unbeaten" : "is-locked"}">` +
        `${sealMarkup((rec.darkDefeated ? CHALLENGE_SEALS_DARK : rec.defeated ? CHALLENGE_SEALS_AGED : CHALLENGE_SEALS)[c.id])}</span>` +
      `<span class="chall-detail-name">${escapeHtml(c.name)}</span>` +
      (showDark
        ? `<span class="chall-detail-dark">${CHALL_ECLIPSE}dark side</span>`
        : rec.defeated ? `<span class="chall-detail-star">${CHALL_STAR}</span><span class="chall-detail-stamp">defeated</span>` : "") +
    `</div>` +
    `<div class="chall-diff">` +
      `<span class="chall-eyebrow">Difficulty</span>` +
      `${tapesMarkup(c.tapes)}` +
      `<span class="chall-diff-word">${TAPE_WORD[(c.tapes || 0) === 0 ? 0 : Math.max(1, Math.min(4, c.tapes))]}</span>` +
    `</div>` +
    `<div class="chall-sec${showDark ? " is-dark" : ""}">` +
      `<div class="chall-eyebrow">The rule</div>` +
      `<div class="chall-rule">${escapeHtml(view.desc)}</div>` +
    `</div>` +
    `<div class="chall-sec chall-sec--beat${showDark ? " is-dark" : ""}">` +
      `<div class="chall-eyebrow">To beat it</div>` +
      `<div class="chall-goal">${escapeHtml(view.win)}</div>` +
      `<div class="chall-mods">${escapeHtml(view.blurb || viewMode.blurb)}</div>` +
    `</div>` +
    `<div class="chall-act">` +
      `<span class="chall-meta${showDark ? " is-dark" : ""}">` +
        `${showDark && rec.darkDefeated ? `<span class="chall-meta-stamp">defeated</span>` : ""}${shownMeta}</span>` +
      `<span class="chall-act-btns">${darkAction}${action}</span>` +
    `</div>` +
    // Below the actions on purpose: the buttons never move when the card is flipped, and a
    // note about the dark side reads best directly beneath the button it describes.
    // Persistence sits below both — it is about the runs behind you, not the run you're
    // about to start, and it must never crowd Play out of the row it shares with Dark Side.
    persist + darkPeek;

  const peek = el.querySelector("[data-peek]");
  if (peek) peek.addEventListener("click", () => {
    challDetailPeek = !challDetailPeek;
    renderChallengeDetail(id);
  });
  const ub = el.querySelector("[data-unlock]");
  if (ub) ub.addEventListener("click", () => { if (unlockChallenge(ub.dataset.unlock)) renderChallengesPage(); });
  // Re-render the whole page, not just the card: claiming moves the header counter too.
  const cb = el.querySelector("[data-claim]");
  if (cb) cb.addEventListener("click", () => { if (claimTicket(cb.dataset.claim)) renderChallengesPage(); });
  const pb = el.querySelector("[data-play]");
  if (pb) pb.addEventListener("click", () => startChallenge(pb.dataset.play));
  const db = el.querySelector("[data-dark]");
  if (db) db.addEventListener("click", () => startChallenge(db.dataset.dark, { dark: true }));
}

/* ---------- Album Focus page (master/detail; the 12-album completion board) ---------- */
let albumFocusBackTarget = "start";   // where the Album Focus back link returns to
let afSelectedAlbum = null;           // which album the detail panel is showing
let afSelectedDiff = "medium";        // the difficulty tab the detail panel has picked

// Status mark for an album row, scaling with how hard it was beaten/perfected. The exact
// visual tiers are styling — the data (beatenDiff/perfectedDiff) drives which one shows.
// Short caption for a board tile — long titles are trimmed so each name sits on one line.
function albumTileName(a) {
  if (a === "The Tortured Poets Department") return "TTPD";
  if (a === "The Life of a Showgirl") return "Life of a Showgirl";
  return a;
}

/* ---------- Ruthless: the lens picker ----------
   The page is a LYRIC SHEET, not a board. One song is typed down the paper in the order a song
   actually runs — verse into pre-chorus into chorus into post-chorus, second verse, bridge — with
   the words greeked to pencil strokes so the sheet gives nothing away. Picking a lens is pointing
   at a place in a song and saying start reading here, which is the only thing a lens really is.
   That order is the design; listing them grouped (both verses, then the choruses) says nothing.

   A section IS the play button. Unlike Album Focus there is nothing left to choose once a lens is
   picked — no difficulty, no variant — so a detail panel would exist only to hold a second tap.

   THE BLOCK IS THE MEASUREMENT. Each section is drawn as many stroke-lines as its typical page is
   long, so the chorus is one line and the verses are four, all to one scale. That replaces the old
   pencil bar and the "~78 words" beside it: the page says the same thing without a single number.
   The strokes are seeded off the lens id, so the sheet looks the same every time you open it — a
   document that redraws itself differently on each visit is not a document.

   Your best time sits at the end of the section in typewriter; a lens never played shows a dash
   rather than a zero, which on a low-wins board would read as a perfect run. */
// Song order, not roster order: this is the running order of an actual pop song, and it is what
// makes the page an arrangement rather than a list.
// The sheet reads as one song's running order, so From the Top sits where it belongs: first,
// because it is the only lens that opens where the song itself does.
const RUTHLESS_RUNNING_ORDER = ["from-the-top", "pre-chorus", "chorus", "post-chorus", "verse-2", "bridge"];
// Words of typical page per drawn stroke-line. Tuned so the six blocks add up to a document that
// fits one screen while the shortest lens still gets a line of its own.
const RL_LINE_WORDS = 22;
let ruthlessBackTarget = "start";
let rlDocEl = null;
function openRuthless(from) {
  ruthlessBackTarget = from;
  renderRuthlessPage();
  flipAwayToScreen("ruthless");
  // The measure needs the screen visible and laid out, so it waits for the flip to swap it in.
  // Belt and braces on purpose: rAF is the fast path, and the timeout covers the case where
  // frames are throttled (a backgrounded tab is the usual one) and the page would otherwise sit
  // on the fallback height until something else moved.
  requestAnimationFrame(fitRuthlessDoc);
  setTimeout(fitRuthlessDoc, 80);
}

// A tiny seeded generator so a lens's strokes are stable across renders and differ between lenses.
function rlRandom(seedStr) {
  let h = 2166136261;
  for (let i = 0; i < seedStr.length; i++) { h ^= seedStr.charCodeAt(i); h = Math.imul(h, 16777619); }
  let s = h >>> 0;
  return () => ((s = (Math.imul(s, 1103515245) + 12345) >>> 0) / 4294967296);
}

// One section's greeked page: whole lines of stroke-words, widths in % of the column so the
// document reflows with the notebook instead of overflowing it.
function rlStrokes(lens) {
  const rnd = rlRandom(lens.id);
  const lines = Math.max(1, Math.round(lens.median / RL_LINE_WORDS));
  let out = "";
  for (let i = 0; i < lines; i++) {
    const target = 62 + Math.round(rnd() * 26);   // how far across the column this line runs
    let words = "", used = 0;
    while (used < target) {
      const w = 3.4 + rnd() * 6.4;
      words += `<span class="rl-w" style="width:${w.toFixed(1)}%"></span>`;
      used += w + 1;
    }
    out += `<span class="rl-ln">${words}</span>`;
  }
  return out;
}

/* The page never scrolls. Measure what is actually left below the heading and hand it to the CSS
   as --rl-h: the document is exactly that tall, spreads its six sections into it, and every size
   inside scales off that one number. Measured from the document top rather than the viewport so
   the answer does not depend on where the page happens to be scrolled. */
function fitRuthlessPass() {
  // Held references, never a fresh query: the page-turn clones the whole screen INCLUDING its id,
  // so during a flip a lookup by id or class can hand back the throwaway sheet and the measure
  // lands on a node that is about to be removed.
  const doc = rlDocEl, card = screens.ruthless;
  if (!doc || !card || !card.classList.contains("active")) return;
  // Collapse the document, measure where the page ends without it, and hand back everything that
  // is left. Measuring the CARD's foot rather than adding up paddings means the masthead, the
  // blurb, the foot and the card's own bottom padding are all counted whatever they grow into.
  // min-height:min-content has to come off for the measure too, or the document refuses to
  // collapse and the page reads its own floor back as the space it has left.
  doc.style.minHeight = "0";
  doc.style.setProperty("--rl-h", "0px");
  const restingBottom = card.getBoundingClientRect().bottom + window.scrollY;
  doc.style.minHeight = "";
  // ...plus the desk showing below the notebook, which is the last thing that can force a scrollbar.
  const deskBelow = parseFloat(getComputedStyle(document.body).paddingBottom) || 0;
  // No artificial floor: the CSS min-content is the real one, so a window too short to hold the
  // sheet gives in and scrolls a little instead of the sections overlapping the footnote.
  // 2px of slack: sub-pixel rounding in the measure is enough to put a scrollbar on a page that
  // is otherwise exactly the height of the window, and a scrollbar for one pixel is still a scroll.
  const room = Math.max(0, Math.round(window.innerHeight - restingBottom - deskBelow - 2));
  // What must be true is that the DOCUMENT ends up inside the room — not that it matches the
  // number we asked for. Asking for the whole room can overflow, because the type scales off the
  // ask and drags the content's own minimum up with it, so binary search the ask instead. Height
  // rises monotonically with the ask, which is what makes the search sound; comparing against the
  // ask rather than the room does NOT, since below the clamp floors the content stops shrinking.
  const heightAt = (h) => {
    doc.style.setProperty("--rl-h", `${h}px`);
    return doc.getBoundingClientRect().height;
  };
  if (heightAt(room) > room + 0.5) {
    let lo = 0, hi = room;
    while (hi - lo > 2) {
      const mid = Math.round((lo + hi) / 2);
      if (heightAt(mid) <= room + 0.5) lo = mid; else hi = mid;
    }
    doc.style.setProperty("--rl-h", `${lo}px`);
  }
}
/* Two passes, and the second one A FRAME LATER. Straight after a window resize the first measure
   reads chrome that is still laid out for the old height and comes back short — the vh-sized blurb,
   strapline and footnote have not been re-resolved yet, and forcing layout inside the same task
   does not make them so. A second pass on the next frame measures a page that has settled, and the
   fit is idempotent once it has, so a third would change nothing. The timeout is the backstop for
   throttled frames, the same reason openRuthless has one. */
function fitRuthlessDoc() {
  fitRuthlessPass();
  requestAnimationFrame(fitRuthlessPass);
  setTimeout(() => {
    fitRuthlessPass();
    // The notebook is a different height than it was when showScreen told the desk to re-fill, and
    // gutter props left below a now-shorter page are enough to put the scrollbar back on their own.
    window.dispatchEvent(new CustomEvent("deskscatter:refresh"));
  }, 60);
}
let rlFitTimer = null;
addEventListener("resize", () => {
  if (!screens.ruthless.classList.contains("active")) return;
  clearTimeout(rlFitTimer);
  rlFitTimer = setTimeout(fitRuthlessDoc, 120);
});

// Re-paint the sheet under a board that changed beneath it (the dev panel's seeders), and re-fit,
// since a lens gaining a time can change how tall the document wants to be.
function repaintRuthless() {
  if (!rlDocEl || !screens.ruthless.classList.contains("active")) return;
  renderRuthlessPage();
  fitRuthlessDoc();
}

function renderRuthlessPage() {
  const lenses = RUTHLESS_RUNNING_ORDER.map((id) => ruthlessLens(id)).filter(Boolean);
  const played = lenses.filter((l) => ruthlessRecord(l.id).plays).length;
  let secs = "";
  lenses.forEach((lens) => {
    const rec = ruthlessRecord(lens.id);
    const pool = ruthlessPool(allSongs, lens).deal.length;
    const best = rec.plays
      ? `<span class="rl-best">${fmtTime(rec.best)}</span>`
      : `<span class="rl-best rl-best--none">—</span>`;
    // How the best was got, kept UNDER the time. A time with pages handed back is the same record
    // and a different run, so the section says which without making it a second board.
    const note = rec.plays
      ? (rec.bestGaveUp ? `${rec.bestGaveUp} given up` : `named all ${BONUS_ROUNDS}`)
      : "not played";
    secs += `<button type="button" class="rl-sec" data-lens="${lens.id}"` +
        ` aria-label="${escapeHtml(lens.label)}: ${pool} songs, ${rec.plays ? "best " + fmtTime(rec.best) + ", " : ""}${escapeHtml(note)}">` +
      `<span>` +
        `<span class="rl-h">[${escapeHtml(lens.label)}]<span class="rl-pool">${pool} songs</span></span>` +
        `<span class="rl-lines" aria-hidden="true">${rlStrokes(lens)}</span>` +
      `</span>` +
      `<span class="rl-rec">${best}<span class="rl-note">${escapeHtml(note)}</span></span>` +
      `</button>`;
  });
  const el = $("ruthlessBody");
  el.innerHTML =
    `<p class="rl-blurb">Ten songs will write themselves out from wherever you point, ` +
    `one word a second. Name them.</p>` +
    `<p class="rl-sub"><span>ten pages · the clock is the score · low wins</span>` +
      `<span class="rl-count">played ${played}/${lenses.length}</span></p>` +
    `<div class="rl-doc">${secs}</div>` +
    `<p class="rl-foot">a wrong guess costs nothing but the seconds it took. ` +
      `each section is as long as its pages usually run.</p>`;
  rlDocEl = el.querySelector(".rl-doc");
  el.querySelectorAll(".rl-sec").forEach((b) =>
    b.addEventListener("click", () => startRuthlessMode(b.dataset.lens)));
}

/* A Ruthless mode run: ten pages whose streams all open on the chosen section. It runs on the
   shelf's own machinery deliberately — the loop, the drip, the clock and the give-up are all
   the same, and the lens plus the ending are the only differences. */
function startRuthlessMode(lensId) {
  const lens = ruthlessLens(lensId);
  if (!lens) return;
  const g = BONUS_GAMES.find((x) => x.id === "ruthless-game");
  if (!g) return;
  startBonusGame(g, lens.id);
}

function openAlbumFocus(from) {
  albumFocusBackTarget = from;
  renderAlbumFocusPage();
  flipAwayToScreen("albumfocus");
}

function renderAlbumFocusPage() {
  const board = loadAlbumFocus();
  const beaten = STUDIO_ALBUMS.filter((a) => board[a] && board[a].beaten).length;
  const perfected = STUDIO_ALBUMS.filter((a) => board[a] && board[a].perfected).length;

  // Default selection: keep the current pick if valid, else the first not-yet-beaten album.
  if (!afSelectedAlbum || !STUDIO_ALBUMS.includes(afSelectedAlbum)) {
    afSelectedAlbum = STUDIO_ALBUMS.find((a) => !(board[a] && board[a].beaten)) || STUDIO_ALBUMS[0];
  }

  // The board — 12 pinned snapshots that "develop" with progress: blank when fresh,
  // a faint era wash once played (with the best score pencilled in), full era colour
  // when beaten, and gold-leafed when perfected. The era colour is exposed as --era so
  // the picture layer can later swap the flat wash for a per-album illustration.
  let tiles = "";
  STUDIO_ALBUMS.forEach((a) => {
    const rec = albumFocusRecord(a);
    const state = rec.perfected ? "is-perfect" : rec.beaten ? "is-beaten" : rec.best > 0 ? "is-played" : "is-fresh";
    const stateWord = rec.perfected ? "perfected" : rec.beaten ? "beaten" : rec.best > 0 ? "in progress" : "not played yet";
    const score = (rec.best > 0 && !rec.beaten) ? `<span class="af-tile-score">${rec.best}/${TOTAL_ROUNDS}</span>` : "";
    const gold = rec.perfected
      ? `<span class="af-corner af-corner--tl" aria-hidden="true"></span><span class="af-corner af-corner--tr" aria-hidden="true"></span>` : "";
    tiles += `<button type="button" class="af-tile ${state}" data-album="${escapeHtml(a)}" style="--era:${albumColor(a) || "#999"}" aria-label="${escapeHtml(a)}: ${stateWord}">` +
      `<span class="af-pin" aria-hidden="true"></span>${gold}` +
      `<span class="af-tile-win" aria-hidden="true"></span>${score}` +
      `<span class="af-tile-cap">${escapeHtml(albumTileName(a))}</span>` +
      `</button>`;
  });

  const perfectLine = perfected ? ` · perfected <b>${perfected}</b>/${STUDIO_ALBUMS.length}` : "";
  const html =
    `<div class="chall-head">` +
      `<div class="chall-head-sub">tap an album · beat all 12</div>` +
      `<span class="chall-tokens">beaten <b>${beaten}</b>/${STUDIO_ALBUMS.length}${perfectLine}</span>` +
    `</div>` +
    `<div class="af-board">${tiles}</div>` +
    `<div class="chall-detail af-detail" id="afDetail"></div>`;

  const el = $("albumFocusBody");
  el.innerHTML = html;
  el.querySelectorAll(".af-tile").forEach((b) =>
    b.addEventListener("click", () => selectAlbum(b.dataset.album)));
  selectAlbum(afSelectedAlbum);
}

function selectAlbum(album) {
  afSelectedAlbum = album;
  const body = $("albumFocusBody");
  if (!body) return;
  body.querySelectorAll(".af-tile").forEach((b) =>
    b.classList.toggle("selected", b.dataset.album === album));
  renderAlbumDetail(album);
}

function renderAlbumDetail(album) {
  const el = $("afDetail");
  if (!el) return;
  const rec = albumFocusRecord(album);
  const col = albumColor(album) || "#999";

  const tabs = ALBUM_FOCUS_DIFFS.map((d) =>
    `<button type="button" class="af-diff${d === afSelectedDiff ? " is-on" : ""}" data-diff="${d}">${escapeHtml(MODES[d].label)}</button>`
  ).join("");

  const stamp = rec.perfected
    ? `<span class="chall-detail-star">${CHALL_STAR}</span><span class="chall-detail-stamp af-stamp">perfected</span>`
    : rec.beaten ? `<span class="chall-detail-stamp af-stamp">beaten</span>` : "";

  let meta = "";
  if (rec.best > 0) {
    meta = `best ${rec.best}/${TOTAL_ROUNDS}`;
    if (rec.beatenDiff) meta += ` · beaten on ${(MODES[rec.beatenDiff] || {}).label || rec.beatenDiff}`;
  } else {
    meta = "not played yet";
  }

  el.innerHTML =
    `<div class="chall-detail-head">` +
      `<span class="af-detail-spine" style="background:${col}"></span>` +
      `<span class="chall-detail-name">${escapeHtml(album)}</span>${stamp}` +
    `</div>` +
    `<div class="chall-sec">` +
      `<div class="chall-eyebrow">The rule</div>` +
      `<div class="chall-rule">Every word and every answer comes from <b>${escapeHtml(album)}</b>.</div>` +
    `</div>` +
    `<div class="chall-sec chall-sec--beat">` +
      `<div class="chall-eyebrow">To beat it</div>` +
      `<div class="chall-goal">Score ${ALBUM_FOCUS_TARGET}/${TOTAL_ROUNDS}. A perfect 13/13 completes it in style.</div>` +
      `<div class="af-diffs">${tabs}</div>` +
    `</div>` +
    `<div class="chall-act">` +
      `<span class="chall-meta">${escapeHtml(meta)}</span>` +
      `<button type="button" class="chall-go" data-play="${escapeHtml(album)}">${rec.beaten ? "Play again" : "Start writing"}</button>` +
    `</div>`;

  el.querySelectorAll(".af-diff").forEach((b) =>
    b.addEventListener("click", () => { afSelectedDiff = b.dataset.diff; renderAlbumDetail(album); }));
  const pb = el.querySelector("[data-play]");
  if (pb) pb.addEventListener("click", () => startAlbumFocus(pb.dataset.play, afSelectedDiff));
}

/* ---------- Guest shelf ----------
   The destination the corner guest stamp franks you through to: other artists' catalogues,
   hung on a rail as backstage passes. GUESTS carries only the name and the ink; every number
   on a pass (songs, records, prompt words) comes from the guest's own file, fetched the first
   time the shelf is opened and cached for the session. Nothing about a guest is hardcoded
   here, so growing guests/olivia-rodrigo.json changes the pass without touching this file.

   The remaining slots are drawn as bare rings. An empty hanger is honest — it shows the rail
   has room without inventing a name we cannot play. */
// The hardware, shared by every hanger: the split ring the strap loops through (drawn as
// three ellipses — the metal itself, plus a darker edge either side of it) and the notebook
// star printed on the pass band.
const GUEST_RING_SHAPES =
  `<ellipse class="ring" cx="48" cy="19" rx="12" ry="13.5"/>` +
  `<ellipse class="ring-edge" cx="48" cy="19" rx="14.7" ry="16.2"/>` +
  `<ellipse class="ring-edge" cx="48" cy="19" rx="9.3" ry="10.8"/>`;
const GUEST_STAR =
  `<svg class="guest-band-star" viewBox="0 0 24 24" aria-hidden="true">` +
  `<path d="M12 1.6l2.7 6.1 6.6.6-5 4.4 1.5 6.5L12 16.3 6.2 19.7l1.5-6.5-5-4.4 6.6-.6z"/></svg>`;

let guestBackTarget = "start";        // where the shelf's back link returns to
let guestSelected = null;             // id of the pass whose detail is open, or null
let guestSelectedDiff = "medium";     // the difficulty tab the detail panel has picked
let guestShelfScrollY = 0;             // restored after returning from a visiting catalogue
const guestFiles = new Map();         // id -> Promise<catalogue json>, one fetch per session

// Deal the five established strap lengths out in a fresh order on every page load. Keying the
// result by guest keeps a pass fixed through shelf re-renders (navigation and responsive rail
// changes), while a full reload makes the rack look newly hung. Tilts use the same restrained
// seven-step range as the old slot formula, so randomising never makes a pass look untidy.
const GUEST_STRAP_LENGTHS = [96, 113, 130, 147, 164];
const guestHangLayout = new Map();
for (let offset = 0; offset < GUESTS.length; offset += GUEST_STRAP_LENGTHS.length) {
  const lengths = shuffle(GUEST_STRAP_LENGTHS.slice());
  GUESTS.slice(offset, offset + lengths.length).forEach((guest, i) => {
    guestHangLayout.set(guest.id, {
      len: lengths[i],
      tilt: (Math.floor(Math.random() * 7) - 3) * 0.7,
    });
  });
}

// Lazy-load a guest's catalogue. Rejections are swallowed by the caller (the pass just keeps
// its em-dashes) but NOT cached as a failure, so a flaky first fetch can be retried by
// reopening the shelf.
function loadGuest(id) {
  const guest = GUESTS.find((g) => g.id === id);
  if (!guest) return Promise.reject(new Error("unknown guest " + id));
  if (!guestFiles.has(id)) {
    guestFiles.set(id, fetch(guest.file)
      .then((r) => { if (!r.ok) throw new Error(guest.file + " " + r.status); return r.json(); })
      .catch((err) => { guestFiles.delete(id); throw err; }));
  }
  return guestFiles.get(id);
}

// The counts a pass shows, derived from the file rather than stored anywhere.
function guestCounts(cat) {
  const albums = Array.isArray(cat.albums) ? cat.albums : [];
  return {
    records: albums.length,
    songs: albums.reduce((n, a) => n + (a.songs ? a.songs.length : 0), 0),
    words: Array.isArray(cat.words) ? cat.words.length : 0,
  };
}

// How many passes hang from one rail. A pass never shrinks past the point where its own name
// is readable, so a narrow page gets MORE rails rather than smaller passes. The count comes
// from the notebook card's real content width (NOT the window: the card is narrower than the
// viewport, and its left margin gutter is wide), so it stays right at any page width.
const GUEST_PASS_W = 128, GUEST_PASS_MIN = 100, GUEST_RAIL_GAP = 14;
function guestRailWidth() {
  const el = $("guestBody");
  if (el && el.clientWidth) return el.clientWidth;
  // Rendered before the flip, so the shelf is still display:none and measures 0. Every screen
  // is the same card, so borrow the width of whichever one is currently visible.
  const active = Object.values(screens).find((s) => s.classList.contains("active"));
  if (active && active.clientWidth) {
    const cs = getComputedStyle(active);
    return active.clientWidth - parseFloat(cs.paddingLeft || 0) - parseFloat(cs.paddingRight || 0);
  }
  return window.innerWidth;
}
function guestPerRail() {
  // Fit is measured against the pass's floor width, not its comfortable one: five across
  // squeezed to 100 reads better than a rail count that leaves the last rail half empty.
  const fit = Math.floor((guestRailWidth() + GUEST_RAIL_GAP) / (GUEST_PASS_MIN + GUEST_RAIL_GAP));
  return Math.max(2, Math.min(5, fit));
}
// How the slots divide across the rails. Filling each rail to the maximum leaves the last one
// stranded (4+4+2), so the count that fits only decides how FEW rails we need — the slots are
// then spread evenly over them, and the rails being centred hides the odd one out.
function guestRailPlan() {
  const rails = Math.max(1, Math.ceil(GUEST_SHELF_SLOTS / guestPerRail()));
  const base = Math.floor(GUEST_SHELF_SLOTS / rails), extra = GUEST_SHELF_SLOTS % rails;
  return Array.from({ length: rails }, (_, i) => base + (i < extra ? 1 : 0));
}

// The corner guest stamp is franked in a random ink from STAMP_INKS once per page load and
// then left alone: a stamp that changed colour while you looked at it would read as a bug,
// and the point is the small pleasure of noticing a different plate on the next visit. The
// figure and caption knock out in the paper colour, so one property does the whole plate.
function frankGuestStamp() {
  const btn = $("guestShelfBtn");
  if (!btn) return;
  btn.style.setProperty("--gs-ink", STAMP_INKS[Math.floor(Math.random() * STAMP_INKS.length)]);
}

function openGuestShelf(from) {
  guestBackTarget = from;
  // Arriving straight off a finished run, the masthead is still advertising it by name
  // ("… · Olivia Rodrigo"). The shelf is the desk, not a live run, so drop the run's game type
  // the same way renderStartPickers does on the way back to the front page.
  if (gameType === "guest") { gameType = "classic"; updateTagline(); }
  renderGuestShelfPage();
  flipAwayToScreen("guests");
}

function renderGuestShelfPage() {
  let rails = "", slot = 0;
  for (const count of guestRailPlan()) {
    let pegs = "";
    for (let n = 0; n < count; n++, slot++) {
      pegs += GUESTS[slot] ? guestPassMarkup(GUESTS[slot], slot) : guestEmptyMarkup();
    }
    rails += `<div class="guest-rail">${pegs}</div>`;
  }

  const el = $("guestBody");
  el.innerHTML =
    `<div class="chall-head">` +
      `<div class="chall-head-sub">visiting catalogues</div>` +
      `<span class="chall-tokens">on the rail <b>${GUESTS.length}</b>/${GUEST_SHELF_SLOTS}</span>` +
    `</div>` +
    `<div class="guest-rack">${rails}</div>`;

  el.querySelectorAll(".guest-pass").forEach((b) =>
    b.addEventListener("click", () => selectGuest(b.dataset.guest)));

  // Fill the counts in as the files land. Each pass renders with em-dashes first so the rail
  // never waits on the network to draw.
  GUESTS.forEach((g) => {
    loadGuest(g.id)
      .then((cat) => { paintGuestCounts(g.id, guestCounts(cat)); })
      .catch(() => {});
  });

}

// One hanger: a ring, a woven strap of its own length, and the pass. The strap length and
// tilt come from the page-load layout above, so the rail reads as hung rather than laid out
// on a grid without moving around during the same visit.
function guestPassMarkup(g, slot) {
  const { len, tilt } = guestHangLayout.get(g.id) || { len: 130, tilt: 0 };
  const ticks = g.ink.ticks.map((c) => `<i style="background:${c}"></i>`).join("");
  // The stub is printed "admit one" until the guest is admitted, then franked across. The
  // stamp angle is derived from the slot too, so it sits like a hand-pressed one and, like
  // the hang, is the same every time this guest is drawn.
  const rec = guestRecord(g.id);
  const stub = rec.admitted
    ? `<span class="guest-stub guest-stub--stamped">` +
        `<i class="guest-admit" style="--stamp-rot:${(((slot * 29) % 5) - 2) * 1.6}deg">admitted</i></span>`
    : `<span class="guest-stub"></span>`;
  return (
    `<span class="guest-peg" style="--g-deep:${g.ink.deep};--g-accent:${g.ink.accent};` +
      `--g-strap:${g.ink.strap};--g-pen:${g.ink.pen};">` +
      guestStrapMarkup(len) +
      `<button type="button" class="guest-pass" data-guest="${escapeHtml(g.id)}"` +
        ` style="--tilt:${tilt.toFixed(1)}deg" aria-label="${escapeHtml(g.name)}: guest catalogue${rec.admitted ? ", admitted" : ""}">` +
        `<span class="guest-slot" aria-hidden="true"></span>` +
        `<span class="guest-print">` +
          `<span class="guest-band">guest${GUEST_STAR}</span>` +
          `<span class="guest-face">` +
            `<span class="guest-name">${escapeHtml(g.name).replace(" ", "<br>")}</span>` +
            `<span class="guest-ticks" aria-hidden="true">${ticks}</span>` +
            `<span class="guest-line"><span data-count="songs"><strong class="guest-song-count">—</strong> songs</span></span>` +
            stub +
          `</span>` +
        `</span>` +
      `</button>` +
    `</span>`
  );
}

// An empty hanger: the ring and nothing on it.
function guestEmptyMarkup() {
  return `<span class="guest-peg guest-peg--empty" aria-hidden="true">` +
    `<svg class="guest-strap guest-strap--bare" viewBox="0 0 96 44" aria-hidden="true">${GUEST_RING_SHAPES}</svg></span>`;
}

function guestStrapMarkup(len) {
  const mid = 30 + (len - 48) * 0.3, low = 30 + (len - 48) * 0.66;
  return (
    `<svg class="guest-strap" viewBox="0 0 96 ${len}" style="height:${Math.round(len * 0.66)}px" aria-hidden="true">` +
      GUEST_RING_SHAPES +
      `<path class="webbing" d="M43 30 C 28 ${mid}, 25 ${low}, 31 ${len - 18} L42 ${len - 18} C 36 ${low}, 36 ${mid}, 50 34 Z"/>` +
      `<path class="webbing webbing--dark" d="M53 30 C 68 ${mid}, 71 ${low}, 65 ${len - 18} L54 ${len - 18} C 60 ${low}, 60 ${mid}, 46 34 Z"/>` +
      `<rect class="crimp" x="31" y="${len - 22}" width="34" height="15" rx="2"/>` +
    `</svg>`
  );
}

// Drop the real numbers onto a pass once its file has landed.
function paintGuestCounts(id, counts) {
  const body = $("guestBody");
  if (!body) return;
  const pass = body.querySelector(`.guest-pass[data-guest="${CSS.escape(id)}"]`);
  if (pass) {
    const songs = pass.querySelector('.guest-song-count');
    if (songs) songs.textContent = counts.songs;
  }
}

function selectGuest(id) {
  guestSelected = id;
  guestShelfScrollY = window.scrollY;
  renderGuestDetail(id);
  flipAwayToScreen("guestdetail");
  window.scrollTo({ top: 0, behavior: "instant" });
}

function closeGuestDetail() {
  renderGuestShelfPage();
  flipInToScreen("guests");
  requestAnimationFrame(() => window.scrollTo({ top: guestShelfScrollY, behavior: "instant" }));
}

// The pass turned over: what is actually in this catalogue. The record list comes straight
// from the file, so it can never drift from what a guest round would draw on.
function renderGuestDetail(id) {
  const el = $("guestDetailBody");
  if (!el) return;
  const g = GUESTS.find((x) => x.id === id);
  if (!g) { el.innerHTML = ""; return; }

  loadGuest(id).then((c) => {
    if (guestSelected !== id || !$("guestDetailBody")) return;
    const counts = guestCounts(c);
    const rec = guestRecord(id);
    const records = (c.albums || []).map((a) =>
      `<li><span class="guest-rec-name">${escapeHtml(a.album)}</span>` +
      `<span class="guest-rec-n">${(a.songs || []).length}</span></li>`).join("");
    const tabs = GUEST_DIFFS.map((d) =>
      `<button type="button" class="af-diff${d === guestSelectedDiff ? " is-on" : ""}" data-diff="${d}">${escapeHtml(MODES[d].label)}</button>`
    ).join("");
    const stamp = rec.admitted
      ? `<span class="chall-detail-star">${CHALL_STAR}</span><span class="chall-detail-stamp af-stamp">admitted</span>` : "";
    let meta = "not played yet";
    if (rec.best > 0) {
      meta = `best ${rec.best}/${TOTAL_ROUNDS}`;
      if (rec.admittedDiff) meta += ` · admitted on ${(MODES[rec.admittedDiff] || {}).label || rec.admittedDiff}`;
    }
    $("guestDetailBody").innerHTML =
      `<div class="chall-detail guest-detail">` +
      `<div class="guest-detail-head" style="--g-pen:${g.ink.pen}">` +
        `<span class="guest-detail-name">${escapeHtml(g.name)}</span>${stamp}` +
        `<span class="guest-detail-nums">${counts.songs} songs · ${counts.records} records · ${counts.words} words</span>` +
      `</div>` +
      `<ul class="guest-recs">${records}</ul>` +
      `<div class="chall-sec">` +
        `<div class="chall-eyebrow">The rule</div>` +
        `<div class="chall-rule">Every word and every answer comes from <b>${escapeHtml(g.name)}</b>'s catalogue. ` +
          `Nothing here counts toward your Taylor records.</div>` +
      `</div>` +
      `<div class="chall-sec chall-sec--beat">` +
        `<div class="chall-eyebrow">To be admitted</div>` +
        `<div class="chall-goal">Name all ${TOTAL_ROUNDS}. Anything less is a visit, not a residency.</div>` +
        `<div class="af-diffs">${tabs}</div>` +
      `</div>` +
      `<div class="chall-act">` +
        `<span class="chall-meta">${escapeHtml(meta)}</span>` +
        `<button type="button" class="chall-go" data-play="${escapeHtml(id)}">${rec.best > 0 ? "Play again" : "Start writing"}</button>` +
      `</div></div>`;
    const el2 = $("guestDetailBody");
    el2.querySelectorAll(".af-diff").forEach((b) =>
      b.addEventListener("click", () => { guestSelectedDiff = b.dataset.diff; renderGuestDetail(id); }));
    const pb = el2.querySelector("[data-play]");
    if (pb) pb.addEventListener("click", () => startGuestRun(pb.dataset.play, guestSelectedDiff));
  }).catch(() => {
    if (guestSelected !== id || !$("guestDetailBody")) return;
    $("guestDetailBody").innerHTML =
      `<p class="guest-detail-note">couldn't fetch this catalogue — check your connection and reopen the shelf</p>`;
  });
  if (!el.innerHTML) el.innerHTML = `<p class="guest-detail-note">reading the sleeve…</p>`;
}

/* ---------- Custom mode start-row (the active preset summary + Change) ----------
   Custom is a first-class game type: selecting the Custom tab shows this row (in place of the
   difficulty ladder), and the launchpad "Start writing" button runs the active preset. */
function renderCustomRow() {
  const el = $("customStartSummary");
  if (!el) return;
  const store = loadCustom();
  const active = store.presets.find((p) => p.id === store.activeId) || store.presets[0];
  const activeMode = normalizeCustomMode(active.mode);

  // One clean section: the active preset's name + lever summary, and a single Change button
  // that opens the full editor (which also holds the preset switcher). No extra chips here.
  el.innerHTML =
    `<div class="custom-active">` +
      `<div class="custom-active-head">` +
        `<span class="custom-active-name">${escapeHtml(active.name || "Custom")}</span>` +
        `<button type="button" id="customChangeBtn" class="custom-change-btn">${TYPE_GLYPHS.custom}Change</button>` +
      `</div>` +
      `<span class="custom-active-levers">${escapeHtml(customLeverSummary(activeMode))}</span>` +
    `</div>`;

  $("customChangeBtn").addEventListener("click", () => openCustomModal());
}

// Re-render whatever custom UI is currently on screen (the start row and/or the open modal).
// Shared by the dev tools so seeding/patching a preset reflects immediately.
function syncCustomUI() {
  if (screens.start.classList.contains("active") && gameType === "custom") { renderCustomRow(); updateTagline(); }
  if ($("customModal") && $("customModal").classList.contains("open")) renderCustomModalBody();
}

/* ---------- Bracelet (hand-strung SVG) ---------- */
let justEarnedIndex = -1; // bead that just became a charm, for the swing-in

// The shuffle behind a "random" charm strand. Per RUN, not per render and not per bead
// index: the bracelet is rebuilt on every page turn, so a seed that moved with the render
// would reshuffle the strand under the player between pages, and a seed that was only the
// bead index would make bead 3 a moon on every bracelet forever. Never persisted — no
// bracelet outlives its run. The one apparent exception is the saved daily snapshot, which
// redraws a finished run's strand hours later; the daily overrides this with its own
// date-derived seed at both ends so the two renders agree (see startDaily / showDailyResult).
let braceletSeed = 0;

// Wraps the pure buildBraceletSVG, injecting the Mastery-chosen dangling charm into
// every render so app.js stays the single owner of that game-state default.
function renderBraceletSVG(results, active, fresh, albums, opts) {
  // Impostor challenge: a bead that flagged a fake dangles a little devil, not the star.
  const impostorCaught = impostorRuleActive()
    ? results.map((ok, i) => ok === true && impostorRounds.has(i + 1))
    : null;
  // Risk challenges: a bead won at stake dangles a horseshoe instead of the usual charm,
  // and the uninsured miss that ended an Insurance run strings a skull in place of a spacer.
  const riskWon = riskRuleActive() ? riskCharm.slice() : null;
  const skullMiss = riskRuleActive() ? riskSkull.slice() : null;
  return buildBraceletSVG(results, active, fresh, albums,
    { ...opts, charm: settings.masteryCharm, charmSeed: braceletSeed, impostorCaught, riskWon, skullMiss });
}

// ---- Bracelet-as-PNG keepsake ----
// The finished strand on screen is a bare SVG; on its own it exports as a lonely
// sliver. buildCardMeta gathers everything the export needs to frame it as a torn
// notebook page: the run's headline + stat chips, the live colour tokens (so the
// card matches whatever era/paper/colour-blind palette is active), and the exact
// strand markup already on the results screen — reused verbatim so the keepsake is
// pixel-identical to what the player just saw.
function cardVars() {
  const cs = getComputedStyle(document.body);
  const g = (name, fallback) => (cs.getPropertyValue(name).trim() || fallback);
  return {
    ink:       g("--ink", "#2b2722"),
    inkSoft:   g("--ink-soft", "#6f675a"),
    inkAccent: g("--ink-accent", "#a9791f"),
    paper:     g("--paper", "#f5efe1"),
    paperEdge: g("--paper-edge", "#efe7d4"),
    bead:      g("--bead", "#c8951f"),
    margin:    g("--margin", "rgba(160,62,46,0.45)"),
    rule:      g("--rule", "rgba(74,54,30,0.09)"),
  };
}

function buildCardMeta() {
  const correct = roundResults.filter(Boolean).length;
  const runTime = currentMode.seconds > 0 ? gameTimeSum : null;
  const dateKey = window.__devDate || todayKey();
  const dateLabel = new Date(dateKey + "T00:00:00").toLocaleDateString("en-US",
    { month: "long", day: "numeric", year: "numeric" });
  // Stamp the time the keepsake was made (real clock; the date honours any dev override).
  const timeLabel = fmtClock(new Date());

  const stats = [];
  let title = "the bracelet you made";

  if (gameType === "infinite") {
    title = "an infinite strand";
    stats.push({ v: "Infinite", l: "mode" });
    stats.push({ v: String(roundResults.length), l: "rounds" });
    stats.push({ v: String(correct), l: "strung" });
    if (runTime != null) stats.push({ v: fmtTime(runTime), l: "on the clock" });
  } else if (gameType === "adaptive") {
    const name = ADAPTIVE_LEVELS[adaptivePeak] || "";
    title = adaptivePeak >= ADAPT_MAX_LEVEL ? "climbed all the way up ★" : "how high you climbed";
    stats.push({ v: "Adaptive", l: "mode" });
    stats.push({ v: "L" + adaptivePeak, l: name || "peak level" });
    stats.push({ v: correct + "/" + TOTAL_ROUNDS, l: "strung" });
  } else if (gameType === "album" && focusAlbum) {
    const perfect = correct === TOTAL_ROUNDS;
    title = perfect ? focusAlbum + ", start to finish ★" : "an album, in beads";
    stats.push({ v: "Album Focus", l: "mode" });
    stats.push({ v: focusAlbum, l: "the album" });
    stats.push({ v: correct + "/" + TOTAL_ROUNDS, l: "strung" });
  } else if (gameType === "guest" && guestRunId) {
    const guest = GUESTS.find((x) => x.id === guestRunId);
    const perfect = correct === TOTAL_ROUNDS;
    title = perfect ? "admitted to the shelf ★" : "a night on someone else's catalogue";
    stats.push({ v: "Guest shelf", l: "mode" });
    stats.push({ v: (guest && guest.name) || "Guest", l: "the catalogue" });
    stats.push({ v: correct + "/" + TOTAL_ROUNDS, l: "strung" });
  } else if (gameType === "ruthless" && ruthlessCard) {
    // Read off the run's own snapshot rather than roundResults, which a Ruthless run never
    // touches: the bonus loop keeps its pages in bonusLog and would otherwise hand the card
    // the last classic run's thirteen.
    const clean = ruthlessCard.named === ruthlessCard.pages;
    title = clean ? "ten named, nothing handed back ★" : "ten pages against the clock";
    stats.push({ v: "Ruthless", l: ruthlessCard.lens || "mode" });
    stats.push({ v: fmtTime(ruthlessCard.secs), l: "the run" });
    stats.push({ v: ruthlessCard.named + "/" + ruthlessCard.pages, l: "named" });
  } else if (gameType === "custom") {
    const finite = !customInfinite();
    title = "a bracelet on my terms";
    stats.push({ v: "Custom", l: customPreset ? customPreset.name : "mode" });
    stats.push({ v: finite ? correct + "/" + customSessionLen : String(roundResults.length), l: finite ? "strung" : "rounds" });
    if (runTime != null) stats.push({ v: fmtTime(runTime), l: "on the clock" });
  } else {
    // classic, daily, challenge — a fixed 13-round page
    const perfect = correct === TOTAL_ROUNDS;
    const hidden = gameType === "daily" && settings.hideDailyScore;
    title = perfect ? "thirteen for thirteen ★"
          : gameType === "daily" ? "today's daily" : "the bracelet you made";
    stats.push({ v: gameType === "daily" ? "Daily" : (GAMETYPE_LABELS[gameType] || "Classic"), l: "mode" });
    stats.push({ v: hidden ? "?" : correct + "/" + TOTAL_ROUNDS, l: "strung" });
    if (runTime != null && !hidden) stats.push({ v: fmtTime(runTime), l: "on the clock" });
    if (verseBonus > 0 && !hidden) stats.push({ v: "+" + verseBonus, l: "verse bonus" });
  }

  const name = (settings.playerName || "").trim();
  return {
    kicker: "Swift to the Song Association",
    title,
    braceletMarkup: $("resultBracelet").innerHTML,
    stats: stats.slice(0, 4),
    signature: name,
    footer: dateLabel + " · " + timeLabel + " · swiftassociation.com",
    filename: "swift-bracelet-" + dateKey + ".png",
    heartHands: HEART_HANDS_SVG,   // the notebook's own emblem, re-tinted on the card
    vars: cardVars(),
  };
}

/* An exported SVG is rasterised through an <img>, in an isolated document that cannot see
   index.html's #bd-* sprite — so every piece the disc points at has to travel WITH it. This
   walks the disc markup's own hrefs and lifts those defs out of the live page, which means a
   new mark added to the sprite is carried by the keepsake without anyone remembering to. */
function discSpriteDefs(markup) {
  const ids = new Set();
  String(markup).replace(/href="#([\w-]+)"/g, (m, id) => (ids.add(id), m));
  let out = "";
  ids.forEach((id) => { const el = document.getElementById(id); if (el) out += el.outerHTML; });
  return out;
}

/* The bonus sleeve's keepsake. Almost all of it was written down when the run ended (see
   bonusSleeveRun); what's added here is what belongs to the moment the button is pressed —
   the disc and its sprite pieces, the clock, the era's colours, and the player's signature. */
function buildSleeveMeta() {
  const r = bonusSleeveRun;
  const dateKey = window.__devDate || todayKey();
  const dateLabel = new Date(dateKey + "T00:00:00").toLocaleDateString("en-US",
    { month: "long", day: "numeric", year: "numeric" });
  const disc = bonusDisc(r.game);
  return {
    eyebrow: "Swift to the Song Association · bonus games",
    name: r.game.name,
    kicker: r.game.kicker,
    tint: r.game.tint,
    remark: r.remark,
    aside: r.aside,
    score: r.score,
    scoreSub: r.scoreSub,
    stamp: r.stamp,
    foot: r.foot,
    tracks: r.tracks.map((t) => ({ n: t.n, ok: t.ok, title: censor(t.title), note: t.note || "" })),
    disc,
    discDefs: discSpriteDefs(disc),
    signature: (settings.playerName || "").trim(),
    footer: dateLabel + " · " + fmtClock(new Date()) + " · swiftassociation.com",
    filename: "swift-" + r.game.id + "-" + dateKey + ".png",
    heartHands: HEART_HANDS_SVG,
    vars: cardVars(),
  };
}

/* ---------- Taking a keepsake off the page ----------
   One handler behind every "save this" button on the site (the results bracelet, the bonus
   shelf's sleeve). A plain click copies the PNG to the clipboard; a shift- (or ⌘/ctrl-)
   click downloads it instead. If the browser can't write images to the clipboard, the copy
   path quietly falls back to a download so the button always does *something*. Guards
   against a double-click while rasterising.
   The meta is built LATE (inside the handler) rather than passed in, so a button that has
   been sitting on screen for a minute still exports what is on the page now. */

/* Two shapes of button share that handler. The bracelet's is a worded one and says what it
   is doing in its own label; the sleeve's is a mark set at the end of the card's footer, so
   its wording lives in a hidden span and the visible answer is a state on the element (the
   copy glyph swaps to a tick). Both read and write through this pair, and a button with no
   hidden span keeps the old plain-text behaviour. */
function keepsakeLabel(btn) {
  const sr = btn.querySelector(".sr-only");
  return sr ? sr.textContent : btn.textContent;
}
function setKeepsakeLabel(btn, text, state) {
  const sr = btn.querySelector(".sr-only");
  if (!sr) { btn.textContent = text; return; }
  sr.textContent = text;
  if (state) btn.setAttribute("data-state", state);
  else btn.removeAttribute("data-state");
}

let keepsakeSaveBusy = false;
async function saveKeepsakePNG(e, { btn, meta, copy, download, noun, onKept }) {
  if (keepsakeSaveBusy) return;
  const wantDownload = !!(e && (e.shiftKey || e.metaKey || e.ctrlKey));
  keepsakeSaveBusy = true;
  const label = btn ? keepsakeLabel(btn) : "";
  let kept = false;
  if (btn) { btn.disabled = true; setKeepsakeLabel(btn, wantDownload ? "Saving…" : "Copying…", "busy"); }
  try {
    // NOT awaited before the clipboard call: the write has to stay inside the user gesture.
    if (wantDownload) await download(meta());
    else await copy(meta());
    kept = true;
    if (btn) setKeepsakeLabel(btn, wantDownload ? "Saved ✓" : "Copied ✓", "kept");
  } catch (e2) {
    console.warn(noun + " PNG export failed:", e2);
    if (!wantDownload) {
      // Clipboard-image writes aren't supported everywhere — fall back to a download.
      try {
        await download(meta());
        kept = true;
        if (btn) setKeepsakeLabel(btn, "Saved ✓", "kept");
      } catch (e3) {
        console.warn(noun + " PNG download fallback failed:", e3);
        if (btn) setKeepsakeLabel(btn, "Couldn’t save", "failed");
        notifyNote("couldn’t save the " + noun, "try again in a moment");
      }
    } else {
      if (btn) setKeepsakeLabel(btn, "Couldn’t save", "failed");
      notifyNote("couldn’t save the " + noun, "try again in a moment");
    }
  } finally {
    keepsakeSaveBusy = false;
    if (kept && onKept) onKept();
    if (btn) setTimeout(() => { btn.disabled = false; setKeepsakeLabel(btn, label, ""); }, 1800);
  }
}

// Wired to the results-screen bracelet button.
function saveBraceletPNG(e) {
  if (!$("resultBracelet").innerHTML.trim()) return;   // nothing strung yet
  return saveKeepsakePNG(e, {
    btn: $("saveBraceletBtn"),
    meta: buildCardMeta,
    copy: copyBraceletCard,
    download: exportBraceletCard,
    noun: "bracelet",
    onKept: () => unlock("youre-on-your-own-kid"),     // "You're On Your Own, Kid"
  });
}

// Wired to the bonus sleeve's button. No `onKept`, and that is the sandbox rather than an
// oversight: a bonus run writes nothing but its own best score, so keeping its sleeve must
// not quietly hand out the charm a bracelet does.
function saveSleevePNG(e) {
  if (!bonusSleeveRun) return;
  return saveKeepsakePNG(e, {
    btn: $("saveSleeveBtn"),
    meta: buildSleeveMeta,
    copy: copySleeveCard,
    download: exportSleeveCard,
    noun: "sleeve",
  });
}

function renderBracelet() {
  const opts = (gameType === "infinite" || customInfinite())
    ? { total: Math.max(round, 1), letterBead: false, colors: albumPalette(), hinted: roundHinted, verseTiers: roundVerseTier }
    : gameType === "custom"
    ? { total: customSessionLen, colors: albumPalette(), hinted: roundHinted, verseTiers: roundVerseTier }
    : { colors: albumPalette(), hinted: roundHinted, verseTiers: roundVerseTier };
  $("bracelet").innerHTML = renderBraceletSVG(roundResults, round, justEarnedIndex, roundAlbums, opts);
  const correct = roundResults.filter(Boolean).length;
  $("charmCount").textContent = correct;
  const uncapped = gameType === "infinite" || customInfinite()
    || (gameType === "challenge" && currentChallenge && currentChallenge.rule === "survive");
  const pg = uncapped
    ? Math.max(round, 1)
    : Math.min(Math.max(round, 1), sessionRounds());
  $("pageNum").textContent = pg;
  renderPageRegister(pg, uncapped);
  // Voice the progress the bracelet shows visually (the SVG is aria-hidden). Only
  // re-announces when the text changes, so it fires on round advance and after a verdict.
  const sr = $("srStatus");
  if (sr) {
    sr.textContent = (uncapped ? `Round ${pg}. ` : `Page ${pg} of ${sessionRounds()}. `)
      + `${correct} correct so far.`;
  }
}

// A quiet, hand-drawn register in the paper margin for the notebook's canonical 13 pages.
// Other run lengths already have their own progress language, so they do not borrow this motif.
function renderPageRegister(page, uncapped) {
  const el = $("pageRegister");
  if (uncapped || sessionRounds() !== TOTAL_ROUNDS) {
    renderNotebookPageRegister(el, 0, 0);
    return;
  }
  renderNotebookPageRegister(el, page, TOTAL_ROUNDS);
}

// Shared painter for the main game's 13-page register and the bonus shelf's ten-page one.
function renderNotebookPageRegister(el, page, total, accent = "") {
  if (!el) return;
  if (!total) {
    el.classList.remove("show");
    el.innerHTML = "";
    el.style.removeProperty("--register-accent");
    return;
  }
  const widths = [8, 10, 7, 9, 8, 11, 7, 9, 8, 10, 7, 9, 8];
  const tilts = [-2, 1, -1, 2, 0, -2, 1, -1, 2, -1, 1, -2, 0];
  const shifts = [1, 0, 2, 0, 1, 0, 2, 1, 0, 1, 2, 0, 1];
  const current = Math.min(Math.max(page, 1), total);
  el.innerHTML = Array.from({ length: total }, (_, i) => {
    const pageNumber = i + 1;
    const state = pageNumber < current ? " is-complete" : pageNumber === current ? " is-current" : "";
    return `<span class="page-register-mark${state}" style="--register-width:${widths[i % widths.length]}px;--register-tilt:${tilts[i % tilts.length]}deg;--register-x:${shifts[i % shifts.length]}px"></span>`;
  }).join("");
  if (accent) el.style.setProperty("--register-accent", accent);
  else el.style.removeProperty("--register-accent");
  el.classList.add("show");
}

// Pencil tally in the margin: one mark per starting life, spent ones struck out.
// Shown in infinite mode and in an infinite custom run; every other mode hides the element.
function startingLives() { return infiniteVariant === "sudden" ? 1 : 3; }
// Starting lives for whichever run counts them down (Infinite variant, or a custom infinite run).
function runStartingLives() { return customInfinite() ? currentMode.lives : startingLives(); }
function renderLives() {
  const el = $("livesTally");
  if (!el) return;
  if (gameType !== "infinite" && !customInfinite()) { el.classList.remove("show"); el.innerHTML = ""; return; }
  const total = runStartingLives();
  let marks = "";
  for (let i = 0; i < total; i++) {
    const spent = i >= lives;
    marks += `<span class="life-mark${spent ? " spent" : ""}" aria-hidden="true"></span>`;
  }
  el.innerHTML = marks;
  el.classList.add("show");
}

/* ---------- Adaptive level ---------- */
// Move the rarity level after a verdict: promote-slow (ADAPT_PROMO_STREAK correct at a
// level climbs one), demote-fast (any miss/timeout drops one). The visible level maps
// exactly onto the bucket in play; the promo sub-meter shows progress toward the next.
function adaptiveAdjust(correct) {
  if (correct) {
    adaptivePromo++;
    if (adaptivePromo >= ADAPT_PROMO_STREAK && adaptiveLevel < ADAPT_MAX_LEVEL) {
      adaptiveLevel++;
      adaptivePromo = 0;
    } else if (adaptiveLevel >= ADAPT_MAX_LEVEL) {
      adaptivePromo = 0;   // already at the ceiling — keep the meter empty, no overflow
    }
  } else {
    adaptivePromo = 0;
    if (adaptiveLevel > 1) adaptiveLevel--;
  }
  adaptivePeak = Math.max(adaptivePeak, adaptiveLevel);
  // Adaptive charms: The Lakes the moment you touch the Rarest tier; Stay Stay Stay stays
  // alive only while no miss has landed since reaching the top (judged at endAdaptive).
  if (adaptiveLevel >= ADAPT_MAX_LEVEL) { adaptiveReachedTop = true; unlock("the-lakes"); }
  if (!correct && adaptiveReachedTop) adaptiveHeldTop = false;
  renderAdaptiveGauge();
}

// The visible rarity gauge: four tier pips lit up to the current level, with a promo
// sub-meter filling toward the next. Only shown in Adaptive; every other mode hides it.
function renderAdaptiveGauge() {
  const el = $("adaptiveGauge");
  if (!el) return;
  if (gameType !== "adaptive") { el.classList.remove("show"); el.innerHTML = ""; return; }
  const atTop = adaptiveLevel >= ADAPT_MAX_LEVEL;
  const pips = [];
  for (let lvl = 1; lvl <= ADAPT_MAX_LEVEL; lvl++) {
    const on = lvl <= adaptiveLevel ? " on" : "";
    const cur = lvl === adaptiveLevel ? " cur" : "";
    pips.push(`<span class="adapt-pip${on}${cur}" aria-hidden="true"></span>`);
  }
  // Promo meter: fraction of the way to the next level (hidden at the ceiling).
  const frac = atTop ? 1 : Math.min(1, adaptivePromo / ADAPT_PROMO_STREAK);
  const meter = atTop
    ? `<span class="adapt-meter adapt-meter--top" aria-hidden="true"></span>`
    : `<span class="adapt-meter" aria-hidden="true"><i style="width:${Math.round(frac * 100)}%"></i></span>`;
  const name = ADAPTIVE_LEVELS[adaptiveLevel] || "";
  el.innerHTML =
    `<span class="adapt-label">Level ${adaptiveLevel} · ${name}</span>` +
    `<span class="adapt-pips">${pips.join("")}</span>` +
    meter;
  el.classList.add("show");
}

/* ---------- Data load ---------- */
async function loadData() {
  const [wordsRes, songsRes] = await Promise.all([
    fetch("words.json"),
    fetch("songs.json"),
  ]);
  if (!wordsRes.ok || !songsRes.ok) throw new Error("Failed to fetch data files");
  const words = await wordsRes.json();
  const grouped = await songsRes.json();
  taylorCorpus = installCorpus(grouped, words, { aliases: true });
}

/* ---------- The corpus (which catalogue the game is currently playing) ----------
   Everything below the matcher — allSongs, the title indexes, the playable word list, the
   rarity buckets — is derived ONCE from songs.json and then read as module state by the whole
   game. A guest run needs the same machinery pointed at a different catalogue, so rather than
   thread a corpus argument through every matching call site, a guest SWAPS these globals for
   the length of its run and swaps them back on the way out (see startGuestRun / restoreCorpus).

   The swap is only safe because it is total: `installCorpus` rebuilds every one of these
   fields together, and `snapshotCorpus` captures every one of them. If a new derived index is
   added to loadData, it must be added to BOTH or a guest run will leave a stale Taylor index
   sitting beside Olivia's songs. That is the whole contract; there is nothing else to it. */
let taylorCorpus = null;              // the main catalogue, snapshotted at load
const guestCorpora = new Map();       // guest id -> its built corpus, one build per session
let activeCorpus = "taylor";          // which catalogue the globals currently hold

function snapshotCorpus() {
  return { allSongs, titleIndex, spacelessIndex, playableWords, titleWordList,
           shortTitleWordLists, albumWordMap, albumOrder, wordBuckets, lyricVocab };
}
function applyCorpus(c) {
  allSongs = c.allSongs; titleIndex = c.titleIndex; spacelessIndex = c.spacelessIndex;
  playableWords = c.playableWords; titleWordList = c.titleWordList;
  shortTitleWordLists = c.shortTitleWordLists; albumWordMap = c.albumWordMap;
  albumOrder = c.albumOrder; wordBuckets = c.wordBuckets; lyricVocab = c.lyricVocab;
}
// Put Taylor's catalogue back. Safe to call at any time, including when it is already
// active — every exit from a guest run goes through it rather than trusting one path.
function restoreCorpus() {
  if (activeCorpus === "taylor" || !taylorCorpus) return;
  applyCorpus(taylorCorpus);
  activeCorpus = "taylor";
}

// Build a corpus from a grouped album list + its word list and INSTALL it into the globals,
// then hand back a snapshot of what was built. Installing as it goes is deliberate: the
// derivation leans on songsContainingWord / validSongs / titleSongsForWord, which read the
// globals themselves, so the corpus has to be live to be measured.
// `opts.aliases` folds in TITLE_ALIASES (Taylor-specific, so guests pass it false);
// `opts.buckets` is the rarity threshold set (a guest carries its own, see buildWordBuckets).
function installCorpus(grouped, words, opts = {}) {
  // songs.json stores lyrics as structured sections ([{label, lines}]); the game
  // works off a flat newline-joined `lyrics` string, so derive it here once. The
  // `sections` stay on the song object (line numbers + verse/chorus/bridge) for the
  // lyrics searcher. The flatten is byte-identical to the old flat `lyrics` field.
  allSongs = grouped.flatMap(({ album, songs }) =>
    songs.map((s) => ({
      ...s,
      album,
      lyrics: Array.isArray(s.sections)
        ? s.sections.flatMap((sec) => sec.lines || []).join("\n")
        : (s.lyrics || ""),
    }))
  );
  // Precompute a normalized comparison key per song and index by it, so a typed
  // answer matches regardless of punctuation / & / $ / numerals. Then fold in the
  // irregular aliases, never letting one shadow a genuine title.
  titleIndex = new Map();
  lyricVocab = new Set();
  for (const s of allSongs) {
    s._norm = normalizeTitle(s.title);
    s._normLyrics = normalizeLyric(s.lyrics);   // flat blob for lyric-line matching
    // The title in LYRIC normalization (not normalizeTitle's), so isTitleFragment can
    // compare it against typed text on the same footing as a lyric fragment. A per-song
    // field rather than a corpus-level index on purpose: it rides on allSongs, so a guest
    // swap carries it automatically and there is nothing to add to snapshotCorpus.
    s._normTitleLyric = normalizeLyric(s.title);
    for (const t of s._normLyrics.split(" ")) lyricVocab.add(t);
    titleIndex.set(s._norm, s);
    // A catalogue may retain an official display title while accepting its common
    // short form. Keep aliases with the song so guest catalogues remain self-contained.
    for (const alias of s.aliases || []) {
      const key = normalizeTitle(alias);
      const existing = titleIndex.get(key);
      if (existing && existing !== s) {
        console.warn(`Song alias: "${alias}" collides with "${existing.title}"; skipped`);
        continue;
      }
      titleIndex.set(key, s);
    }
  }
  for (const [canonical, aliases] of Object.entries(opts.aliases ? TITLE_ALIASES : {})) {
    const song = allSongs.find((s) => s.title === canonical);
    if (!song) { console.warn(`TITLE_ALIASES: no song titled "${canonical}"`); continue; }
    for (const alias of aliases) {
      const key = normalizeTitle(alias);
      const existing = titleIndex.get(key);
      if (existing && existing !== song) {
        console.warn(`TITLE_ALIASES: "${alias}" collides with "${existing.title}"; skipped`);
        continue;
      }
      titleIndex.set(key, song);
    }
  }
  // Spaceless fallback: forgive misplaced spaces ("all to owell" -> "all too well") by
  // indexing each title/alias with its spaces stripped. Only kept when unambiguous — if
  // two distinct songs collapse to the same spaceless key, we drop it rather than guess.
  spacelessIndex = new Map();
  const spaceClash = new Set();
  for (const [key, song] of titleIndex) {
    const sp = key.replace(/ /g, "");
    if (!sp || sp === key) continue;          // no spaces -> the normal index already covers it
    const existing = spacelessIndex.get(sp);
    if (existing && existing !== song) { spaceClash.add(sp); continue; }
    spacelessIndex.set(sp, song);
  }
  for (const sp of spaceClash) spacelessIndex.delete(sp);
  // Lenient playability (Easy/Medium/Hard use derived forms).
  playableWords = words.filter((w) => songsContainingWord(w, false).length >= 1);
  if (!playableWords.length) throw new Error("No playable words found in data");
  // Title...? challenge pool: words that appear in at least one song title (so every
  // round can be won by naming a title that holds the word).
  titleWordList = playableWords.filter((w) => titleSongsForWord(w, false).length >= 1);
  // Short n' Sweet pool: words with at least one valid (lyrics) song whose title is ≤2 words,
  // so every round can be won with a one- or two-word title.
  // One pool per title-length rule, so the dark side's one-word-only run is guaranteed a
  // winnable page just as the base ≤2-word run is.
  shortTitleWordLists = {};
  for (const max of [1, 2]) {
    shortTitleWordLists[max] = playableWords.filter((w) =>
      validSongs(w, false, false).some((s) => titleWordCount(s.title) <= max));
  }
  // On Tour! pools: for each album, the playable words that have a valid (lyrics) song
  // in it, so each tour stop can be handed a winnable word. Plus the canonical album order.
  albumOrder = grouped.map((g) => g.album);
  albumWordMap = {};
  for (const w of playableWords) {
    for (const a of new Set(validSongs(w, false, false).map((s) => s.album)))
      (albumWordMap[a] = albumWordMap[a] || []).push(w);
  }
  buildWordBuckets(opts.buckets);
  return snapshotCorpus();
}

// Bucket words by how many songs contain them, so each mode draws from an
// appropriate-rarity pool. Thresholds are tunable; each bucket falls back to
// the full list if it ends up too thin to sustain a 13-round, no-repeat game.
// `cfg` is a threshold set: TAYLOR_BUCKETS for the main catalogue, or a guest's own out of
// its file. The numbers are per-catalogue and deliberately NOT scaled off catalogue size —
// no clean formula fits both 287 songs and 42, and one bent through two points would be a
// false generalisation waiting to misfit the third guest.
function buildWordBuckets(cfg = TAYLOR_BUCKETS) {
  const MIN = RECENT_WINDOW + 8;
  // Easy counts plain lyric matches (title songs are allowed in Easy/Medium).
  const easy = playableWords.filter((w) => songsContainingWord(w, false).length >= cfg.easy);
  // Hard/Ultra count only *valid* answers (word in lyrics but NOT the title), so
  // every bucketed word still has at least one answerable, non-giveaway song.
  const hard = playableWords.filter((w) => {
    const n = validSongs(w, false, true).length;
    return n >= cfg.hard[0] && n <= cfg.hard[1];
  });
  const ultra = playableWords.filter((w) => {
    const n = validSongs(w, true, true).length;   // strict word, no title, rarest
    return n >= cfg.ultra[0] && n <= cfg.ultra[1];
  });
  const safe = (arr) => (arr.length >= MIN ? arr : playableWords);
  wordBuckets = { easy: safe(easy), all: playableWords, hard: safe(hard), ultra: safe(ultra) };
}

/* ---------- Difficulty ---------- */
function setMode(id) {
  if (!MODES[id]) return;
  currentMode = MODES[id];
  try { localStorage.setItem(DIFF_KEY, id); } catch (e) { /* ignore */ }
  renderModePicker();
  refreshStartBoard();
}
const GAMETYPE_LABELS = { classic: "Classic", infinite: "Infinite", adaptive: "Adaptive", custom: "Custom" };
// Glyphs that sit before a game type's label in the start-screen picker. A mark
// only earns a spot when it IS the concept: Infinite's endless ∞, Adaptive's
// self-adjusting gauge (rarity floats on a visible level), and Custom's levers
// (the mode is a board of levers you drag). Classic stays plain — the default.
// All are pen-stroke SVGs that inherit the tab's ink via currentColor, so they
// flip to paper on an inked-active tab exactly as the old Unicode ∞ did. INF_GLYPH
// is shared with the stats mode tabs (renderStatsTabs) so the two ∞s never drift.
const INF_GLYPH = `<svg class="type-glyph type-glyph--inf" viewBox="2 4 20 16" aria-hidden="true">` +
  `<path d="M12 12 C 8.6 5.8, 4 6.6, 4 12 C 4 17.4, 8.6 18.2, 12 12 C 15.4 5.8, 20 6.6, 20 12 C 20 17.4, 15.4 18.2, 12 12 Z"/></svg>`;
const TYPE_GLYPHS = {
  classic: `<svg class="type-glyph type-glyph--note" viewBox="0 0 24 24" aria-hidden="true">` +
    `<circle class="head" cx="8.9" cy="17.5" r="2.8"/><path d="M10.7 17.5 L10.7 4.8"/>` +
    `<path d="M10.7 4.8 C 13.8 6, 16 8.1, 15.4 11.5"/></svg>`,
  infinite: INF_GLYPH,
  adaptive: `<svg class="type-glyph type-glyph--gauge" viewBox="0 0 24 24" aria-hidden="true">` +
    `<path d="M4 17a8 8 0 0 1 16 0"/><path d="M12 17l4.6 -5.2"/><circle class="hub" cx="12" cy="17" r="1.3"/></svg>`,
  custom: `<svg class="type-glyph type-glyph--levers" viewBox="0 0 24 24" aria-hidden="true">` +
    `<path d="M4 6h6"/><path d="M14 6h6"/><path d="M4 12h8"/><path d="M16 12h4"/><path d="M4 18h3"/><path d="M11 18h9"/>` +
    `<circle cx="12" cy="6" r="2.1"/><circle cx="14" cy="12" r="2.1"/><circle cx="9" cy="18" r="2.1"/></svg>`,
};
const GAME_TYPES = ["classic", "infinite", "adaptive", "custom"];
const VARIANT_LABELS = { "3lives": "3 lives", sudden: "Sudden death" };

// The start-screen "your best" line follows the selected mode (+ infinite variant).
function refreshStartBoard() {
  const t = $("startPodiumTitle");
  if (gameType === "custom") {
    // Custom is sandboxed — no ranked board. Say so plainly where "your best" would sit.
    if (t) t.textContent = "Custom";
    const el = $("startBest");
    if (el) el.innerHTML = `<div class="best-empty">a workshop mode: a run trains your skills, but never sets records</div>`;
    return;
  }
  if (t) t.textContent = "Your best";
  if (gameType === "adaptive") { renderAdaptiveBest($("startBest")); return; }
  renderBestLine($("startBest"), boardMode());
}
// The active custom preset's playable lever set (clamped + derived). Reused by the start-row
// summary, the tagline, and startCustom.
function activeCustomMode() { return normalizeCustomMode(activeCustomPreset().mode); }
// Adaptive's "your best" line — the highest level ever reached (its board metric),
// with the score on that run as the tie-break detail.
function renderAdaptiveBest(el) {
  const rec = adaptiveRecord();
  if (!rec.played) {
    el.innerHTML = `<div class="best-empty">no climbs yet — see how high you reach <span class="best-empty-star">${STAR_SVG}</span></div>`;
    return;
  }
  const name = ADAPTIVE_LEVELS[rec.bestPeak] || "";
  el.innerHTML =
    `<div class="best-line"><span class="best-num"><span class="lvl-prefix">L</span>${rec.bestPeak}<span class="best-unit"> · ${escapeHtml(name)}</span></span>` +
    `<span class="best-meta">★ highest level · ${rec.bestScore}/${TOTAL_ROUNDS} that run${rec.date ? " · " + recordDateLabel(rec.date) : ""}</span></div>`;
}
// Show/hide the start-screen rows that only apply to a particular game type:
// the lives variant row (Infinite only) and the difficulty picker vs the Adaptive
// explainer (difficulty floats in Adaptive, so its picker is meaningless).
function applyTypeLayout() {
  const isAdaptive = gameType === "adaptive";
  const isCustom = gameType === "custom";
  const vr = $("variantRow"); if (vr) vr.style.display = gameType === "infinite" ? "" : "none";
  // Neither Adaptive (difficulty floats) nor Custom (its own lever set) uses the difficulty ladder.
  const dr = $("difficultyRow"); if (dr) dr.style.display = (isAdaptive || isCustom) ? "none" : "";
  const an = $("adaptiveNote"); if (an) an.style.display = isAdaptive ? "" : "none";
  const cr = $("customRow"); if (cr) cr.style.display = isCustom ? "" : "none";
}
function updateBlurb() {
  if (gameType === "custom") {
    renderCustomRow();   // the custom row carries its own summary; there's no shared blurb line
  } else if (gameType === "adaptive") {
    const an = $("adaptiveNote");
    if (an) an.textContent = "Start in the middle. Every right answer climbs you toward rarer words; a miss drops you back. Your level is shown as you play.";
  } else {
    const b = $("modeBlurb");
    if (b) {
      if (gameType === "infinite") {
        const v = infiniteVariant === "sudden" ? "one miss ends it" : "three lives";
        b.textContent = v + " · " + currentMode.blurb;
      } else {
        b.textContent = currentMode.blurb;
      }
    }
  }
  updateTagline();
}
// Masthead tagline reflects the active/selected game config.
function updateTagline() {
  const el = $("tagline");
  if (!el) return;
  // Custom's clock comes from the active preset, not the difficulty currentMode.
  const cm = gameType === "custom" ? activeCustomMode() : currentMode;
  const clock = cm.seconds > 0 ? `${cm.seconds} seconds each` : "no timer";
  const line = gameType === "infinite"
    ? `endless pages · ${clock}`
    : gameType === "adaptive"
    ? `${TOTAL_ROUNDS} pages · difficulty that climbs with you`
    : gameType === "custom"
    ? `${cm.rounds === 0 ? "endless pages" : cm.rounds + " pages"} · ${clock} · your own rules`
    // A guest run is the one place where "name the song" doesn't mean a Taylor song, and the
    // tagline is the only line on the game screen with room to say so.
    : gameType === "guest"
    ? `${TOTAL_ROUNDS} pages · ${clock} · ${(currentGuest() || {}).name || "a guest"}`
    // Ruthless is the one run with no per-page clock at all, so quoting `clock` here would
    // hang the last difficulty's seconds over a mode that doesn't have any. What it has
    // instead is the only thing worth saying: the clock is not the limit, it is the result.
    : gameType === "ruthless"
    ? `${BONUS_ROUNDS} pages · the clock is the score`
    : `${TOTAL_ROUNDS} pages · ${clock} · ${currentMode.label} difficulty`;
  // Without this a dark run is indistinguishable from the base challenge: same tagline, same
  // page count, just quietly harder numbers. The eclipse + "dark side" is the only thing on
  // the game screen that says which variant you're actually in.
  el.classList.toggle("is-dark-run", !!challengeDark);
  if (challengeDark) {
    el.innerHTML = `${escapeHtml(line)}<span class="tagline-dark">${CHALL_ECLIPSE}dark side</span>`;
  } else {
    el.textContent = line;
  }
}
function renderModePicker() {
  const tabs = $("modeTabs");
  if (!tabs) return;
  const tab = (m, extra) =>
    `<button type="button" class="mode-tab${extra || ""}${m === currentMode.id ? " active" : ""}" data-mode="${m}">${MODES[m].label}</button>`;
  // The relaxed→ultra ladder is one axis; lyricist is a separate modality, so it sits past a
  // divider with its own "by heart" caption rather than reading as a sixth difficulty rung.
  const ladder = DIFFICULTY_LADDER.map((m) => tab(m)).join("");
  const modality = MODALITY_MODES.length
    ? `<span class="mode-tab-sep" aria-hidden="true"></span>` +
      MODALITY_MODES.map((m) => tab(m, " mode-tab--modality")).join("")
    : "";
  tabs.innerHTML = ladder + modality;
  tabs.querySelectorAll("[data-mode]").forEach((b) =>
    b.addEventListener("click", () => setMode(b.dataset.mode)));
  updateBlurb();
}
function renderTypePicker() {
  const tabs = $("typeTabs");
  if (!tabs) return;
  tabs.innerHTML = GAME_TYPES.map((g) =>
    `<button type="button" class="mode-tab${g === gameType ? " active" : ""}" data-type="${g}">${TYPE_GLYPHS[g] || ""}${GAMETYPE_LABELS[g]}</button>`
  ).join("");
  tabs.querySelectorAll("[data-type]").forEach((b) =>
    b.addEventListener("click", () => setGameType(b.dataset.type)));
}
function renderVariantPicker() {
  const tabs = $("variantTabs");
  if (!tabs) return;
  tabs.innerHTML = ["3lives", "sudden"].map((v) =>
    `<button type="button" class="mode-tab${v === infiniteVariant ? " active" : ""}" data-variant="${v}">${VARIANT_LABELS[v]}</button>`
  ).join("");
  tabs.querySelectorAll("[data-variant]").forEach((b) =>
    b.addEventListener("click", () => setVariant(b.dataset.variant)));
}
// Render all three start-screen pickers + the board for the current selection.
function renderStartPickers() {
  if (!GAME_TYPES.includes(gameType)) gameType = "classic";
  // Back on the desk, there's no live run — so no dark run either. `challengeDark` only clears
  // at the NEXT game's resetRunState, which leaves the masthead tagline still reading "dark
  // side" on the start screen after a dark challenge is quit or finished. Clear it here, the
  // one choke point every return-to-start passes through, so the tagline reflects the mode
  // that's actually selected.
  challengeDark = false;
  // Same reasoning for the guest catalogue: back on the desk there is no live guest run, so
  // the stats, records and searcher reachable from here must be reading Taylor's songs.
  restoreCorpus();
  // A daily game forces currentMode to Normal without persisting; restore the
  // player's preference (a fixed default-difficulty setting, else their last pick).
  currentMode = (settings.defaultDifficulty !== "last" && MODES[settings.defaultDifficulty])
    ? MODES[settings.defaultDifficulty]
    : loadMode();
  renderTypePicker();
  renderVariantPicker();
  applyTypeLayout();
  renderModePicker();
  refreshStartBoard();
  renderDailyButtonState();
  renderAnniversaryNote();
}
// The era ink for a milestone's album, honouring the colour-blind setting (null album →
// plain ink, used by the birthday note and as a safe fallback for the sticky heart).
function milestoneColor(album) {
  const colors = settings.colorBlindAlbums ? CB_ALBUM_COLORS : ALBUM_COLORS;
  return (album && colors[album]) || "";
}
// Today's dated note for the margin and the game sticky: a real Taylor milestone always wins;
// on a quiet day we fall back to the game's sacred 13 (the 13th, or a date that adds up to 13).
// Album-only paths (daily theming) keep calling anniversaryNote directly, so a 13-day never
// tints the daily challenge.
function dayNote(dateKey) {
  return anniversaryNote(dateKey, TS_MILESTONES) || thirteenNote(dateKey);
}
// Every surface that reads today's date, re-rendered together. Called whenever the dev
// date override moves (see buildDevApi's `date`), so the page can never show one day in
// the margin and another on the desk. The desk calendar is an optional decorative prop —
// desktop-only, and its module may not have run — so it's refreshed only if it's there.
function refreshDateSurfaces() {
  renderAnniversaryNote();
  renderMilestoneSticky();
  window.deskCalendar?.refresh();
  // Moving the date moves what "today" means to the daily gate, so the button's
  // played/unplayed coat, its countdown and the streak on the desk placard all
  // have to be redrawn with it.
  renderDailyButtonState();
}
// Dated marginalia at the top of today's page: on a real Taylor milestone (an album
// release or her birthday) a torn slip is taped to the page, the album name tinted to its
// era. Most days it's silent (hidden). Keyed on todayKey() so it flips on the player's day.
function renderAnniversaryNote() {
  const el = $("anniversaryNote");
  if (!el) return;
  const note = dayNote(todayKey());
  if (!note) { el.hidden = true; el.innerHTML = ""; return; }
  const accent = milestoneColor(note.album);
  const name = accent
    ? `<span class="an-name" style="color:${accent}">${escapeHtml(note.headline)}</span>`
    : `<span class="an-name">${escapeHtml(note.headline)}</span>`;
  el.innerHTML =
    `<div class="an-slip${note.tone === "minor" ? " an-slip--minor" : ""}">` +
      `<span class="an-tape an-tape-l"></span><span class="an-tape an-tape-r"></span>` +
      `<div class="an-eyebrow">${escapeHtml(note.eyebrow)}</div>` +
      `<div class="an-headline">${name}${note.headlineRest ? " " + escapeHtml(note.headlineRest) : ""}</div>` +
      (note.note ? `<div class="an-note">${escapeHtml(note.note)}</div>` : "") +
    `</div>`;
  el.hidden = false;
}
// The game-screen counterpart: a tiny taped corner sticky on a milestone day. An era-
// coloured heart for an album/re-record, the "13" birthday cake on Dec 13, with a short
// handwritten caption. Re-rendered on every show of the game screen (and by dev tools).
function renderMilestoneSticky() {
  const el = $("milestoneSticky");
  if (!el) return;
  const note = dayNote(todayKey());
  if (!note) { el.hidden = true; el.innerHTML = ""; el.removeAttribute("aria-label"); return; }
  const icon = note.icon === "cake" ? cakeSvg()
    : note.icon === "thirteen" ? thirteenSvg()
    : note.icon === "salt" ? saltSvg(milestoneColor(note.album) || "var(--bead)")
    : heartSvg(milestoneColor(note.album) || "var(--bead)");
  el.innerHTML =
    `<div class="ms-slip${note.tone === "minor" ? " ms-slip--minor" : ""}"><span class="ms-tape"></span>${icon}</div>` +
    `<div class="ms-cap">${escapeHtml(note.caption)}</div>`;
  el.setAttribute("aria-label", note.aria || note.caption);
  el.hidden = false;
}
// Hand-built notebook SVGs for the milestone sticky (no album art, no emoji). The heart
// takes the era ink as its fill, with a translucent dark edge so any era reads on cream.
function heartSvg(fill) {
  return `<svg viewBox="0 0 32 32" width="38" height="38" aria-hidden="true">` +
    `<path d="M16 27.5C15.4 27.1 4.5 19.6 4.5 11.7c0-3.6 2.7-6.4 6-6.4 2.3 0 4.2 1.3 5.5 3.4 1.3-2.1 3.2-3.4 5.5-3.4 3.3 0 6 2.8 6 6.4 0 7.9-10.9 15.4-11.5 15.8z" fill="${fill}" stroke="rgba(0,0,0,0.22)" stroke-width="0.7" stroke-linejoin="round"/>` +
    `<path d="M9.5 9.2c-1 .6-1.6 1.7-1.7 3" fill="none" stroke="rgba(255,255,255,0.55)" stroke-width="1.1" stroke-linecap="round"/>` +
    `</svg>`;
}
